      OR (v_old_row->'reference_number') IS DISTINCT FROM (v_new_row->'reference_number')
      OR (v_old_row->'status') IS DISTINCT FROM (v_new_row->'status')
      OR (v_old_row->'submission_mode') IS DISTINCT FROM (v_new_row->'submission_mode')
      OR (v_old_row->'contract_id') IS DISTINCT FROM (v_new_row->'contract_id')
      OR (v_old_row->'is_adjustment') IS DISTINCT FROM (v_new_row->'is_adjustment')
      OR (v_old_row->'parent_timesheet_id') IS DISTINCT FROM (v_new_row->'parent_timesheet_id')
      OR (v_old_row->'correction_id') IS DISTINCT FROM (v_new_row->'correction_id')
      OR (v_old_row->'correction_kind') IS DISTINCT FROM (v_new_row->'correction_kind')
      OR (v_old_row->'adjustment_origin') IS DISTINCT FROM (v_new_row->'adjustment_origin');
  ELSIF TG_OP = 'UPDATE' AND v_trigger_table = 'timesheets_financials' THEN
    v_authorise_boundary_changed :=
      (NULLIF(BTRIM(COALESCE(v_old_row->>'authorised_at_utc', '')), '') IS NOT NULL)
      IS DISTINCT FROM
      (NULLIF(BTRIM(COALESCE(v_new_row->>'authorised_at_utc', '')), '') IS NOT NULL);

    IF LOWER(BTRIM(COALESCE(v_new_row->>'is_current', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on') THEN
      v_material_live_source_changed :=
      (v_old_row->'pay_method') IS DISTINCT FROM (v_new_row->'pay_method')
      OR (v_old_row->'policy_snapshot_json') IS DISTINCT FROM (v_new_row->'policy_snapshot_json')
      OR (v_old_row->'rate_source_refs_json') IS DISTINCT FROM (v_new_row->'rate_source_refs_json')
      OR (v_old_row->'hours_day') IS DISTINCT FROM (v_new_row->'hours_day')
      OR (v_old_row->'hours_night') IS DISTINCT FROM (v_new_row->'hours_night')
      OR (v_old_row->'hours_sat') IS DISTINCT FROM (v_new_row->'hours_sat')
      OR (v_old_row->'hours_sun') IS DISTINCT FROM (v_new_row->'hours_sun')
      OR (v_old_row->'hours_bh') IS DISTINCT FROM (v_new_row->'hours_bh')
      OR (v_old_row->'pay_day') IS DISTINCT FROM (v_new_row->'pay_day')
      OR (v_old_row->'pay_night') IS DISTINCT FROM (v_new_row->'pay_night')
      OR (v_old_row->'pay_sat') IS DISTINCT FROM (v_new_row->'pay_sat')
      OR (v_old_row->'pay_sun') IS DISTINCT FROM (v_new_row->'pay_sun')
      OR (v_old_row->'pay_bh') IS DISTINCT FROM (v_new_row->'pay_bh')
      OR (v_old_row->'total_hours') IS DISTINCT FROM (v_new_row->'total_hours')
      OR (v_old_row->'total_pay_ex_vat') IS DISTINCT FROM (v_new_row->'total_pay_ex_vat')
      OR (v_old_row->'expenses_pay_ex_vat') IS DISTINCT FROM (v_new_row->'expenses_pay_ex_vat')
      OR (v_old_row->'travel_pay_ex_vat') IS DISTINCT FROM (v_new_row->'travel_pay_ex_vat')
      OR (v_old_row->'accommodation_pay_ex_vat') IS DISTINCT FROM (v_new_row->'accommodation_pay_ex_vat')
      OR (v_old_row->'other_pay_ex_vat') IS DISTINCT FROM (v_new_row->'other_pay_ex_vat')
      OR (v_old_row->'mileage_units') IS DISTINCT FROM (v_new_row->'mileage_units')
      OR (v_old_row->'mileage_pay_rate') IS DISTINCT FROM (v_new_row->'mileage_pay_rate')
      OR (v_old_row->'mileage_pay_ex_vat') IS DISTINCT FROM (v_new_row->'mileage_pay_ex_vat')
      OR (v_old_row->'additional_pay_ex_vat') IS DISTINCT FROM (v_new_row->'additional_pay_ex_vat')
      OR (v_old_row->'pay_wtr_rate_pct_snapshot') IS DISTINCT FROM (v_new_row->'pay_wtr_rate_pct_snapshot')
      OR (v_old_row->'pay_vat_rate_pct_snapshot') IS DISTINCT FROM (v_new_row->'pay_vat_rate_pct_snapshot')
      OR (v_old_row->'pay_vat_amount_snapshot') IS DISTINCT FROM (v_new_row->'pay_vat_amount_snapshot')
      OR (v_old_row->'pay_total_inc_vat_snapshot') IS DISTINCT FROM (v_new_row->'pay_total_inc_vat_snapshot')
      OR (v_old_row->'invoice_breakdown_json') IS DISTINCT FROM (v_new_row->'invoice_breakdown_json')
      OR (v_old_row->'additional_units_json') IS DISTINCT FROM (v_new_row->'additional_units_json')
      OR (v_old_row->'actual_schedule_json') IS DISTINCT FROM (v_new_row->'actual_schedule_json')
      OR (v_old_row->'worked_start_iso') IS DISTINCT FROM (v_new_row->'worked_start_iso')
      OR (v_old_row->'worked_end_iso') IS DISTINCT FROM (v_new_row->'worked_end_iso')
      OR (v_old_row->'break_start_iso') IS DISTINCT FROM (v_new_row->'break_start_iso')
      OR (v_old_row->'break_end_iso') IS DISTINCT FROM (v_new_row->'break_end_iso')
      OR (v_old_row->'break_minutes') IS DISTINCT FROM (v_new_row->'break_minutes')
      OR (v_old_row->'pay_on_hold') IS DISTINCT FROM (v_new_row->'pay_on_hold')
      OR (v_old_row->'pay_on_hold_reason') IS DISTINCT FROM (v_new_row->'pay_on_hold_reason')
      OR (v_old_row->'has_rate_issue') IS DISTINCT FROM (v_new_row->'has_rate_issue')
      OR (v_old_row->'has_pay_channel_issue') IS DISTINCT FROM (v_new_row->'has_pay_channel_issue')
      OR (v_old_row->'processing_status') IS DISTINCT FROM (v_new_row->'processing_status')
      OR (v_old_row->'locked_by_invoice_id') IS DISTINCT FROM (v_new_row->'locked_by_invoice_id')
      OR (v_old_row->'unlocked_by_credit_note_id') IS DISTINCT FROM (v_new_row->'unlocked_by_credit_note_id')
      OR (v_old_row->'candidate_id') IS DISTINCT FROM (v_new_row->'candidate_id')
      OR (v_old_row->'client_id') IS DISTINCT FROM (v_new_row->'client_id');
    ELSE
      -- Snapshot rotation demotes the previous row before inserting its
      -- replacement.  The demotion itself is bookkeeping, not a live-source
      -- economic change and must not mark a frozen Draft stale.
      v_material_live_source_changed := false;
    END IF;
  ELSIF TG_OP = 'INSERT' AND v_trigger_table = 'timesheets_financials' THEN
    IF LOWER(BTRIM(COALESCE(v_new_row->>'is_current', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on') THEN
      SELECT COALESCE(to_jsonb(previous_financial_row), '{}'::jsonb)
      INTO v_previous_tsfin_row
      FROM public.timesheets_financials AS previous_financial_row
      WHERE previous_financial_row.timesheet_id = v_new_timesheet_id
        AND previous_financial_row.id IS DISTINCT FROM
          CASE
            WHEN NULLIF(BTRIM(COALESCE(v_new_row->>'id', '')), '') ~* v_uuid_re
              THEN NULLIF(BTRIM(COALESCE(v_new_row->>'id', '')), '')::uuid
            ELSE NULL::uuid
          END
      ORDER BY
        previous_financial_row.timesheet_version DESC NULLS LAST,
        previous_financial_row.computed_at_utc DESC NULLS LAST,
        previous_financial_row.created_at DESC NULLS LAST,
        previous_financial_row.id DESC
      LIMIT 1;

      v_previous_tsfin_row := COALESCE(v_previous_tsfin_row, '{}'::jsonb);
      IF v_previous_tsfin_row = '{}'::jsonb THEN
        v_material_live_source_changed := true;
      ELSE
        v_material_live_source_changed :=
          (v_previous_tsfin_row->'pay_method') IS DISTINCT FROM (v_new_row->'pay_method')
          OR (v_previous_tsfin_row->'policy_snapshot_json') IS DISTINCT FROM (v_new_row->'policy_snapshot_json')
          OR (v_previous_tsfin_row->'rate_source_refs_json') IS DISTINCT FROM (v_new_row->'rate_source_refs_json')
          OR (v_previous_tsfin_row->'hours_day') IS DISTINCT FROM (v_new_row->'hours_day')
          OR (v_previous_tsfin_row->'hours_night') IS DISTINCT FROM (v_new_row->'hours_night')
          OR (v_previous_tsfin_row->'hours_sat') IS DISTINCT FROM (v_new_row->'hours_sat')
          OR (v_previous_tsfin_row->'hours_sun') IS DISTINCT FROM (v_new_row->'hours_sun')
          OR (v_previous_tsfin_row->'hours_bh') IS DISTINCT FROM (v_new_row->'hours_bh')
          OR (v_previous_tsfin_row->'pay_day') IS DISTINCT FROM (v_new_row->'pay_day')
          OR (v_previous_tsfin_row->'pay_night') IS DISTINCT FROM (v_new_row->'pay_night')
          OR (v_previous_tsfin_row->'pay_sat') IS DISTINCT FROM (v_new_row->'pay_sat')
          OR (v_previous_tsfin_row->'pay_sun') IS DISTINCT FROM (v_new_row->'pay_sun')
          OR (v_previous_tsfin_row->'pay_bh') IS DISTINCT FROM (v_new_row->'pay_bh')
          OR (v_previous_tsfin_row->'total_hours') IS DISTINCT FROM (v_new_row->'total_hours')
          OR (v_previous_tsfin_row->'total_pay_ex_vat') IS DISTINCT FROM (v_new_row->'total_pay_ex_vat')
          OR (v_previous_tsfin_row->'expenses_pay_ex_vat') IS DISTINCT FROM (v_new_row->'expenses_pay_ex_vat')
          OR (v_previous_tsfin_row->'travel_pay_ex_vat') IS DISTINCT FROM (v_new_row->'travel_pay_ex_vat')
          OR (v_previous_tsfin_row->'accommodation_pay_ex_vat') IS DISTINCT FROM (v_new_row->'accommodation_pay_ex_vat')
          OR (v_previous_tsfin_row->'other_pay_ex_vat') IS DISTINCT FROM (v_new_row->'other_pay_ex_vat')
          OR (v_previous_tsfin_row->'mileage_units') IS DISTINCT FROM (v_new_row->'mileage_units')
          OR (v_previous_tsfin_row->'mileage_pay_rate') IS DISTINCT FROM (v_new_row->'mileage_pay_rate')
          OR (v_previous_tsfin_row->'mileage_pay_ex_vat') IS DISTINCT FROM (v_new_row->'mileage_pay_ex_vat')
          OR (v_previous_tsfin_row->'additional_pay_ex_vat') IS DISTINCT FROM (v_new_row->'additional_pay_ex_vat')
          OR (v_previous_tsfin_row->'pay_wtr_rate_pct_snapshot') IS DISTINCT FROM (v_new_row->'pay_wtr_rate_pct_snapshot')
          OR (v_previous_tsfin_row->'pay_vat_rate_pct_snapshot') IS DISTINCT FROM (v_new_row->'pay_vat_rate_pct_snapshot')
          OR (v_previous_tsfin_row->'pay_vat_amount_snapshot') IS DISTINCT FROM (v_new_row->'pay_vat_amount_snapshot')
          OR (v_previous_tsfin_row->'pay_total_inc_vat_snapshot') IS DISTINCT FROM (v_new_row->'pay_total_inc_vat_snapshot')
          OR (v_previous_tsfin_row->'invoice_breakdown_json') IS DISTINCT FROM (v_new_row->'invoice_breakdown_json')
          OR (v_previous_tsfin_row->'additional_units_json') IS DISTINCT FROM (v_new_row->'additional_units_json')
          OR (v_previous_tsfin_row->'actual_schedule_json') IS DISTINCT FROM (v_new_row->'actual_schedule_json')
          OR (v_previous_tsfin_row->'worked_start_iso') IS DISTINCT FROM (v_new_row->'worked_start_iso')
          OR (v_previous_tsfin_row->'worked_end_iso') IS DISTINCT FROM (v_new_row->'worked_end_iso')
          OR (v_previous_tsfin_row->'break_start_iso') IS DISTINCT FROM (v_new_row->'break_start_iso')
          OR (v_previous_tsfin_row->'break_end_iso') IS DISTINCT FROM (v_new_row->'break_end_iso')
          OR (v_previous_tsfin_row->'break_minutes') IS DISTINCT FROM (v_new_row->'break_minutes')
          OR (v_previous_tsfin_row->'pay_on_hold') IS DISTINCT FROM (v_new_row->'pay_on_hold')
          OR (v_previous_tsfin_row->'pay_on_hold_reason') IS DISTINCT FROM (v_new_row->'pay_on_hold_reason')
          OR (v_previous_tsfin_row->'has_rate_issue') IS DISTINCT FROM (v_new_row->'has_rate_issue')
          OR (v_previous_tsfin_row->'has_pay_channel_issue') IS DISTINCT FROM (v_new_row->'has_pay_channel_issue')
          OR (v_previous_tsfin_row->'processing_status') IS DISTINCT FROM (v_new_row->'processing_status')
          OR (v_previous_tsfin_row->'locked_by_invoice_id') IS DISTINCT FROM (v_new_row->'locked_by_invoice_id')
          OR (v_previous_tsfin_row->'unlocked_by_credit_note_id') IS DISTINCT FROM (v_new_row->'unlocked_by_credit_note_id')
          OR (v_previous_tsfin_row->'candidate_id') IS DISTINCT FROM (v_new_row->'candidate_id')
          OR (v_previous_tsfin_row->'client_id') IS DISTINCT FROM (v_new_row->'client_id');
      END IF;
    END IF;
  END IF;

  IF TG_OP = 'UPDATE' AND v_trigger_table = 'timesheets' THEN
    IF v_authorise_boundary_changed IS NOT TRUE
       AND v_archive_boundary_changed IS NOT TRUE
       AND v_explicit_banking_pay_action IS NOT TRUE THEN
      PERFORM public._temp_diag_log('TEMP_TRIGGER_DIRTY_STAGE', 'TEMP_BANKING_PAY_DIRTY', COALESCE(v_new_timesheet_id::text, v_old_timesheet_id::text), jsonb_build_object('function_name', 'pay_workbench_mark_candidate_dirty', 'stage', 'early_return_ordinary_timesheet_edit_save_no_dirty', 'trigger_table', v_trigger_table, 'trigger_op', TG_OP, 'material_live_source_changed', v_material_live_source_changed, 'draft_stale_signal_only', v_material_live_source_changed, 'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::numeric, 2)));
      RETURN NEW;
    END IF;
  ELSIF TG_OP = 'UPDATE' AND v_trigger_table = 'timesheets_financials' THEN
    IF v_authorise_boundary_changed IS NOT TRUE AND v_explicit_banking_pay_action IS NOT TRUE THEN
      PERFORM public._temp_diag_log('TEMP_TRIGGER_DIRTY_STAGE', 'TEMP_BANKING_PAY_DIRTY', COALESCE(v_new_timesheet_id::text, v_old_timesheet_id::text), jsonb_build_object('function_name', 'pay_workbench_mark_candidate_dirty', 'stage', 'early_return_ordinary_timesheet_financials_edit_save_no_dirty', 'trigger_table', v_trigger_table, 'trigger_op', TG_OP, 'material_live_source_changed', v_material_live_source_changed, 'draft_stale_signal_only', v_material_live_source_changed, 'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::numeric, 2)));
      RETURN NEW;
    END IF;
  END IF;

  IF TG_OP = 'INSERT'
     AND v_trigger_table = 'timesheets_financials'
     AND v_explicit_banking_pay_action IS NOT TRUE
     AND NULLIF(BTRIM(COALESCE(v_new_row->>'authorised_at_utc', '')), '') IS NULL THEN
    PERFORM public._temp_diag_log(
      'TEMP_TRIGGER_DIRTY_STAGE',
      'TEMP_BANKING_PAY_DIRTY',
      COALESCE(v_new_timesheet_id::text, v_old_timesheet_id::text),
      jsonb_build_object(
        'function_name', 'pay_workbench_mark_candidate_dirty',
        'stage', 'early_return_ordinary_timesheet_financials_insert_edit_save_no_dirty',
        'trigger_table', v_trigger_table,
        'trigger_op', TG_OP,
        'mutation_context', v_lifecycle_context,
        'authorised_at_utc_present', false,
        'explicit_banking_pay_action', false,
        'banking_pay_dirty_required', false,
        'source_build_required', false,
        'line_work_required', false,
        'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
        'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::numeric, 2)
      )
    );
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' AND v_trigger_table = 'timesheet_pay_state' THEN
    v_timesheet_pay_state_settlement_changed :=
      (v_old_row->'last_settled_snapshot_json') IS DISTINCT FROM (v_new_row->'last_settled_snapshot_json')
      OR NULLIF(BTRIM(COALESCE(v_old_row->>'last_settled_signature', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'last_settled_signature', '')), '')
      OR NULLIF(BTRIM(COALESCE(v_old_row->>'last_settled_pay_batch_id', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'last_settled_pay_batch_id', '')), '')
      OR NULLIF(BTRIM(COALESCE(v_old_row->>'last_settled_at_utc', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'last_settled_at_utc', '')), '');

    v_timesheet_pay_state_summary_changed :=
      NULLIF(BTRIM(COALESCE(v_old_row->>'summary_pay_status_code', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'summary_pay_status_code', '')), '')
      OR NULLIF(BTRIM(COALESCE(v_old_row->>'summary_pay_icon_code', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'summary_pay_icon_code', '')), '')
      OR NULLIF(BTRIM(COALESCE(v_old_row->>'summary_pay_paid_at_utc', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'summary_pay_paid_at_utc', '')), '')
      OR NULLIF(BTRIM(COALESCE(v_old_row->>'summary_net_delta_ex_vat', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'summary_net_delta_ex_vat', '')), '');

    IF v_timesheet_pay_state_settlement_changed IS NOT TRUE THEN
      v_timesheet_pay_state_bookkeeping_ignored := COALESCE(v_timesheet_pay_state_summary_changed, false);
      v_timesheet_pay_state_noop_ignored := COALESCE(v_timesheet_pay_state_summary_changed, false) IS NOT TRUE;

      PERFORM public._temp_diag_log(
        'TEMP_TRIGGER_DIRTY_STAGE',
        'TEMP_BANKING_PAY_DIRTY',
        COALESCE(v_new_timesheet_id::text, v_old_timesheet_id::text),
        jsonb_build_object(
          'function_name', 'pay_workbench_mark_candidate_dirty',
          'stage', CASE
            WHEN v_timesheet_pay_state_bookkeeping_ignored IS TRUE THEN 'early_return_timesheet_pay_state_bookkeeping_no_dirty'
            ELSE 'early_return_timesheet_pay_state_noop_no_dirty'
          END,
          'trigger_table', v_trigger_table,
          'trigger_op', TG_OP,
          'dirty_classification', CASE
            WHEN v_timesheet_pay_state_bookkeeping_ignored IS TRUE THEN 'TIMESHEET_PAY_STATE_BOOKKEEPING_IGNORED'
            ELSE 'TIMESHEET_PAY_STATE_NOOP_IGNORED'
          END,
          'timesheet_pay_state_settlement_changed', COALESCE(v_timesheet_pay_state_settlement_changed, false),
          'timesheet_pay_state_summary_changed', COALESCE(v_timesheet_pay_state_summary_changed, false),
          'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
          'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::numeric, 2)
        )
      );
      RETURN NEW;
    END IF;

    v_timesheet_pay_state_routing_reason := 'SOURCE_BUILD_REQUIRED_PAY_STATE_SETTLED_BASELINE_CHANGE';
  END IF;

  IF TG_OP = 'UPDATE' AND v_trigger_table = 'timesheets' THEN
    v_old_payment_eligible := NULLIF(BTRIM(COALESCE(v_old_row->>'authorised_at_server', '')), '') IS NOT NULL
      AND NULLIF(BTRIM(COALESCE(v_old_row->>'revoked_at', '')), '') IS NULL
      AND NULLIF(BTRIM(COALESCE(v_old_row->>'archived_at_utc', '')), '') IS NULL;
    v_new_payment_eligible := NULLIF(BTRIM(COALESCE(v_new_row->>'authorised_at_server', '')), '') IS NOT NULL
      AND NULLIF(BTRIM(COALESCE(v_new_row->>'revoked_at', '')), '') IS NULL
      AND NULLIF(BTRIM(COALESCE(v_new_row->>'archived_at_utc', '')), '') IS NULL;
    IF v_old_payment_eligible IS NOT TRUE
       AND v_new_payment_eligible IS NOT TRUE
       AND v_archive_boundary_changed IS NOT TRUE THEN
      PERFORM public._temp_diag_log('TEMP_TRIGGER_DIRTY_STAGE', 'TEMP_BANKING_PAY_DIRTY', COALESCE(v_new_timesheet_id::text, v_old_timesheet_id::text), jsonb_build_object('function_name', 'pay_workbench_mark_candidate_dirty', 'stage', 'early_return_ordinary_unauthorised_edit', 'trigger_table', v_trigger_table, 'trigger_op', TG_OP, 'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::numeric, 2)));
      RETURN NEW;
    END IF;
  ELSIF TG_OP = 'UPDATE' AND v_trigger_table = 'timesheets_financials' THEN
    v_old_payment_eligible := NULLIF(BTRIM(COALESCE(v_old_row->>'authorised_at_utc', '')), '') IS NOT NULL;
    v_new_payment_eligible := NULLIF(BTRIM(COALESCE(v_new_row->>'authorised_at_utc', '')), '') IS NOT NULL;
    IF v_old_payment_eligible IS NOT TRUE AND v_new_payment_eligible IS NOT TRUE THEN
      v_tsfin_payability_state_changed :=
        NULLIF(BTRIM(COALESCE(v_old_row->>'paid_at_utc', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'paid_at_utc', '')), '')
        OR NULLIF(BTRIM(COALESCE(v_old_row->>'paid_by_user_id', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'paid_by_user_id', '')), '')
        OR NULLIF(BTRIM(COALESCE(v_old_row->>'payment_reference', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'payment_reference', '')), '')
        OR NULLIF(BTRIM(COALESCE(v_old_row->>'pay_on_hold', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'pay_on_hold', '')), '')
        OR NULLIF(BTRIM(COALESCE(v_old_row->>'pay_on_hold_reason', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'pay_on_hold_reason', '')), '')
        OR NULLIF(BTRIM(COALESCE(v_old_row->>'pay_on_hold_since_utc', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'pay_on_hold_since_utc', '')), '')
        OR NULLIF(BTRIM(COALESCE(v_old_row->>'locked_by_invoice_id', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'locked_by_invoice_id', '')), '')
        OR NULLIF(BTRIM(COALESCE(v_old_row->>'locked_at_utc', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'locked_at_utc', '')), '')
        OR NULLIF(BTRIM(COALESCE(v_old_row->>'unlocked_by_credit_note_id', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'unlocked_by_credit_note_id', '')), '')
        OR NULLIF(BTRIM(COALESCE(v_old_row->>'remittance_last_sent_at_utc', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'remittance_last_sent_at_utc', '')), '')
        OR NULLIF(BTRIM(COALESCE(v_old_row->>'remittance_send_count', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'remittance_send_count', '')), '');
      IF v_tsfin_payability_state_changed IS NOT TRUE THEN
        PERFORM public._temp_diag_log('TEMP_TRIGGER_DIRTY_STAGE', 'TEMP_BANKING_PAY_DIRTY', COALESCE(v_new_timesheet_id::text, v_old_timesheet_id::text), jsonb_build_object('function_name', 'pay_workbench_mark_candidate_dirty', 'stage', 'early_return_ordinary_unauthorised_edit', 'trigger_table', v_trigger_table, 'trigger_op', TG_OP, 'payability_state_changed', false, 'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::numeric, 2)));
        RETURN NEW;
      END IF;
    END IF;
  END IF;

  IF TG_OP = 'UPDATE'
     AND v_trigger_table IN ('timesheets', 'timesheets_financials')
     AND v_authorise_boundary_changed IS TRUE THEN
    IF v_new_payment_eligible IS TRUE AND v_old_payment_eligible IS NOT TRUE THEN
      v_authorise_boundary_is_authorise := true;
    ELSIF v_old_payment_eligible IS TRUE AND v_new_payment_eligible IS NOT TRUE THEN
      v_authorise_boundary_is_unauthorise := true;
    ELSIF lower(BTRIM(COALESCE(v_lifecycle_context, ''))) IN ('timesheet_authorise', 'authorise_timesheet') THEN
      v_authorise_boundary_is_authorise := true;
    ELSIF lower(BTRIM(COALESCE(v_lifecycle_context, ''))) IN ('timesheet_unauthorise', 'unauthorise_timesheet') THEN
      v_authorise_boundary_is_unauthorise := true;
    END IF;
  END IF;

  IF TG_OP = 'UPDATE'
     AND v_trigger_table = 'timesheets'
     AND v_archive_boundary_changed IS TRUE THEN
    IF NULLIF(BTRIM(COALESCE(v_old_row->>'archived_at_utc', '')), '') IS NULL
       AND NULLIF(BTRIM(COALESCE(v_new_row->>'archived_at_utc', '')), '') IS NOT NULL THEN
      v_archive_boundary_is_archive := true;
    ELSIF NULLIF(BTRIM(COALESCE(v_old_row->>'archived_at_utc', '')), '') IS NOT NULL
       AND NULLIF(BTRIM(COALESCE(v_new_row->>'archived_at_utc', '')), '') IS NULL THEN
      v_archive_boundary_is_unarchive := true;
    ELSIF lower(BTRIM(COALESCE(v_lifecycle_context, ''))) IN ('timesheet_archive', 'archive_timesheet') THEN
      v_archive_boundary_is_archive := true;
    ELSIF lower(BTRIM(COALESCE(v_lifecycle_context, ''))) IN ('timesheet_unarchive', 'unarchive_timesheet') THEN
      v_archive_boundary_is_unarchive := true;
    END IF;
  END IF;

  v_effective_lifecycle_context := CASE
    WHEN v_archive_boundary_is_archive IS TRUE THEN 'timesheet_archive'
    WHEN v_archive_boundary_is_unarchive IS TRUE THEN 'timesheet_unarchive'
    WHEN v_authorise_boundary_is_unauthorise IS TRUE THEN 'timesheet_unauthorise'
    WHEN v_authorise_boundary_is_authorise IS TRUE THEN 'timesheet_authorise'
    WHEN lower(BTRIM(COALESCE(v_lifecycle_context, ''))) IN ('timesheet_authorise', 'authorise_timesheet') THEN 'timesheet_authorise'
    WHEN lower(BTRIM(COALESCE(v_lifecycle_context, ''))) IN ('timesheet_unauthorise', 'unauthorise_timesheet') THEN 'timesheet_unauthorise'
    WHEN lower(BTRIM(COALESCE(v_lifecycle_context, ''))) IN ('timesheet_archive', 'archive_timesheet') THEN 'timesheet_archive'
    WHEN lower(BTRIM(COALESCE(v_lifecycle_context, ''))) IN ('timesheet_unarchive', 'unarchive_timesheet') THEN 'timesheet_unarchive'
    ELSE v_lifecycle_context
  END;

  v_banking_pay_dirty_required := v_authorise_boundary_changed IS TRUE
    OR v_archive_boundary_changed IS TRUE
    OR v_explicit_banking_pay_action IS TRUE
    OR (v_trigger_table = 'timesheet_pay_state' AND v_timesheet_pay_state_settlement_changed IS TRUE);
  v_ordinary_timesheet_edit_save_no_dirty := TG_OP = 'UPDATE'
    AND v_trigger_table IN ('timesheets', 'timesheets_financials')
    AND v_banking_pay_dirty_required IS NOT TRUE;

  IF v_old_timesheet_id IS NOT NULL OR v_new_timesheet_id IS NOT NULL THEN
    v_refresh_scope_kind := 'TARGETED_TIMESHEETS';
    SELECT COALESCE(array_agg(DISTINCT timesheet_ids.timesheet_id ORDER BY timesheet_ids.timesheet_id), ARRAY[]::uuid[])
    INTO v_targeted_timesheet_ids
    FROM (
      SELECT v_old_timesheet_id AS timesheet_id
      UNION ALL
      SELECT v_new_timesheet_id AS timesheet_id
    ) AS timesheet_ids
    WHERE timesheet_ids.timesheet_id IS NOT NULL;
  END IF;

  IF v_trigger_table = 'candidates' THEN
    IF NULLIF(BTRIM(COALESCE(v_old_row->>'id', '')), '') ~* v_uuid_re THEN
      v_candidate_ids := array_append(v_candidate_ids, NULLIF(BTRIM(COALESCE(v_old_row->>'id', '')), '')::uuid);
    END IF;
    IF NULLIF(BTRIM(COALESCE(v_new_row->>'id', '')), '') ~* v_uuid_re THEN
      v_candidate_ids := array_append(v_candidate_ids, NULLIF(BTRIM(COALESCE(v_new_row->>'id', '')), '')::uuid);
    END IF;

    IF TG_OP = 'UPDATE' THEN
      v_route_source_method := UPPER(BTRIM(COALESCE(v_old_row->>'pay_method', '')));
      v_route_target_method := UPPER(BTRIM(COALESCE(v_new_row->>'pay_method', '')));
      v_candidate_route_change := v_route_source_method IN ('PAYE', 'UMBRELLA')
        AND v_route_target_method IN ('PAYE', 'UMBRELLA')
        AND v_route_source_method <> v_route_target_method;

      IF v_candidate_route_change IS TRUE THEN
        IF v_route_operation_id IS NULL OR v_route_operation_id !~* v_uuid_re THEN
          RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_OPERATION_CONTEXT_REQUIRED'
            USING ERRCODE = '22023';
        END IF;
        IF v_route_actor_user_id IS NULL OR v_route_actor_user_id !~* v_uuid_re THEN
          RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_ACTOR_CONTEXT_REQUIRED'
            USING ERRCODE = '22023';
        END IF;

        v_route_scope_result := public.candidate_pay_method_change_refresh_scope_v1(
          NULLIF(BTRIM(COALESCE(v_new_row->>'id', '')), '')::uuid,
          v_route_source_method,
          v_route_target_method
        );

        v_route_exact_scope := LOWER(BTRIM(COALESCE(v_route_scope_result->>'exact_scope', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
        v_route_coverage_complete := LOWER(BTRIM(COALESCE(v_route_scope_result->>'coverage_complete', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');

        IF COALESCE(v_route_scope_result->>'ok', 'false') <> 'true'
           OR v_route_exact_scope IS NOT TRUE
           OR v_route_coverage_complete IS NOT TRUE
           OR jsonb_typeof(v_route_scope_result->'targeted_timesheet_ids') IS DISTINCT FROM 'array' THEN
          RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_EXACT_SCOPE_UNAVAILABLE'
            USING ERRCODE = 'P0001', DETAIL = COALESCE(v_route_scope_result, '{}'::jsonb)::text;
        END IF;

        IF EXISTS (
          SELECT 1
          FROM jsonb_array_elements_text(v_route_scope_result->'targeted_timesheet_ids') AS raw_target(value)
          WHERE raw_target.value !~* v_uuid_re
        ) THEN
          RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_TARGET_SCOPE_INVALID'
            USING ERRCODE = 'P0001';
        END IF;

        SELECT COALESCE(array_agg(DISTINCT target_value::uuid ORDER BY target_value::uuid), ARRAY[]::uuid[])
        INTO v_targeted_timesheet_ids
        FROM jsonb_array_elements_text(
          CASE
            WHEN jsonb_typeof(v_route_scope_result->'targeted_timesheet_ids') = 'array'
              THEN v_route_scope_result->'targeted_timesheet_ids'
            ELSE '[]'::jsonb
          END
        ) AS target_values(target_value)
        WHERE target_value ~* v_uuid_re;

        v_refresh_scope_kind := 'TARGETED_TIMESHEETS';
        v_route_targeted_scope_is_empty := COALESCE(array_length(v_targeted_timesheet_ids, 1), 0) = 0;
        v_route_authoritative_sessions := COALESCE(v_route_scope_result->'authoritative_sessions', '[]'::jsonb);
        v_route_replaced_source_session_ids := COALESCE(v_route_scope_result->'replaced_source_session_ids', '[]'::jsonb);
        v_route_target_details := COALESCE(v_route_scope_result->'target_details', '[]'::jsonb);
        v_route_authorised_timesheet_ids := COALESCE(v_route_scope_result->'authorised_timesheet_ids', '[]'::jsonb);
        v_route_active_advance_timesheet_ids := COALESCE(v_route_scope_result->'active_advance_timesheet_ids', '[]'::jsonb);
        v_route_retained_finance_timesheet_ids := COALESCE(v_route_scope_result->'retained_finance_timesheet_ids', '[]'::jsonb);
        v_route_authorised_timesheet_count := COALESCE(
          CASE WHEN COALESCE(v_route_scope_result->>'authorised_timesheet_count', '') ~ '^[0-9]{1,10}$'
            THEN (v_route_scope_result->>'authorised_timesheet_count')::integer END,
          0
        );
        v_route_active_advance_timesheet_count := COALESCE(
          CASE WHEN COALESCE(v_route_scope_result->>'active_advance_timesheet_count', '') ~ '^[0-9]{1,10}$'
            THEN (v_route_scope_result->>'active_advance_timesheet_count')::integer END,
          0
        );
        v_route_retained_finance_timesheet_count := COALESCE(
          CASE WHEN COALESCE(v_route_scope_result->>'retained_finance_timesheet_count', '') ~ '^[0-9]{1,10}$'
            THEN (v_route_scope_result->>'retained_finance_timesheet_count')::integer END,
          0
        );
        v_route_source_target_mismatch_count := COALESCE(
          CASE WHEN COALESCE(v_route_scope_result->>'source_target_mismatch_count', '') ~ '^[0-9]{1,10}$'
            THEN (v_route_scope_result->>'source_target_mismatch_count')::integer END,
          0
        );

        IF COALESCE(v_route_scope_result->>'durable_job_id', '') !~* v_uuid_re
           OR LOWER(BTRIM(COALESCE(v_route_scope_result->>'durable_scope_persisted', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on') THEN
          RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_DURABLE_QUEUE_MISSING'
            USING ERRCODE = 'P0001', DETAIL = COALESCE(v_route_scope_result, '{}'::jsonb)::text;
        END IF;

        v_route_job_id := (v_route_scope_result->>'durable_job_id')::uuid;
        v_route_job_status := NULLIF(BTRIM(COALESCE(v_route_scope_result->>'durable_job_status', '')), '');
        v_route_dedupe_key := NULLIF(BTRIM(COALESCE(v_route_scope_result->>'durable_job_dedupe_key', '')), '');
        v_route_job_source_change_seq := COALESCE(
          CASE
            WHEN COALESCE(v_route_scope_result->>'source_change_seq', '') ~ '^[0-9]{1,18}$'
              THEN (v_route_scope_result->>'source_change_seq')::bigint
            ELSE 0
          END,
          0
        );

        IF v_route_job_status NOT IN ('QUEUED', 'RUNNING', 'SUCCEEDED')
           OR v_route_dedupe_key IS NULL
           OR v_route_job_source_change_seq <= 0 THEN
          RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_DURABLE_QUEUE_INVALID'
            USING ERRCODE = 'P0001', DETAIL = COALESCE(v_route_scope_result, '{}'::jsonb)::text;
        END IF;

        v_explicit_banking_pay_action := true;
        v_banking_pay_dirty_required := true;
        v_ordinary_timesheet_edit_save_no_dirty := false;
        v_effective_lifecycle_context := 'candidate_pay_method_change';
      END IF;
    END IF;
  END IF;

  IF v_trigger_table IN ('bank_name_checks', 'bank_payee_map') THEN
    v_entity_kind_old := UPPER(BTRIM(COALESCE(v_old_row->>'entity_kind', '')));
    v_entity_kind_new := UPPER(BTRIM(COALESCE(v_new_row->>'entity_kind', '')));
    IF v_entity_kind_old = 'CANDIDATE' AND NULLIF(BTRIM(COALESCE(v_old_row->>'entity_id', '')), '') ~* v_uuid_re THEN
      v_candidate_ids := array_append(v_candidate_ids, NULLIF(BTRIM(COALESCE(v_old_row->>'entity_id', '')), '')::uuid);
    ELSIF v_entity_kind_old IN ('UMBRELLA', 'UMBRELLA_COMPANY') AND NULLIF(BTRIM(COALESCE(v_old_row->>'entity_id', '')), '') ~* v_uuid_re THEN
      v_umbrella_id_old := NULLIF(BTRIM(COALESCE(v_old_row->>'entity_id', '')), '')::uuid;
    END IF;
    IF v_entity_kind_new = 'CANDIDATE' AND NULLIF(BTRIM(COALESCE(v_new_row->>'entity_id', '')), '') ~* v_uuid_re THEN
      v_candidate_ids := array_append(v_candidate_ids, NULLIF(BTRIM(COALESCE(v_new_row->>'entity_id', '')), '')::uuid);
    ELSIF v_entity_kind_new IN ('UMBRELLA', 'UMBRELLA_COMPANY') AND NULLIF(BTRIM(COALESCE(v_new_row->>'entity_id', '')), '') ~* v_uuid_re THEN
      v_umbrella_id_new := NULLIF(BTRIM(COALESCE(v_new_row->>'entity_id', '')), '')::uuid;
    END IF;
  END IF;

  IF v_trigger_table = 'umbrellas' THEN
    IF NULLIF(BTRIM(COALESCE(v_old_row->>'id', '')), '') ~* v_uuid_re THEN
      v_umbrella_id_old := NULLIF(BTRIM(COALESCE(v_old_row->>'id', '')), '')::uuid;
    END IF;
    IF NULLIF(BTRIM(COALESCE(v_new_row->>'id', '')), '') ~* v_uuid_re THEN
      v_umbrella_id_new := NULLIF(BTRIM(COALESCE(v_new_row->>'id', '')), '')::uuid;
    END IF;
  END IF;

  IF v_umbrella_id_old IS NOT NULL OR v_umbrella_id_new IS NOT NULL THEN
    FOR v_scope_id IN
      SELECT DISTINCT umbrella_scope.umbrella_id::text
      FROM (
        SELECT v_umbrella_id_old AS umbrella_id
        UNION ALL
        SELECT v_umbrella_id_new AS umbrella_id
      ) AS umbrella_scope
      WHERE umbrella_scope.umbrella_id IS NOT NULL
    LOOP
      v_reason := 'DIRTY_TRIGGER:' || upper(v_trigger_table) || ':' || TG_OP;
      v_payload_json := jsonb_build_object(
        'trigger_table', v_trigger_table,
        'trigger_op', TG_OP,
        'trigger_operation', TG_OP,
        'scope_kind', 'UMBRELLA',
        'scope_id', v_scope_id,
        'reason', v_reason,
        'fallback_reason', 'UMBRELLA_BANK_DETAIL_DIRTY',
        'refresh_scope_kind', 'CANDIDATE_FULL_LIVE',
        'source_build_required', true,
        'line_work_required', true,
        'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
      );
      PERFORM public.pay_workbench_dirty_event_enqueue(
        p_job_type => 'CONTRACT_CLIENT_DIRTY_FANOUT',
        p_scope_kind => 'UMBRELLA',
        p_scope_id => v_scope_id,
        p_candidate_id => NULL::uuid,
        p_targeted_timesheet_ids => ARRAY[]::uuid[],
        p_linked_timesheet_ids => ARRAY[]::uuid[],
        p_payload_json => v_payload_json,
        p_reason => v_reason,
        p_priority => -1000,
        p_run_at_utc => v_now
      );
    END LOOP;
  END IF;

  SELECT COALESCE(array_agg(DISTINCT candidate_candidates.candidate_id ORDER BY candidate_candidates.candidate_id), ARRAY[]::uuid[])
  INTO v_candidate_ids
  FROM (
    SELECT unnest(COALESCE(v_candidate_ids, ARRAY[]::uuid[])) AS candidate_id
    UNION ALL
    SELECT contract_old.candidate_id FROM public.contracts AS contract_old WHERE contract_old.id = v_old_contract_id
    UNION ALL
    SELECT contract_new.candidate_id FROM public.contracts AS contract_new WHERE contract_new.id = v_new_contract_id
    UNION ALL
    SELECT financial_old.candidate_id FROM public.timesheets_financials AS financial_old WHERE financial_old.timesheet_id = v_old_timesheet_id AND financial_old.is_current = true
    UNION ALL
    SELECT financial_new.candidate_id FROM public.timesheets_financials AS financial_new WHERE financial_new.timesheet_id = v_new_timesheet_id AND financial_new.is_current = true
    UNION ALL
    SELECT timesheet_contract_old.candidate_id
    FROM public.timesheets AS timesheet_old
    JOIN public.contracts AS timesheet_contract_old ON timesheet_contract_old.id = timesheet_old.contract_id
    WHERE timesheet_old.timesheet_id = v_old_timesheet_id
    UNION ALL
    SELECT timesheet_contract_new.candidate_id
    FROM public.timesheets AS timesheet_new
    JOIN public.contracts AS timesheet_contract_new ON timesheet_contract_new.id = timesheet_new.contract_id
    WHERE timesheet_new.timesheet_id = v_new_timesheet_id
  ) AS candidate_candidates
  WHERE candidate_candidates.candidate_id IS NOT NULL;

  IF COALESCE(array_length(v_candidate_ids, 1), 0) = 0 THEN
    PERFORM public._temp_diag_log('TEMP_TRIGGER_DIRTY_STAGE', 'TEMP_BANKING_PAY_DIRTY', COALESCE(v_new_timesheet_id::text, v_old_timesheet_id::text), jsonb_build_object('function_name', 'pay_workbench_mark_candidate_dirty', 'stage', 'return_no_candidate', 'trigger_table', v_trigger_table, 'trigger_op', TG_OP, 'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::numeric, 2)));
    IF TG_OP = 'DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
  END IF;

  v_reason := CASE
    WHEN v_candidate_route_change IS TRUE
      THEN 'CANDIDATE_PAY_METHOD_CHANGE:' || v_route_source_method || '_TO_' || v_route_target_method
    ELSE 'DIRTY_TRIGGER:' || upper(v_trigger_table) || ':' || TG_OP
  END;

  FOREACH v_candidate_id IN ARRAY v_candidate_ids
  LOOP

    IF TG_OP = 'INSERT' AND v_trigger_table = 'timesheets_financials' THEN
      v_tsfin_insert_not_coalesced_reason := NULL::text;
      v_tsfin_insert_coalesced_job_id := NULL::uuid;
      v_tsfin_insert_coalesced_projection_run_id := NULL::uuid;
      v_tsfin_insert_coalesced_session_id := NULL::uuid;
      v_tsfin_insert_coalesced_source_change_seq := NULL::bigint;
      v_tsfin_insert_authorise_like := v_new_timesheet_id IS NOT NULL
        AND COALESCE(array_length(v_targeted_timesheet_ids, 1), 0) = 1
        AND NULLIF(BTRIM(COALESCE(v_new_row->>'authorised_at_utc', '')), '') IS NOT NULL
        AND COALESCE(LOWER(BTRIM(COALESCE(v_new_row->>'is_current', 'true'))), 'true') NOT IN ('false', 'f', '0', 'no', 'n', 'off');

      IF v_tsfin_insert_authorise_like IS TRUE THEN
        SELECT
          existing_delta.id,
          CASE
            WHEN COALESCE(existing_delta.payload_json->>'projection_run_id', '') ~* v_uuid_re
              THEN (existing_delta.payload_json->>'projection_run_id')::uuid
            ELSE NULL::uuid
          END,
          existing_delta.session_id,
          CASE
            WHEN COALESCE(existing_delta.payload_json->>'source_change_seq', '') ~ '^[0-9]{1,18}$'
              THEN (existing_delta.payload_json->>'source_change_seq')::bigint
            WHEN COALESCE(existing_delta.payload_json->>'source_change_sequence', '') ~ '^[0-9]{1,18}$'
              THEN (existing_delta.payload_json->>'source_change_sequence')::bigint
            ELSE NULL::bigint
          END
        INTO
          v_tsfin_insert_coalesced_job_id,
          v_tsfin_insert_coalesced_projection_run_id,
          v_tsfin_insert_coalesced_session_id,
          v_tsfin_insert_coalesced_source_change_seq
        FROM public.banking_pay_workbench_jobs AS existing_delta
        JOIN public.banking_pay_workbench_sessions AS existing_session
          ON existing_session.id = existing_delta.session_id
         AND UPPER(BTRIM(COALESCE(existing_session.status, ''))) = 'OPEN'
         AND existing_session.discarded_at_utc IS NULL
        WHERE existing_delta.candidate_id = v_candidate_id
          AND existing_delta.created_at_utc >= (v_now - INTERVAL '10 minutes')
          AND UPPER(BTRIM(COALESCE(existing_delta.status, ''))) IN ('QUEUED', 'RUNNING', 'SUCCEEDED')
          AND UPPER(BTRIM(COALESCE(existing_delta.job_type, ''))) IN ('WORKBENCH_CANDIDATE_DELTA_REFRESH', 'CANDIDATE_DELTA_REFRESH', 'DELTA_REFRESH')
          AND UPPER(BTRIM(COALESCE(existing_delta.payload_json->>'projection_class', ''))) = 'NORMAL_TIMESHEET'
          AND UPPER(BTRIM(COALESCE(existing_delta.payload_json->>'trigger_table', ''))) = 'TIMESHEETS'
          AND UPPER(BTRIM(COALESCE(existing_delta.payload_json->>'trigger_operation', existing_delta.payload_json->>'trigger_op', ''))) = 'UPDATE'
          AND UPPER(BTRIM(COALESCE(existing_delta.payload_json->>'mutation_context', existing_delta.payload_json->>'lifecycle_mutation_context', ''))) IN ('TIMESHEET_AUTHORISE', 'AUTHORISE_TIMESHEET')
          AND LOWER(BTRIM(COALESCE(existing_delta.payload_json->>'authorise_boundary_changed', existing_delta.payload_json#>>'{complexity_flags,authorise_boundary_changed}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
          AND EXISTS (
            SELECT 1
            FROM jsonb_array_elements_text(
              CASE
                WHEN jsonb_typeof(existing_delta.payload_json->'targeted_timesheet_ids') = 'array'
                  THEN existing_delta.payload_json->'targeted_timesheet_ids'
                ELSE '[]'::jsonb
              END
            ) AS targeted_timesheet_id(value)
            WHERE targeted_timesheet_id.value ~* v_uuid_re
              AND targeted_timesheet_id.value::uuid = v_new_timesheet_id
          )
        ORDER BY existing_delta.created_at_utc DESC, existing_delta.id DESC
        LIMIT 1;

        IF v_tsfin_insert_coalesced_job_id IS NOT NULL THEN
          PERFORM public._temp_diag_log(
            'TEMP_TRIGGER_DIRTY_STAGE',
            'TEMP_BANKING_PAY_DIRTY',
            v_new_timesheet_id::text,
            jsonb_build_object(
              'function_name', 'pay_workbench_mark_candidate_dirty',
              'stage', 'early_return_timesheet_financials_insert_authorise_coalesced_no_dirty',
              'trigger_table', v_trigger_table,
              'trigger_op', TG_OP,
              'coalesced_with_timesheets_authorise_delta', true,
              'coalesced_source_change_seq', v_tsfin_insert_coalesced_source_change_seq,
              'coalesced_job_id', v_tsfin_insert_coalesced_job_id::text,
              'coalesced_projection_run_id', CASE WHEN v_tsfin_insert_coalesced_projection_run_id IS NULL THEN NULL ELSE v_tsfin_insert_coalesced_projection_run_id::text END,
              'coalesced_session_id', CASE WHEN v_tsfin_insert_coalesced_session_id IS NULL THEN NULL ELSE v_tsfin_insert_coalesced_session_id::text END,
              'coalesced_candidate_id', v_candidate_id::text,
              'coalesced_timesheet_id', v_new_timesheet_id::text,
              'banking_pay_dirty_required', false,
              'source_build_required', false,
              'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
              'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::numeric, 2)
            )
          );
          CONTINUE;
        END IF;

        v_tsfin_insert_not_coalesced_reason := 'NO_PRIOR_AUTHORISE_DELTA';
      ELSE
        v_tsfin_insert_not_coalesced_reason := CASE
          WHEN v_new_timesheet_id IS NULL THEN 'NO_TARGET_TIMESHEET'
          WHEN COALESCE(array_length(v_targeted_timesheet_ids, 1), 0) <> 1 THEN 'MULTI_OR_EMPTY_TARGET_SCOPE'
          WHEN NULLIF(BTRIM(COALESCE(v_new_row->>'authorised_at_utc', '')), '') IS NULL THEN 'UNAUTHORISED_INSERT'
          WHEN COALESCE(LOWER(BTRIM(COALESCE(v_new_row->>'is_current', 'true'))), 'true') IN ('false', 'f', '0', 'no', 'n', 'off') THEN 'NON_CURRENT_INSERT'
          ELSE 'UNKNOWN_SAFE_STATE'
        END;
      END IF;
    END IF;

    IF v_effective_lifecycle_context IN ('timesheet_authorise', 'timesheet_unauthorise', 'timesheet_archive', 'timesheet_unarchive') THEN
      v_lifecycle_dedupe_token := '|LIFECYCLE_DIRTY:' || v_effective_lifecycle_context || ':' || v_candidate_id::text || ':' || COALESCE(array_to_string(v_targeted_timesheet_ids, ','), '') || '|';
      v_lifecycle_dedupe_keys := COALESCE(current_setting('cloudtms.pay_dirty_dedupe_keys', true), '');
      IF POSITION(v_lifecycle_dedupe_token IN v_lifecycle_dedupe_keys) > 0 THEN
        PERFORM public._temp_diag_log('TEMP_TRIGGER_DIRTY_STAGE', 'TEMP_BANKING_PAY_DIRTY', CASE WHEN COALESCE(array_length(v_targeted_timesheet_ids, 1), 0) > 0 THEN v_targeted_timesheet_ids[1]::text ELSE NULL::text END, jsonb_build_object('function_name', 'pay_workbench_mark_candidate_dirty', 'stage', 'dedupe_skip_lifecycle_duplicate', 'trigger_table', v_trigger_table, 'trigger_op', TG_OP, 'mutation_context', v_lifecycle_context, 'candidate_id', v_candidate_id::text, 'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::numeric, 2)));
        CONTINUE;
      END IF;
      PERFORM set_config('cloudtms.pay_dirty_dedupe_keys', LEFT(v_lifecycle_dedupe_keys || v_lifecycle_dedupe_token, 60000), true);
    END IF;

    v_payload_json := jsonb_build_object(
      'trigger_table', v_trigger_table,
      'trigger_op', TG_OP,
      'trigger_operation', TG_OP,
      'mutation_context', v_effective_lifecycle_context,
      'lifecycle_mutation_context', v_effective_lifecycle_context,
      'authorise_boundary_changed', COALESCE(v_authorise_boundary_is_authorise, false),
      'unauthorise_boundary_changed', COALESCE(v_authorise_boundary_is_unauthorise, false),
      'archive_boundary_changed', COALESCE(v_archive_boundary_is_archive, false),
      'unarchive_boundary_changed', COALESCE(v_archive_boundary_is_unarchive, false),
      'explicit_banking_pay_action', COALESCE(v_explicit_banking_pay_action, false) OR COALESCE(v_authorise_boundary_changed, false) OR COALESCE(v_archive_boundary_changed, false),
      'banking_pay_dirty_required', COALESCE(v_banking_pay_dirty_required, false),
      'ordinary_timesheet_edit_save_no_dirty', COALESCE(v_ordinary_timesheet_edit_save_no_dirty, false),
      'timesheets_financials_insert_not_coalesced_reason', CASE WHEN v_trigger_table = 'timesheets_financials' AND TG_OP = 'INSERT' THEN v_tsfin_insert_not_coalesced_reason ELSE NULL END,
      'timesheets_financials_insert_coalesced_authorise_delta', false,
      'scope_kind', 'CANDIDATE',
      'scope_id', v_candidate_id::text,
      'candidate_id', v_candidate_id::text,
      'reason', v_reason,
      'dirty_reason', v_reason,
      'timesheet_pay_state_settlement_changed', CASE WHEN v_trigger_table = 'timesheet_pay_state' THEN COALESCE(v_timesheet_pay_state_settlement_changed, false) ELSE NULL END,
      'timesheet_pay_state_summary_changed', CASE WHEN v_trigger_table = 'timesheet_pay_state' THEN COALESCE(v_timesheet_pay_state_summary_changed, false) ELSE NULL END,
      'timesheet_pay_state_bookkeeping_ignored', CASE WHEN v_trigger_table = 'timesheet_pay_state' THEN COALESCE(v_timesheet_pay_state_bookkeeping_ignored, false) ELSE NULL END,
      'timesheet_pay_state_noop_ignored', CASE WHEN v_trigger_table = 'timesheet_pay_state' THEN COALESCE(v_timesheet_pay_state_noop_ignored, false) ELSE NULL END,
      'pay_state_dirty_routing_reason', CASE WHEN v_trigger_table = 'timesheet_pay_state' THEN v_timesheet_pay_state_routing_reason ELSE NULL END,
      'source_build_required_reason', CASE WHEN v_trigger_table = 'timesheet_pay_state' THEN v_timesheet_pay_state_routing_reason ELSE NULL END,
      'refresh_scope_kind', v_refresh_scope_kind,
      'targeted_timesheet_ids', COALESCE(to_jsonb(v_targeted_timesheet_ids), '[]'::jsonb),
      'linked_timesheet_ids', '[]'::jsonb,
      'linked_scope_recompute_required', true,
      'source_build_required', true,
      'line_work_required', true,
      'line_work_only', false,
      'line_work_action', 'SOURCE_BUILD',
      'force_legacy', false,
      'force_broad_legacy', false,
      'projection_class', CASE
        WHEN v_candidate_route_change IS TRUE THEN 'PAYE_UMBRELLA_SWITCH'
        WHEN v_trigger_table IN ('timesheets', 'timesheets_financials')
             AND (v_authorise_boundary_changed IS TRUE OR v_archive_boundary_changed IS TRUE) THEN 'TIMESHEET_LIFECYCLE'
        ELSE 'DIRTY_TRIGGER'
      END,
      'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
    );

    IF v_candidate_route_change IS TRUE THEN
      v_payload_json := v_payload_json
        || jsonb_strip_nulls(
          jsonb_build_object(
            'candidate_pay_method_change', true,
            'candidate_payment_status_changed', true,
            'pay_method_changed', true,
            'prospective_only', true,
            'old_pay_method', v_route_source_method,
            'new_pay_method', v_route_target_method,
            'route_change_operation_id', v_route_operation_id,
            'route_change_actor_user_id', v_route_actor_user_id,
            'actor_user_id', v_route_actor_user_id,
            'route_change_reason', COALESCE(v_route_reason, 'PAY_METHOD_CHANGE'),
            'route_change_source_method', v_route_source_method,
            'route_change_target_method', v_route_target_method,
            'authorised_timesheet_ids', v_route_authorised_timesheet_ids,
            'authorised_timesheet_count', v_route_authorised_timesheet_count,
            'active_advance_timesheet_ids', v_route_active_advance_timesheet_ids,
            'active_advance_timesheet_count', v_route_active_advance_timesheet_count,
            'retained_finance_timesheet_ids', v_route_retained_finance_timesheet_ids,
            'retained_finance_timesheet_count', v_route_retained_finance_timesheet_count,
            'source_target_mismatch_count', v_route_source_target_mismatch_count,
            'authoritative_sessions', v_route_authoritative_sessions,
            'replaced_source_session_ids', v_route_replaced_source_session_ids,
            'target_details', v_route_target_details,
            'coverage_basis', COALESCE(v_route_scope_result->>'coverage_basis', 'CANONICAL_TIMESHEETS_WITH_RETAINED_FINANCE_AUTHORITY'),
            'coverage_complete', v_route_coverage_complete,
            'exact_target_scope', v_route_exact_scope,
            'targeted_scope_is_empty', v_route_targeted_scope_is_empty
          )
          || jsonb_build_object(
            'contracts_changed', 0,
            'contract_weeks_changed', 0,
            'timesheets_changed', 0,
            'rates_changed', 0,
            'tsfin_repricing_rows', 0,
            'source_records_mutated', false,
            'economic_truth_mutation_allowed', false,
            'refresh_completion_requires_terminal_exact_scope', true,
            'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
            'policy_x_dirtying_only', true
          )
        );
    END IF;

    IF v_candidate_route_change IS TRUE THEN
      v_enqueue_result := jsonb_build_object(
        'ok', true,
        'job_id', v_route_job_id::text,
        'job_type', 'WORKBENCH_CANDIDATE_DIRTY_APPLY',
        'status', v_route_job_status,
        'dedupe_key', v_route_dedupe_key,
        'scope_kind', 'CANDIDATE',
        'scope_id', v_candidate_id::text,
        'candidate_id', v_candidate_id::text,
        'targeted_timesheet_count', COALESCE(array_length(v_targeted_timesheet_ids, 1), 0),
        'latest_source_change_seq', v_route_job_source_change_seq,
        'exact_target_scope', true,
        'targeted_scope_is_empty', v_route_targeted_scope_is_empty,
        'durable_scope_persisted', true
      );
    ELSE
      SELECT public.pay_workbench_dirty_event_enqueue(
        p_job_type => 'WORKBENCH_CANDIDATE_DIRTY_APPLY',
        p_scope_kind => 'CANDIDATE',
        p_scope_id => v_candidate_id::text,
        p_candidate_id => v_candidate_id,
        p_targeted_timesheet_ids => v_targeted_timesheet_ids,
        p_linked_timesheet_ids => ARRAY[]::uuid[],
        p_payload_json => v_payload_json,
        p_reason => v_reason,
        p_priority => -1000,
        p_run_at_utc => v_now
      )
      INTO v_enqueue_result;
    END IF;

    v_jobs_queued := v_jobs_queued + 1;
  END LOOP;

  PERFORM public._temp_diag_log(
    'TEMP_TRIGGER_DIRTY_STAGE',
    'TEMP_BANKING_PAY_DIRTY',
    CASE WHEN COALESCE(array_length(v_targeted_timesheet_ids, 1), 0) > 0 THEN v_targeted_timesheet_ids[1]::text ELSE NULL::text END,
    jsonb_build_object(
      'function_name', 'pay_workbench_mark_candidate_dirty',
      'stage', CASE
        WHEN v_jobs_queued = 0 AND TG_OP = 'INSERT' AND v_trigger_table = 'timesheets_financials' THEN 'return_no_dirty_after_timesheet_financials_insert_coalesced'
        ELSE 'return_enqueued_dirty_priority'
      END,
      'trigger_table', v_trigger_table,
      'trigger_op', TG_OP,
      'mutation_context', v_lifecycle_context,
      'candidate_count', COALESCE(array_length(v_candidate_ids, 1), 0),
      'targeted_timesheet_count', COALESCE(array_length(v_targeted_timesheet_ids, 1), 0),
      'jobs_queued', v_jobs_queued,
      'queue_class', 'DIRTY_TRIGGER_PRIORITY',
      'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::numeric, 2)
    )
  );

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  ELSE
    RETURN NEW;
  END IF;
END;
$function$;

create or replace function private.bpay_next_workbench_candidate_name_trigger_v1()
returns trigger language plpgsql security definer set search_path=pg_catalog,private
as $function$
declare v_name text;v_old_name text;v_bank_changed boolean;
begin
  if not exists(select 1 from private.bpay_next_module_control where id=1 and active_owner='NEXT') then return new;end if;
  v_name:=coalesce(nullif(btrim(new.display_name),''),nullif(btrim(concat_ws(' ',new.first_name,new.last_name)),''),new.id::text);
  v_old_name:=coalesce(nullif(btrim(old.display_name),''),nullif(btrim(concat_ws(' ',old.first_name,old.last_name)),''),old.id::text);
  v_bank_changed:=(new.pay_method,new.umbrella_id) is distinct from (old.pay_method,old.umbrella_id)
    or(new.pay_method is distinct from 'UMBRELLA' and new.bank_details_hash is distinct from old.bank_details_hash);
  if (v_name,new.tms_ref,new.pay_method,new.umbrella_id)
    is not distinct from (v_old_name,old.tms_ref,old.pay_method,old.umbrella_id) and not v_bank_changed then return new;end if;
  perform private.bpay_next_workbench_metadata_changed_v1(new.id,v_bank_changed,
    (new.pay_method,new.umbrella_id) is distinct from (old.pay_method,old.umbrella_id));
  return new;
end
$function$;

create or replace function private.timesheet_correction_a0_candidate_before_v1()
returns trigger language plpgsql volatile security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare v_old_key text; v_new_key text; v_old_aliases jsonb; v_new_aliases jsonb; v_ids uuid[];
begin
  if tg_table_schema<>'public' or tg_table_name<>'candidates' or tg_op not in('INSERT','UPDATE','DELETE') then
    raise exception 'CORRECTION_A0_WRITER_TRIGGER_CONTEXT_INVALID' using errcode='55000'; end if;
  if tg_op<>'INSERT' then v_old_key:=old.key_norm;v_old_aliases:=old.nhsp_hr_name_aliases; end if;
  if tg_op<>'DELETE' then v_new_key:=new.key_norm;v_new_aliases:=new.nhsp_hr_name_aliases; end if;
  -- Exact same equality/JSON containment as tsfin_load_context_batch; no
  -- additional name normalization, Contract identity fallback or new resolver.
  select array_agg(distinct t.timesheet_id order by t.timesheet_id) into v_ids from public.timesheets t
    where t.occupant_key_norm is not null and (t.occupant_key_norm in(v_old_key,v_new_key)
      or v_old_aliases @> to_jsonb(array[t.occupant_key_norm]::text[])
      or v_new_aliases @> to_jsonb(array[t.occupant_key_norm]::text[]))
      and (private.timesheet_correction_a0_signed_precursor_v1(t.timesheet_id)
        or exists(select 1 from private.timesheet_correction_requests q where q.state='WAITING'
          and q.origin='SIGNED_TIMESHEET_CORRECTION' and q.reversed_financial_id is null
          and q.frozen_original_json#>>'{timesheet,sheet_scope}'='WEEKLY'
          and t.timesheet_id in(q.root_timesheet_id,q.reversed_timesheet_id,q.replacement_timesheet_id)));
  if v_ids is not null then perform private.timesheet_correction_a0_writer_admit_v1(v_ids,null,'CANDIDATE_IDENTITY'); end if;
  if tg_op='DELETE' then return old; end if; return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.pay_workbench_mark_contract_client_dirty()
RETURNS trigger
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_started_at timestamptz := clock_timestamp();
  v_now timestamptz := clock_timestamp();
  v_trigger_table text := lower(TG_TABLE_NAME);
  v_new_row jsonb := '{}'::jsonb;
  v_old_row jsonb := '{}'::jsonb;
  v_uuid_re text := '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';
  v_contract_id_old uuid := NULL::uuid;
  v_contract_id_new uuid := NULL::uuid;
  v_client_id_old uuid := NULL::uuid;
  v_client_id_new uuid := NULL::uuid;
  v_candidate_id_old uuid := NULL::uuid;
  v_candidate_id_new uuid := NULL::uuid;
  v_row_id_old uuid := NULL::uuid;
  v_row_id_new uuid := NULL::uuid;
  v_scope record;
  v_reason text;
  v_payload_json jsonb := '{}'::jsonb;
  v_enqueue_result jsonb := '{}'::jsonb;
  v_jobs_queued integer := 0;
BEGIN
  PERFORM public._temp_diag_log('TEMP_TRIGGER_DIRTY_STAGE', 'TEMP_BANKING_PAY_DIRTY', NULL::text, jsonb_build_object('function_name', 'pay_workbench_mark_contract_client_dirty', 'stage', 'entry', 'trigger_table', v_trigger_table, 'trigger_op', TG_OP, 'queue_class', 'DIRTY_TRIGGER_PRIORITY'));

  IF TG_OP <> 'DELETE' THEN v_new_row := to_jsonb(NEW); END IF;
  IF TG_OP <> 'INSERT' THEN v_old_row := to_jsonb(OLD); END IF;

  IF v_trigger_table = 'contracts' THEN
    IF NULLIF(BTRIM(COALESCE(v_old_row->>'id', '')), '') ~* v_uuid_re THEN v_contract_id_old := NULLIF(BTRIM(COALESCE(v_old_row->>'id', '')), '')::uuid; END IF;
    IF NULLIF(BTRIM(COALESCE(v_new_row->>'id', '')), '') ~* v_uuid_re THEN v_contract_id_new := NULLIF(BTRIM(COALESCE(v_new_row->>'id', '')), '')::uuid; END IF;
    IF NULLIF(BTRIM(COALESCE(v_old_row->>'client_id', '')), '') ~* v_uuid_re THEN v_client_id_old := NULLIF(BTRIM(COALESCE(v_old_row->>'client_id', '')), '')::uuid; END IF;
    IF NULLIF(BTRIM(COALESCE(v_new_row->>'client_id', '')), '') ~* v_uuid_re THEN v_client_id_new := NULLIF(BTRIM(COALESCE(v_new_row->>'client_id', '')), '')::uuid; END IF;
    IF NULLIF(BTRIM(COALESCE(v_old_row->>'candidate_id', '')), '') ~* v_uuid_re THEN v_candidate_id_old := NULLIF(BTRIM(COALESCE(v_old_row->>'candidate_id', '')), '')::uuid; END IF;
    IF NULLIF(BTRIM(COALESCE(v_new_row->>'candidate_id', '')), '') ~* v_uuid_re THEN v_candidate_id_new := NULLIF(BTRIM(COALESCE(v_new_row->>'candidate_id', '')), '')::uuid; END IF;
    v_row_id_old := v_contract_id_old;
    v_row_id_new := v_contract_id_new;
  ELSIF v_trigger_table = 'client_settings' THEN
    IF NULLIF(BTRIM(COALESCE(v_old_row->>'client_id', '')), '') ~* v_uuid_re THEN v_client_id_old := NULLIF(BTRIM(COALESCE(v_old_row->>'client_id', '')), '')::uuid; END IF;
    IF NULLIF(BTRIM(COALESCE(v_new_row->>'client_id', '')), '') ~* v_uuid_re THEN v_client_id_new := NULLIF(BTRIM(COALESCE(v_new_row->>'client_id', '')), '')::uuid; END IF;
    IF NULLIF(BTRIM(COALESCE(v_old_row->>'id', '')), '') ~* v_uuid_re THEN v_row_id_old := NULLIF(BTRIM(COALESCE(v_old_row->>'id', '')), '')::uuid; END IF;
    IF NULLIF(BTRIM(COALESCE(v_new_row->>'id', '')), '') ~* v_uuid_re THEN v_row_id_new := NULLIF(BTRIM(COALESCE(v_new_row->>'id', '')), '')::uuid; END IF;
  ELSE
    IF NULLIF(BTRIM(COALESCE(v_old_row->>'contract_id', '')), '') ~* v_uuid_re THEN v_contract_id_old := NULLIF(BTRIM(COALESCE(v_old_row->>'contract_id', '')), '')::uuid; END IF;
    IF NULLIF(BTRIM(COALESCE(v_new_row->>'contract_id', '')), '') ~* v_uuid_re THEN v_contract_id_new := NULLIF(BTRIM(COALESCE(v_new_row->>'contract_id', '')), '')::uuid; END IF;
    IF NULLIF(BTRIM(COALESCE(v_old_row->>'client_id', '')), '') ~* v_uuid_re THEN v_client_id_old := NULLIF(BTRIM(COALESCE(v_old_row->>'client_id', '')), '')::uuid; END IF;
    IF NULLIF(BTRIM(COALESCE(v_new_row->>'client_id', '')), '') ~* v_uuid_re THEN v_client_id_new := NULLIF(BTRIM(COALESCE(v_new_row->>'client_id', '')), '')::uuid; END IF;
    IF NULLIF(BTRIM(COALESCE(v_old_row->>'candidate_id', '')), '') ~* v_uuid_re THEN v_candidate_id_old := NULLIF(BTRIM(COALESCE(v_old_row->>'candidate_id', '')), '')::uuid; END IF;
    IF NULLIF(BTRIM(COALESCE(v_new_row->>'candidate_id', '')), '') ~* v_uuid_re THEN v_candidate_id_new := NULLIF(BTRIM(COALESCE(v_new_row->>'candidate_id', '')), '')::uuid; END IF;
    IF NULLIF(BTRIM(COALESCE(v_old_row->>'id', '')), '') ~* v_uuid_re THEN v_row_id_old := NULLIF(BTRIM(COALESCE(v_old_row->>'id', '')), '')::uuid; END IF;
    IF NULLIF(BTRIM(COALESCE(v_new_row->>'id', '')), '') ~* v_uuid_re THEN v_row_id_new := NULLIF(BTRIM(COALESCE(v_new_row->>'id', '')), '')::uuid; END IF;
  END IF;

  v_reason := 'DIRTY_TRIGGER:' || upper(v_trigger_table) || ':' || TG_OP;

  FOR v_scope IN
    WITH scope_rows AS (
      SELECT 1::integer AS source_order, 'CONTRACT'::text AS scope_kind, v_contract_id_old AS scope_id, v_contract_id_old AS contract_id, v_client_id_old AS client_id, v_candidate_id_old AS candidate_id, v_row_id_old AS row_id
      UNION ALL
      SELECT 2::integer, 'CONTRACT', v_contract_id_new, v_contract_id_new, v_client_id_new, v_candidate_id_new, v_row_id_new
      UNION ALL
      SELECT 1::integer, 'CLIENT', v_client_id_old, NULL::uuid, v_client_id_old, v_candidate_id_old, v_row_id_old
      UNION ALL
      SELECT 2::integer, 'CLIENT', v_client_id_new, NULL::uuid, v_client_id_new, v_candidate_id_new, v_row_id_new
    )
    SELECT
      scope_rows.scope_kind,
      scope_rows.scope_id,
      (array_agg(scope_rows.contract_id ORDER BY scope_rows.source_order DESC))[1] AS contract_id,
      (array_agg(scope_rows.client_id ORDER BY scope_rows.source_order DESC))[1] AS client_id,
      (array_agg(scope_rows.candidate_id ORDER BY scope_rows.source_order) FILTER (WHERE scope_rows.candidate_id IS NOT NULL))[1] AS candidate_id,
      COALESCE(array_agg(DISTINCT scope_rows.candidate_id ORDER BY scope_rows.candidate_id) FILTER (WHERE scope_rows.candidate_id IS NOT NULL), ARRAY[]::uuid[]) AS candidate_ids,
      (array_agg(scope_rows.row_id ORDER BY scope_rows.source_order DESC))[1] AS row_id
    FROM scope_rows
    WHERE scope_rows.scope_id IS NOT NULL
    GROUP BY scope_rows.scope_kind, scope_rows.scope_id
    ORDER BY scope_rows.scope_kind, scope_rows.scope_id
  LOOP
    v_payload_json := jsonb_build_object(
      'trigger_table', v_trigger_table,
      'trigger_op', TG_OP,
      'trigger_operation', TG_OP,
      'scope_kind', v_scope.scope_kind,
      'scope_id', v_scope.scope_id::text,
      'contract_id', CASE WHEN v_scope.contract_id IS NULL THEN NULL ELSE v_scope.contract_id::text END,
      'client_id', CASE WHEN v_scope.client_id IS NULL THEN NULL ELSE v_scope.client_id::text END,
      'candidate_id', CASE WHEN v_scope.candidate_id IS NULL THEN NULL ELSE v_scope.candidate_id::text END,
      'candidate_ids', to_jsonb(v_scope.candidate_ids),
      'row_id', CASE WHEN v_scope.row_id IS NULL THEN NULL ELSE v_scope.row_id::text END,
      'reason', v_reason,
      'page_limit', 100,
      'force_legacy', true,
      'projection_class', 'CONTRACT_CLIENT_DIRTY',
      'fallback_reason', 'CONTRACT_CLIENT_OR_CLIENT_SETTINGS_DIRTY',
      'refresh_scope_kind', 'CANDIDATE_FULL_LIVE',
      'source_build_required', true,
      'line_work_required', true,
      'delta_refresh_required', false,
      'row_backed_scope_required', true,
      'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
    );

    SELECT public.pay_workbench_dirty_event_enqueue(
      p_job_type => 'CONTRACT_CLIENT_DIRTY_FANOUT',
      p_scope_kind => v_scope.scope_kind,
      p_scope_id => v_scope.scope_id::text,
      p_candidate_id => NULL::uuid,
      p_targeted_timesheet_ids => ARRAY[]::uuid[],
      p_linked_timesheet_ids => ARRAY[]::uuid[],
      p_payload_json => v_payload_json,
      p_reason => v_reason,
      p_priority => -1000,
      p_run_at_utc => v_now
    )
    INTO v_enqueue_result;

    v_jobs_queued := v_jobs_queued + 1;
  END LOOP;

  PERFORM public._temp_diag_log('TEMP_TRIGGER_DIRTY_STAGE', 'TEMP_BANKING_PAY_DIRTY', NULL::text, jsonb_build_object('function_name', 'pay_workbench_mark_contract_client_dirty', 'stage', 'return_enqueued_dirty_priority', 'trigger_table', v_trigger_table, 'trigger_op', TG_OP, 'jobs_queued', v_jobs_queued, 'queue_class', 'DIRTY_TRIGGER_PRIORITY', 'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::numeric, 2)));

  IF TG_OP = 'DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END;
$function$;

create or replace function public.contracts_enforce_overrideclientsettings()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_no_timesheet_required boolean;
  v_daily_calc_of_invoices boolean;
  v_group_nightsat_sunbh boolean;
  v_is_nhsp boolean;
  v_autoprocess_hr boolean;
  v_requires_hr boolean;
  v_hr_attach_to_invoice boolean;
  v_ts_attach_to_invoice boolean;
  v_reference_number_required_to_issue_invoice boolean;
  v_send_manual_invoices_to_different_email boolean;
  v_manual_invoices_alt_email_address text;
  v_default_submission_mode public.submission_mode_enum;
  v_timesheet_break_entry_mode public.timesheet_break_entry_mode_enum;
  v_auto_invoice boolean;
  v_require_reference_to_pay boolean;
  v_require_reference_to_invoice boolean;
  v_self_bill boolean;
begin
  new.overrideclientsettings := coalesce(new.overrideclientsettings, false);

  if new.overrideclientsettings = false then
    new.no_timesheet_required := null;
    new.daily_calc_of_invoices := null;
    new.group_nightsat_sunbh := null;
    new.is_nhsp := null;
    new.autoprocess_hr := null;
    new.requires_hr := null;
    new.hr_attach_to_invoice := null;
    new.ts_attach_to_invoice := null;
    new.reference_number_required_to_issue_invoice := null;
    new.send_manual_invoices_to_different_email := null;
    new.manual_invoices_alt_email_address := null;
    new.default_submission_mode := null;
    new.timesheet_break_entry_mode := null;

    -- These legacy columns are NOT NULL. Their values have no authority while
    -- the override switch is off and are replaced from Client settings on the
    -- next saved OFF -> ON transition.
    new.auto_invoice := coalesce(new.auto_invoice, false);
    new.require_reference_to_pay := coalesce(new.require_reference_to_pay, false);
    new.require_reference_to_invoice := coalesce(new.require_reference_to_invoice, false);
    new.self_bill := coalesce(new.self_bill, false);
    return new;
  end if;

  select
    cs.no_timesheet_required,
    cs.daily_calc_of_invoices,
    cs.group_nightsat_sunbh,
    cs.is_nhsp,
    cs.autoprocess_hr,
    cs.requires_hr,
    cs.hr_attach_to_invoice,
    cs.ts_attach_to_invoice,
    cs.reference_number_required_to_issue_invoice,
    cs.send_manual_invoices_to_different_email,
    cs.manual_invoices_alt_email_address,
    cs.default_submission_mode,
    cs.timesheet_break_entry_mode,
    cs.auto_invoice_default,
    cs.pay_reference_required,
    cs.invoice_reference_required,
    cs.self_bill_no_invoices_sent
  into
    v_no_timesheet_required,
    v_daily_calc_of_invoices,
    v_group_nightsat_sunbh,
    v_is_nhsp,
    v_autoprocess_hr,
    v_requires_hr,
    v_hr_attach_to_invoice,
    v_ts_attach_to_invoice,
    v_reference_number_required_to_issue_invoice,
    v_send_manual_invoices_to_different_email,
    v_manual_invoices_alt_email_address,
    v_default_submission_mode,
    v_timesheet_break_entry_mode,
    v_auto_invoice,
    v_require_reference_to_pay,
    v_require_reference_to_invoice,
    v_self_bill
  from public.client_settings cs
  where cs.client_id = new.client_id
  order by cs.effective_from desc nulls last, cs.updated_at desc
  limit 1;

  new.no_timesheet_required := coalesce(new.no_timesheet_required, v_no_timesheet_required, false);
  new.daily_calc_of_invoices := coalesce(new.daily_calc_of_invoices, v_daily_calc_of_invoices, false);
  new.group_nightsat_sunbh := coalesce(new.group_nightsat_sunbh, v_group_nightsat_sunbh, false);
  new.is_nhsp := coalesce(new.is_nhsp, v_is_nhsp, false);
  new.autoprocess_hr := coalesce(new.autoprocess_hr, v_autoprocess_hr, false);
  new.requires_hr := coalesce(new.requires_hr, v_requires_hr, false);
  new.hr_attach_to_invoice := coalesce(new.hr_attach_to_invoice, v_hr_attach_to_invoice, true);
  new.ts_attach_to_invoice := coalesce(new.ts_attach_to_invoice, v_ts_attach_to_invoice, true);
  new.reference_number_required_to_issue_invoice := coalesce(
    new.reference_number_required_to_issue_invoice,
    v_reference_number_required_to_issue_invoice,
    false
  );
  new.send_manual_invoices_to_different_email := coalesce(
    new.send_manual_invoices_to_different_email,
    v_send_manual_invoices_to_different_email,
    false
  );
  new.default_submission_mode := coalesce(new.default_submission_mode, v_default_submission_mode, 'ELECTRONIC');
  new.timesheet_break_entry_mode := coalesce(
    new.timesheet_break_entry_mode,
    v_timesheet_break_entry_mode,
    'START_END_TIMES'
  );
  new.auto_invoice := coalesce(new.auto_invoice, v_auto_invoice, false);
  new.require_reference_to_pay := coalesce(new.require_reference_to_pay, v_require_reference_to_pay, false);
  new.require_reference_to_invoice := coalesce(
    new.require_reference_to_invoice,
    v_require_reference_to_invoice,
    false
  );
  new.self_bill := coalesce(new.self_bill, v_self_bill, false);

  if new.send_manual_invoices_to_different_email = true then
    if new.manual_invoices_alt_email_address is null or btrim(new.manual_invoices_alt_email_address) = '' then
      new.manual_invoices_alt_email_address := v_manual_invoices_alt_email_address;
    end if;
    if new.manual_invoices_alt_email_address is null or btrim(new.manual_invoices_alt_email_address) = '' then
      raise exception 'manual_invoices_alt_email_address is required when send_manual_invoices_to_different_email is true';
    end if;
    new.manual_invoices_alt_email_address := btrim(new.manual_invoices_alt_email_address);
  else
    new.manual_invoices_alt_email_address := null;
  end if;

  return new;
end;
$$;

create or replace function private.weekly_source_sha256_text_v1(
  p_domain text,
  p_value text
) returns bytea
language sql immutable
set search_path to 'pg_catalog','extensions','pg_temp'
as $function$
  select extensions.digest(
    pg_catalog.convert_to(
      coalesce(p_domain,'') || pg_catalog.chr(31) || coalesce(p_value,''),
      'UTF8'
    ),
    'sha256'
  );
$function$;

create or replace function public._change_bump(p_entity_key text)
returns void
language plpgsql
as $$
begin
  if p_entity_key is null or btrim(p_entity_key) = '' then
    return;
  end if;

  update public.app_change_counters c
     set seq = c.seq + 1,
         updated_at = now()
   where c.entity_key = p_entity_key;

  if not found then
    insert into public.app_change_counters(entity_key, seq, updated_at)
    values (p_entity_key, 1, now())
    on conflict (entity_key) do update
      set seq = public.app_change_counters.seq + 1,
          updated_at = now();
  end if;
end;
$$;

create or replace function private.bpay_next_legacy_callback_enabled_v1()
returns boolean language plpgsql volatile security definer
set search_path=pg_catalog,private
as $function$
declare
  v_owner text;
  v_epoch bigint;
begin
  select m.active_owner,m.owner_epoch into v_owner,v_epoch
    from private.bpay_next_module_control m where m.id=1 for share;
  if not found or v_owner is null or v_owner not in ('LEGACY','NEXT','DISABLED')
     or v_epoch is null or v_epoch<=0 then
    raise exception using errcode='55000',message='BPAY_NEXT_OWNER_STATUS_UNAVAILABLE';
  end if;
  return v_owner='LEGACY';
end;
$function$;

CREATE OR REPLACE FUNCTION private.pay_workbench_finance_effect_normalise_row_v1(
  p_relation_name text,
  p_operation text,
  p_row_json jsonb,
  p_before_row_json jsonb DEFAULT NULL::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
IMMUTABLE
PARALLEL SAFE
SECURITY DEFINER
SET search_path = ''
AS $function$
DECLARE
  v_relation text:=LOWER(NULLIF(BTRIM(COALESCE(p_relation_name,'')),''));
  v_operation text:=UPPER(NULLIF(BTRIM(COALESCE(p_operation,'')),''));
  v_row jsonb:=CASE WHEN jsonb_typeof(COALESCE(p_row_json,'{}'::jsonb))='object'
    THEN COALESCE(p_row_json,'{}'::jsonb) ELSE '{}'::jsonb END;
  v_before jsonb:=CASE WHEN jsonb_typeof(COALESCE(p_before_row_json,'{}'::jsonb))='object'
    THEN COALESCE(p_before_row_json,'{}'::jsonb) ELSE '{}'::jsonb END;
  v_field text;
  v_before_value jsonb;
  v_after_value jsonb;
  v_nested_before jsonb := '{}'::jsonb;
  v_nested_after jsonb := '{}'::jsonb;
BEGIN
  IF v_relation NOT IN ('pay_advances','pay_finance_case_components','pay_finance_case_events')
     OR v_operation NOT IN ('INSERT','UPDATE','DELETE') THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_EFFECT_RELATION_INVALID' USING ERRCODE='22023';
  END IF;

  v_row:=v_row-'created_at'-'created_at_utc'-'updated_at'-'updated_at_utc'-'event_at_utc';

  -- Component sync refreshes this one nested audit timestamp whenever an
  -- existing amount-only resolution remains reusable. Capture and execute run
  -- in separate transactions, so their generated instants must be attested as
  -- the same non-economic transition. Keep every sibling amount, ratio,
  -- fingerprint and resolution field exact.
  IF v_relation='pay_finance_case_components'
     AND v_operation='UPDATE'
     AND jsonb_typeof(v_row->'saved_resolution_result_json')='object'
     AND LOWER(COALESCE(
       v_row#>>'{saved_resolution_result_json,amount_only_resolution_reused}',
       'false'
     )) IN ('true','t','1','yes','y','on')
     AND NULLIF(BTRIM(COALESCE(
       v_row#>>'{saved_resolution_result_json,amount_only_resolution_reused_at_utc}',
       ''
     )), '') IS NOT NULL THEN
    v_row:=jsonb_set(
      v_row,
      ARRAY['saved_resolution_result_json','amount_only_resolution_reused_at_utc'],
      to_jsonb('__GENERATED_NON_NULL__'::text),
      false
    );
  END IF;

  IF v_operation='INSERT' THEN
    v_row:=v_row-'id'-'finance_case_id'-'finance_component_id';

    -- Event rows duplicate their stable parent identities inside the captured
    -- before/after snapshots.  A newly inserted case/component receives a new
    -- physical UUID in capture and execute, while its logical parent identity
    -- is already attested independently by the expected-effect identity map.
    -- Remove only those duplicated generated identities from the event digest;
    -- all economic, classification and lifecycle fields remain exact.
    IF v_relation='pay_finance_case_events' THEN
      IF jsonb_typeof(v_row->'before_json')='object' THEN
        v_row:=jsonb_set(v_row,ARRAY['before_json'],
          (v_row->'before_json')-'id'-'finance_case_id'-'finance_component_id',false);
      END IF;
      IF jsonb_typeof(v_row->'after_json')='object' THEN
        v_row:=jsonb_set(v_row,ARRAY['after_json'],
          (v_row->'after_json')-'id'-'finance_case_id'-'finance_component_id',false);
      END IF;

      -- Closure timestamps are repeated in the immutable event snapshot.  The
      -- capture and execute transactions generate different instants for the
      -- same NULL -> non-NULL lifecycle transition, so attest that transition
      -- semantically.  Existing/manual timestamps, removals, and every other
      -- nested field remain exact and therefore still fail on any difference.
      v_nested_before:=CASE WHEN jsonb_typeof(v_row->'before_json')='object'
        THEN v_row->'before_json' ELSE '{}'::jsonb END;
      v_nested_after:=CASE WHEN jsonb_typeof(v_row->'after_json')='object'
        THEN v_row->'after_json' ELSE '{}'::jsonb END;
      FOR v_field IN
        SELECT field_name FROM unnest(ARRAY[
          'closed_at_utc','cleared_at_utc','written_off_at_utc'
        ]::text[]) field_name
      LOOP
        v_before_value:=v_nested_before->v_field;
        v_after_value:=v_nested_after->v_field;
        IF (v_before_value IS NULL OR v_before_value='null'::jsonb)
           AND v_after_value IS NOT NULL
           AND v_after_value<>'null'::jsonb THEN
          v_nested_after:=jsonb_set(v_nested_after,ARRAY[v_field],
            to_jsonb('__GENERATED_NON_NULL__'::text),true);
        END IF;
      END LOOP;
      IF jsonb_typeof(v_row->'after_json')='object' THEN
        v_row:=jsonb_set(v_row,ARRAY['after_json'],v_nested_after,false);
      END IF;
    END IF;
  END IF;

  FOR v_field IN
    SELECT field_name FROM unnest(CASE v_relation
      WHEN 'pay_advances' THEN ARRAY['cleared_at_utc','written_off_at_utc']::text[]
      WHEN 'pay_finance_case_components' THEN ARRAY['closed_at_utc']::text[]
      ELSE ARRAY[]::text[] END) field_name
  LOOP
    v_before_value:=v_before->v_field;
    v_after_value:=v_row->v_field;
    IF v_before_value IS NOT NULL AND v_before_value<>'null'::jsonb THEN
      IF v_after_value IS NOT NULL AND v_after_value<>'null'::jsonb
         AND v_after_value IS DISTINCT FROM v_before_value THEN
        RAISE EXCEPTION 'PAY_WORKBENCH_EXPECTED_EFFECT_LIFECYCLE_TIMESTAMP_MISMATCH'
          USING ERRCODE='23514';
      END IF;
      -- An existing manual/lifecycle timestamp remains exact authority.
    ELSIF v_after_value IS NOT NULL AND v_after_value<>'null'::jsonb THEN
      v_row:=jsonb_set(v_row,ARRAY[v_field],to_jsonb('__GENERATED_NON_NULL__'::text),true);
    END IF;
  END LOOP;
  RETURN v_row;
END;
$function$;

CREATE OR REPLACE FUNCTION private._candidate_expense_summary_queue_v1(p_timesheet_id uuid, p_now_utc timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'extensions', 'pg_temp'
AS $function$
declare
  v_fin public.timesheets_financials%rowtype;
  v_is_daily boolean:=false;
  v_total numeric;
  v_has_summary boolean;
  v_totals jsonb;
  v_digest bytea;
  v_generation integer;
  v_refresh public.candidate_expense_summary_refreshes%rowtype;
  v_identity jsonb;
  v_evidence_counts jsonb;
  v_categories jsonb;
  v_cleanup_failures jsonb:='[]'::jsonb;
  v_cleanup_record jsonb;
begin
  if private._candidate_expense_source_family_v1(p_timesheet_id) then
    return jsonb_build_object('ok',true,'timesheet_id',p_timesheet_id,'summary_state','NOT_REQUIRED');
  end if;
  if p_timesheet_id is null then
    raise exception 'TIMESHEET_ID_REQUIRED' using errcode='22023';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('candidate-expense-summary|'||p_timesheet_id::text,0)
  );
  select financial.* into v_fin
  from public.timesheets_financials financial
  where financial.timesheet_id=p_timesheet_id and financial.is_current
  order by financial.computed_at_utc desc nulls last,
    financial.updated_at desc,financial.id desc
  limit 1 for update;
  if not found then
    return jsonb_build_object('ok',true,'timesheet_id',p_timesheet_id,
      'summary_state','NOT_REQUIRED');
  end if;
  select exists(
    select 1 from public.timesheets timesheet
    where timesheet.timesheet_id=p_timesheet_id
      and timesheet.sheet_scope='DAILY'::public.timesheet_scope_enum
  ) into v_is_daily;
  v_total:=case when v_is_daily then 0 else
    coalesce(v_fin.mileage_pay_ex_vat,0)
      +coalesce(v_fin.travel_pay_ex_vat,0)
      +coalesce(v_fin.accommodation_pay_ex_vat,0)
      +coalesce(v_fin.other_pay_ex_vat,0) end;
  select jsonb_build_object(
    'candidate_name',nullif(btrim(coalesce(candidate.display_name,
      concat_ws(' ',candidate.first_name,candidate.last_name))),''),
    'candidate_reference',candidate.tms_ref,
    'client_name',client.name,'client_reference',client.cli_ref,
    'contract_id',contract.id,'contract_role',contract.role,
    'contract_site',contract.display_site,
    'week_ending_date',v_timesheet.week_ending_date
  ) into v_identity
  from public.timesheets v_timesheet
  left join public.contracts contract on contract.id=v_timesheet.contract_id
  left join public.candidates candidate on candidate.id=v_fin.candidate_id
  left join public.clients client on client.id=v_fin.client_id
  where v_timesheet.timesheet_id=p_timesheet_id;
  select coalesce(jsonb_object_agg(category.expense_category,
    category.source_count+category.materialised_only_count
    order by category.expense_category),'{}'::jsonb)
  into v_evidence_counts
  from (
    select requested.expense_category,
      (select count(distinct coalesce(source.source_component_id,source.id))::integer
       from public.candidate_expense_components component
       join public.candidate_submission_components source
         on source.workflow_id=component.workflow_id
        and source.workflow_generation=component.workflow_generation
        and source.expense_category=component.expense_category
        and source.component_kind in ('MILEAGE_FORM','EXPENSE_EVIDENCE')
        and source.state not in ('SUPERSEDED','REJECTED','ABANDONED')
       where component.expense_category=requested.expense_category
         and component.lifecycle_state not in (
           'MANAGER_REFUSED','OFFICE_REJECTED','WITHDRAWN','CANCELLED','SUPERSEDED'
         )
         and private._candidate_expense_owned_timesheet_id_v1(
           component.workflow_id,component.owning_timesheet_id
         )=p_timesheet_id) as source_count,
      (select count(distinct evidence.id)::integer
       from public.timesheet_evidence evidence
       where evidence.timesheet_id=p_timesheet_id
         and evidence.processing_state<>'SUPERSEDED'
         and evidence.document_role<>'EXPENSE_MILEAGE_APPROVAL_SUMMARY'
         and upper(coalesce(evidence.kind::text,''))=requested.expense_category
         and (evidence.candidate_component_id is null or not exists(
           select 1
           from public.candidate_expense_components active_component
           join public.candidate_submission_components source
             on source.workflow_id=active_component.workflow_id
            and source.workflow_generation=active_component.workflow_generation
            and source.expense_category=active_component.expense_category
            and source.component_kind in ('MILEAGE_FORM','EXPENSE_EVIDENCE')
            and source.state not in ('SUPERSEDED','REJECTED','ABANDONED')
           left join public.candidate_submission_components materialised_source
             on materialised_source.id=evidence.candidate_component_id
           where active_component.expense_category=requested.expense_category
             and active_component.lifecycle_state not in (
               'MANAGER_REFUSED','OFFICE_REJECTED','WITHDRAWN','CANCELLED','SUPERSEDED'
             )
             and private._candidate_expense_owned_timesheet_id_v1(
               active_component.workflow_id,active_component.owning_timesheet_id
             )=p_timesheet_id
             and coalesce(source.source_component_id,source.id)
               =coalesce(materialised_source.source_component_id,
                 evidence.candidate_component_id)
         ))) as materialised_only_count
    from (values ('MILEAGE'),('TRAVEL'),('ACCOMMODATION'),('OTHER'))
      requested(expense_category)
  ) category;
  select coalesce(jsonb_agg(jsonb_build_object(
    'expense_category',category.expense_category,
    'amount',category.amount,
    'mileage_units',category.mileage_units,
    'supporting_evidence_count',coalesce(
      (v_evidence_counts->>category.expense_category)::integer,0
    )
  ) order by category.ordinal),'[]'::jsonb)
  into v_categories
  from (
    values
      (1,'MILEAGE',coalesce(v_fin.mileage_pay_ex_vat,0),coalesce(v_fin.mileage_units,0)),
      (2,'TRAVEL',coalesce(v_fin.travel_pay_ex_vat,0),0::numeric),
      (3,'ACCOMMODATION',coalesce(v_fin.accommodation_pay_ex_vat,0),0::numeric),
      (4,'OTHER',coalesce(v_fin.other_pay_ex_vat,0),0::numeric)
  ) category(ordinal,expense_category,amount,mileage_units)
  where not v_is_daily and (category.amount<>0 or category.mileage_units<>0);
  v_has_summary:=jsonb_array_length(v_categories)>0;
  v_totals:=jsonb_build_object(
    'identity',coalesce(v_identity,'{}'::jsonb),
    'evidence_counts',coalesce(v_evidence_counts,'{}'::jsonb),
    'categories',v_categories,
    'mileage_units',case when v_is_daily then 0 else coalesce(v_fin.mileage_units,0) end,
    'mileage_pay_ex_vat',case when v_is_daily then 0 else coalesce(v_fin.mileage_pay_ex_vat,0) end,
    'travel_pay_ex_vat',case when v_is_daily then 0 else coalesce(v_fin.travel_pay_ex_vat,0) end,
    'accommodation_pay_ex_vat',case when v_is_daily then 0 else coalesce(v_fin.accommodation_pay_ex_vat,0) end,
    'other_pay_ex_vat',case when v_is_daily then 0 else coalesce(v_fin.other_pay_ex_vat,0) end,
    'expenses_pay_ex_vat',case when v_is_daily then 0 else
      coalesce(v_fin.travel_pay_ex_vat,0)
        +coalesce(v_fin.accommodation_pay_ex_vat,0)
        +coalesce(v_fin.other_pay_ex_vat,0) end,
    'total_pay_ex_vat',v_total
  );
  v_digest:=extensions.digest(pg_catalog.convert_to(v_totals::text,'UTF8'),'sha256');

  select refresh.* into v_refresh
  from public.candidate_expense_summary_refreshes refresh
  where refresh.timesheet_id_snapshot=p_timesheet_id
    and refresh.state in ('PENDING','RENDERING','READY','REMOVED')
  order by refresh.summary_generation desc
  limit 1 for update;
  if found and v_refresh.totals_sha256=v_digest
     and ((not v_has_summary and v_refresh.state='REMOVED')
       or (v_has_summary and v_refresh.state in ('PENDING','RENDERING','READY'))) then
    return jsonb_build_object(
      'ok',true,'timesheet_id',p_timesheet_id,
      'refresh_id',v_refresh.refresh_id,
      'summary_generation',v_refresh.summary_generation,
      'summary_state',v_refresh.state,'totals',v_totals,
      'idempotent_replay',true
    );
  end if;

  update public.candidate_expense_summary_refreshes refresh set
    state='SUPERSEDED',completed_at_utc=p_now_utc,updated_at_utc=p_now_utc,
    -- Retain the exact in-flight claim identity on a superseded render.  Its
    -- late completion can then prove and durably retire the attempt-specific
    -- R2 object instead of orphaning it.  A merely PENDING row has no claim.
    claim_token=case when refresh.state='RENDERING' then refresh.claim_token end,
    claimed_at_utc=case when refresh.state='RENDERING' then refresh.claimed_at_utc end,
    lease_expires_at_utc=case when refresh.state='RENDERING'
      then refresh.lease_expires_at_utc end
  where refresh.timesheet_id_snapshot=p_timesheet_id
    and refresh.state in ('PENDING','RENDERING');

  select coalesce(max(refresh.summary_generation),0)+1 into v_generation
  from public.candidate_expense_summary_refreshes refresh
  where refresh.timesheet_id_snapshot=p_timesheet_id;
  insert into public.candidate_expense_summary_refreshes(
    timesheet_id,timesheet_id_snapshot,summary_generation,state,totals_json,totals_sha256,
    source_financials_id,idempotency_key,requested_at_utc,completed_at_utc,
    updated_at_utc
  ) values (
    p_timesheet_id,p_timesheet_id,v_generation,
    case when not v_has_summary then 'REMOVED' else 'PENDING' end,
    v_totals,v_digest,v_fin.id,
    'expense-summary:'||p_timesheet_id::text||':'||v_generation::text||':'||encode(v_digest,'hex'),
    p_now_utc,case when not v_has_summary then p_now_utc else null end,p_now_utc
  ) returning * into v_refresh;

  if not v_has_summary then
    select coalesce(jsonb_agg(jsonb_build_object(
      'r2_key',current_summary.storage_key,'attempt_count',1,
      'error','EXPENSE_SUMMARY_REMOVED'
    ) order by current_summary.storage_key),'[]'::jsonb)
    into v_cleanup_failures
    from (
      select distinct evidence.storage_key
      from public.timesheet_evidence evidence
      where evidence.timesheet_id=p_timesheet_id
        and evidence.document_role='EXPENSE_MILEAGE_APPROVAL_SUMMARY'
        and evidence.processing_state<>'SUPERSEDED'
        and nullif(btrim(coalesce(evidence.storage_key,'')),'') is not null
    ) current_summary;
    update public.timesheet_evidence evidence set processing_state='SUPERSEDED'
    where evidence.timesheet_id=p_timesheet_id
      and evidence.document_role='EXPENSE_MILEAGE_APPROVAL_SUMMARY'
      and evidence.processing_state<>'SUPERSEDED';
    if jsonb_array_length(v_cleanup_failures)>0 then
      v_cleanup_record:=public.timesheet_r2_cleanup_record_v1(
        'candidate-expense-summary-remove:'||v_refresh.refresh_id::text,
        p_timesheet_id,array[]::uuid[],v_cleanup_failures,null
      );
      if coalesce((v_cleanup_record->>'ok')::boolean,false) is not true
         or coalesce((v_cleanup_record->>'valid_distinct_keys')::integer,-1)
            is distinct from jsonb_array_length(v_cleanup_failures) then
        raise exception 'CANDIDATE_EXPENSE_SUMMARY_CLEANUP_NOT_DURABLE'
          using errcode='40001';
      end if;
    end if;
  end if;
  return jsonb_build_object(
    'ok',true,'timesheet_id',p_timesheet_id,
    'refresh_id',v_refresh.refresh_id,
    'summary_generation',v_refresh.summary_generation,
    'summary_state',v_refresh.state,'totals',v_totals,
    'idempotent_replay',false
  );
end;
$function$;

create or replace function private.bpay_next_workbench_metadata_changed_v1(p_candidate_id uuid,p_bank_changed boolean default false,p_control_changed boolean default false)
returns void language plpgsql security definer set search_path=pg_catalog,private
as $function$
declare v_metadata private.bpay_next_workbench_candidate_metadata%rowtype;v_warning text;
begin
  perform private.bpay_next_workbench_require_next_v1();
  insert into private.bpay_next_worker_control(candidate_id) values(p_candidate_id) on conflict do nothing;
  perform 1 from private.bpay_next_worker_control where candidate_id=p_candidate_id for update;
  v_metadata:=private.bpay_next_workbench_ensure_metadata_v1(p_candidate_id);
  select case when nullif(btrim(case when c.pay_method='UMBRELLA' then u.bank_details_hash else c.bank_details_hash end),'') is null
    then 'BANK_DETAILS_MISSING' when p_bank_changed then 'BANK_DETAILS_CHANGED' else v_metadata.bank_warning_code end
    into v_warning from public.candidates c left join public.umbrellas u on u.id=c.umbrella_id where c.id=p_candidate_id;
  update private.bpay_next_workbench_candidate_metadata m set
    candidate_sort_name=coalesce(nullif(btrim(c.display_name),''),nullif(btrim(concat_ws(' ',c.first_name,c.last_name)),''),c.id::text),
    tms_ref=c.tms_ref,target_pay_channel=case when c.pay_method in ('PAYE','UMBRELLA') then c.pay_method end,
    target_umbrella_id=case when c.pay_method='UMBRELLA' then c.umbrella_id end,
    target_umbrella_vat_chargeable=case when c.pay_method='UMBRELLA' then u.vat_chargeable end,
    target_umbrella_enabled=case when c.pay_method='UMBRELLA' then u.enabled end,
    bank_warning_code=v_warning,metadata_version=m.metadata_version+1,continuation_pending=true,updated_at_utc=transaction_timestamp()
    from public.candidates c left join public.umbrellas u on u.id=c.umbrella_id
    where m.candidate_id=p_candidate_id and c.id=m.candidate_id;
  perform private.bpay_next_workbench_schedule_task_v1('METADATA',p_candidate_id,null,null,false,p_control_changed,v_metadata.continuation_pending);
end
$function$;

create or replace function private.timesheet_correction_a0_signed_precursor_v1(p_timesheet_id uuid)
returns boolean language plpgsql volatile security definer
set search_path to 'pg_catalog','pg_temp'
as $function$
declare t public.timesheets%rowtype; v_witness jsonb;
begin
  select ts.* into t from public.timesheets ts where ts.timesheet_id=p_timesheet_id;
  if not found or t.sheet_scope::text is distinct from 'WEEKLY' or t.submission_mode::text is distinct from 'ELECTRONIC'
    or t.contract_id is null or exists(select 1 from public.timesheets_financials f where f.timesheet_id=t.timesheet_id)
    or private.timesheet_correction_origin_v1(t.timesheet_id) is distinct from 'SIGNED_TIMESHEET_CORRECTION' then return false; end if;
  v_witness:=private.timesheet_correction_signed_witness_v1(t.timesheet_id,false);
  return v_witness is not null;
exception when sqlstate '55000' then return false;
end;
$function$;

create or replace function private.timesheet_correction_a0_writer_admit_v1(p_ids uuid[],p_bookings text[],p_kind text)
returns jsonb language plpgsql volatile security definer
set search_path to 'pg_catalog','pg_temp'
as $function$
declare
  v_requests jsonb; v_after jsonb; v_req_ids uuid[]; v_candidates uuid[]; v_roots uuid[];
  v_parent_ids uuid[]; v_members uuid[]; v_gate jsonb; v_lock jsonb; v_family_before jsonb; v_family_after jsonb;
  v_old_timeout text:=current_setting('lock_timeout'); r record;
begin
  if p_kind not in('VALIDATION_REFERENCE','INVOICE_REFERENCE','BOOKING_IDENTITY','CANDIDATE_IDENTITY') then
    raise exception 'CORRECTION_A0_WRITER_TRIGGER_CONTEXT_INVALID' using errcode='55000'; end if;
  -- Actual private immutable request/physical identity is the only active arm.
  -- Caller arguments are trigger-owned OLD/NEW references, not client flags.
  select jsonb_agg(jsonb_build_object('id',q.id,'state_revision',q.state_revision::text,'target_revision',q.target_revision,
    'candidate_id',q.candidate_id,'client_id',q.client_id,'contract_id',q.contract_id,'root',q.root_timesheet_id,
    'original',q.reversed_timesheet_id,'p0',q.replacement_timesheet_id,'original_booking',q.original_booking_id,
    'reversed_booking',q.frozen_original_json#>>'{timesheet,booking_id}','p0_booking',q.replacement_booking_id) order by q.id)
    into v_requests from private.timesheet_correction_requests q
    where q.state='WAITING' and q.origin='SIGNED_TIMESHEET_CORRECTION' and q.reversed_financial_id is null
      and q.frozen_original_json#>>'{timesheet,sheet_scope}'='WEEKLY'
      and (q.root_timesheet_id=any(p_ids) or q.reversed_timesheet_id=any(p_ids) or q.replacement_timesheet_id=any(p_ids)
        or exists(select 1 from public.timesheets t where t.timesheet_id=any(p_ids)
          and t.booking_id in(q.original_booking_id,q.frozen_original_json#>>'{timesheet,booking_id}',q.replacement_booking_id))
        or exists(select 1 from unnest(p_bookings) b(value) where btrim(b.value) in(
          btrim(q.original_booking_id),btrim(q.frozen_original_json#>>'{timesheet,booking_id}'),btrim(q.replacement_booking_id))));
  if v_requests is not null then
    -- Refusal is limited to an actual visible active missing-A0 request.
    -- An older RR snapshot that cannot see the parent/request is separately
    -- HELD in the native recipe, never certified by this source predicate.
    if current_setting('transaction_isolation')<>'read committed' then
      raise exception 'CORRECTION_A0_TRANSACTION_SNAPSHOT_UNPROVED' using errcode='55000'; end if;
    if jsonb_array_length(v_requests)>4 then raise exception 'CORRECTION_A0_WRITER_SCOPE_UNPROVED' using errcode='55000'; end if;
    select array_agg((x.value->>'id')::uuid order by x.value->>'id') into v_req_ids from jsonb_array_elements(v_requests) x(value);
    select array_agg(distinct (x.value->>'candidate_id')::uuid order by (x.value->>'candidate_id')::uuid)
      into v_candidates from jsonb_array_elements(v_requests) x(value);
    select array_agg(distinct t.timesheet_id order by t.timesheet_id) into v_roots
      from jsonb_array_elements(v_requests) x(value)
      cross join lateral unnest(array[(x.value->>'root')::uuid,(x.value->>'original')::uuid,(x.value->>'p0')::uuid]) i(id)
      join public.timesheets t on t.timesheet_id=i.id;
    -- P0 may be the same unit's not-yet-inserted physical row. Original/root
    -- must already exist; no missing existing family is silently dropped.
    if v_roots is null or exists(select 1 from jsonb_array_elements(v_requests) x(value)
      where not exists(select 1 from public.timesheets t where t.timesheet_id=(x.value->>'root')::uuid)
        or not exists(select 1 from public.timesheets t where t.timesheet_id=(x.value->>'original')::uuid)) then
      raise exception 'CORRECTION_A0_WRITER_SCOPE_UNPROVED' using errcode='55000'; end if;
    select jsonb_agg(to_jsonb(s) order by s.requested_timesheet_id,s.family_version,s.family_timesheet_id)
      into v_family_before from public._pay_timesheet_rotation_scope(v_roots) s;
    begin
      perform set_config('lock_timeout','1ms',true);
      -- ALL Candidate gates precede ONE native complete family acquisition.
      for r in select c.id from unnest(v_candidates) c(id) order by c.id loop
        v_gate:=private.weekly_source_candidate_serial_gate_v1(r.id,'WORKBENCH_CANDIDATE_FIRST_AUTHORISATION',
          v_req_ids[1],'CORRECTION_A0_SCOPED_CREATOR');
        if v_gate->'ok' is distinct from 'true'::jsonb or v_gate->>'gate' is distinct from 'GRANTED' then
          raise exception 'CORRECTION_A0_AUTHORITY_BUSY' using errcode='55P03'; end if;
      end loop;
      perform set_config('lock_timeout','1ms',true);
      -- Optional Candidate NULL is the native multi-Candidate set interface;
      -- exact persisted request/Contract dimensions are checked below.
      v_lock:=private.weekly_source_lock_family_rows_v1(v_roots,null);
      if v_lock->'ok' is distinct from 'true'::jsonb then
        raise exception 'CORRECTION_A0_WRITER_SCOPE_UNPROVED' using errcode='55000'; end if;
      perform set_config('lock_timeout',v_old_timeout,true);
    exception when others then perform set_config('lock_timeout',v_old_timeout,true); raise; end;
    select jsonb_agg(to_jsonb(s) order by s.requested_timesheet_id,s.family_version,s.family_timesheet_id)
      into v_family_after from public._pay_timesheet_rotation_scope(v_roots) s;
    if v_family_before is null or v_family_after is distinct from v_family_before then
      raise exception 'CORRECTION_A0_WRITER_SCOPE_CHANGED' using errcode='40001'; end if;
    perform 1 from private.timesheet_correction_requests q where q.id=any(v_req_ids) order by q.id for share nowait;
    select jsonb_agg(jsonb_build_object('id',q.id,'state_revision',q.state_revision::text,'target_revision',q.target_revision,
      'candidate_id',q.candidate_id,'client_id',q.client_id,'contract_id',q.contract_id,'root',q.root_timesheet_id,
      'original',q.reversed_timesheet_id,'p0',q.replacement_timesheet_id,'original_booking',q.original_booking_id,
      'reversed_booking',q.frozen_original_json#>>'{timesheet,booking_id}','p0_booking',q.replacement_booking_id) order by q.id)
      into v_after from private.timesheet_correction_requests q
      where q.state='WAITING' and q.origin='SIGNED_TIMESHEET_CORRECTION' and q.reversed_financial_id is null
        and q.frozen_original_json#>>'{timesheet,sheet_scope}'='WEEKLY'
        and (q.root_timesheet_id=any(p_ids) or q.reversed_timesheet_id=any(p_ids) or q.replacement_timesheet_id=any(p_ids)
          or exists(select 1 from public.timesheets t where t.timesheet_id=any(p_ids)
            and t.booking_id in(q.original_booking_id,q.frozen_original_json#>>'{timesheet,booking_id}',q.replacement_booking_id))
          or exists(select 1 from unnest(p_bookings) b(value) where btrim(b.value) in(
            btrim(q.original_booking_id),btrim(q.frozen_original_json#>>'{timesheet,booking_id}'),btrim(q.replacement_booking_id))));
    if v_after is distinct from v_requests then raise exception 'CORRECTION_A0_WRITER_SCOPE_CHANGED' using errcode='40001'; end if;
    if exists(select 1 from jsonb_array_elements(v_requests) x(value)
      join public.timesheets t on t.timesheet_id=(x.value->>'original')::uuid
      left join public.contracts c on c.id=t.contract_id
      where t.contract_id is distinct from (x.value->>'contract_id')::uuid
        or c.candidate_id is distinct from (x.value->>'candidate_id')::uuid
        or c.client_id is distinct from (x.value->>'client_id')::uuid) then
      raise exception 'CORRECTION_A0_WRITER_SCOPE_UNPROVED' using errcode='55000'; end if;
    select array_agg(distinct s.family_timesheet_id order by s.family_timesheet_id) into v_members
      from public._pay_timesheet_rotation_scope(v_roots) s;
  end if;
  -- Retain the existing parent intent through commit even before SEND exists.
  -- This narrowly covers the actual manager-signed weekly/no-FIN precursor
  -- required by the missing-A0 arm; it grants no pricing/signature authority.
  -- Other ordinary, historical NULL/dangling and existing-finance rows have
  -- no new parent admission outside an actual active request.
  -- Invoice already has the unchanged archived-Timesheet guard's real parent
  -- intent. Do not duplicate or widen its ordinary/dangling reference policy.
  select array_agg(distinct t.timesheet_id order by t.timesheet_id) into v_parent_ids
    from public.timesheets t where (t.timesheet_id=any(p_ids) or exists(select 1 from unnest(p_bookings) b(value)
      where btrim(t.booking_id)=btrim(b.value)))
      and (t.timesheet_id=any(v_members)
        or (p_kind<>'INVOICE_REFERENCE' and private.timesheet_correction_a0_signed_precursor_v1(t.timesheet_id)));
  if v_parent_ids is not null then
    if cardinality(v_parent_ids)>256 then raise exception 'CORRECTION_A0_WRITER_SCOPE_UNPROVED' using errcode='55000'; end if;
    perform 1 from public.timesheets t where t.timesheet_id=any(v_parent_ids) order by t.timesheet_id for key share nowait;
  end if;
  return jsonb_build_object('requests',coalesce(v_requests,'[]'::jsonb),'parent_ids',coalesce(to_jsonb(v_parent_ids),'[]'::jsonb));
end;
$function$;

create or replace function private._contract_settings_refresh_planned_for_contract_v1(
  p_contract_id uuid
)
returns integer
language plpgsql
volatile
security definer
set search_path = pg_catalog, public, private, extensions, pg_temp
as $function$
declare v_row record; v_count integer:=0;
begin
  for v_row in
    select cw.id from public.contract_weeks cw
    where cw.contract_id=p_contract_id and cw.timesheet_id is null
    order by cw.week_ending_date,cw.id
  loop
    if private._contract_settings_apply_week_snapshot_v1(v_row.id) then
      v_count:=v_count+1;
    end if;
  end loop;
  return v_count;
end
$function$;

create or replace function public._trg_touch_client_from_client_settings()
returns trigger
language plpgsql
as $$
declare
  v_client_id uuid;
begin
  v_client_id := coalesce(new.client_id, old.client_id);

  if v_client_id is not null then
    update public.clients cl
       set rev = coalesce(cl.rev, 0) + 1,
           updated_at = now()
     where cl.id = v_client_id;
  end if;

  if tg_op = 'DELETE' then
    return old;
  else
    return new;
  end if;
end;
$$;

create or replace function private._contract_settings_after_client_v1()
returns trigger language plpgsql volatile security definer
set search_path = pg_catalog, public, private, extensions, pg_temp
as $function$
begin
  if tg_op='DELETE' then
    perform private._contract_settings_refresh_planned_for_client_v1(old.client_id);
    return old;
  end if;
  perform private._contract_settings_refresh_planned_for_client_v1(new.client_id);
  return new;
end
$function$;

CREATE OR REPLACE FUNCTION public.pay_workbench_scope_counter_stage_trg_v1()
RETURNS trigger
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_inherited_generation bigint;
BEGIN
  -- BEGIN A8 OWNER CALLBACK BOUNDARY
  IF NOT private.bpay_next_legacy_callback_enabled_v1() THEN
    RETURN NEW;
  END IF;
  -- END A8 OWNER CALLBACK BOUNDARY
  IF NEW.entity_key !~* '^pay_candidate:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' AND NEW.seq IS NOT DISTINCT FROM OLD.seq THEN
    RETURN NEW;
  END IF;

  IF LOWER(BTRIM(COALESCE(current_setting('cloudtms.scope_generation_finalising', true), 'false')))
       IN ('true', 't', '1', 'yes', 'y', 'on') THEN
    RETURN NEW;
  END IF;

  BEGIN
    v_inherited_generation := NULLIF(BTRIM(COALESCE(
      current_setting('cloudtms.banking_pay_inherited_scope_generation', true),
      ''
    )), '')::bigint;
  EXCEPTION WHEN invalid_text_representation THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_INHERITED_SCOPE_GENERATION_INVALID'
      USING ERRCODE = 'P0001';
  END;

  IF v_inherited_generation IS NOT NULL THEN
    IF TG_OP = 'UPDATE'
       AND v_inherited_generation <= COALESCE(OLD.scope_change_generation, 0) THEN
      -- A retried/equal or older broad-fanout child is already represented.
      -- Preserve the ordinary candidate source sequence as well as generation.
      NEW.seq := OLD.seq;
      NEW.updated_at := OLD.updated_at;
      NEW.scope_change_generation := OLD.scope_change_generation;
      NEW.scope_change_tx_token := NULL::uuid;
      RETURN NEW;
    END IF;

    NEW.scope_change_generation := GREATEST(
      COALESCE(NEW.scope_change_generation, 0),
      v_inherited_generation
    );
    NEW.scope_change_tx_token := NULL::uuid;
  ELSE
    NEW.scope_change_tx_token := public.pay_workbench_scope_change_tx_token_v1();
  END IF;

  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION private.pay_workbench_scope_invalidate_v1(
  p_candidate_ids uuid[],
  p_timesheet_ids uuid[],
  p_reason text,
  p_scope_change_tx_token uuid DEFAULT NULL::uuid,
  p_payload_json jsonb DEFAULT '{}'::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
PARALLEL UNSAFE
SECURITY INVOKER
SET search_path = ''
AS $function$
DECLARE
  v_reason text := NULLIF(btrim(COALESCE(p_reason,'')), '');
  v_payload jsonb := COALESCE(p_payload_json,'{}'::jsonb);
  v_tx_token uuid;
  v_pair_count integer := 0;
  v_candidate_count integer := 0;
  v_timesheet_count integer := 0;
  v_registry_existing integer := 0;
  v_state_existing integer := 0;
  v_registry_affected integer := 0;
  v_state_affected integer := 0;
  v_job_inserted integer := 0;
  v_job_coalesced integer := 0;
  v_job_result jsonb;
  v_candidate record;
  v_source_change_seq bigint := 0;
  v_invalidation_at_utc timestamptz;
  v_pair_candidate_ids uuid[] := ARRAY[]::uuid[];
  v_pair_timesheet_ids uuid[] := ARRAY[]::uuid[];
BEGIN
  -- BEGIN A8 OWNER CALLBACK BOUNDARY
  IF NOT private.bpay_next_legacy_callback_enabled_v1() THEN
    RETURN jsonb_build_object(
      'ok',true,'skipped',true,'skip_reason','FINANCIAL_OWNER_NOT_LEGACY',
      'candidate_count',0,'timesheet_count',0,
      'registry_inserted_count',0,'registry_updated_count',0,
      'state_inserted_count',0,'state_updated_count',0,
      'job_inserted_count',0,'job_coalesced_count',0,
      'scope_change_tx_token',NULL::uuid,'reason',v_reason);
  END IF;
  -- END A8 OWNER CALLBACK BOUNDARY
  IF jsonb_typeof(v_payload) <> 'object' THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_SCOPE_INVALIDATION_INPUT_INVALID'
      USING ERRCODE='22023', DETAIL=jsonb_build_object(
        'code','PAY_WORKBENCH_SCOPE_INVALIDATION_INPUT_INVALID',
        'field','p_payload_json'
      )::text;
  END IF;

  IF v_reason IS NULL
     OR cardinality(COALESCE(p_candidate_ids,ARRAY[]::uuid[]))
        <> cardinality(COALESCE(p_timesheet_ids,ARRAY[]::uuid[])) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_SCOPE_INVALIDATION_INPUT_INVALID'
      USING ERRCODE='22023', DETAIL=jsonb_build_object(
        'code','PAY_WORKBENCH_SCOPE_INVALIDATION_INPUT_INVALID',
        'candidate_count',cardinality(COALESCE(p_candidate_ids,ARRAY[]::uuid[])),
        'timesheet_count',cardinality(COALESCE(p_timesheet_ids,ARRAY[]::uuid[]))
      )::text;
  END IF;

  SELECT COALESCE(
           array_agg(
             canonical_pair.candidate_id
             ORDER BY canonical_pair.candidate_id,
                      canonical_pair.timesheet_id NULLS FIRST
           ),
           ARRAY[]::uuid[]
         ),
         COALESCE(
           array_agg(
             canonical_pair.timesheet_id
             ORDER BY canonical_pair.candidate_id,
                      canonical_pair.timesheet_id NULLS FIRST
           ),
           ARRAY[]::uuid[]
         )
  INTO v_pair_candidate_ids,v_pair_timesheet_ids
  FROM (
    SELECT DISTINCT input_pair.candidate_id,input_pair.timesheet_id
    FROM ROWS FROM (
      pg_catalog.unnest(COALESCE(p_candidate_ids,ARRAY[]::uuid[])),
      pg_catalog.unnest(COALESCE(p_timesheet_ids,ARRAY[]::uuid[]))
    ) AS input_pair(candidate_id,timesheet_id)
    WHERE input_pair.candidate_id IS NOT NULL
  ) AS canonical_pair;

  v_pair_count := cardinality(v_pair_candidate_ids);
  IF v_pair_count = 0 THEN
    RETURN jsonb_build_object(
      'ok',true,'candidate_count',0,'timesheet_count',0,
      'registry_inserted_count',0,'registry_updated_count',0,
      'state_inserted_count',0,'state_updated_count',0,
      'job_inserted_count',0,'job_coalesced_count',0,
      'scope_change_tx_token',NULL,'reason',v_reason
    );
  END IF;

  IF EXISTS (
    SELECT 1
    FROM ROWS FROM (
      pg_catalog.unnest(v_pair_candidate_ids),
      pg_catalog.unnest(v_pair_timesheet_ids)
    ) AS invalidation_pair(candidate_id,timesheet_id)
    LEFT JOIN public.candidates AS candidate_row
      ON candidate_row.id=invalidation_pair.candidate_id
    WHERE candidate_row.id IS NULL
  ) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_SCOPE_INVALIDATION_OWNERSHIP_MISMATCH'
      USING ERRCODE='23503', DETAIL=jsonb_build_object(
        'code','PAY_WORKBENCH_SCOPE_INVALIDATION_OWNERSHIP_MISMATCH',
        'kind','CANDIDATE_NOT_FOUND'
      )::text;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM ROWS FROM (
      pg_catalog.unnest(v_pair_candidate_ids),
      pg_catalog.unnest(v_pair_timesheet_ids)
    ) AS invalidation_pair(candidate_id,timesheet_id)
    LEFT JOIN public.timesheets AS timesheet_row
      ON timesheet_row.timesheet_id=invalidation_pair.timesheet_id
    WHERE invalidation_pair.timesheet_id IS NOT NULL
      AND (
        timesheet_row.timesheet_id IS NULL
        OR EXISTS (
          SELECT 1
          FROM public.timesheets_financials AS ownership_financial
          WHERE ownership_financial.timesheet_id=invalidation_pair.timesheet_id
            AND ownership_financial.is_current
            AND ownership_financial.candidate_id IS DISTINCT FROM invalidation_pair.candidate_id
        )
      )
  ) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_SCOPE_INVALIDATION_OWNERSHIP_MISMATCH'
      USING ERRCODE='23503', DETAIL=jsonb_build_object(
        'code','PAY_WORKBENCH_SCOPE_INVALIDATION_OWNERSHIP_MISMATCH',
        'kind','TIMESHEET_CANDIDATE_MISMATCH'
      )::text;
  END IF;

  v_tx_token := COALESCE(p_scope_change_tx_token,public.pay_workbench_scope_change_tx_token_v1());
  IF NOT EXISTS (
    SELECT 1 FROM public.banking_pay_scope_change_transactions AS scope_tx
    WHERE scope_tx.tx_token=v_tx_token AND scope_tx.state='PENDING'
  ) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_SCOPE_TRANSACTION_TOKEN_INVALID'
      USING ERRCODE='22023', DETAIL=jsonb_build_object(
        'code','PAY_WORKBENCH_SCOPE_TRANSACTION_TOKEN_INVALID',
        'scope_change_tx_token',v_tx_token
      )::text;
  END IF;

  SELECT count(DISTINCT candidate_id)::integer,
         count(DISTINCT timesheet_id) FILTER (WHERE timesheet_id IS NOT NULL)::integer
  INTO v_candidate_count,v_timesheet_count
  FROM ROWS FROM (
    pg_catalog.unnest(v_pair_candidate_ids),
    pg_catalog.unnest(v_pair_timesheet_ids)
  ) AS invalidation_pair(candidate_id,timesheet_id);

  SELECT count(*)::integer INTO v_registry_existing
  FROM private.banking_pay_workbench_candidate_scope_registry AS registry
  WHERE registry.candidate_id IN (
    SELECT DISTINCT candidate_id
    FROM ROWS FROM (
      pg_catalog.unnest(v_pair_candidate_ids),
      pg_catalog.unnest(v_pair_timesheet_ids)
    ) AS invalidation_pair(candidate_id,timesheet_id)
  );

  -- Use one timestamp for every lifecycle column in the proposed inserts.
  -- PostgreSQL validates CHECK constraints on the proposed INSERT row before
  -- resolving ON CONFLICT, so separate clock_timestamp() calls can otherwise
  -- make created_at_utc a few microseconds later than last_dirtied/updated.
  v_invalidation_at_utc := clock_timestamp();
  v_source_change_seq := GREATEST(
    COALESCE(CASE WHEN COALESCE(v_payload->>'latest_source_change_seq','') ~ '^\d+$'
      THEN (v_payload->>'latest_source_change_seq')::bigint END,0),
    COALESCE(CASE WHEN COALESCE(v_payload->>'source_change_seq','') ~ '^\d+$'
      THEN (v_payload->>'source_change_seq')::bigint END,0),
    COALESCE(CASE WHEN COALESCE(v_payload->>'source_change_sequence','') ~ '^\d+$'
      THEN (v_payload->>'source_change_sequence')::bigint END,0)
  );

  INSERT INTO private.banking_pay_workbench_candidate_scope_registry AS registry(
    candidate_id,last_dirty_reason,last_scope_change_tx_token,
    current_source_change_seq,last_dirtied_at_utc,created_at_utc,updated_at_utc
  )
  SELECT DISTINCT candidate_id,v_reason,v_tx_token,v_source_change_seq,
         v_invalidation_at_utc,v_invalidation_at_utc,v_invalidation_at_utc
  FROM ROWS FROM (
    pg_catalog.unnest(v_pair_candidate_ids),
    pg_catalog.unnest(v_pair_timesheet_ids)
  ) AS invalidation_pair(candidate_id,timesheet_id)
  ORDER BY candidate_id
  ON CONFLICT(candidate_id) DO UPDATE
  SET last_dirty_reason=EXCLUDED.last_dirty_reason,
      last_scope_change_tx_token=EXCLUDED.last_scope_change_tx_token,
      current_source_change_seq=GREATEST(
        registry.current_source_change_seq,
        EXCLUDED.current_source_change_seq
      ),
      last_dirtied_at_utc=EXCLUDED.last_dirtied_at_utc,
      updated_at_utc=EXCLUDED.updated_at_utc;
  GET DIAGNOSTICS v_registry_affected = ROW_COUNT;

  SELECT count(*)::integer INTO v_state_existing
  FROM private.banking_pay_workbench_timesheet_scope_state AS scope_state
  WHERE scope_state.timesheet_id IN (
    SELECT timesheet_id
    FROM ROWS FROM (
      pg_catalog.unnest(v_pair_candidate_ids),
      pg_catalog.unnest(v_pair_timesheet_ids)
    ) AS invalidation_pair(candidate_id,timesheet_id)
    WHERE timesheet_id IS NOT NULL
  );

  INSERT INTO private.banking_pay_workbench_timesheet_scope_state AS scope_state(
    timesheet_id,candidate_id,economic_state,dirty_generation,
    last_dirty_reason,last_scope_change_tx_token,registered_at_utc,
    last_dirtied_at_utc,updated_at_utc
  )
  SELECT timesheet_id,candidate_id,'DIRTY',0,v_reason,v_tx_token,
         v_invalidation_at_utc,v_invalidation_at_utc,v_invalidation_at_utc
  FROM ROWS FROM (
    pg_catalog.unnest(v_pair_candidate_ids),
    pg_catalog.unnest(v_pair_timesheet_ids)
  ) AS invalidation_pair(candidate_id,timesheet_id)
  WHERE timesheet_id IS NOT NULL
  ORDER BY candidate_id,timesheet_id
  ON CONFLICT(timesheet_id) DO UPDATE
  SET candidate_id=EXCLUDED.candidate_id,
      economic_state='DIRTY',
      last_dirty_reason=EXCLUDED.last_dirty_reason,
      last_scope_change_tx_token=EXCLUDED.last_scope_change_tx_token,
      last_dirtied_at_utc=EXCLUDED.last_dirtied_at_utc,
      closed_at_utc=NULL,
      updated_at_utc=EXCLUDED.updated_at_utc;
  GET DIAGNOSTICS v_state_affected = ROW_COUNT;

  IF COALESCE((v_payload->>'skip_candidate_job_enqueue')::boolean,false) IS NOT TRUE THEN
    PERFORM set_config('cloudtms.bpay_scope_invalidator_active','true',true);
    FOR v_candidate IN
      SELECT candidate_id,
             COALESCE(array_agg(timesheet_id ORDER BY timesheet_id)
               FILTER (WHERE timesheet_id IS NOT NULL),ARRAY[]::uuid[]) AS timesheet_ids
      FROM ROWS FROM (
        pg_catalog.unnest(v_pair_candidate_ids),
        pg_catalog.unnest(v_pair_timesheet_ids)
      ) AS invalidation_pair(candidate_id,timesheet_id)
      GROUP BY candidate_id
      ORDER BY candidate_id
    LOOP
      v_job_result := public.pay_workbench_dirty_event_enqueue(
        p_job_type=>'WORKBENCH_CANDIDATE_DIRTY_APPLY',
        p_scope_kind=>'CANDIDATE',
        p_scope_id=>v_candidate.candidate_id::text,
        p_candidate_id=>v_candidate.candidate_id,
        p_targeted_timesheet_ids=>v_candidate.timesheet_ids,
        p_linked_timesheet_ids=>ARRAY[]::uuid[],
        p_payload_json=>v_payload || jsonb_build_object(
          'scope_change_tx_token',v_tx_token,
          'bounded_scope_state_precedes_job',true
        ),
        p_reason=>v_reason,
        p_priority=>COALESCE((v_payload->>'priority')::integer,-1000),
        p_run_at_utc=>clock_timestamp()
      );
      IF COALESCE(v_job_result->>'status','')='QUEUED' THEN
        v_job_inserted := v_job_inserted+1;
      ELSE
        v_job_coalesced := v_job_coalesced+1;
      END IF;
      IF COALESCE(v_job_result->>'latest_source_change_seq','') ~ '^\d+$' THEN
        v_source_change_seq := (v_job_result->>'latest_source_change_seq')::bigint;
        UPDATE private.banking_pay_workbench_candidate_scope_registry
        SET current_source_change_seq=GREATEST(current_source_change_seq,v_source_change_seq),
            updated_at_utc=clock_timestamp()
        WHERE candidate_id=v_candidate.candidate_id;
      END IF;
    END LOOP;
  END IF;

  RETURN jsonb_build_object(
    'ok',true,
    'candidate_count',v_candidate_count,
    'timesheet_count',v_timesheet_count,
    'registry_inserted_count',GREATEST(v_registry_affected-v_registry_existing,0),
    'registry_updated_count',LEAST(v_registry_existing,v_registry_affected),
    'state_inserted_count',GREATEST(v_state_affected-v_state_existing,0),
    'state_updated_count',LEAST(v_state_existing,v_state_affected),
    'job_inserted_count',v_job_inserted,
    'job_coalesced_count',v_job_coalesced,
    'scope_change_tx_token',v_tx_token,
    'reason',v_reason
  );
END;
$function$;

CREATE OR REPLACE FUNCTION public.pay_workbench_scope_job_stage_trg_v1()
RETURNS trigger
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_job_type text := UPPER(BTRIM(COALESCE(NEW.job_type, '')));
  v_inherited_generation bigint;
  v_is_source_enqueue boolean := false;
BEGIN
  IF v_job_type = 'WORKBENCH_SCOPE_RECONCILE' THEN
    IF NEW.scope_change_tx_token IS NOT NULL THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_COORDINATOR_SOURCE_TOKEN_FORBIDDEN'
        USING ERRCODE = 'P0001';
    END IF;
    RETURN NEW;
  END IF;

  IF v_job_type NOT IN (
    'WORKBENCH_CANDIDATE_DIRTY_APPLY',
    'WORKBENCH_FINANCE_CASE_DIRTY_APPLY',
    'CONTRACT_CLIENT_DIRTY_FANOUT'
  ) THEN
    RETURN NEW;
  END IF;

  v_is_source_enqueue := TG_OP = 'INSERT'
    OR COALESCE(NEW.payload_json->>'latest_event_at_utc', '')
       IS DISTINCT FROM COALESCE(OLD.payload_json->>'latest_event_at_utc', '');

  IF NOT v_is_source_enqueue THEN
    RETURN NEW;
  END IF;

  BEGIN
    v_inherited_generation := NULLIF(BTRIM(COALESCE(
      current_setting('cloudtms.banking_pay_inherited_scope_generation', true),
      ''
    )), '')::bigint;
  EXCEPTION WHEN invalid_text_representation THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_INHERITED_SCOPE_GENERATION_INVALID'
      USING ERRCODE = 'P0001';
  END;

  IF v_inherited_generation IS NOT NULL THEN
    NEW.scope_change_generation := GREATEST(
      COALESCE(NEW.scope_change_generation, 0),
      v_inherited_generation
    );
    NEW.scope_change_tx_token := NULL::uuid;
  ELSE
    NEW.scope_change_tx_token := public.pay_workbench_scope_change_tx_token_v1();
  END IF;

  RETURN NEW;
END;
$function$;

create or replace function private.weekly_source_observe_effect_v1()
returns trigger language plpgsql security definer
set search_path to 'pg_catalog','pg_temp'
as $fn$
declare v_frame uuid; v_id uuid; v_old_id uuid; v_kind text; v_sealed boolean;
begin
  if pg_catalog.to_regclass('pg_temp.ws_observation_frame_v1') is null then return null; end if;
  perform private.weekly_source_observation_storage_v1();
  select frame_id,sealed into v_frame,v_sealed from pg_temp.ws_observation_frame_v1 where singleton;
  if v_frame is null then return null; end if;
  if v_sealed then raise exception 'WEEKLY_SOURCE_OBSERVATION_WRITE_AFTER_PROOF' using errcode='55000'; end if;
  if tg_relid='public.banking_pay_workbench_jobs'::regclass then
    v_kind:='JOB';
    if tg_op='DELETE' then v_id:=old.id; else v_id:=new.id; end if;
    if tg_op='UPDATE' then v_old_id:=old.id; end if;
  elsif tg_relid='public.banking_pay_scope_change_transactions'::regclass then
    v_kind:='TOKEN';
    if tg_op='DELETE' then v_id:=old.tx_token; else v_id:=new.tx_token; end if;
    if tg_op='UPDATE' then v_old_id:=old.tx_token; end if;
  elsif tg_relid='private.banking_pay_workbench_timesheet_scope_state'::regclass then
    v_kind:='SCOPE';
    if tg_op='DELETE' then v_id:=old.timesheet_id; else v_id:=new.timesheet_id; end if;
    if tg_op='UPDATE' then v_old_id:=old.timesheet_id; end if;
  elsif tg_relid='private.banking_pay_workbench_candidate_scope_registry'::regclass then
    v_kind:='REGISTRY';
    if tg_op='DELETE' then v_id:=old.candidate_id; else v_id:=new.candidate_id; end if;
    if tg_op='UPDATE' then v_old_id:=old.candidate_id; end if;
  else
    raise exception 'WEEKLY_SOURCE_OBSERVATION_RELATION_INVALID' using errcode='55000';
  end if;
  if tg_op='UPDATE' and v_old_id is distinct from v_id then
    raise exception 'WEEKLY_SOURCE_OBSERVATION_IDENTITY_CHANGE' using errcode='55000';
  end if;
  insert into pg_temp.ws_observation_rows_v1(frame_id,kind,row_id,deleted)
    values(v_frame,v_kind,v_id,tg_op='DELETE')
    on conflict(frame_id,kind,row_id) do update
      set deleted=pg_temp.ws_observation_rows_v1.deleted or excluded.deleted;
  return null;
end;
$fn$;

CREATE OR REPLACE FUNCTION public._pay_workbench_dirty_payload_merge(p_existing jsonb, p_incoming jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
  v_existing jsonb := COALESCE(p_existing, '{}'::jsonb);
  v_incoming jsonb := COALESCE(p_incoming, '{}'::jsonb);
  v_merged jsonb := '{}'::jsonb;
  v_latest_source_change_seq bigint := 0;
  v_reason_count integer := 0;
  v_targeted_timesheet_ids jsonb := '[]'::jsonb;
  v_linked_timesheet_ids jsonb := '[]'::jsonb;
  v_trigger_sources jsonb := '[]'::jsonb;
  v_reasons jsonb := '[]'::jsonb;
  v_candidate_ids jsonb := '[]'::jsonb;
  v_finance_case_ids jsonb := '[]'::jsonb;
  v_existing_seq bigint := 0;
  v_incoming_seq bigint := 0;
  v_incoming_has_reason_event boolean := false;
  v_authorise_boundary_changed boolean := false;
  v_unauthorise_boundary_changed boolean := false;
  v_existing_authorise_boundary_changed boolean := false;
  v_incoming_authorise_boundary_changed boolean := false;
  v_existing_unauthorise_boundary_changed boolean := false;
  v_incoming_unauthorise_boundary_changed boolean := false;
  v_explicit_banking_pay_action boolean := false;
  v_existing_explicit_banking_pay_action boolean := false;
  v_incoming_explicit_banking_pay_action boolean := false;
  v_existing_dirty_required boolean := false;
  v_incoming_dirty_required boolean := false;
  v_existing_ordinary_no_dirty boolean := false;
  v_incoming_ordinary_no_dirty boolean := false;
  v_banking_pay_dirty_required boolean := false;
  v_ordinary_timesheet_edit_save_no_dirty boolean := false;
  v_existing_lifecycle_context text := NULL::text;
  v_incoming_lifecycle_context text := NULL::text;
  v_effective_lifecycle_context text := NULL::text;
  v_trigger_table text := NULL::text;
  v_trigger_op text := NULL::text;
  v_trigger_operation text := NULL::text;
  v_projection_class text := NULL::text;
  v_refresh_scope_kind text := NULL::text;
BEGIN
  IF jsonb_typeof(v_existing) IS DISTINCT FROM 'object' THEN
    v_existing := '{}'::jsonb;
  END IF;
  IF jsonb_typeof(v_incoming) IS DISTINCT FROM 'object' THEN
    v_incoming := '{}'::jsonb;
  END IF;

  v_existing_seq := GREATEST(
    COALESCE(CASE WHEN COALESCE(v_existing->>'latest_source_change_seq', '') ~ '^\d+$' THEN (v_existing->>'latest_source_change_seq')::bigint END, 0),
    COALESCE(CASE WHEN COALESCE(v_existing->>'source_change_seq', '') ~ '^\d+$' THEN (v_existing->>'source_change_seq')::bigint END, 0),
    COALESCE(CASE WHEN COALESCE(v_existing->>'source_change_sequence', '') ~ '^\d+$' THEN (v_existing->>'source_change_sequence')::bigint END, 0)
  );
  v_incoming_seq := GREATEST(
    COALESCE(CASE WHEN COALESCE(v_incoming->>'latest_source_change_seq', '') ~ '^\d+$' THEN (v_incoming->>'latest_source_change_seq')::bigint END, 0),
    COALESCE(CASE WHEN COALESCE(v_incoming->>'source_change_seq', '') ~ '^\d+$' THEN (v_incoming->>'source_change_seq')::bigint END, 0),
    COALESCE(CASE WHEN COALESCE(v_incoming->>'source_change_sequence', '') ~ '^\d+$' THEN (v_incoming->>'source_change_sequence')::bigint END, 0)
  );
  v_latest_source_change_seq := GREATEST(v_existing_seq, v_incoming_seq);

  v_existing_authorise_boundary_changed := lower(BTRIM(COALESCE(v_existing->>'authorise_boundary_changed', v_existing->>'timesheet_authorise_boundary_changed', v_existing#>>'{complexity_flags,authorise_boundary_changed}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
  v_incoming_authorise_boundary_changed := lower(BTRIM(COALESCE(v_incoming->>'authorise_boundary_changed', v_incoming->>'timesheet_authorise_boundary_changed', v_incoming#>>'{complexity_flags,authorise_boundary_changed}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
  v_existing_unauthorise_boundary_changed := lower(BTRIM(COALESCE(v_existing->>'unauthorise_boundary_changed', v_existing->>'timesheet_unauthorise_boundary_changed', v_existing#>>'{complexity_flags,unauthorise_boundary_changed}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
  v_incoming_unauthorise_boundary_changed := lower(BTRIM(COALESCE(v_incoming->>'unauthorise_boundary_changed', v_incoming->>'timesheet_unauthorise_boundary_changed', v_incoming#>>'{complexity_flags,unauthorise_boundary_changed}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
  v_authorise_boundary_changed := v_existing_authorise_boundary_changed OR v_incoming_authorise_boundary_changed;
  v_unauthorise_boundary_changed := v_existing_unauthorise_boundary_changed OR v_incoming_unauthorise_boundary_changed;

  v_existing_lifecycle_context := NULLIF(BTRIM(COALESCE(v_existing->>'lifecycle_mutation_context', v_existing->>'mutation_context', v_existing->>'lifecycle_context', '')), '');
  v_incoming_lifecycle_context := NULLIF(BTRIM(COALESCE(v_incoming->>'lifecycle_mutation_context', v_incoming->>'mutation_context', v_incoming->>'lifecycle_context', '')), '');

  IF lower(BTRIM(COALESCE(v_existing_lifecycle_context, ''))) IN ('timesheet_authorise', 'authorise_timesheet')
     OR lower(BTRIM(COALESCE(v_incoming_lifecycle_context, ''))) IN ('timesheet_authorise', 'authorise_timesheet') THEN
    v_authorise_boundary_changed := true;
  END IF;
  IF lower(BTRIM(COALESCE(v_existing_lifecycle_context, ''))) IN ('timesheet_unauthorise', 'unauthorise_timesheet')
     OR lower(BTRIM(COALESCE(v_incoming_lifecycle_context, ''))) IN ('timesheet_unauthorise', 'unauthorise_timesheet') THEN
    v_unauthorise_boundary_changed := true;
  END IF;

  v_effective_lifecycle_context := CASE
    WHEN v_unauthorise_boundary_changed THEN 'timesheet_unauthorise'
    WHEN v_authorise_boundary_changed THEN 'timesheet_authorise'
    ELSE COALESCE(v_incoming_lifecycle_context, v_existing_lifecycle_context)
  END;

  v_existing_explicit_banking_pay_action := lower(BTRIM(COALESCE(v_existing->>'explicit_banking_pay_action', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
  v_incoming_explicit_banking_pay_action := lower(BTRIM(COALESCE(v_incoming->>'explicit_banking_pay_action', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
  v_existing_dirty_required := lower(BTRIM(COALESCE(v_existing->>'banking_pay_dirty_required', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
  v_incoming_dirty_required := lower(BTRIM(COALESCE(v_incoming->>'banking_pay_dirty_required', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
  v_existing_ordinary_no_dirty := lower(BTRIM(COALESCE(v_existing->>'ordinary_timesheet_edit_save_no_dirty', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
  v_incoming_ordinary_no_dirty := lower(BTRIM(COALESCE(v_incoming->>'ordinary_timesheet_edit_save_no_dirty', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');

  v_explicit_banking_pay_action := v_existing_explicit_banking_pay_action
    OR v_incoming_explicit_banking_pay_action
    OR v_authorise_boundary_changed
    OR v_unauthorise_boundary_changed;
  v_ordinary_timesheet_edit_save_no_dirty := (v_existing_ordinary_no_dirty OR v_incoming_ordinary_no_dirty)
    AND v_explicit_banking_pay_action IS NOT TRUE
    AND v_existing_dirty_required IS NOT TRUE
    AND v_incoming_dirty_required IS NOT TRUE
    AND v_authorise_boundary_changed IS NOT TRUE
    AND v_unauthorise_boundary_changed IS NOT TRUE;
  v_banking_pay_dirty_required := v_ordinary_timesheet_edit_save_no_dirty IS NOT TRUE;

  v_trigger_table := CASE
    WHEN (v_authorise_boundary_changed OR v_unauthorise_boundary_changed)
         AND lower(BTRIM(COALESCE(v_existing->>'trigger_table', ''))) = 'timesheets' THEN 'timesheets'
    WHEN (v_authorise_boundary_changed OR v_unauthorise_boundary_changed)
         AND lower(BTRIM(COALESCE(v_incoming->>'trigger_table', ''))) = 'timesheets' THEN 'timesheets'
    ELSE NULLIF(BTRIM(COALESCE(v_incoming->>'trigger_table', v_existing->>'trigger_table', '')), '')
  END;
  v_trigger_op := NULLIF(BTRIM(COALESCE(v_incoming->>'trigger_op', v_incoming->>'trigger_operation', v_existing->>'trigger_op', v_existing->>'trigger_operation', '')), '');
  v_trigger_operation := NULLIF(BTRIM(COALESCE(v_incoming->>'trigger_operation', v_incoming->>'trigger_op', v_existing->>'trigger_operation', v_existing->>'trigger_op', '')), '');

  v_incoming_has_reason_event := (
    NULLIF(BTRIM(COALESCE(v_incoming->>'reason_latest', v_incoming->>'reason', v_incoming->>'trigger_source', '')), '') IS NOT NULL
    OR jsonb_typeof(v_incoming->'reasons') = 'array'
    OR jsonb_typeof(v_incoming->'trigger_sources') = 'array'
  );

  v_reason_count := COALESCE(
      CASE WHEN COALESCE(v_existing->>'reason_count', '') ~ '^\d+$' THEN (v_existing->>'reason_count')::integer END,
      0
    )
    + COALESCE(
      CASE WHEN COALESCE(v_incoming->>'reason_count', '') ~ '^\d+$' THEN (v_incoming->>'reason_count')::integer END,
      CASE WHEN v_incoming_has_reason_event THEN 1 ELSE 0 END
    );

  SELECT COALESCE(jsonb_agg(to_jsonb(union_values.value) ORDER BY union_values.value), '[]'::jsonb)
  INTO v_targeted_timesheet_ids
  FROM (
    SELECT DISTINCT NULLIF(BTRIM(array_values.value), '') AS value
    FROM (
      SELECT value
      FROM jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_existing->'targeted_timesheet_ids') = 'array' THEN v_existing->'targeted_timesheet_ids' ELSE '[]'::jsonb END)
      UNION ALL
      SELECT value
      FROM jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_incoming->'targeted_timesheet_ids') = 'array' THEN v_incoming->'targeted_timesheet_ids' ELSE '[]'::jsonb END)
    ) AS array_values(value)
    WHERE NULLIF(BTRIM(array_values.value), '') IS NOT NULL
  ) AS union_values;

  SELECT COALESCE(jsonb_agg(to_jsonb(union_values.value) ORDER BY union_values.value), '[]'::jsonb)
  INTO v_linked_timesheet_ids
  FROM (
    SELECT DISTINCT NULLIF(BTRIM(array_values.value), '') AS value
    FROM (
      SELECT value
      FROM jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_existing->'linked_timesheet_ids') = 'array' THEN v_existing->'linked_timesheet_ids' ELSE '[]'::jsonb END)
      UNION ALL
      SELECT value
      FROM jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_incoming->'linked_timesheet_ids') = 'array' THEN v_incoming->'linked_timesheet_ids' ELSE '[]'::jsonb END)
    ) AS array_values(value)
    WHERE NULLIF(BTRIM(array_values.value), '') IS NOT NULL
  ) AS union_values;

  SELECT COALESCE(jsonb_agg(to_jsonb(union_values.value) ORDER BY union_values.value), '[]'::jsonb)
  INTO v_trigger_sources
  FROM (
    SELECT DISTINCT NULLIF(BTRIM(array_values.value), '') AS value
    FROM (
      SELECT value
      FROM jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_existing->'trigger_sources') = 'array' THEN v_existing->'trigger_sources' ELSE '[]'::jsonb END)
      UNION ALL
      SELECT value
      FROM jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_incoming->'trigger_sources') = 'array' THEN v_incoming->'trigger_sources' ELSE '[]'::jsonb END)
      UNION ALL
      SELECT COALESCE(v_existing->>'trigger_source', '')
      UNION ALL
      SELECT COALESCE(v_incoming->>'trigger_source', '')
    ) AS array_values(value)
    WHERE NULLIF(BTRIM(array_values.value), '') IS NOT NULL
  ) AS union_values;

  SELECT COALESCE(jsonb_agg(to_jsonb(union_values.value) ORDER BY union_values.value), '[]'::jsonb)
  INTO v_reasons
  FROM (
    SELECT DISTINCT NULLIF(BTRIM(array_values.value), '') AS value
    FROM (
      SELECT value
      FROM jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_existing->'reasons') = 'array' THEN v_existing->'reasons' ELSE '[]'::jsonb END)
      UNION ALL
      SELECT value
      FROM jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_incoming->'reasons') = 'array' THEN v_incoming->'reasons' ELSE '[]'::jsonb END)
      UNION ALL
      SELECT COALESCE(v_existing->>'reason_latest', v_existing->>'reason', '')
      UNION ALL
      SELECT COALESCE(v_incoming->>'reason_latest', v_incoming->>'reason', '')
    ) AS array_values(value)
    WHERE NULLIF(BTRIM(array_values.value), '') IS NOT NULL
  ) AS union_values;

  SELECT COALESCE(jsonb_agg(to_jsonb(union_values.value) ORDER BY union_values.value), '[]'::jsonb)
  INTO v_candidate_ids
  FROM (
    SELECT DISTINCT NULLIF(BTRIM(array_values.value), '') AS value
    FROM (
      SELECT value
      FROM jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_existing->'candidate_ids') = 'array' THEN v_existing->'candidate_ids' ELSE '[]'::jsonb END)
      UNION ALL
      SELECT value
      FROM jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_incoming->'candidate_ids') = 'array' THEN v_incoming->'candidate_ids' ELSE '[]'::jsonb END)
      UNION ALL
      SELECT COALESCE(v_existing->>'candidate_id', '')
      UNION ALL
      SELECT COALESCE(v_incoming->>'candidate_id', '')
      UNION ALL
      SELECT CASE WHEN UPPER(BTRIM(COALESCE(v_existing->>'scope_kind', ''))) = 'CANDIDATE' THEN COALESCE(v_existing->>'scope_id', '') ELSE '' END
      UNION ALL
      SELECT CASE WHEN UPPER(BTRIM(COALESCE(v_incoming->>'scope_kind', ''))) = 'CANDIDATE' THEN COALESCE(v_incoming->>'scope_id', '') ELSE '' END
    ) AS array_values(value)
    WHERE NULLIF(BTRIM(array_values.value), '') IS NOT NULL
  ) AS union_values;

  SELECT COALESCE(jsonb_agg(to_jsonb(union_values.value) ORDER BY union_values.value), '[]'::jsonb)
  INTO v_finance_case_ids
  FROM (
    SELECT DISTINCT NULLIF(BTRIM(array_values.value), '') AS value
    FROM (
      SELECT value
      FROM jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_existing->'finance_case_ids') = 'array' THEN v_existing->'finance_case_ids' ELSE '[]'::jsonb END)
      UNION ALL
      SELECT value
      FROM jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_incoming->'finance_case_ids') = 'array' THEN v_incoming->'finance_case_ids' ELSE '[]'::jsonb END)
      UNION ALL
      SELECT COALESCE(v_existing->>'finance_case_id', '')
      UNION ALL
      SELECT COALESCE(v_incoming->>'finance_case_id', '')
      UNION ALL
      SELECT CASE WHEN UPPER(BTRIM(COALESCE(v_existing->>'scope_kind', ''))) = 'FINANCE_CASE' THEN COALESCE(v_existing->>'scope_id', '') ELSE '' END
      UNION ALL
      SELECT CASE WHEN UPPER(BTRIM(COALESCE(v_incoming->>'scope_kind', ''))) = 'FINANCE_CASE' THEN COALESCE(v_incoming->>'scope_id', '') ELSE '' END
    ) AS array_values(value)
    WHERE NULLIF(BTRIM(array_values.value), '') IS NOT NULL
  ) AS union_values;

  v_merged := v_existing || v_incoming;

  v_projection_class := CASE
    WHEN v_authorise_boundary_changed OR v_unauthorise_boundary_changed THEN 'NORMAL_TIMESHEET'
    ELSE NULLIF(UPPER(BTRIM(COALESCE(v_incoming->>'projection_class', v_existing->>'projection_class', ''))), '')
  END;
  v_refresh_scope_kind := CASE
    WHEN jsonb_array_length(COALESCE(v_targeted_timesheet_ids, '[]'::jsonb)) > 0 THEN 'TARGETED_TIMESHEETS'
    ELSE NULLIF(UPPER(BTRIM(COALESCE(v_incoming->>'refresh_scope_kind', v_existing->>'refresh_scope_kind', ''))), '')
  END;

  v_merged := jsonb_strip_nulls(
    v_merged
    || jsonb_build_object(
      'queue_class', 'DIRTY_TRIGGER_PRIORITY',
      'priority_class', 'DIRTY_TRIGGER_PRIORITY',
      'trigger_table', v_trigger_table,
      'trigger_op', v_trigger_op,
      'trigger_operation', v_trigger_operation,
      'mutation_context', v_effective_lifecycle_context,
      'lifecycle_mutation_context', v_effective_lifecycle_context,
      'authorise_boundary_changed', COALESCE(v_authorise_boundary_changed, false),
      'unauthorise_boundary_changed', COALESCE(v_unauthorise_boundary_changed, false),
      'explicit_banking_pay_action', COALESCE(v_explicit_banking_pay_action, false),
      'banking_pay_dirty_required', COALESCE(v_banking_pay_dirty_required, true),
      'ordinary_timesheet_edit_save_no_dirty', COALESCE(v_ordinary_timesheet_edit_save_no_dirty, false),
      'projection_class', v_projection_class,
      'refresh_scope_kind', v_refresh_scope_kind,
      'targeted_timesheet_ids', v_targeted_timesheet_ids,
      'linked_timesheet_ids', v_linked_timesheet_ids,
      'trigger_sources', v_trigger_sources,
      'reasons', v_reasons,
      'candidate_ids', v_candidate_ids,
      'finance_case_ids', v_finance_case_ids,
      'reason_count', v_reason_count,
      'latest_source_change_seq', v_latest_source_change_seq,
      'source_change_seq', v_latest_source_change_seq,
      'source_change_sequence', v_latest_source_change_seq,
      'latest_event_at_utc', COALESCE(v_incoming->>'latest_event_at_utc', v_incoming->>'event_at_utc', v_existing->>'latest_event_at_utc', v_existing->>'event_at_utc'),
      'reason_latest', COALESCE(v_incoming->>'reason_latest', v_incoming->>'reason', v_existing->>'reason_latest', v_existing->>'reason'),
      'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
      'policy_x_dirtying_only', true,
      'economic_truth_mutation_allowed', false
    )
  );

  RETURN v_merged;
END;
$function$;

create or replace function private._candidate_expense_owned_timesheet_id_v1(
  p_workflow_id uuid,
  p_stored_timesheet_id uuid
)
returns uuid
language plpgsql
stable
security definer
set search_path = pg_catalog, public, private, pg_temp
as $function$
declare
  v_workflow public.candidate_submission_workflows%rowtype;
  v_stored public.timesheets%rowtype;
  v_result uuid;
  v_count integer;
begin
  if p_stored_timesheet_id is null then return null; end if;
  select * into v_workflow from public.candidate_submission_workflows
  where id=p_workflow_id;
  if not found then return null; end if;
  select * into v_stored from public.timesheets old_row
  where old_row.timesheet_id=p_stored_timesheet_id;
  if not found then return null; end if;
  if v_stored.sheet_scope<>'WEEKLY'::public.timesheet_scope_enum then return null; end if;
  if v_stored.is_current and v_stored.archived_at_utc is null then
    return v_stored.timesheet_id;
  end if;
  if nullif(btrim(coalesce(v_stored.booking_id,'')),'') is null then
    return null;
  end if;
  select count(*)::integer,
    case when count(*)=1 then min(candidate.timesheet_id::text)::uuid end
  into v_count,v_result
  from public.timesheets candidate
  where candidate.booking_id=v_stored.booking_id
    and candidate.contract_id is not distinct from v_workflow.contract_id
    and candidate.week_ending_date is not distinct from v_workflow.week_ending_date
    and candidate.sheet_scope='WEEKLY'::public.timesheet_scope_enum
    and candidate.is_current and candidate.archived_at_utc is null;
  if v_count=1 then return v_result; end if;
  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION public.timesheet_archived_evidence_guard_v1()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_old_timesheet_id uuid := CASE WHEN TG_OP IN ('UPDATE', 'DELETE') THEN OLD.timesheet_id ELSE NULL END;
  v_new_timesheet_id uuid := CASE WHEN TG_OP IN ('INSERT', 'UPDATE') THEN NEW.timesheet_id ELSE NULL END;
  v_timesheet_ids uuid[] := array_remove(ARRAY[v_old_timesheet_id, v_new_timesheet_id]::uuid[], NULL);
  v_archived_timesheet_id uuid := NULL;
BEGIN
  PERFORM 1
  FROM public.timesheets AS t
  WHERE t.timesheet_id = ANY(v_timesheet_ids)
  ORDER BY t.timesheet_id
  FOR KEY SHARE OF t;

  SELECT t.timesheet_id
    INTO v_archived_timesheet_id
  FROM public.timesheets AS t
  WHERE t.archived_at_utc IS NOT NULL
    AND t.timesheet_id = ANY(v_timesheet_ids)
  ORDER BY t.timesheet_id
  LIMIT 1;

  IF v_archived_timesheet_id IS NOT NULL THEN
    RAISE EXCEPTION USING
      MESSAGE = 'TIMESHEET_ARCHIVED',
      DETAIL = jsonb_build_object(
        'timesheet_id', v_archived_timesheet_id,
        'reason', 'archived_timesheet_evidence_is_read_only'
      )::text;
  END IF;

  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$function$;

create or replace function private._candidate_evidence_lineage_guard_v1()
returns trigger
language plpgsql
security definer
set search_path = pg_catalog, public, private, pg_temp
as $function$
declare
  v_component public.candidate_submission_components%rowtype;
  v_workflow public.candidate_submission_workflows%rowtype;
  v_paper_page jsonb;
  v_expected_kind text;
  v_expected_role text;
begin
  if new.candidate_component_id is null then return new; end if;
  select * into v_component from public.candidate_submission_components
  where id=new.candidate_component_id;
  if not found or v_component.state<>'IMMUTABLE' or v_component.immutable_at_utc is null then
    raise exception 'CANDIDATE_COMPONENT_NOT_FINAL_SIGNED' using errcode='55000';
  end if;
  if v_component.component_kind='SIGNED_RETURN' then
    if v_component.storage_key is distinct from new.storage_key then
      raise exception 'CANDIDATE_COMPONENT_NOT_FINAL_SIGNED' using errcode='55000';
    end if;
    select * into v_workflow from public.candidate_submission_workflows
    where id=v_component.workflow_id and generation=v_component.workflow_generation
      and route='PAPER' and paper_return_manifest_sha256 is not null;
    if not found then raise exception 'CANDIDATE_PAPER_RETURN_MANIFEST_STALE' using errcode='55000'; end if;
    select expected_page into v_paper_page
    from jsonb_array_elements(v_workflow.paper_return_manifest_json->'pages') expected_page
    where expected_page->>'page_key'=v_component.paper_return_page_key;
    if not found then raise exception 'CANDIDATE_PAPER_RETURN_PAGE_NOT_EXPECTED' using errcode='55000'; end if;
  elsif v_component.final_signed_render_state<>'READY'
     or v_component.final_signed_storage_key is distinct from new.storage_key then
    raise exception 'CANDIDATE_COMPONENT_NOT_FINAL_SIGNED' using errcode='55000';
  end if;
  if v_component.timesheet_id is not null and v_component.timesheet_id is distinct from new.timesheet_id then
    raise exception 'CANDIDATE_COMPONENT_TIMESHEET_MISMATCH' using errcode='22023';
  end if;

  if v_component.component_kind='SIGNED_RETURN' then
    v_expected_kind:=case v_paper_page->>'component_kind'
      when 'HOURS_TIMESHEET' then 'TIMESHEET'
      when 'MILEAGE_FORM' then 'MILEAGE'
      when 'EXPENSE_SUMMARY' then 'OTHER'
      when 'EXPENSE_EVIDENCE' then v_paper_page->>'expense_category'
      else null end;
    v_expected_role:=case v_paper_page->>'component_kind'
      when 'HOURS_TIMESHEET' then 'SIGNED_TIMESHEET'
      when 'MILEAGE_FORM' then 'MILEAGE_CLAIM_FORM'
      when 'EXPENSE_SUMMARY' then 'EXPENSE_MILEAGE_APPROVAL_SUMMARY'
      when 'EXPENSE_EVIDENCE' then 'SOURCE_EVIDENCE'
      else null end;
  else
    v_expected_kind:=case v_component.component_kind
      when 'HOURS_TIMESHEET' then 'TIMESHEET'
      when 'MILEAGE_FORM' then 'MILEAGE'
      when 'EXPENSE_SUMMARY' then 'OTHER'
      when 'EXPENSE_EVIDENCE' then v_component.expense_category
      else null end;
    v_expected_role:=case v_component.component_kind
      when 'HOURS_TIMESHEET' then 'SIGNED_TIMESHEET'
      when 'MILEAGE_FORM' then 'MILEAGE_CLAIM_FORM'
      when 'EXPENSE_SUMMARY' then 'EXPENSE_MILEAGE_APPROVAL_SUMMARY'
      when 'EXPENSE_EVIDENCE' then 'SOURCE_EVIDENCE'
      else null end;
  end if;
  if v_expected_kind is null
     or upper(btrim(new.kind))<>v_expected_kind
     or new.document_role<>v_expected_role then
    raise exception 'CANDIDATE_COMPONENT_DOCUMENT_ROLE_MISMATCH' using errcode='22023';
  end if;
  return new;
end;
$function$;

create or replace function private._candidate_expense_evidence_summary_trigger_v1()
returns trigger
language plpgsql
security definer
set search_path = pg_catalog, public, private, pg_temp
as $function$
declare
  v_old_timesheet_id uuid;
  v_new_timesheet_id uuid;
  v_suppressed boolean:=false;
begin
  begin
    v_suppressed:=coalesce(current_setting(
      'cloudtms.candidate_expense_summary_suppressed',true
    ),'false')='true';
  exception when others then
    v_suppressed:=false;
  end;
  if v_suppressed then
    return coalesce(new,old);
  end if;
  if tg_op<>'INSERT'
     and old.document_role<>'EXPENSE_MILEAGE_APPROVAL_SUMMARY' then
    v_old_timesheet_id:=old.timesheet_id;
  end if;
  if tg_op<>'DELETE'
     and new.document_role<>'EXPENSE_MILEAGE_APPROVAL_SUMMARY' then
    v_new_timesheet_id:=new.timesheet_id;
  end if;
  if v_old_timesheet_id is not null then
    perform private._candidate_expense_summary_queue_v1(
      v_old_timesheet_id,pg_catalog.transaction_timestamp()
    );
  end if;
  if v_new_timesheet_id is not null
     and v_new_timesheet_id is distinct from v_old_timesheet_id then
    perform private._candidate_expense_summary_queue_v1(
      v_new_timesheet_id,pg_catalog.transaction_timestamp()
    );
  end if;
  return coalesce(new,old);
end;
$function$;

create or replace function private.bpay_next_workbench_require_next_v1()
returns void language plpgsql stable security definer set search_path=pg_catalog,private
as $function$
begin
  if not exists(select 1 from private.bpay_next_module_control m where m.id=1 and m.active_owner='NEXT') then
    raise exception using errcode='55000',message='BPAY_NEXT_MODULE_NOT_ACTIVE';
  end if;
end
$function$;

create or replace function private.bpay_next_workbench_schedule_task_v1(
  p_type text,p_candidate_id uuid,p_work_id uuid,p_umbrella_id uuid,p_bank_changed boolean default false,
  p_control_changed boolean default false,p_previous_pending boolean default null)
returns uuid language plpgsql security definer set search_path=pg_catalog,private
as $function$
declare v_key text;v_phase text;v_epoch bigint;v_id uuid;v_task private.bpay_next_workbench_task%rowtype;
  v_metadata private.bpay_next_workbench_candidate_metadata%rowtype;v_work private.bpay_next_work%rowtype;
  v_financial bigint;v_wait boolean;v_through_case uuid;v_through_candidate uuid;v_through_work uuid;v_through_group text;v_through_summary text;
begin
  perform private.bpay_next_workbench_require_next_v1();
  select owner_epoch into strict v_epoch from private.bpay_next_module_control where id=1;
  if p_type not in ('METADATA','ORIGIN','UMBRELLA') or p_type is null or p_bank_changed is null or p_control_changed is null then
    raise exception using errcode='22023',message='BPAY_NEXT_WORKBENCH_TASK_SCOPE_INVALID';end if;
  if p_type='UMBRELLA' then
    if p_candidate_id is not null or p_work_id is not null or p_umbrella_id is null then
      raise exception using errcode='22023',message='BPAY_NEXT_WORKBENCH_TASK_SCOPE_INVALID';end if;
    v_key:='UMBRELLA:'||p_umbrella_id::text;v_phase:='UMBRELLA_CANDIDATE';
    select candidate_id into v_through_candidate from private.bpay_next_workbench_candidate_metadata
      where target_umbrella_id=p_umbrella_id and target_pay_channel='UMBRELLA' order by candidate_id desc limit 1;
  else
    if p_candidate_id is null or p_umbrella_id is not null or (p_type='ORIGIN')<>(p_work_id is not null) then
      raise exception using errcode='22023',message='BPAY_NEXT_WORKBENCH_TASK_SCOPE_INVALID';end if;
    insert into private.bpay_next_worker_control(candidate_id) values(p_candidate_id) on conflict do nothing;
    select financial_view_revision into strict v_financial from private.bpay_next_worker_control
      where candidate_id=p_candidate_id for update;
    if p_type='ORIGIN' then
      select task_row.* into strict v_work from private.bpay_next_work task_row where id=p_work_id and candidate_id=p_candidate_id for update;
      v_wait:=private.bpay_next_work_wait_state_v1(p_work_id);
      select wc.case_id into v_through_case from private.bpay_next_work_collection wc
        where wc.work_id=p_work_id and wc.case_id is not null order by wc.case_id desc limit 1;
      v_key:='ORIGIN:'||p_work_id::text;v_phase:='ORIGIN_CASE';
    else
      select group_key into v_through_group from private.bpay_next_workbench_group
        where candidate_id=p_candidate_id order by group_key desc limit 1;
      v_key:='METADATA:'||p_candidate_id::text;v_phase:='METADATA_GROUP';
      select client_scope||':'||pay_channel||':'||section into v_through_summary
        from private.bpay_next_workbench_candidate_summary where candidate_id=p_candidate_id
        order by (client_scope||':'||pay_channel||':'||section) collate "C" desc limit 1;
    end if;
  end if;
  -- Lock task before metadata/revision, always after Candidate/work.
  select task_row.* into v_task from private.bpay_next_workbench_task task_row where task_key=v_key for update;
  if p_candidate_id is not null then
    v_metadata:=private.bpay_next_workbench_ensure_metadata_v1(p_candidate_id);
    if v_task.id is not null and v_task.status<>'DONE' and v_task.module_epoch=v_epoch
      and (p_type='METADATA' and v_task.metadata_version=v_metadata.metadata_version
        or p_type='ORIGIN' and (v_task.expected_revision_id,v_task.expected_applied_revision_id,
          v_task.expected_approval_state,v_task.financial_view_revision,v_task.expected_wait_state)
          is not distinct from (v_work.current_revision_id,v_work.applied_revision_id,
            v_work.approval_state,v_financial,v_wait)) then return v_task.id;end if;
  end if;
  insert into private.bpay_next_workbench_task(task_key,task_type,candidate_id,work_id,umbrella_id,module_epoch,phase,
    through_work_id,through_case_id,through_candidate_id,through_group_key,through_summary_key,financial_view_revision,metadata_version,
    expected_revision_id,expected_applied_revision_id,expected_approval_state,expected_wait_state,bank_warning_changed,control_changed)
    values(v_key,p_type,p_candidate_id,p_work_id,p_umbrella_id,v_epoch,v_phase,v_through_work,v_through_case,v_through_candidate,v_through_group,v_through_summary,
      v_financial,v_metadata.metadata_version,v_work.current_revision_id,v_work.applied_revision_id,
      v_work.approval_state,v_wait,p_bank_changed,p_control_changed)
    on conflict(task_key) do update set generation=private.bpay_next_workbench_task.generation+1,
      module_epoch=excluded.module_epoch,owner_epoch=private.bpay_next_workbench_task.owner_epoch+1,
      status='READY',phase=excluded.phase,cursor_key=null,through_work_id=excluded.through_work_id,
      through_case_id=excluded.through_case_id,through_candidate_id=excluded.through_candidate_id,through_group_key=excluded.through_group_key,
      through_summary_key=excluded.through_summary_key,
      financial_view_revision=excluded.financial_view_revision,metadata_version=excluded.metadata_version,
      expected_revision_id=excluded.expected_revision_id,expected_applied_revision_id=excluded.expected_applied_revision_id,
      expected_approval_state=excluded.expected_approval_state,expected_wait_state=excluded.expected_wait_state,
      bank_warning_changed=excluded.bank_warning_changed or (private.bpay_next_workbench_task.status<>'DONE'
        and private.bpay_next_workbench_task.bank_warning_changed),
      control_changed=excluded.control_changed or(private.bpay_next_workbench_task.status<>'DONE' and private.bpay_next_workbench_task.control_changed),
      step_no=0,rows_visited=0,
      lease_nonce=null,lease_until_utc=null,wake_after_utc=clock_timestamp(),available_at_utc=clock_timestamp(),
      last_error_code=null,updated_at_utc=transaction_timestamp()
    returning id into v_id;
  if p_candidate_id is not null then
    update private.bpay_next_workbench_candidate_metadata set continuation_pending=true,updated_at_utc=transaction_timestamp()
      where candidate_id=p_candidate_id;
  end if;
  update private.bpay_next_workbench_revision set workbench_revision=workbench_revision+1,
    pending_task_count=pending_task_count+case when v_task.id is null or v_task.status='DONE' then 1 else 0 end,
    dirty_candidate_count=dirty_candidate_count+case when p_candidate_id is not null
      and not coalesce(p_previous_pending,v_metadata.continuation_pending) then 1 else 0 end,
    updated_at_utc=transaction_timestamp() where id=1;
  return v_id;
end
$function$;

create or replace function private.bpay_next_case_list_native_changed_v1()
returns trigger language plpgsql volatile security definer set search_path=pg_catalog,private
as $function$
declare v_id uuid;v_candidate uuid;
begin
 if tg_table_schema<>'private' then raise exception using errcode='42501',message='BPAY_NEXT_CASE_LIST_TRIGGER_SCOPE';end if;
 update private.bpay_next_workbench_revision set workbench_revision=workbench_revision+1,
  updated_at_utc=pg_catalog.transaction_timestamp() where id=1;
 if tg_table_name='bpay_next_workbench_candidate_metadata' then
  v_candidate:=case when tg_op='DELETE' then old.candidate_id else new.candidate_id end;
  if tg_op='UPDATE' and (old.candidate_sort_name,old.tms_ref)
    is not distinct from (new.candidate_sort_name,new.tms_ref) then return null;end if;
  update private.bpay_next_case_list_key k set
   candidate_sort_name=lower(coalesce(m.candidate_sort_name,nullif(btrim(ca.display_name),''),
    nullif(btrim(concat_ws(' ',ca.first_name,ca.last_name)),''),ca.id::text)),
   candidate_display_name=coalesce(m.candidate_sort_name,nullif(btrim(ca.display_name),''),
    nullif(btrim(concat_ws(' ',ca.first_name,ca.last_name)),''),ca.id::text),
   candidate_reference=coalesce(m.tms_ref,ca.tms_ref)
  from public.candidates ca left join private.bpay_next_workbench_candidate_metadata m on m.candidate_id=ca.id
  where k.candidate_id=v_candidate and ca.id=v_candidate;
 elsif tg_table_name='bpay_next_finance_case' then
  v_id:=case when tg_op='DELETE' then old.id else new.id end;
  perform private.bpay_next_case_list_refresh_key_v1(v_id);
 elsif tg_table_name in ('bpay_next_case_rule','bpay_next_case_component','bpay_next_case_period','bpay_next_snooze','bpay_next_work_collection') then
  v_id:=case when tg_op='DELETE' then old.case_id else new.case_id end;
  if v_id is null then return null;end if;
  perform private.bpay_next_case_list_refresh_key_v1(v_id);
 else raise exception using errcode='42501',message='BPAY_NEXT_CASE_LIST_TRIGGER_SCOPE';end if;

 return null;
end
$function$;

create or replace function private.timesheet_correction_origin_v1(p_timesheet_id uuid)
returns text language plpgsql stable security definer
set search_path to 'pg_catalog','public','private','extensions','pg_temp'
as $function$
declare
  v_agency boolean:=false;
  v_signed boolean:=false;
begin
  if to_regprocedure('private.weekly_source_agency_invoice_check_only_v1(uuid)') is not null then
    execute 'select private.weekly_source_agency_invoice_check_only_v1($1)' into v_agency using p_timesheet_id;
    if v_agency is true then return 'AGENCY_INVOICE_CORRECTION'; end if;
  end if;
  if to_regprocedure('private.weekly_source_signed_check_only_v1(uuid)') is not null then
    execute 'select private.weekly_source_signed_check_only_v1($1)' into v_signed using p_timesheet_id;
    if v_signed is true then return 'SIGNED_TIMESHEET_CORRECTION'; end if;
  end if;
  return null;
exception when sqlstate '55000' or sqlstate '22023' then return null;
end;
$function$;

create or replace function private.timesheet_correction_signed_witness_v1(p_timesheet_id uuid,p_lock_rows boolean default false)
returns jsonb language plpgsql security definer
set search_path to 'pg_catalog','public','private','pg_temp'
as $function$
declare
  v_ts public.timesheets%rowtype;
  v_workflow public.candidate_submission_workflows%rowtype;
  v_approval public.candidate_approval_requests%rowtype;
  v_hours public.candidate_submission_components%rowtype;
  v_candidate public.candidate_submission_components%rowtype;
  v_manager public.candidate_submission_components%rowtype;
begin
  select t.* into v_ts from public.timesheets t where t.timesheet_id=p_timesheet_id;
  if v_ts.timesheet_id is null or v_ts.submission_mode::text<>'ELECTRONIC'
    or v_ts.candidate_workflow_id is null or v_ts.candidate_workflow_generation is null then
    raise exception 'CORRECTION_MANAGER_SIGNED_TIMESHEET_REQUIRED' using errcode='55000';
  end if;
  if p_lock_rows then
    perform 1 from public.candidate_submission_workflows w where w.id=v_ts.candidate_workflow_id for update;
    perform 1 from public.candidate_approval_requests a where a.workflow_id=v_ts.candidate_workflow_id
      order by a.id for update;
    perform 1 from public.candidate_submission_components c where c.workflow_id=v_ts.candidate_workflow_id
      and c.workflow_generation=v_ts.candidate_workflow_generation order by c.id for update;
  end if;
  select w.* into v_workflow from public.candidate_submission_workflows w
    where w.id=v_ts.candidate_workflow_id and w.generation=v_ts.candidate_workflow_generation
      and w.route in('EMAIL','PHONE') and w.state='FINALISED'
      and w.workflow_kind in('CONTRACT_HOURS','CONTRACT_COMBINED','DAILY')
      and w.manager_approved_at_utc is not null;
  if (select count(*) from public.candidate_approval_requests a
    where a.workflow_id=v_workflow.id and a.workflow_generation=v_workflow.generation and a.state='APPROVED')<>1
    or (select count(*) from public.candidate_submission_components c
      where c.workflow_id=v_workflow.id and c.workflow_generation=v_workflow.generation
        and c.component_kind='HOURS_TIMESHEET' and c.required and c.state='IMMUTABLE')<>1 then
    raise exception 'CORRECTION_MANAGER_SIGNATURE_WITNESS_AMBIGUOUS' using errcode='55000';
  end if;
  select a.* into v_approval from public.candidate_approval_requests a
    where a.workflow_id=v_workflow.id and a.workflow_generation=v_workflow.generation
      and a.state='APPROVED' order by a.id limit 1;
  select c.* into v_hours from public.candidate_submission_components c
    where c.workflow_id=v_workflow.id and c.workflow_generation=v_workflow.generation
      and c.component_kind='HOURS_TIMESHEET' and c.required and c.state='IMMUTABLE';
  select c.* into v_candidate from public.candidate_submission_components c
    where c.id=v_workflow.candidate_signature_component_id and c.workflow_id=v_workflow.id
      and c.workflow_generation=v_workflow.generation and c.document_role='CANDIDATE_SIGNATURE' and c.state='IMMUTABLE';
  select c.* into v_manager from public.candidate_submission_components c
    where c.id=v_workflow.manager_signature_component_id and c.workflow_id=v_workflow.id
      and c.workflow_generation=v_workflow.generation and c.document_role='MANAGER_SIGNATURE'
      and c.state='IMMUTABLE' and c.approval_request_id=v_approval.id;
  if v_workflow.id is null or v_approval.id is null or v_hours.id is null or v_candidate.id is null or v_manager.id is null
    or nullif(btrim(v_candidate.storage_key),'') is null or nullif(btrim(v_manager.storage_key),'') is null
    or octet_length(v_candidate.source_content_sha256) is distinct from 32
    or octet_length(v_manager.source_content_sha256) is distinct from 32
    or v_hours.review_render_state is distinct from 'READY' or v_hours.final_signed_render_state is distinct from 'READY'
    or nullif(btrim(v_hours.final_signed_storage_key),'') is null
    or octet_length(v_hours.final_signed_content_sha256) is distinct from 32
    or coalesce(v_hours.final_signed_page_count,0)<=0 or coalesce(v_hours.final_signed_byte_size,0)<=0
    or v_hours.review_render_input_sha256 is distinct from v_hours.final_signed_render_input_sha256
    or v_candidate.source_content_sha256 is distinct from v_workflow.candidate_signature_sha256
    or v_manager.source_content_sha256 is distinct from v_workflow.manager_signature_sha256
    or v_ts.r2_nurse_key is distinct from v_candidate.storage_key or v_ts.r2_auth_key is distinct from v_manager.storage_key
    or v_ts.img_sha256_nurse is distinct from encode(v_candidate.source_content_sha256,'hex')
    or v_ts.img_sha256_auth is distinct from encode(v_manager.source_content_sha256,'hex') then
    raise exception 'CORRECTION_MANAGER_SIGNATURE_WITNESS_INVALID' using errcode='55000';
  end if;
  return jsonb_build_object('workflow_id',v_workflow.id,'workflow_generation',v_workflow.generation,
    'approval_request_id',v_approval.id,'hours_component_id',v_hours.id,
    'candidate_component_id',v_candidate.id,'manager_component_id',v_manager.id,
    'candidate_sha256',encode(v_candidate.source_content_sha256,'hex'),
    'manager_sha256',encode(v_manager.source_content_sha256,'hex'),
    'manager_approved_at_utc',v_workflow.manager_approved_at_utc,
    'document_version_id',v_ts.current_document_version_id);
end;
$function$;

create or replace function private.weekly_source_candidate_serial_gate_v1(
  p_candidate_id uuid,
  p_job_type text,
  p_job_id uuid,
  p_reason text
) returns jsonb
language plpgsql
volatile
security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_allowed_job_types constant text[]:=array[
    'WORKBENCH_CANDIDATE_FIRST_AUTHORISATION',
    'WORKBENCH_CANDIDATE_FIRST_AUTHORISATION_WITHDRAWAL',
    'WORKBENCH_CANDIDATE_ENTITLEMENT_PUBLICATION',
    'WORKBENCH_CANDIDATE_PENDING_ENTITLEMENT_RELEASE'
  ];
  v_job_type text:=nullif(pg_catalog.btrim(coalesce(p_job_type,'')),'');
  v_gate jsonb;
  v_decision text;
begin
  -- Any job type outside the four pinned Weekly Source types is refused by this
  -- helper itself, before the installed gate is consulted, because the installed
  -- helper would return BYPASSED for it and take no lock at all.  The refusal
  -- carries the same code as a real BYPASSED so no caller has to learn a second
  -- one; the reason distinguishes the two.
  if p_candidate_id is null
     or v_job_type is null
     or not (v_job_type=any(v_allowed_job_types)) then
    return pg_catalog.jsonb_build_object(
      'ok',false,
      'code','WEEKLY_SOURCE_SERIAL_GATE_BYPASSED',
      'retryable',false,
      'gate','BYPASSED',
      'reason',case when p_candidate_id is null
        then 'CANDIDATE_REQUIRED' else 'JOB_TYPE_NOT_PINNED' end,
      'job_type',v_job_type,
      'candidate_id',p_candidate_id
    );
  end if;

  v_gate:=public._pay_workbench_candidate_serial_try_gate(
    p_job_id:=p_job_id,
    p_candidate_id:=p_candidate_id,
    p_job_type:=v_job_type,
    p_payload_json:=pg_catalog.jsonb_build_object('candidate_id',p_candidate_id::text),
    p_reason:=coalesce(nullif(pg_catalog.btrim(coalesce(p_reason,'')),''),'WEEKLY_SOURCE_ROTATION_AUTHORITY')
  );
  v_decision:=coalesce(nullif(pg_catalog.btrim(coalesce(
    v_gate->>'candidate_serial_gate_decision',''
  )),''),'UNKNOWN');

  -- A GRANTED decision is only trusted when the installed gate actually
  -- attempted and obtained the transaction-scoped advisory lock; anything else
  -- is the BYPASSED failure, never a silent pass.
  if v_decision='GRANTED'
     and coalesce((v_gate->>'advisory_lock_attempted')::boolean,false)
     and coalesce((v_gate->>'advisory_lock_granted')::boolean,false) then
    return pg_catalog.jsonb_build_object(
      'ok',true,'gate','GRANTED','candidate_id',p_candidate_id,'job_type',v_job_type
    );
  elsif v_decision='BLOCKED' then
    return pg_catalog.jsonb_build_object(
      'ok',false,
      'code','WEEKLY_SOURCE_CANDIDATE_BUSY',
      'retryable',true,
      'gate','BLOCKED',
      'candidate_id',p_candidate_id,
      'job_type',v_job_type
    );
  end if;

  return pg_catalog.jsonb_build_object(
    'ok',false,
    'code','WEEKLY_SOURCE_SERIAL_GATE_BYPASSED',
    'retryable',false,
    'gate',v_decision,
    'reason','GATE_DECISION_NOT_GRANTED',
    'candidate_id',p_candidate_id,
    'job_type',v_job_type
  );
end;
$function$;

create or replace function private.weekly_source_lock_family_rows_v1(
  p_requested_timesheet_ids uuid[],
  p_candidate_id uuid default null
) returns jsonb
language plpgsql
volatile
security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_ids uuid[];
  v_before jsonb:='{}'::jsonb;
  v_after jsonb:='{}'::jsonb;
  v_missing_count integer;
  v_foreign_count integer;
  v_split_count integer;
  v_unresolved_count integer;
  v_family record;
  v_families jsonb;
  v_failure text;
begin
  -- Review F6: a NULL element or a duplicate must fail closed, never be dropped
  -- silently.  A caller that builds the array from a nullable variable would
  -- otherwise get ok:true and believe every root it named is locked.
  if p_requested_timesheet_ids is null
     or pg_catalog.cardinality(p_requested_timesheet_ids)=0 then
    return pg_catalog.jsonb_build_object(
      'ok',false,'code','WEEKLY_SOURCE_ROOT_INTEGRITY_FAILURE','retryable',false,
      'reason','NO_REQUESTED_ROOTS'
    );
  end if;
  if pg_catalog.array_position(p_requested_timesheet_ids,null::uuid) is not null then
    return pg_catalog.jsonb_build_object(
      'ok',false,'code','WEEKLY_SOURCE_ROOT_INTEGRITY_FAILURE','retryable',false,
      'reason','REQUESTED_ROOT_NULL_ELEMENT'
    );
  end if;
  if (select pg_catalog.count(distinct requested.timesheet_id)
      from pg_catalog.unnest(p_requested_timesheet_ids) as requested(timesheet_id))
     <>pg_catalog.cardinality(p_requested_timesheet_ids) then
    return pg_catalog.jsonb_build_object(
      'ok',false,'code','WEEKLY_SOURCE_ROOT_INTEGRITY_FAILURE','retryable',false,
      'reason','REQUESTED_ROOT_DUPLICATE'
    );
  end if;

  select pg_catalog.array_agg(requested.timesheet_id order by requested.ord)
  into v_ids
  from pg_catalog.unnest(p_requested_timesheet_ids)
    with ordinality as requested(timesheet_id,ord);

  -- Step 2 (first half): the booking identity of every requested row, read
  -- before any lock is taken so the re-read in step 3 has something to compare.
  select
    coalesce(pg_catalog.jsonb_object_agg(
      timesheet.timesheet_id::text,timesheet.booking_id
    ),'{}'::jsonb),
    pg_catalog.count(*) filter (
      where timesheet.booking_id is null
         or pg_catalog.btrim(timesheet.booking_id)=''
    )
  into v_before,v_missing_count
  from public.timesheets timesheet
  where timesheet.timesheet_id=any(v_ids);

  -- WP-08a review F1: the installed resolver returns NO row at all for a
  -- Timesheet that exists but whose booking_id is blank or whitespace-only, so
  -- a guard that only inspects returned rows never fires.  Every requested id is
  -- therefore accounted for here, explicitly, before any lock is taken.
  if v_missing_count>0
     or (select pg_catalog.count(*) from pg_catalog.jsonb_object_keys(v_before))
        <>pg_catalog.array_length(v_ids,1) then
    return pg_catalog.jsonb_build_object(
      'ok',false,'code','WEEKLY_SOURCE_ROOT_INTEGRITY_FAILURE','retryable',false,
      'reason','BOOKING_IDENTITY_MISSING'
    );
  end if;

  -- Every requested root must belong to the Candidate the caller pinned at the
  -- serial gate.  A root from another Candidate would be serialised under the
  -- wrong Candidate key, so it fails closed rather than proceeding.
  if p_candidate_id is not null then
    select pg_catalog.count(*)
    into v_foreign_count
    from public.timesheets timesheet
    left join public.contracts contract on contract.id=timesheet.contract_id
    where timesheet.timesheet_id=any(v_ids)
      and contract.candidate_id is distinct from p_candidate_id;
    if v_foreign_count>0 then
      return pg_catalog.jsonb_build_object(
        'ok',false,'code','WEEKLY_SOURCE_ROOT_INTEGRITY_FAILURE','retryable',false,
        'reason','ROOT_CANDIDATE_MISMATCH'
      );
    end if;
  end if;

  -- Step 2 (second half): the exact lock set, in the exact order.
  for v_family in
    select distinct_family.trimmed_booking_id,distinct_family.booking_id
    from (
      select distinct
        pg_catalog.btrim(timesheet.booking_id) as trimmed_booking_id,
        timesheet.booking_id as booking_id
      from public.timesheets timesheet
      where timesheet.timesheet_id=any(v_ids)
    ) distinct_family
    order by distinct_family.trimmed_booking_id,distinct_family.booking_id
  loop
    perform pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtext(v_family.trimmed_booking_id)
    );
    if v_family.booking_id<>v_family.trimmed_booking_id then
      perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtext(v_family.booking_id));
    end if;
    perform 1
    from public.timesheets timesheet
    where timesheet.booking_id=v_family.booking_id
    for update;
  end loop;

  -- Step 3: the booking identity must be unchanged since step 2.
  select coalesce(pg_catalog.jsonb_object_agg(
    timesheet.timesheet_id::text,timesheet.booking_id
  ),'{}'::jsonb)
  into v_after
  from public.timesheets timesheet
  where timesheet.timesheet_id=any(v_ids);

  if v_after is distinct from v_before then
    return pg_catalog.jsonb_build_object(
      'ok',false,'code','WEEKLY_SOURCE_ROOT_INTEGRITY_FAILURE','retryable',false,
      'reason','BOOKING_REPOINTED_DURING_LOCK'
    );
  end if;

  -- WP-08a review F3: the confirmed rotation route serialises on the trimmed
  -- key and the schema package keys the one-current-head index on the trimmed
  -- family booking id, but family membership in the installed resolver is by
  -- the exact raw value.  A sibling row whose btrim() matches but whose raw
  -- value differs therefore splits one logical family in two.  That is
  -- ambiguous, not resolvable, so it fails closed.  A single padded booking id
  -- with no such sibling is unaffected (the R37 case).
  --
  -- HANDOVER 2 round-5 Part E, "Rotation readings": this case is a canonical
  -- booking-reference collision and must be named as one, never described
  -- merely as a non-unique family (WP-09b handoff N2, WP-03 handoff N20).  It
  -- is a change of NAME only: the case keeps its own outcome and is never
  -- merged with blank, null, unknown or all-revoked, which keep
  -- BOOKING_IDENTITY_MISSING, ROOT_ID_REQUIRED and CANONICAL_AMBIGUOUS.
  select pg_catalog.count(*)
  into v_split_count
  from (
    select distinct requested.booking_id
    from public.timesheets requested
    where requested.timesheet_id=any(v_ids)
  ) family
  where exists(
    select 1
    from public.timesheets sibling
    where pg_catalog.btrim(sibling.booking_id)=pg_catalog.btrim(family.booking_id)
      and sibling.booking_id<>family.booking_id
  );
  if v_split_count>0 then
    return pg_catalog.jsonb_build_object(
      'ok',false,'code','WEEKLY_SOURCE_ROOT_INTEGRITY_FAILURE','retryable',false,
      'reason','BOOKING_REFERENCE_CANONICAL_COLLISION'
    );
  end if;

  -- Step 4 (completeness, WP-08a review F1): the resolver must return at least
  -- one row for every requested id.  Never return ok:true with fewer families
  -- than the request implies.
  select pg_catalog.count(*)
  into v_unresolved_count
  from pg_catalog.unnest(v_ids) as requested(timesheet_id)
  where not exists(
    select 1
    from public._pay_timesheet_rotation_scope(v_ids) resolved
    where resolved.requested_timesheet_id=requested.timesheet_id
  );
  if v_unresolved_count>0 then
    return pg_catalog.jsonb_build_object(
      'ok',false,'code','WEEKLY_SOURCE_ROOT_INTEGRITY_FAILURE','retryable',false,
      'reason','ROOT_NOT_RETURNED_BY_RESOLVER'
    );
  end if;

  -- Step 4: resolve through the installed Workbench rotation resolver only.
  with requested as (
    select input.timesheet_id,input.ord
    from pg_catalog.unnest(v_ids) with ordinality as input(timesheet_id,ord)
  ),
  scope as (
    select * from public._pay_timesheet_rotation_scope(v_ids)
  ),
  per_request as (
    select
      requested.ord as ord,
      requested.timesheet_id as requested_timesheet_id,
      pg_catalog.min(resolved.booking_id) as family_booking_id,
      pg_catalog.count(distinct resolved.booking_id) as booking_count,
      pg_catalog.min(resolved.canonical_timesheet_id::text)::uuid as canonical_timesheet_id,
      pg_catalog.count(distinct resolved.canonical_timesheet_id::text) as canonical_count,
      pg_catalog.bool_or(resolved.requested_is_canonical) as requested_is_canonical,
      pg_catalog.count(*) as member_count,
      pg_catalog.count(*) filter (where resolved.family_is_current) as current_count,
      pg_catalog.count(distinct resolved.family_version) as distinct_version_count,
      pg_catalog.count(*) filter (where resolved.family_version is null) as null_version_count,
      pg_catalog.count(*) filter (
        where resolved.family_timesheet_id=requested.timesheet_id
      ) as requested_member_count,
      pg_catalog.bool_or(
        resolved.family_timesheet_id=requested.timesheet_id
        and resolved.family_is_current
      ) as family_is_current,
      pg_catalog.count(*) filter (
        where resolved.family_timesheet_id=resolved.canonical_timesheet_id
      ) as canonical_member_count,
      pg_catalog.min(resolved.family_version) filter (
        where resolved.family_timesheet_id=resolved.canonical_timesheet_id
      ) as canonical_version,
      pg_catalog.array_agg(
        resolved.family_timesheet_id
        order by resolved.family_version,resolved.family_timesheet_id
      ) as member_timesheet_ids
    from requested
    left join scope resolved
      on resolved.requested_timesheet_id=requested.timesheet_id
    group by requested.ord,requested.timesheet_id
  ),
  checked as (
    select
      per_request.*,
      case
        when per_request.family_booking_id is null
          or per_request.booking_count<>1
          or per_request.member_count=0
          or per_request.requested_member_count<>1
          then 'FAMILY_UNRESOLVED'
        when per_request.family_booking_id is distinct from (v_before->>per_request.requested_timesheet_id::text)
          then 'BOOKING_REPOINTED_DURING_LOCK'
        when per_request.canonical_timesheet_id is null
          or per_request.canonical_count<>1
          or per_request.canonical_member_count<>1
          then 'CANONICAL_AMBIGUOUS'
        when per_request.current_count<>1 then 'CURRENT_ROW_CARDINALITY'
        when per_request.null_version_count>0
          or per_request.distinct_version_count<>per_request.member_count
          then 'VERSION_NOT_UNIQUE'
        else null
      end as failure_reason
    from per_request
  )
  select
    pg_catalog.min(checked.failure_reason),
    coalesce(pg_catalog.jsonb_agg(
      pg_catalog.jsonb_build_object(
        'requested_timesheet_id',checked.requested_timesheet_id,
        'family_booking_id',checked.family_booking_id,
        'canonical_timesheet_id',checked.canonical_timesheet_id,
        'canonical_version',checked.canonical_version,
        'requested_is_canonical',coalesce(checked.requested_is_canonical,false),
        'family_is_current',coalesce(checked.family_is_current,false),
        'member_timesheet_ids',pg_catalog.to_jsonb(checked.member_timesheet_ids)
      ) order by checked.ord
    ) filter (where checked.failure_reason is null),'[]'::jsonb)
  into v_failure,v_families
  from checked;

  if v_failure is not null then
    return pg_catalog.jsonb_build_object(
      'ok',false,'code','WEEKLY_SOURCE_ROOT_INTEGRITY_FAILURE','retryable',false,
      'reason',v_failure
    );
  end if;

  -- Final completeness assertion: one family per distinct requested id, always.
  if pg_catalog.jsonb_array_length(v_families)
     is distinct from pg_catalog.array_length(v_ids,1) then
    return pg_catalog.jsonb_build_object(
      'ok',false,'code','WEEKLY_SOURCE_ROOT_INTEGRITY_FAILURE','retryable',false,
      'reason','FAMILY_RESULT_INCOMPLETE'
    );
  end if;

  return pg_catalog.jsonb_build_object('ok',true,'families',v_families);
end;
$function$;

create or replace function private._contract_settings_apply_week_snapshot_v1(
  p_week_id uuid
)
returns boolean
language plpgsql
volatile
security definer
set search_path = pg_catalog, public, private, extensions, pg_temp
as $function$
declare
  v_week public.contract_weeks%rowtype;
  v_contract public.contracts%rowtype;
  v_snapshot jsonb;
  v_fingerprint text;
begin
  select * into v_week from public.contract_weeks where id=p_week_id for update;
  if not found or v_week.timesheet_id is not null then return false; end if;
  select * into v_contract from public.contracts where id=v_week.contract_id;
  if not found then raise exception 'CONTRACT_SETTINGS_CONTRACT_NOT_FOUND' using errcode='P0002'; end if;
  v_snapshot:=private._contract_settings_effective_core_v1(
    v_contract.client_id,v_contract.id,v_week.week_ending_date,'WEEKLY',null
  );
  v_fingerprint:=v_snapshot->>'authority_fingerprint';
  if v_week.settings_authority_fingerprint is not distinct from v_fingerprint then
    return false;
  end if;
  update public.contract_weeks set
    submission_mode_snapshot=case
      when coalesce(v_week.is_adjustment,false) or coalesce(v_week.additional_seq,0)>0
        then v_week.submission_mode_snapshot
      else coalesce(
        v_snapshot#>>'{values,default_submission_mode}',
        'ELECTRONIC'
      )::public.submission_mode_enum
    end,
    settings_authority_json=v_snapshot,
    settings_authority_version='CONTRACT_SETTINGS_AUTHORITY_V1',
    settings_authority_fingerprint=v_fingerprint,
    settings_authority_resolved_at=(v_snapshot->>'resolved_at_utc')::timestamptz,
    updated_at=statement_timestamp()
  where id=v_week.id and timesheet_id is null;
  return found;
end
$function$;

CREATE OR REPLACE FUNCTION public.pay_workbench_scope_change_tx_token_v1()
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_token uuid;
  v_state text;
BEGIN
  IF LOWER(BTRIM(COALESCE(current_setting('cloudtms.scope_generation_finalising', true), 'false')))
       IN ('true', 't', '1', 'yes', 'y', 'on') THEN
    RETURN NULL::uuid;
  END IF;

  BEGIN
    v_token := NULLIF(BTRIM(COALESCE(
      current_setting('cloudtms.banking_pay_scope_tx_token', true),
      ''
    )), '')::uuid;
  EXCEPTION WHEN invalid_text_representation THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_SCOPE_TRANSACTION_TOKEN_INVALID'
      USING ERRCODE = 'P0001';
  END;

  -- This finalizer seals transaction-wide collected work. Under an IMMEDIATE
  -- entry mode its token INSERT must not finalize before counters/jobs exist.
  -- Defer this internal finalizer only, preserving every other constraint mode.
  SET CONSTRAINTS public.trg_pay_workbench_scope_change_finalize_v1 DEFERRED;

  IF v_token IS NULL THEN
    v_token := gen_random_uuid();
    PERFORM set_config('cloudtms.banking_pay_scope_tx_token', v_token::text, true);
    INSERT INTO public.banking_pay_scope_change_transactions(
      tx_token, state, created_at_utc
    ) VALUES (
      v_token, 'PENDING', clock_timestamp()
    );
    RETURN v_token;
  END IF;

  SELECT scope_tx.state
  INTO v_state
  FROM public.banking_pay_scope_change_transactions AS scope_tx
  WHERE scope_tx.tx_token = v_token;

  IF v_state IN ('FINALIZED', 'NOOP') THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_SCOPE_GENERATION_FINALIZED_TOO_EARLY'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_SCOPE_GENERATION_FINALIZED_TOO_EARLY',
              'state', v_state
            )::text;
  END IF;

  INSERT INTO public.banking_pay_scope_change_transactions(
    tx_token, state, created_at_utc
  ) VALUES (
    v_token, 'PENDING', clock_timestamp()
  ) ON CONFLICT (tx_token) DO NOTHING;

  RETURN v_token;
END;
$function$;

create or replace function private.weekly_source_observation_storage_v1()
returns void language plpgsql security definer
set search_path to 'pg_catalog','pg_temp'
as $fn$
declare v_name text; v_rel oid; v_owner oid;
begin
  select oid into strict v_owner from pg_catalog.pg_roles where rolname=current_user;
  foreach v_name in array array['ws_observation_frame_v1','ws_observation_rows_v1','ws_inventory_checked_v1'] loop
    select c.oid into v_rel from pg_catalog.pg_class c
      where c.relnamespace=pg_catalog.pg_my_temp_schema() and c.relname=v_name;
    if v_rel is not null and not exists (
      select 1 from pg_catalog.pg_class c where c.oid=v_rel
        and c.relowner=v_owner and c.relpersistence='t' and c.relkind='r'
    ) then
      raise exception 'WEEKLY_SOURCE_OBSERVATION_STORAGE_UNTRUSTED' using errcode='42501';
    end if;
  end loop;
  if pg_catalog.to_regclass('pg_temp.ws_observation_frame_v1') is null then
    create temporary table pg_temp.ws_observation_frame_v1 (
      singleton boolean primary key check(singleton), frame_id uuid not null,
      sealed boolean not null default false
    ) on commit delete rows;
    revoke all on pg_temp.ws_observation_frame_v1 from public,anon,authenticated,service_role;
  end if;
  if pg_catalog.to_regclass('pg_temp.ws_observation_rows_v1') is null then
    create temporary table pg_temp.ws_observation_rows_v1 (
      frame_id uuid not null, kind text not null check(kind in ('JOB','TOKEN','SCOPE','REGISTRY')),
      row_id uuid not null, deleted boolean not null default false,
      primary key(frame_id,kind,row_id)
    ) on commit delete rows;
    revoke all on pg_temp.ws_observation_rows_v1 from public,anon,authenticated,service_role;
  end if;
  if pg_catalog.to_regclass('pg_temp.ws_inventory_checked_v1') is null then
    create temporary table pg_temp.ws_inventory_checked_v1 (
      head_id uuid primary key
    ) on commit delete rows;
    revoke all on pg_temp.ws_inventory_checked_v1 from public,anon,authenticated,service_role;
  end if;
end;
$fn$;

create or replace function public.trg_invoice_document_immutability_guard()
returns trigger
language plpgsql
set search_path to 'pg_catalog'
as $function$
begin
  if tg_table_name='invoice_document_versions' then
    if tg_op='DELETE' then
      if old.status='READY' then
        raise exception using errcode='55000',
          message='IMMUTABLE_READY_DOCUMENT';
      end if;
      return old;
    end if;

    if old.status='READY'
       and(
         new.operation_id is distinct from old.operation_id
         or new.entity_type is distinct from old.entity_type
         or new.entity_id is distinct from old.entity_id
         or new.purpose is distinct from old.purpose
         or new.source_revision is distinct from old.source_revision
         or new.template_version is distinct from old.template_version
         or new.snapshot_json is distinct from old.snapshot_json
         or new.snapshot_hash is distinct from old.snapshot_hash
         or new.manifest_json is distinct from old.manifest_json
         or new.manifest_hash is distinct from old.manifest_hash
         or new.r2_key is distinct from old.r2_key
         or new.sha256 is distinct from old.sha256
         or new.size_bytes is distinct from old.size_bytes
         or new.expected_page_count is distinct from old.expected_page_count
         or new.page_count is distinct from old.page_count
         or new.core_page_count is distinct from old.core_page_count
         or new.supporting_page_count is distinct from old.supporting_page_count
         or new.ready_at_utc is distinct from old.ready_at_utc
         or new.verified_at_utc is distinct from old.verified_at_utc
      ) then
      raise exception using errcode='55000',
        message='IMMUTABLE_READY_DOCUMENT';
    end if;
    if old.status='READY' and old.purpose='FINAL_ISSUE'
       and new.status is distinct from old.status then
      raise exception using errcode='55000',
        message='IMMUTABLE_READY_FINAL_ISSUE_STATUS';
    end if;
    if old.status='READY' and old.purpose<>'FINAL_ISSUE'
       and new.status not in('READY','SUPERSEDED') then
      raise exception using errcode='55000',
        message='READY_DOCUMENT_MAY_ONLY_BE_SUPERSEDED';
    end if;
    return new;
  end if;

  if tg_table_name='invoice_document_assets' then
    if tg_op='DELETE' then
      if old.status='READY' then
        raise exception using errcode='55000',
          message='IMMUTABLE_READY_DOCUMENT_ASSET';
      end if;
      return old;
    end if;
    if new.source_kind is distinct from old.source_kind
       or new.source_id is distinct from old.source_id
       or new.source_revision is distinct from old.source_revision
       or new.original_r2_key is distinct from old.original_r2_key
       or(old.original_sha256 is not null
          and new.original_sha256 is distinct from old.original_sha256) then
      raise exception using errcode='55000',
        message='IMMUTABLE_DOCUMENT_ASSET_SOURCE_IDENTITY';
    end if;
    if old.status='READY' and(
       new.status is distinct from old.status
       or new.normalised_manifest_json is distinct from old.normalised_manifest_json
       or new.normalised_r2_key is distinct from old.normalised_r2_key
       or new.normalised_sha256 is distinct from old.normalised_sha256
       or new.normalised_manifest_hash is distinct from old.normalised_manifest_hash
       or new.normalised_size_bytes is distinct from old.normalised_size_bytes
       or new.normalised_page_count is distinct from old.normalised_page_count
       or new.ready_at_utc is distinct from old.ready_at_utc) then
      raise exception using errcode='55000',
        message='IMMUTABLE_READY_DOCUMENT_ASSET_OUTPUT';
    end if;
    return new;
  end if;

  raise exception using errcode='55000',
    message='IMMUTABILITY_GUARD_ATTACHED_TO_UNSUPPORTED_TABLE';
end;
$function$;

create or replace function public.trg_invoices_set_invoice_no()
returns trigger
language plpgsql
as $$
begin
  if new.invoice_no is null or btrim(new.invoice_no) = '' then
    new.invoice_no := public.invoice_no_next();
  end if;
  return new;
end;
$$;

create or replace function private.weekly_source_invoice_issue_guard_v1()
returns trigger
language plpgsql security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
begin
  if coalesce(
    new.header_snapshot_json#>>'{meta,source}'='WEEKLY_FINAL_SOURCE'
    and new.header_snapshot_json#>>'{meta,self_bill}'='true',false
  ) then
    if (old.status::text<>'ISSUED' and new.status::text='ISSUED')
       or (old.issue_state<>'ISSUED' and new.issue_state='ISSUED') then
      if not exists(
        select 1 from public.weekly_source_invoice_line_bindings binding
        where binding.invoice_id=new.id and binding.state='CURRENT'
      ) then
        raise exception 'WEEKLY_SOURCE_INVOICE_EMPTY' using errcode='55000';
      end if;
      perform private.weekly_source_invoice_allocation_assert_v1(new.id);
      update public.weekly_source_billing_movements movement
      set placement_state='ISSUED'
      from public.weekly_source_invoice_line_bindings binding
      where binding.invoice_id=new.id and binding.state='CURRENT'
        and binding.billing_movement_id=movement.id
        and movement.placement_state='PLACED';
    elsif old.status::text='ISSUED' and new.status::text='DRAFT' then
      update public.weekly_source_billing_movements movement
      set placement_state='PLACED'
      from public.weekly_source_invoice_line_bindings binding
      where binding.invoice_id=new.id and binding.state='CURRENT'
        and binding.billing_movement_id=movement.id
        and movement.placement_state='ISSUED';
    end if;
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.timesheet_archive_row_guard_v1()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  v_archive_fields_changed boolean := false;
  v_transition_action text := NULL;
  v_capability_token uuid := NULL;
  v_capability_consumed boolean := false;
  v_old_without_archive jsonb;
  v_new_without_archive jsonb;
BEGIN
  -- Archive metadata cannot be manufactured while inserting a new timesheet.
  -- Every Archive starts from an existing authoritative row and must pass
  -- through timesheet_archive_transition_v1.
  IF TG_OP = 'INSERT' THEN
    IF NEW.archived_at_utc IS NOT NULL
       OR NEW.archived_by_user_id IS NOT NULL
       OR NEW.archived_reason_code IS NOT NULL THEN
      RAISE EXCEPTION USING
        MESSAGE = 'ARCHIVE_TRANSITION_RPC_REQUIRED',
        DETAIL = jsonb_build_object(
          'timesheet_id', NEW.timesheet_id,
          'action', 'ARCHIVE',
          'reason', 'archive_metadata_on_insert_is_forbidden'
        )::text;
    END IF;
    RETURN NEW;
  END IF;

  IF TG_OP = 'DELETE' THEN
    IF OLD.archived_at_utc IS NOT NULL THEN
      RAISE EXCEPTION USING
        MESSAGE = 'TIMESHEET_ARCHIVED',
        DETAIL = jsonb_build_object(
          'timesheet_id', OLD.timesheet_id,
          'reason', 'ordinary_delete_for_archived_timesheet_is_forbidden'
        )::text;
    END IF;
    RETURN OLD;
  END IF;

  IF NEW.archived_at_utc IS NULL THEN
    IF NEW.archived_by_user_id IS NOT NULL OR NEW.archived_reason_code IS NOT NULL THEN
      RAISE EXCEPTION USING MESSAGE = 'ARCHIVE_METADATA_INVALID';
    END IF;
  ELSE
    IF NEW.archived_by_user_id IS NULL OR NULLIF(BTRIM(NEW.archived_reason_code), '') IS NULL THEN
      RAISE EXCEPTION USING MESSAGE = 'ARCHIVE_METADATA_INVALID';
    END IF;
    IF NEW.authorised_at_server IS NOT NULL THEN
      RAISE EXCEPTION USING MESSAGE = 'TIMESHEET_MUST_BE_UNAUTHORISED_BEFORE_ARCHIVE';
    END IF;
  END IF;

  v_archive_fields_changed :=
    NEW.archived_at_utc IS DISTINCT FROM OLD.archived_at_utc
    OR NEW.archived_by_user_id IS DISTINCT FROM OLD.archived_by_user_id
    OR NEW.archived_reason_code IS DISTINCT FROM OLD.archived_reason_code;

  IF v_archive_fields_changed THEN
    IF OLD.archived_at_utc IS NULL AND NEW.archived_at_utc IS NOT NULL THEN
      v_transition_action := 'ARCHIVE';
    ELSIF OLD.archived_at_utc IS NOT NULL AND NEW.archived_at_utc IS NULL THEN
      v_transition_action := 'UNARCHIVE';
    ELSE
      RAISE EXCEPTION USING
        MESSAGE = 'ARCHIVE_TRANSITION_INVALID',
        DETAIL = jsonb_build_object('timesheet_id', OLD.timesheet_id)::text;
    END IF;

    v_old_without_archive := to_jsonb(OLD) - ARRAY[
      'archived_at_utc', 'archived_by_user_id', 'archived_reason_code', 'updated_at'
    ];
    v_new_without_archive := to_jsonb(NEW) - ARRAY[
      'archived_at_utc', 'archived_by_user_id', 'archived_reason_code', 'updated_at'
    ];

    IF v_new_without_archive IS DISTINCT FROM v_old_without_archive THEN
      RAISE EXCEPTION USING
        MESSAGE = 'ARCHIVE_TRANSITION_METADATA_ONLY',
        DETAIL = jsonb_build_object('timesheet_id', OLD.timesheet_id)::text;
    END IF;

    BEGIN
      v_capability_token := NULLIF(
        current_setting('cloudtms.archive_transition_capability', true),
        ''
      )::uuid;
    EXCEPTION
      WHEN invalid_text_representation THEN
        v_capability_token := NULL;
    END;

    IF v_capability_token IS NOT NULL THEN
      DELETE FROM public.timesheet_archive_transition_capability AS capability
      WHERE capability.capability_token = v_capability_token
        AND capability.backend_pid = pg_backend_pid()
        AND capability.transaction_id = txid_current()
        AND capability.timesheet_id = OLD.timesheet_id
        AND capability.action = v_transition_action
      RETURNING true INTO v_capability_consumed;
    END IF;

    IF COALESCE(v_capability_consumed, false) IS DISTINCT FROM true THEN
      RAISE EXCEPTION USING
        MESSAGE = 'ARCHIVE_TRANSITION_RPC_REQUIRED',
        DETAIL = jsonb_build_object(
          'timesheet_id', OLD.timesheet_id,
          'action', v_transition_action
        )::text;
    END IF;
  ELSIF OLD.archived_at_utc IS NOT NULL THEN
    v_old_without_archive := to_jsonb(OLD) - ARRAY['updated_at'];
    v_new_without_archive := to_jsonb(NEW) - ARRAY['updated_at'];
    IF v_new_without_archive IS DISTINCT FROM v_old_without_archive THEN
      RAISE EXCEPTION USING
        MESSAGE = 'TIMESHEET_ARCHIVED',
        DETAIL = jsonb_build_object(
          'timesheet_id', OLD.timesheet_id,
          'reason', 'archived_timesheet_content_is_read_only'
        )::text;
    END IF;
  END IF;

  RETURN NEW;
END;
$function$;

