CREATE OR REPLACE FUNCTION public.timesheets_invalidate_prevalidation_on_change()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
declare
  v_tv_status public.validation_status_enum;
  v_tv_pre_validated boolean;
  v_tv_hr_request_id text;
  v_tv_hr_request_source public.reference_source_enum;

  v_changed boolean := false;

  -- DAILY change flags
  v_daily_changed_worked boolean := false;
  v_daily_changed_break boolean := false;
  v_daily_changed_refnum boolean := false;
  v_daily_changed_dayrefs boolean := false;

  -- WEEKLY change flags
  v_weekly_changed_sched boolean := false;
  v_weekly_changed_refnum boolean := false;
  v_weekly_changed_dayrefs boolean := false;
  v_weekly_changed_units_week boolean := false;
  v_weekly_changed_units_per_day boolean := false;

  v_ignore_daily_ref_autoset boolean := false;
begin
  if tg_op <> 'UPDATE' then
    return new;
  end if;

  -- Only apply to current row updates
  if coalesce(new.is_current, false) is not true then
    return new;
  end if;

  -- If the old row was not current, do not invalidate (avoid version-rotation noise)
  if coalesce(old.is_current, false) is not true then
    return new;
  end if;

  -- Load current validation row (if any)
  select
    tv.status,
    coalesce(tv.pre_validated, false),
    tv.hr_request_id,
    tv.hr_request_source
  into
    v_tv_status,
    v_tv_pre_validated,
    v_tv_hr_request_id,
    v_tv_hr_request_source
  from public.timesheet_validations tv
  where tv.timesheet_id = new.timesheet_id
  limit 1;

  if not found then
    return new;
  end if;

  -- Only invalidate when validation was previously "good" OR pre_validated was set
  if not (
    v_tv_pre_validated is true
    or v_tv_status = 'VALIDATION_OK'::public.validation_status_enum
    or v_tv_status = 'OVERRIDDEN'::public.validation_status_enum
  ) then
    return new;
  end if;

  -- ─────────────────────────────────────────────
  -- Determine whether validation-relevant truth changed
  -- ─────────────────────────────────────────────
  if new.sheet_scope = 'DAILY'::public.timesheet_scope_enum then
    v_daily_changed_worked :=
      (new.worked_start_iso is distinct from old.worked_start_iso)
      or (new.worked_end_iso is distinct from old.worked_end_iso);

    v_daily_changed_break :=
      (new.break_start_iso is distinct from old.break_start_iso)
      or (new.break_end_iso is distinct from old.break_end_iso)
      or (new.break_minutes is distinct from old.break_minutes);

    v_daily_changed_refnum :=
      (new.reference_number is distinct from old.reference_number);

    v_daily_changed_dayrefs :=
      (new.day_references_json is distinct from old.day_references_json);

    -- Special-case: DAILY reference_number auto-set to imported HR request id
    -- Do NOT invalidate if the ONLY relevant change is reference_number and it matches the imported hr_request_id.
    if v_daily_changed_refnum is true
       and v_daily_changed_worked is false
       and v_daily_changed_break is false
       and v_daily_changed_dayrefs is false
       and v_tv_hr_request_source = 'IMPORTED'::public.reference_source_enum
       and v_tv_hr_request_id is not null
       and new.reference_number is not distinct from v_tv_hr_request_id
    then
      v_ignore_daily_ref_autoset := true;
    end if;

    v_changed :=
      (v_daily_changed_worked or v_daily_changed_break or v_daily_changed_dayrefs or v_daily_changed_refnum)
      and v_ignore_daily_ref_autoset is false;

  elsif new.sheet_scope = 'WEEKLY'::public.timesheet_scope_enum then
    v_weekly_changed_sched :=
      (new.actual_schedule_json is distinct from old.actual_schedule_json);

    v_weekly_changed_refnum :=
      (new.reference_number is distinct from old.reference_number);

    v_weekly_changed_dayrefs :=
      (new.day_references_json is distinct from old.day_references_json);

    v_weekly_changed_units_week :=
      (new.additional_units_week is distinct from old.additional_units_week);

    v_weekly_changed_units_per_day :=
      (new.additional_units_per_day is distinct from old.additional_units_per_day);

    v_changed :=
      v_weekly_changed_sched
      or v_weekly_changed_refnum
      or v_weekly_changed_dayrefs
      or v_weekly_changed_units_week
      or v_weekly_changed_units_per_day;
  else
    return new;
  end if;

  if v_changed is not true then
    return new;
  end if;

  -- ─────────────────────────────────────────────
  -- Invalidate pre-validation + force re-validation
  -- ─────────────────────────────────────────────
  update public.timesheet_validations tvu
     set status = 'PENDING'::public.validation_status_enum,
         pre_validated = false,
         validated_at_utc = null,
         reason_code = 'TIMESHEET_CHANGED',
         updated_at = now()
   where tvu.timesheet_id = new.timesheet_id;

  return new;
end;
$function$;

create or replace function private._candidate_qr_pack_ready_notification_v1()
returns trigger
language plpgsql
security definer
set search_path = pg_catalog, public, private, pg_temp
as $function$
declare
  v_notification jsonb;
begin
  if (not private._candidate_feature_enabled_current_v1('candidate_route_confirmation')
       and not private._candidate_office_service_context_valid_v1(null,null,'ROUTE_CONFIRM'))
     or new.candidate_submission_route_intent is distinct from 'PAPER'
     or new.sheet_scope is distinct from 'WEEKLY'::public.timesheet_scope_enum
     or upper(coalesce(new.document_state::text,''))<>'READY'
     or upper(coalesce(new.qr_status::text,'')) not in ('PENDING','SENT','READY') then
    return new;
  end if;
  if new.current_document_version_id is null or not exists(
    select 1 from public.invoice_document_versions document_version
    where document_version.id=new.current_document_version_id
      and document_version.entity_type='TIMESHEET'
      and document_version.entity_id=new.timesheet_id
      and upper(document_version.status)='READY'
  ) then
    return new;
  end if;
  if exists(
    select 1
    from public.candidate_submission_workflows workflow
    where workflow.route='PAPER'
      and workflow.state='AWAITING_PAPER_RETURN'
      and (workflow.target_timesheet_id=new.timesheet_id
        or workflow.anchor_timesheet_id=new.timesheet_id)
  ) then
    return new;
  end if;
  v_notification:=private._timesheet_route_resubmission_notifications_v1(
    new.timesheet_id,new.timesheet_id,new.version,'ALLOW_QR_AGAIN',now()
  );
  new.candidate_submission_route_intent:=null;
  return new;
end;
$function$;

create or replace function private._timesheet_authorisation_overlap_trg_v1()
returns trigger language plpgsql volatile security definer
set search_path='public','private','pg_temp' as $function$
declare
  v_candidate_id uuid;
  v_candidate_count integer:=0;
  v_fin_schedule jsonb;
  v_fin_start timestamptz;
  v_fin_end timestamptz;
  v_interval_count integer:=0;
begin
  if new.authorised_at_server is null then return new; end if;
  if tg_op='UPDATE' and old.authorised_at_server is not distinct from new.authorised_at_server then
    return new;
  end if;

  select f.actual_schedule_json,f.worked_start_iso,f.worked_end_iso
  into v_fin_schedule,v_fin_start,v_fin_end
  from public.timesheets_financials f
  where f.timesheet_id=new.timesheet_id and f.is_current=true
  order by f.updated_at desc nulls last,f.created_at desc nulls last,f.id desc
  limit 1;

  select count(*)::integer into v_interval_count
  from private._timesheet_work_intervals_v1(
    '{}'::jsonb,COALESCE(new.actual_schedule_json,v_fin_schedule),
    COALESCE(new.worked_start_iso,v_fin_start),COALESCE(new.worked_end_iso,v_fin_end)
  );
  if v_interval_count=0 then return new; end if;

  with candidate_ids as (
    select w.candidate_id
    from public.candidate_submission_workflows w
    where w.id=new.candidate_workflow_id
    union
    select f.candidate_id
    from public.timesheets_financials f
    where f.timesheet_id=new.timesheet_id and f.is_current=true and f.candidate_id is not null
    union
    select c.candidate_id from public.contracts c where c.id=new.contract_id and c.candidate_id is not null
    union
    select c.id from public.candidates c
    where c.key_norm is not null and c.key_norm=new.occupant_key_norm
  )
  select count(*)::integer,min(candidate_id::text)::uuid
  into v_candidate_count,v_candidate_id from candidate_ids;

  if v_candidate_count<>1 or v_candidate_id is null then
    raise exception using
      errcode='PT409',
      message='TIMESHEET_CANDIDATE_IDENTITY_REQUIRED_FOR_OVERLAP_CHECK';
  end if;

  perform private._timesheet_cross_record_overlap_assert_v1(
    v_candidate_id,'{}'::jsonb,COALESCE(new.actual_schedule_json,v_fin_schedule),
    COALESCE(new.worked_start_iso,v_fin_start),COALESCE(new.worked_end_iso,v_fin_end),
    new.candidate_workflow_id,new.timesheet_id,new.booking_id
  );
  return new;
end;$function$;

create or replace function private._timesheet_settings_authority_before_v1()
returns trigger
language plpgsql
volatile
security definer
set search_path = pg_catalog, public, private, extensions, pg_temp
as $function$
declare
  v_contract public.contracts%rowtype;
  v_snapshot jsonb;
  v_client_id uuid;
  v_relevant_date date;
begin
  if tg_op='UPDATE' and old.settings_authority_json<>'{}'::jsonb then
    new.settings_authority_json:=old.settings_authority_json;
    new.settings_authority_version:=old.settings_authority_version;
    new.settings_authority_fingerprint:=old.settings_authority_fingerprint;
    new.settings_authority_resolved_at:=old.settings_authority_resolved_at;
    return new;
  end if;
  if new.sheet_scope<>'WEEKLY'::public.timesheet_scope_enum then
    if tg_op='INSERT' then
      new.settings_authority_json:='{}'::jsonb;
      new.settings_authority_version:=null;
      new.settings_authority_fingerprint:=null;
      new.settings_authority_resolved_at:=null;
      return new;
    end if;
    select tf.client_id into v_client_id
    from public.timesheets_financials tf
    where tf.timesheet_id=new.timesheet_id and tf.is_current=true
      and tf.processed_at_utc is not null
    order by tf.computed_at_utc desc nulls last,tf.updated_at desc,tf.id desc
    limit 1;
    if not found then
      new.settings_authority_json:='{}'::jsonb;
      new.settings_authority_version:=null;
      new.settings_authority_fingerprint:=null;
      new.settings_authority_resolved_at:=null;
      return new;
    end if;
    v_relevant_date:=coalesce(
      (new.worked_start_iso at time zone 'Europe/London')::date,
      (new.scheduled_start_iso at time zone 'Europe/London')::date,
      new.week_ending_date
    );
    v_snapshot:=private._contract_settings_effective_core_v1(
      v_client_id,new.contract_id,v_relevant_date,'DAILY',null
    );
    new.settings_authority_json:=v_snapshot;
    new.settings_authority_version:='CONTRACT_SETTINGS_AUTHORITY_V1';
    new.settings_authority_fingerprint:=v_snapshot->>'authority_fingerprint';
    new.settings_authority_resolved_at:=(v_snapshot->>'resolved_at_utc')::timestamptz;
    return new;
  end if;
  if new.contract_id is null then
    new.settings_authority_json:='{}'::jsonb;
    new.settings_authority_version:=null;
    new.settings_authority_fingerprint:=null;
    new.settings_authority_resolved_at:=null;
    return new;
  end if;
  select * into v_contract from public.contracts c where c.id=new.contract_id;
  if not found then return new; end if;
  v_snapshot:=private._contract_settings_effective_core_v1(
    v_contract.client_id,v_contract.id,new.week_ending_date,'WEEKLY',null
  );
  new.settings_authority_json:=v_snapshot;
  new.settings_authority_version:='CONTRACT_SETTINGS_AUTHORITY_V1';
  new.settings_authority_fingerprint:=v_snapshot->>'authority_fingerprint';
  new.settings_authority_resolved_at:=(v_snapshot->>'resolved_at_utc')::timestamptz;
  return new;
end
$function$;

create or replace function private._candidate_expense_timesheet_sync_trigger_v1()
returns trigger
language plpgsql
security definer
set search_path = pg_catalog, public, private, pg_temp
as $function$
begin
  if tg_op='UPDATE' and old.timesheet_id is distinct from new.timesheet_id then
    raise exception 'CANDIDATE_TIMESHEET_ID_MUTATION_NOT_SUPPORTED' using errcode='55000';
  end if;
  if new.is_current and new.archived_at_utc is null then
    perform private._candidate_expense_components_sync_financial_v1(
      new.timesheet_id,pg_catalog.transaction_timestamp()
    );
    perform private._candidate_expense_summary_queue_v1(
      new.timesheet_id,pg_catalog.transaction_timestamp()
    );
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION private.bpay_clock_changed_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
BEGIN
 IF TG_OP='DELETE' THEN PERFORM private.bpay_clock_rebuild_v1(OLD.timesheet_id);
 ELSIF TG_OP='INSERT' THEN PERFORM private.bpay_clock_rebuild_v1(NEW.timesheet_id);
 ELSE
  IF OLD.timesheet_id IS DISTINCT FROM NEW.timesheet_id THEN
   PERFORM private.bpay_clock_rebuild_v1(OLD.timesheet_id);
  END IF;
  PERFORM private.bpay_clock_rebuild_v1(NEW.timesheet_id);
 END IF;
 RETURN NULL;
END;
$function$;

CREATE OR REPLACE FUNCTION private.bpay_expense_classification_ts_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
BEGIN
 IF TG_WHEN='BEFORE' THEN
  -- S-02: an ordinary classification write holds this row's own row lock, which every claim/week/lineage
  -- writer must share-lock before deciding; only a booking change needs the (old and new) family locks.
  IF TG_OP='UPDATE' AND OLD.booking_id IS DISTINCT FROM NEW.booking_id THEN
   PERFORM private.bpay_source_family_try_lock_v1(OLD.booking_id);
   PERFORM private.bpay_source_family_try_lock_v1(NEW.booking_id);
  END IF;
 ELSE
  PERFORM private._candidate_expense_source_family_v1(NEW.timesheet_id);
 END IF;
 RETURN NEW;
END; $function$;

CREATE OR REPLACE FUNCTION private.bpay_source_timesheet_family_gate_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$ BEGIN
 -- S-02: an ordinary insert, delete or rotation (is_current/version) takes no advisory lock. Rotations and
 -- deletes UPDATE/DELETE the family's current row, so Source events that share-lock that row serialise with
 -- them natively; a new row is invisible to every Source event until it commits (23503 NOT_VISIBLE).
 -- The family lock remains for a booking change (both families) and for a non-canonical booking whose
 -- whitespace variant collides with its trimmed family.
 IF TG_OP='UPDATE' AND OLD.booking_id IS DISTINCT FROM NEW.booking_id THEN
  PERFORM private.bpay_source_family_try_lock_v1(OLD.booking_id);
  PERFORM private.bpay_source_family_try_lock_v1(NEW.booking_id);
 ELSIF TG_OP<>'INSERT' AND OLD.booking_id<>btrim(OLD.booking_id) THEN
  PERFORM private.bpay_source_family_try_lock_v1(OLD.booking_id);
 ELSIF TG_OP<>'DELETE' AND NEW.booking_id<>btrim(NEW.booking_id) THEN
  PERFORM private.bpay_source_family_try_lock_v1(NEW.booking_id);
 END IF;
 IF TG_OP<>'DELETE' THEN RETURN NEW; END IF;
 RETURN OLD;
END; $function$;

CREATE OR REPLACE FUNCTION private.bpay_timesheet_work_revision_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
BEGIN
 IF TG_OP='INSERT' THEN NEW.bpay_work_revision_v1:=0;
 ELSE NEW.bpay_work_revision_v1:=OLD.bpay_work_revision_v1+
   CASE WHEN NEW.booking_id IS DISTINCT FROM OLD.booking_id THEN 1 ELSE 0 END;
 END IF;
 RETURN NEW;
END;
$function$;

create or replace function private.timesheet_correction_whole_state_guard_v1()
returns trigger language plpgsql security definer
set search_path to 'pg_catalog','private','public','pg_temp'
as $function$
declare v_request private.timesheet_correction_requests%rowtype; v_r public.timesheets%rowtype; v_p public.timesheets%rowtype;
begin
  if new.correction_kind not in('WHOLE_TIMESHEET_REVERSAL','WHOLE_TIMESHEET_REPLACEMENT')
    or new.correction_kind is null then
    if tg_op='UPDATE' then
      if old.correction_kind in('WHOLE_TIMESHEET_REVERSAL','WHOLE_TIMESHEET_REPLACEMENT') then
        raise exception 'WHOLE_CORRECTION_MEMBER_IDENTITY_IMMUTABLE' using errcode='23514';
      end if;
    end if;
    return new;
  end if;
  select request.* into v_request from private.timesheet_correction_requests request
    where request.correction_id=new.correction_id;
  if v_request.id is null then raise exception 'WHOLE_CORRECTION_REQUEST_REQUIRED' using errcode='23514'; end if;
  if new.timesheet_id not in(v_request.replacement_timesheet_id,coalesce(v_request.reversal_timesheet_id,v_request.replacement_timesheet_id))
    or new.parent_timesheet_id is distinct from v_request.root_timesheet_id
    or new.adjustment_origin is distinct from v_request.origin
    or (new.timesheet_id=v_request.replacement_timesheet_id and
      (new.correction_kind<>'WHOLE_TIMESHEET_REPLACEMENT' or new.booking_id<>v_request.replacement_booking_id))
    or (new.timesheet_id=v_request.reversal_timesheet_id and
      (new.correction_kind<>'WHOLE_TIMESHEET_REVERSAL' or new.booking_id<>v_request.reversal_booking_id)) then
    raise exception 'WHOLE_CORRECTION_REQUEST_MEMBER_INVALID' using errcode='23514';
  end if;
  select t.* into v_p from public.timesheets t where t.timesheet_id=v_request.replacement_timesheet_id;
  select t.* into v_r from public.timesheets t where t.timesheet_id=v_request.reversal_timesheet_id;
  if v_request.state='WAITING' and (v_p.authorised_at_server is not null or v_r.authorised_at_server is not null) then
    raise exception 'WHOLE_CORRECTION_REQUIRES_ATOMIC_APPROVAL' using errcode='23514';
  end if;
  if v_request.state='APPLIED' and (v_r.timesheet_id is null or v_p.timesheet_id is null
    or (select count(*) from public.timesheets_financials tf where tf.timesheet_id in(v_r.timesheet_id,v_p.timesheet_id)
      and tf.is_current)<>2
    or (v_r.authorised_at_server is null) is distinct from (v_p.authorised_at_server is null)
    or exists(select 1 from public.timesheets_financials tf where tf.timesheet_id in(v_r.timesheet_id,v_p.timesheet_id)
      and tf.is_current and (tf.authorised_at_utc is null) is distinct from
        (case when tf.timesheet_id=v_r.timesheet_id then v_r.authorised_at_server is null else v_p.authorised_at_server is null end))) then
    raise exception 'WHOLE_CORRECTION_PAIR_STATE_INVALID' using errcode='23514';
  end if;
  return new;
end;
$function$;

create or replace function private.timesheet_correction_financial_guard_v1()
returns trigger language plpgsql security definer
set search_path to 'pg_catalog','public','private','pg_temp'
as $function$
declare v_id uuid; v_old_id uuid; v_request record;
begin
  v_id:=case when tg_op='DELETE' then old.timesheet_id else new.timesheet_id end;
  if tg_op in('UPDATE','DELETE') then v_old_id:=old.timesheet_id; end if;
  for v_request in select request.id from private.timesheet_correction_requests request
    where request.state='APPLIED' and (v_id in(request.reversed_timesheet_id,request.replacement_timesheet_id,request.reversal_timesheet_id)
      or v_old_id in(request.reversed_timesheet_id,request.replacement_timesheet_id,request.reversal_timesheet_id))
    order by request.id loop
    perform private.timesheet_correction_applied_assert_v1(v_request.id);
  end loop;
  return null;
end;
$function$;

create or replace function private.timesheet_correction_a0_booking_before_v1()
returns trigger language plpgsql volatile security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare v_ids uuid[]; v_bookings text[]; v_admit jsonb; r record; v_match boolean;
begin
  if tg_table_schema<>'public' or tg_table_name<>'timesheets' or tg_op not in('INSERT','UPDATE') then
    raise exception 'CORRECTION_A0_WRITER_TRIGGER_CONTEXT_INVALID' using errcode='55000'; end if;
  if tg_op='UPDATE' then
    if new.booking_id is not distinct from old.booking_id and new.contract_id is not distinct from old.contract_id then return new; end if;
    v_ids:=array[old.timesheet_id,new.timesheet_id];v_bookings:=array[old.booking_id,new.booking_id];
  else v_ids:=array[new.timesheet_id];v_bookings:=array[new.booking_id]; end if;
  v_admit:=private.timesheet_correction_a0_writer_admit_v1(v_ids,v_bookings,'BOOKING_IDENTITY');
  for r in select x.value from jsonb_array_elements(v_admit->'requests') x(value) loop
    v_match:=btrim(new.booking_id) in(btrim(r.value->>'original_booking'),btrim(r.value->>'reversed_booking'),btrim(r.value->>'p0_booking'));
    if v_match and (new.contract_id is distinct from (r.value->>'contract_id')::uuid
      or new.booking_id not in(r.value->>'original_booking',r.value->>'reversed_booking',r.value->>'p0_booking')) then
      raise exception 'CORRECTION_A0_WRITER_IDENTITY_UNPROVED' using errcode='55000'; end if;
    if new.timesheet_id=(r.value->>'p0')::uuid and (new.booking_id is distinct from r.value->>'p0_booking'
      or new.contract_id is distinct from (r.value->>'contract_id')::uuid) then
      raise exception 'CORRECTION_A0_WRITER_IDENTITY_UNPROVED' using errcode='55000'; end if;
    if new.timesheet_id=(r.value->>'original')::uuid and (new.booking_id is distinct from r.value->>'reversed_booking'
      or new.contract_id is distinct from (r.value->>'contract_id')::uuid) then
      raise exception 'CORRECTION_A0_WRITER_IDENTITY_UNPROVED' using errcode='55000'; end if;
    if new.timesheet_id=(r.value->>'root')::uuid and new.booking_id is distinct from r.value->>'original_booking' then
      raise exception 'CORRECTION_A0_WRITER_IDENTITY_UNPROVED' using errcode='55000'; end if;
  end loop;
  return new;
end;
$function$;

create or replace function private.bpay_next_work_wait_state_v1(p_work_id uuid)
returns boolean language plpgsql stable security definer set search_path=pg_catalog,private
as $function$
declare v_state text;
begin
  perform private.bpay_next_workbench_require_next_v1();
  select w.approval_state into strict v_state from private.bpay_next_work w where w.id=p_work_id;
  return v_state='WITHDRAWN' and coalesce((select sum(p.realised_source_ex_vat)
    from private.bpay_next_position p where p.work_id=p_work_id),0)>0;
end
$function$;

create or replace function private.weekly_source_agency_invoice_check_only_v1(p_timesheet_id uuid)
returns boolean language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare v_ts public.timesheets%rowtype; v_contract public.contracts%rowtype;
  v_cycle uuid; v_rules jsonb; v_policy jsonb; v_settings jsonb;
begin
  select * into v_ts from public.timesheets t where t.timesheet_id=p_timesheet_id and t.is_current
    and t.sheet_scope::text='WEEKLY' and t.status::text<>'REVOKED' and t.revoked_at is null and t.archived_at_utc is null;
  if not found or v_ts.contract_id is null or v_ts.week_ending_date is null then return false; end if;
  select * into v_contract from public.contracts c where c.id=v_ts.contract_id
    and c.weekly_timesheet_source::text='HEALTHROSTER';
  if not found or v_contract.self_bill or coalesce(v_contract.no_timesheet_required,false)
    or coalesce(v_contract.is_nhsp,false) then return false; end if;
  if nullif(v_ts.settings_authority_json->>'client_id','') is not null
    and v_ts.settings_authority_json->>'client_id'<>v_contract.client_id::text then return false; end if;
  if v_contract.start_date>v_ts.week_ending_date or v_contract.end_date<v_ts.week_ending_date-6
    or exists(select 1 from public.timesheets_financials f where f.timesheet_id=p_timesheet_id
      and f.is_current and f.timesheet_version=v_ts.version and f.client_id is distinct from v_contract.client_id) then return false; end if;
  select c.id into v_cycle from public.weekly_source_cycles c
    join public.weekly_source_groups g on g.id=c.source_group_id and g.active and g.source_family='ROSTER'
    join public.weekly_source_group_clients gc on gc.source_group_id=g.id and gc.client_id=v_contract.client_id
      and v_ts.week_ending_date between gc.valid_from and coalesce(gc.valid_to,'infinity'::date)
    where c.finalisation_week_ending=v_ts.week_ending_date;
  if v_cycle is null then return false; end if;
  v_rules:=private.weekly_source_effective_rule_set_v1(v_contract.client_id,v_cycle);
  if v_rules is null or v_rules->'values'->>'invoice_sender'<>'AGENCY_INVOICE' then return false; end if;
  if not private.weekly_source_is_import_authoritative_v1(v_contract.client_id,v_contract.id,v_ts.week_ending_date) then return false; end if;
  v_policy:=private._weekly_source_effective_policy_v1(v_contract.client_id,v_contract.id,v_ts.week_ending_date);
  if coalesce((v_policy->>'self_bill_enabled')::boolean,true) then return false; end if;
  if coalesce((select cs.self_bill_no_invoices_sent from public.client_settings cs
    where cs.client_id=v_contract.client_id and (cs.effective_from is null or cs.effective_from<=v_ts.week_ending_date)
    order by cs.effective_from desc nulls last,cs.updated_at desc,cs.id desc limit 1),false) then return false; end if;
  v_settings:=private._contract_settings_effective_core_v1(v_contract.client_id,v_contract.id,v_ts.week_ending_date,'WEEKLY',null);
  return coalesce((v_settings->'applicability'->>'configuration_valid')::boolean,false)
    and not coalesce((v_settings->'values'->>'self_bill')::boolean,true)
    and not coalesce((v_settings->'values'->>'no_timesheet_required')::boolean,true)
    and not coalesce((v_settings->'values'->>'is_nhsp')::boolean,true)
    and coalesce((v_settings->'values'->>'requires_hr')::boolean,false)
    and coalesce((v_settings->'values'->>'autoprocess_hr')::boolean,false);
end;
$function$;

create or replace function private.weekly_source_signed_check_only_v1(p_timesheet_id uuid)
returns boolean language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare v_ts public.timesheets%rowtype; v_contract public.contracts%rowtype;
  v_client uuid; v_client_count integer; v_work_date date; v_policy jsonb; v_route record;
begin
  select * into v_ts from public.timesheets t where t.timesheet_id=p_timesheet_id and t.is_current
    and t.sheet_scope::text in ('WEEKLY','DAILY') and t.status::text not in ('REVOKED','ARCHIVED','CANCELLED') and t.revoked_at is null and t.archived_at_utc is null;
  if not found or v_ts.week_ending_date is null then return false; end if;
  if v_ts.contract_id is not null then
    select * into v_contract from public.contracts c where c.id=v_ts.contract_id;
    if not found or v_contract.self_bill or coalesce(v_contract.no_timesheet_required,false)
      or coalesce(v_contract.is_nhsp,false) then return false; end if;
    v_client:=v_contract.client_id;
    if nullif(v_ts.settings_authority_json->>'client_id','') is not null
      and v_ts.settings_authority_json->>'client_id'<>v_client::text then return false; end if;
    if exists(select 1 from public.timesheets_financials f where f.timesheet_id=p_timesheet_id
      and f.is_current and f.timesheet_version=v_ts.version and f.client_id is distinct from v_client) then return false; end if;
  elsif v_ts.sheet_scope::text='DAILY' then
    select count(distinct f.client_id),(array_agg(distinct f.client_id))[1] into v_client_count,v_client
      from public.timesheets_financials f where f.timesheet_id=p_timesheet_id and f.is_current
        and f.timesheet_version=v_ts.version and f.client_id is not null;
    if v_client_count<>1 then return false; end if;
    if nullif(v_ts.settings_authority_json->>'client_id','') is not null
      and v_ts.settings_authority_json->>'client_id'<>v_client::text then return false; end if;
  else return false;
  end if;
  v_work_date:=case when v_ts.sheet_scope::text='DAILY' then (v_ts.worked_start_iso at time zone 'Europe/London')::date
    else v_ts.week_ending_date end;
  if v_work_date is null or v_work_date>v_ts.week_ending_date or v_work_date<v_ts.week_ending_date-6 then return false; end if;
  if not exists(select 1 from public.weekly_source_group_clients gc
    join public.weekly_source_groups g on g.id=gc.source_group_id and g.active and g.source_family='ROSTER'
    join public.weekly_source_group_rule_assignments a on a.source_group_id=g.id and a.feature_enabled
      and a.feature_purpose='SIGNED_CHECK_ONLY' and a.rule_set_version_id is null
      and v_ts.week_ending_date between a.effective_from_week_ending and coalesce(a.effective_to_week_ending,'infinity'::date)
    where gc.client_id=v_client and v_work_date between gc.valid_from and coalesce(gc.valid_to,'infinity'::date)
      and v_ts.week_ending_date between gc.valid_from and coalesce(gc.valid_to,'infinity'::date)) then return false; end if;
  if not exists(select 1 from public.weekly_source_client_policies cp
    join public.weekly_source_group_clients gc on gc.source_group_id=cp.source_group_id and gc.client_id=cp.client_id
    where cp.client_id=v_client and v_work_date between gc.valid_from and coalesce(gc.valid_to,'infinity'::date)
    and v_work_date between cp.effective_from and coalesce(cp.effective_to,'infinity'::date)) then return false; end if;
  v_policy:=private._weekly_source_effective_policy_v1(v_client,v_ts.contract_id,v_work_date);
  if v_policy->>'source_family'<>'ROSTER' or v_policy->>'authority_mode'<>'TIMESHEET_AUTHORITY'
    or v_policy->>'document_mode'<>'INVOICE_EVIDENCE_REQUIRED' or coalesce((v_policy->>'self_bill_enabled')::boolean,true) then return false; end if;
  select * into v_route from public._import_review_effective_authority_core_v1(
    case when v_ts.sheet_scope::text='DAILY' then 'HR_DAILY' else 'HR_WEEKLY' end,v_ts.contract_id,v_client,v_work_date);
  return coalesce(v_route.route_eligible,false) and coalesce(v_route.validation_eligible,false)
    and not coalesce(v_route.import_authoritative,true) and v_route.authority_mode='VALIDATION_ONLY'
    and not coalesce(v_route.effective_is_nhsp,true) and not coalesce(v_route.effective_no_timesheet_required,true);
end;
$function$;

CREATE OR REPLACE FUNCTION public._pay_workbench_candidate_serial_try_gate(p_job_id uuid DEFAULT NULL::uuid, p_candidate_id uuid DEFAULT NULL::uuid, p_job_type text DEFAULT NULL::text, p_payload_json jsonb DEFAULT '{}'::jsonb, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_payload jsonb := CASE WHEN jsonb_typeof(COALESCE(p_payload_json, '{}'::jsonb)) = 'object' THEN COALESCE(p_payload_json, '{}'::jsonb) ELSE '{}'::jsonb END;
  v_candidate_id uuid := public._pay_workbench_candidate_serial_candidate_id(p_candidate_id, p_payload_json);
  v_serial_key text := public._pay_workbench_candidate_serial_key(v_candidate_id);
  v_required boolean := false;
  v_locked boolean := false;
  v_state jsonb := '{}'::jsonb;
  v_blocked boolean := false;
  v_reason text := NULL::text;
  v_result jsonb := '{}'::jsonb;
BEGIN
  v_required := public._pay_workbench_candidate_serial_is_candidate_job(p_job_type, v_candidate_id, v_payload);

  IF v_candidate_id IS NULL OR v_serial_key IS NULL OR v_required IS NOT TRUE THEN
    v_state := public._pay_workbench_candidate_serial_active_state(p_job_id, v_candidate_id, p_job_type, v_payload, NULL::timestamptz);
    RETURN COALESCE(v_state, '{}'::jsonb) || jsonb_strip_nulls(jsonb_build_object(
      'ok', true, 'allowed', true, 'blocked', false, 'candidate_serial_blocked', false,
      'reason', COALESCE(v_state->>'reason', 'NO_CANDIDATE_SERIAL_SCOPE'),
      'candidate_serial_wait_reason', COALESCE(v_state->>'candidate_serial_wait_reason', v_state->>'reason', 'NO_CANDIDATE_SERIAL_SCOPE'),
      'candidate_id', CASE WHEN v_candidate_id IS NULL THEN NULL ELSE v_candidate_id::text END,
      'candidate_serial_key', v_serial_key,
      'candidate_serial_gate_reason', NULLIF(BTRIM(COALESCE(p_reason, '')), ''),
      'candidate_serial_gate_decision', 'BYPASSED',
      'advisory_lock_attempted', false
    ));
  END IF;

  v_locked := COALESCE(pg_try_advisory_xact_lock(hashtextextended(v_serial_key, 24062027)), false);
  v_state := public._pay_workbench_candidate_serial_active_state(p_job_id, v_candidate_id, p_job_type, v_payload, NULL::timestamptz);
  v_blocked := v_locked IS NOT TRUE
    OR lower(BTRIM(COALESCE(v_state->>'blocked', v_state->>'candidate_serial_blocked', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
  v_reason := CASE
    WHEN v_locked IS NOT TRUE THEN 'CANDIDATE_SERIAL_BLOCKED_BY_ADVISORY_LOCK'
    ELSE COALESCE(NULLIF(BTRIM(COALESCE(v_state->>'reason', '')), ''), CASE WHEN v_blocked THEN 'CANDIDATE_SERIAL_BLOCKED' ELSE 'CANDIDATE_SERIAL_CLEAR' END)
  END;

  v_result := COALESCE(v_state, '{}'::jsonb) || jsonb_strip_nulls(jsonb_build_object(
    'ok', true, 'allowed', NOT COALESCE(v_blocked, false), 'blocked', COALESCE(v_blocked, false),
    'candidate_serial_blocked', COALESCE(v_blocked, false), 'reason', v_reason,
    'candidate_serial_wait_reason', v_reason, 'candidate_id', v_candidate_id::text,
    'candidate_serial_key', v_serial_key,
    'candidate_serial_gate_reason', NULLIF(BTRIM(COALESCE(p_reason, '')), ''),
    'candidate_serial_gate_decision', CASE WHEN v_blocked THEN 'BLOCKED' ELSE 'GRANTED' END,
    'advisory_lock_attempted', true, 'advisory_lock_granted', COALESCE(v_locked, false)
  ));

  PERFORM public._pay_workbench_candidate_serial_audit(
    CASE WHEN v_blocked THEN 'CANDIDATE_SERIAL_GATE_BLOCKED' ELSE 'CANDIDATE_SERIAL_GATE_GRANTED' END,
    p_job_id, v_candidate_id, v_result || jsonb_build_object('job_type', p_job_type),
    COALESCE(NULLIF(BTRIM(COALESCE(p_reason, '')), ''), v_reason), NULL::uuid
  );
  RETURN v_result;
END;
$function$;

create or replace function private._contract_settings_effective_core_v1(
  p_client_id uuid,
  p_contract_id uuid,
  p_relevant_date date,
  p_workflow text,
  p_timesheet_id uuid default null
)
returns jsonb
language plpgsql
stable
security definer
set search_path = pg_catalog, public, private, extensions, pg_temp
as $function$
declare
  v_contract public.contracts%rowtype;
  v_client public.client_settings%rowtype;
  v_client_record public.clients%rowtype;
  v_defaults public.settings_defaults%rowtype;
  v_timesheet public.timesheets%rowtype;
  v_finance jsonb := '{}'::jsonb;
  v_client_id uuid := p_client_id;
  v_client_found boolean := false;
  v_unresolved_daily boolean := false;
  v_workflow text := upper(btrim(coalesce(p_workflow, '')));
  v_override boolean := false;
  v_is_nhsp boolean := false;
  v_requires_hr boolean := false;
  v_autoprocess_hr boolean := false;
  v_no_timesheet_required boolean := false;
  v_import_authoritative boolean := false;
  v_self_bill boolean := false;
  v_configuration_valid boolean := true;
  v_configuration_issue text;
  v_route text := 'STANDARD_WEEKLY';
  v_source text := 'CLIENT_SETTINGS';
  v_holidays jsonb := '[]'::jsonb;
  v_values jsonb;
  v_sources jsonb;
  v_components jsonb;
  v_applicability jsonb;
  v_payload jsonb;
  v_fingerprint text;
begin
  if p_relevant_date is null then
    raise exception 'CONTRACT_SETTINGS_RELEVANT_DATE_REQUIRED' using errcode='22023';
  end if;
  if v_workflow not in ('WEEKLY','DAILY','IMPORT','OFFICE','INVOICE','FINANCE') then
    raise exception 'CONTRACT_SETTINGS_WORKFLOW_INVALID' using errcode='22023';
  end if;

  if p_timesheet_id is not null then
    select * into v_timesheet
    from public.timesheets t
    where t.timesheet_id=p_timesheet_id and t.is_current=true;
    if not found then
      raise exception 'CONTRACT_SETTINGS_CURRENT_TIMESHEET_NOT_FOUND' using errcode='P0002';
    end if;
    if v_timesheet.settings_authority_json <> '{}'::jsonb then
      return private._timesheet_settings_authority_frozen_v1(p_timesheet_id);
    end if;
    if v_timesheet.sheet_scope='WEEKLY'::public.timesheet_scope_enum
       or exists(
         select 1 from public.timesheets_financials tf
         where tf.timesheet_id=v_timesheet.timesheet_id
           and tf.is_current=true
           and tf.processed_at_utc is not null
       ) then
      raise exception 'CONTRACT_SETTINGS_TIMESHEET_AUTHORITY_NOT_FROZEN' using errcode='55000';
    end if;
    if p_contract_id is not null and p_contract_id is distinct from v_timesheet.contract_id then
      raise exception 'CONTRACT_SETTINGS_TIMESHEET_CONTRACT_MISMATCH' using errcode='22023';
    end if;
  end if;

  if p_contract_id is not null then
    select * into v_contract from public.contracts c where c.id=p_contract_id;
    if not found then
      raise exception 'CONTRACT_SETTINGS_CONTRACT_NOT_FOUND' using errcode='P0002';
    end if;
    if v_client_id is not null and v_client_id<>v_contract.client_id then
      raise exception 'CONTRACT_SETTINGS_CLIENT_CONTRACT_MISMATCH' using errcode='22023';
    end if;
    v_client_id:=v_contract.client_id;
    v_override:=coalesce(v_contract.overrideclientsettings,false);
  end if;
  if v_client_id is null then
    v_unresolved_daily:=(
      p_timesheet_id is not null
      and v_workflow='DAILY'
      and v_timesheet.sheet_scope='DAILY'::public.timesheet_scope_enum
      and v_timesheet.contract_id is null
      and v_timesheet.settings_authority_json='{}'::jsonb
    );
    if not v_unresolved_daily then
      raise exception 'CONTRACT_SETTINGS_CLIENT_REQUIRED' using errcode='22023';
    end if;
  else
    select * into v_client_record from public.clients cl where cl.id=v_client_id;
    if not found then
      raise exception 'CONTRACT_SETTINGS_CLIENT_NOT_FOUND' using errcode='P0002';
    end if;

    select * into v_client
    from public.client_settings cs
    where cs.client_id=v_client_id
      and (cs.effective_from is null or cs.effective_from<=p_relevant_date)
    order by cs.effective_from desc nulls last,cs.updated_at desc,cs.id desc
    limit 1;
    v_client_found:=found;
    if not v_client_found then
      raise exception 'CONTRACT_SETTINGS_CLIENT_SETTINGS_NOT_FOUND' using errcode='P0002';
    end if;
  end if;
  select * into v_defaults from public.settings_defaults d where d.id=1;
  if not found then
    raise exception 'CONTRACT_SETTINGS_GLOBAL_SETTINGS_NOT_FOUND' using errcode='P0002';
  end if;
  select to_jsonb(fin) into v_finance
  from public.settings_finance_pick(p_relevant_date) fin
  limit 1;
  v_finance:=coalesce(v_finance,'{}'::jsonb);

  v_is_nhsp:=case when v_override then coalesce(v_contract.is_nhsp,false)
    else coalesce(v_client.is_nhsp,false) end;
  v_requires_hr:=case when v_override then coalesce(v_contract.requires_hr,false)
    else coalesce(v_client.requires_hr,false) end;
  v_autoprocess_hr:=case when v_override then coalesce(v_contract.autoprocess_hr,false)
    else coalesce(v_client.autoprocess_hr,false) end;
  v_no_timesheet_required:=case when v_override then coalesce(v_contract.no_timesheet_required,false)
    else coalesce(v_client.no_timesheet_required,false) end;

  if v_is_nhsp and (v_requires_hr or v_autoprocess_hr or v_no_timesheet_required) then
    v_configuration_valid:=false;
    v_configuration_issue:='MULTIPLE_IMPORT_FAMILIES';
  elsif v_is_nhsp and v_workflow='DAILY' then
    v_configuration_valid:=false;
    v_configuration_issue:='NHSP_WEEKLY_WITH_DAILY_WORKFLOW';
  elsif v_no_timesheet_required and not v_autoprocess_hr then
    v_configuration_valid:=false;
    v_configuration_issue:='AUTHORITATIVE_ROSTER_WITHOUT_AUTOPROCESS';
  elsif v_requires_hr and not v_autoprocess_hr then
    v_configuration_valid:=false;
    v_configuration_issue:='ROSTER_VALIDATION_WITHOUT_AUTOPROCESS';
  elsif v_autoprocess_hr and not v_no_timesheet_required and not v_requires_hr then
    v_configuration_valid:=false;
    v_configuration_issue:='ROSTER_MODE_NOT_SELECTED';
  end if;

  v_route:=case
    when v_is_nhsp then 'DEDICATED_NHSP_WEEKLY'
    when v_autoprocess_hr and v_no_timesheet_required and v_workflow='DAILY' then 'HEALTHROSTER_DAILY_AUTHORITATIVE'
    when v_autoprocess_hr and v_no_timesheet_required then 'HEALTHROSTER_WEEKLY_AUTHORITATIVE'
    when v_autoprocess_hr and v_workflow='DAILY' then 'HEALTHROSTER_DAILY_VALIDATION'
    when v_autoprocess_hr then 'HEALTHROSTER_WEEKLY_VALIDATION'
    when v_workflow='DAILY' then 'STANDARD_DAILY'
    else 'STANDARD_WEEKLY' end;
  v_source:=case
    when v_unresolved_daily then 'UNRESOLVED_DAILY_SAFE'
    when v_override then 'CONTRACT_OVERRIDE'
    else 'CLIENT_SETTINGS' end;
  -- Historical contradictory rows fail safely: they can never grant Candidate
  -- hour entry merely because their old flags disagree.
  v_import_authoritative:=case
    when not v_configuration_valid then v_is_nhsp or v_no_timesheet_required
    else v_is_nhsp or (v_autoprocess_hr and v_no_timesheet_required)
  end;

  -- Self-billing controls expense separation, not Candidate hour-entry authority.
  v_self_bill:=case when v_override then coalesce(v_contract.self_bill,false)
    else coalesce(v_client.self_bill_no_invoices_sent,false) end;

  select coalesce(jsonb_agg(to_jsonb(h.date_value) order by h.date_value),'[]'::jsonb)
  into v_holidays
  from (
    select distinct btrim(x.date_value) date_value
    from (
      select jsonb_array_elements_text(
        case when jsonb_typeof(v_defaults.bh_list)='array' then v_defaults.bh_list else '[]'::jsonb end
      ) date_value
      union all
      select jsonb_array_elements_text(
        case when jsonb_typeof(v_defaults.bh_feed_list)='array' then v_defaults.bh_feed_list else '[]'::jsonb end
      ) date_value
    ) x
    where btrim(x.date_value) ~ '^\d{4}-\d{2}-\d{2}$'
  ) h;

  v_values:=jsonb_build_object(
    'timezone_id',coalesce(v_client.timezone_id,v_defaults.timezone_id,'Europe/London'),
    'day_start',coalesce(v_client.day_start,v_defaults.day_start),
    'day_end',coalesce(v_client.day_end,v_defaults.day_end),
    'night_start',coalesce(v_client.night_start,v_defaults.night_start),
    'night_end',coalesce(v_client.night_end,v_defaults.night_end),
    'sat_start',coalesce(v_client.sat_start,v_defaults.sat_start),
    'sat_end',coalesce(v_client.sat_end,v_defaults.sat_end),
    'sun_start',coalesce(v_client.sun_start,v_defaults.sun_start),
    'sun_end',coalesce(v_client.sun_end,v_defaults.sun_end),
    'bh_start',coalesce(v_client.bh_start,v_defaults.bh_start),
    'bh_end',coalesce(v_client.bh_end,v_defaults.bh_end),
    'bh_list',v_holidays,
    'vat_rate_pct',coalesce(v_client.vat_rate_pct,(v_finance->>'vat_rate_pct')::numeric,20),
    'holiday_pay_pct',coalesce(v_client.holiday_pay_pct,(v_finance->>'holiday_pay_pct')::numeric,12.07),
    'erni_pct',coalesce((v_finance->>'erni_pct')::numeric,13.8),
    'apply_holiday_to',coalesce(v_client.apply_holiday_to,v_finance->>'apply_holiday_to','PAYE_ONLY'),
    'apply_erni_to',coalesce(v_finance->>'apply_erni_to','PAYE_ONLY'),
    'margin_includes',coalesce(v_client.margin_includes,v_finance->'margin_includes','{}'::jsonb),
    'hr_validation_required',coalesce(v_client.hr_validation_required,false),
    'ts_reference_required',coalesce(v_client.ts_reference_required,v_defaults.ts_reference_required,false),
    'week_ending_weekday',coalesce(v_client.week_ending_weekday,
      case when p_contract_id is not null then v_contract.week_ending_weekday_snapshot end,0),
    'default_submission_mode',case when v_override then coalesce(v_contract.default_submission_mode,'ELECTRONIC')
      else coalesce(v_client.default_submission_mode,'ELECTRONIC') end,
    'is_nhsp',v_is_nhsp,
    'requires_hr',v_requires_hr,
    'autoprocess_hr',v_autoprocess_hr,
    'no_timesheet_required',v_no_timesheet_required
  )||jsonb_build_object(
    'hr_validation_required_for_invoice',case when v_override
      then coalesce(v_contract.requires_hr,false)
      else coalesce(v_client.hr_validation_required,false) end,
    'daily_calc_of_invoices',case when v_override then coalesce(v_contract.daily_calc_of_invoices,false)
      else coalesce(v_client.daily_calc_of_invoices,false) end,
    'group_nightsat_sunbh',case when v_override then coalesce(v_contract.group_nightsat_sunbh,false)
      else coalesce(v_client.group_nightsat_sunbh,false) end,
    'auto_invoice',case when v_override then coalesce(v_contract.auto_invoice,false)
      else coalesce(v_client.auto_invoice_default,false) end,
    'self_bill',v_self_bill,
    'require_reference_to_pay',case when v_override then coalesce(v_contract.require_reference_to_pay,false)
      else coalesce(v_client.pay_reference_required,false) end,
    'require_reference_to_invoice',case when v_override then coalesce(v_contract.require_reference_to_invoice,false)
      else coalesce(v_client.invoice_reference_required,false) end,
    'reference_number_required_to_issue_invoice',case when v_override
      then coalesce(v_contract.reference_number_required_to_issue_invoice,false)
      else coalesce(v_client.reference_number_required_to_issue_invoice,false) end,
    'hr_attach_to_invoice',case when v_override then coalesce(v_contract.hr_attach_to_invoice,true)
      else coalesce(v_client.hr_attach_to_invoice,v_defaults.hr_attach_to_invoice,true) end,
    'ts_attach_to_invoice',case when v_override then coalesce(v_contract.ts_attach_to_invoice,true)
      else coalesce(v_client.ts_attach_to_invoice,v_defaults.ts_attach_to_invoice,true) end,
    'send_manual_invoices_to_different_email',case when v_override
      then coalesce(v_contract.send_manual_invoices_to_different_email,false)
      else coalesce(v_client.send_manual_invoices_to_different_email,false) end,
    'manual_invoices_alt_email_address',case when v_override then v_contract.manual_invoices_alt_email_address
      else v_client.manual_invoices_alt_email_address end,
    'invoice_consolidation_mode',v_client.invoice_consolidation_mode,
    'healthroster_import_auto_authorise',case when v_unresolved_daily then false else
      coalesce(v_contract.healthroster_import_auto_authorise_override,
        v_client.healthroster_import_auto_authorise,
        v_defaults.healthroster_import_auto_authorise_default,false) end,
    'nhsp_import_auto_authorise',case when v_unresolved_daily then false else
      coalesce(v_contract.nhsp_import_auto_authorise_override,
        v_client.nhsp_import_auto_authorise,v_defaults.nhsp_import_auto_authorise_default,false) end,
    'candidate_electronic_auto_authorise',case when v_unresolved_daily then false else
      coalesce(v_contract.candidate_electronic_auto_authorise_override,
        v_client.candidate_electronic_auto_authorise,
        v_defaults.candidate_electronic_auto_authorise_default,false) end,
    'auto_authorise_on_validation',coalesce(v_defaults.auto_authorise_on_validation,false),
    'candidate_expenses_require_separate_timesheet',case when v_import_authoritative then true
      when v_self_bill then true
      else coalesce(v_contract.candidate_expenses_require_separate_timesheet_override,
        v_client.candidate_expenses_require_separate_timesheet,false) end,
    'candidate_paper_submission_enabled',case when v_import_authoritative then false
      else coalesce(v_contract.candidate_paper_submission_enabled_override,
        v_client.candidate_paper_submission_enabled,false) end,
    'candidate_expense_invoice_email',coalesce(v_contract.candidate_expense_invoice_email_override,
      v_client.candidate_expense_invoice_email),
    'candidate_manager_approval_policy_json',private._candidate_manager_authoriser_effective_v2(
      coalesce(v_client.candidate_manager_approval_policy_json,'{}'::jsonb),
      case when p_contract_id is null then null else v_contract.candidate_manager_approval_policy_json end
    ),
    'allow_daily_manager_authorise_on_phone',coalesce(v_client.allow_daily_manager_authorise_on_phone,true),
    'allow_daily_manager_authorise_by_email',coalesce(v_client.allow_daily_manager_authorise_by_email,false),
    'timesheet_break_entry_mode',case when v_import_authoritative then null
      when v_override then v_contract.timesheet_break_entry_mode else v_client.timesheet_break_entry_mode end,
    'weekly_timesheet_source',case when p_contract_id is null then null else v_contract.weekly_timesheet_source end,
    'rates_json',case when p_contract_id is null then null else v_contract.rates_json end,
    'additional_rates_json',case when p_contract_id is null then null else v_contract.additional_rates_json end,
    'mileage_pay_rate',case when p_contract_id is null then null else v_contract.mileage_pay_rate end,
    'mileage_charge_rate',case when p_contract_id is null then null else v_contract.mileage_charge_rate end,
    'mileage_pay_defaults',v_finance->'mileage_pay_defaults',
    'mileage_charge_defaults',v_finance->'mileage_charge_defaults',
    'bucket_labels_json',case when p_contract_id is null then null else v_contract.bucket_labels_json end,
    'client_vat_chargeable',coalesce(v_client_record.vat_chargeable,true),
    'client_payment_terms_days',v_client_record.payment_terms_days,
    'client_primary_invoice_email',v_client_record.primary_invoice_email
  );

  v_sources:=jsonb_build_object(
    'time_windows',case when v_unresolved_daily then 'GLOBAL' else 'CLIENT_THEN_GLOBAL' end,
    'bank_holiday_dates','GLOBAL_MANUAL_PLUS_GOV_UK_ENGLAND_AND_WALES',
    'bank_holiday_hours',case when v_unresolved_daily then 'GLOBAL' else 'CLIENT_THEN_GLOBAL' end,
    'erni_pct','GLOBAL_FINANCE_WINDOW',
    'apply_erni_to','GLOBAL_FINANCE_WINDOW',
    'finance_window',coalesce(v_finance->>'source','GLOBAL_FINANCE_WINDOW'),
    'contract_governed_settings',v_source,
    'healthroster_import_auto_authorise',case
      when v_unresolved_daily then 'UNRESOLVED_DAILY_SAFE'
      when p_contract_id is not null and v_contract.healthroster_import_auto_authorise_override is not null
        then 'CONTRACT'
      when v_client.healthroster_import_auto_authorise is not null then 'CLIENT'
      else 'GLOBAL' end,
    'nhsp_import_auto_authorise',case
      when v_unresolved_daily then 'UNRESOLVED_DAILY_SAFE'
      when p_contract_id is not null and v_contract.nhsp_import_auto_authorise_override is not null
        then 'CONTRACT'
      when v_client.nhsp_import_auto_authorise is not null then 'CLIENT'
      else 'GLOBAL' end,
    'candidate_electronic_auto_authorise',case
      when v_unresolved_daily then 'UNRESOLVED_DAILY_SAFE'
      when p_contract_id is not null and v_contract.candidate_electronic_auto_authorise_override is not null
        then 'CONTRACT'
      when v_client.candidate_electronic_auto_authorise is not null then 'CLIENT'
      else 'GLOBAL' end,
    'candidate_expenses_require_separate_timesheet',case
      when v_unresolved_daily then 'UNRESOLVED_DAILY_SAFE'
      when v_import_authoritative then 'IMPORT_MANDATORY'
      when v_self_bill then 'SELF_BILL_MANDATORY'
      when p_contract_id is not null
       and v_contract.candidate_expenses_require_separate_timesheet_override is not null then 'CONTRACT'
      else 'CLIENT' end,
    'candidate_paper_submission_enabled',case
      when v_unresolved_daily then 'UNRESOLVED_DAILY_SAFE'
      when v_import_authoritative then 'IMPORT_DISABLED'
      when p_contract_id is not null and v_contract.candidate_paper_submission_enabled_override is not null
        then 'CONTRACT'
      else 'CLIENT' end,
    'candidate_expense_invoice_email',case
      when v_unresolved_daily then 'UNRESOLVED_DAILY_SAFE'
      when p_contract_id is not null and v_contract.candidate_expense_invoice_email_override is not null
        then 'CONTRACT'
      else 'CLIENT' end,
    'candidate_manager_approval_policy_json',case
      when v_unresolved_daily then 'UNRESOLVED_DAILY_SAFE'
      when p_contract_id is not null and v_contract.candidate_manager_approval_policy_json is not null
        then 'CONTRACT'
      else 'CLIENT' end,
    'contract_rates','CONTRACT'
  );
  v_components:=jsonb_build_object(
    'healthroster_import_auto_authorise',jsonb_build_object(
      'global',v_defaults.healthroster_import_auto_authorise_default,
      'client',v_client.healthroster_import_auto_authorise,
      'contract_override',case when p_contract_id is null then null
        else v_contract.healthroster_import_auto_authorise_override end
    ),
    'nhsp_import_auto_authorise',jsonb_build_object(
      'global',v_defaults.nhsp_import_auto_authorise_default,
      'client',v_client.nhsp_import_auto_authorise,
      'contract_override',case when p_contract_id is null then null
        else v_contract.nhsp_import_auto_authorise_override end
    ),
    'candidate_electronic_auto_authorise',jsonb_build_object(
      'global',v_defaults.candidate_electronic_auto_authorise_default,
      'client',v_client.candidate_electronic_auto_authorise,
      'contract_override',case when p_contract_id is null then null
        else v_contract.candidate_electronic_auto_authorise_override end
    )
  );
  v_applicability:=jsonb_build_object(
    'configuration_valid',v_configuration_valid,
    'configuration_issue',v_configuration_issue,
    'import_authoritative',v_import_authoritative,
    'candidate_hours_view_only',v_import_authoritative,
    'candidate_expense_only_carrier_required',v_import_authoritative,
    'candidate_paper_timesheet',v_configuration_valid and not v_import_authoritative and v_workflow<>'DAILY',
    'timesheet_break_entry',v_configuration_valid and not v_import_authoritative and v_workflow<>'IMPORT',
    'invoice_settings',true,
    'finance_settings',true
  );
  v_payload:=jsonb_build_object(
    'authority_version','CONTRACT_SETTINGS_AUTHORITY_V1',
    'client_id',v_client_id,
    'contract_id',p_contract_id,
    'timesheet_id',p_timesheet_id,
    'relevant_date',p_relevant_date,
    'workflow',v_workflow,
    'client_settings_id',v_client.id,
    'client_settings_effective_from',v_client.effective_from,
    'client_settings_updated_at',v_client.updated_at,
    'global_settings_updated_at',v_defaults.updated_at,
    'finance_settings_id',nullif(v_finance->>'id','')::uuid,
    'finance_settings_date_from',nullif(v_finance->>'date_from','')::date,
    'contract_updated_at',case when p_contract_id is null then null else v_contract.updated_at end,
    'override_client_settings',v_override,
    'configured_route',v_route,
    'values',v_values,
    'sources',v_sources,
    'components',v_components,
    'applicability',v_applicability
  );
  v_fingerprint:=encode(digest(convert_to(v_payload::text,'UTF8'),'sha256'),'hex');
  return v_payload||jsonb_build_object(
    'authority_fingerprint',v_fingerprint,
    'resolved_at_utc',statement_timestamp()
  );
end
$function$;

create or replace function private._contract_week_settings_authority_before_v1()
returns trigger
language plpgsql
volatile
security definer
set search_path = pg_catalog, public, private, extensions, pg_temp
as $function$
declare v_contract public.contracts%rowtype; v_snapshot jsonb;
begin
  if tg_op='UPDATE' and old.timesheet_id is not null then
    new.settings_authority_json:=old.settings_authority_json;
    new.settings_authority_version:=old.settings_authority_version;
    new.settings_authority_fingerprint:=old.settings_authority_fingerprint;
    new.settings_authority_resolved_at:=old.settings_authority_resolved_at;
    return new;
  end if;
  if new.timesheet_id is not null and tg_op='UPDATE'
     and old.settings_authority_json<>'{}'::jsonb then
    new.settings_authority_json:=old.settings_authority_json;
    new.settings_authority_version:=old.settings_authority_version;
    new.settings_authority_fingerprint:=old.settings_authority_fingerprint;
    new.settings_authority_resolved_at:=old.settings_authority_resolved_at;
    return new;
  end if;
  select * into v_contract from public.contracts c where c.id=new.contract_id;
  if not found then return new; end if;
  v_snapshot:=private._contract_settings_effective_core_v1(
    v_contract.client_id,v_contract.id,new.week_ending_date,'WEEKLY',null
  );
  if not coalesce(new.is_adjustment,false) and coalesce(new.additional_seq,0)=0 then
    new.submission_mode_snapshot:=coalesce(
      v_snapshot#>>'{values,default_submission_mode}',
      'ELECTRONIC'
    )::public.submission_mode_enum;
  end if;
  new.settings_authority_json:=v_snapshot;
  new.settings_authority_version:='CONTRACT_SETTINGS_AUTHORITY_V1';
  new.settings_authority_fingerprint:=v_snapshot->>'authority_fingerprint';
  new.settings_authority_resolved_at:=(v_snapshot->>'resolved_at_utc')::timestamptz;
  return new;
end
$function$;

CREATE OR REPLACE FUNCTION private.bpay_expense_classification_week_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
DECLARE old_ts uuid; new_ts uuid; lock_id uuid;
BEGIN
 IF TG_WHEN='BEFORE' THEN
  -- S-07 (a): an UPDATE that changes no Stage 2 decision input read from contract_weeks takes no gate.
  -- Status is not an input (it changes only a refusal reason, never an allow/refuse outcome).
  IF TG_OP='UPDATE'
     AND NEW.timesheet_id IS NOT DISTINCT FROM OLD.timesheet_id
     AND NEW.contract_id IS NOT DISTINCT FROM OLD.contract_id
     AND NEW.week_ending_date IS NOT DISTINCT FROM OLD.week_ending_date
     AND NEW.additional_seq IS NOT DISTINCT FROM OLD.additional_seq
     AND NEW.is_adjustment IS NOT DISTINCT FROM OLD.is_adjustment
  THEN
   RETURN NEW;
  END IF;
  -- A5 V2 / S-02 refusal of a new reference to a Timesheet this transaction cannot see (unchanged).
  IF TG_OP<>'DELETE' THEN
   IF NEW.timesheet_id IS NOT NULL
   AND NOT EXISTS (SELECT 1 FROM public.timesheets t WHERE t.timesheet_id=NEW.timesheet_id) THEN
    IF TG_OP='INSERT' THEN RAISE EXCEPTION 'BPAY_EXPENSE_TIMESHEET_NOT_VISIBLE' USING ERRCODE='23503'; END IF;
    IF NEW.timesheet_id IS DISTINCT FROM OLD.timesheet_id THEN RAISE EXCEPTION 'BPAY_EXPENSE_TIMESHEET_NOT_VISIBLE' USING ERRCODE='23503'; END IF;
   END IF;
  END IF;
  -- S-07 (b): WAIT for the old and new bound Timesheet rows (lower id first), then re-read the new binding.
  IF TG_OP<>'INSERT' THEN old_ts:=OLD.timesheet_id; END IF;
  IF TG_OP='INSERT' THEN new_ts:=NEW.timesheet_id;
  ELSIF TG_OP='UPDATE' AND NEW.timesheet_id IS DISTINCT FROM OLD.timesheet_id THEN new_ts:=NEW.timesheet_id;
  END IF;
  FOR lock_id IN SELECT x FROM unnest(ARRAY[old_ts,new_ts]) x WHERE x IS NOT NULL ORDER BY x LOOP
   IF NOT private.bpay_source_row_wait_gate_v1(lock_id) AND lock_id=new_ts THEN
    RAISE EXCEPTION 'BPAY_EXPENSE_TIMESHEET_NOT_VISIBLE' USING ERRCODE='23503';
   END IF;
  END LOOP;
 ELSE
  PERFORM private._candidate_expense_source_family_v1(NEW.timesheet_id);
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END; $function$;

create or replace function private.weekly_source_invoice_allocation_assert_v1(
  p_invoice_id uuid
) returns jsonb
language plpgsql stable security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_invoice public.invoices%rowtype;
  v_line_count integer;
  v_binding_count integer;
  v_has_source_header boolean;
begin
  select * into v_invoice from public.invoices where id=p_invoice_id;
  if not found then
    raise exception 'WEEKLY_SOURCE_INVOICE_NOT_FOUND' using errcode='22023';
  end if;
  select pg_catalog.count(*)::integer into v_binding_count
  from public.weekly_source_invoice_line_bindings binding
  where binding.invoice_id=p_invoice_id and binding.state='CURRENT';
  v_has_source_header:=coalesce(
    v_invoice.header_snapshot_json#>>'{meta,source}'='WEEKLY_FINAL_SOURCE'
    and v_invoice.header_snapshot_json#>>'{meta,self_bill}'='true',false
  );
  if v_binding_count=0 then
    if not v_has_source_header then
      return pg_catalog.jsonb_build_object(
        'ok',true,'is_source_invoice',false,'invoice_id',p_invoice_id
      );
    end if;
    select pg_catalog.count(*)::integer into v_line_count
    from public.invoice_lines invoice_line where invoice_line.invoice_id=p_invoice_id;
    if exists(select 1 from public.invoice_lines invoice_line where invoice_line.invoice_id=p_invoice_id
      and private.weekly_source_invoice_adjustment_line_valid_v1(invoice_line.id,p_invoice_id) is distinct from true) then
      raise exception 'WEEKLY_SOURCE_INVOICE_EXTRA_LINE' using errcode='55000';
    end if;
    if v_invoice.subtotal_ex_vat is distinct from (select round(coalesce(sum(total_charge_ex_vat),0),2) from public.invoice_lines where invoice_id=p_invoice_id)
      or v_invoice.vat_amount is distinct from (select round(coalesce(sum(vat_amount),0),2) from public.invoice_lines where invoice_id=p_invoice_id)
      or v_invoice.total_inc_vat is distinct from (select round(coalesce(sum(total_inc_vat),0),2) from public.invoice_lines where invoice_id=p_invoice_id) then
      raise exception 'WEEKLY_SOURCE_INVOICE_TOTAL_MISMATCH' using errcode='55000';
    end if;
    return pg_catalog.jsonb_build_object(
      'ok',true,'is_source_invoice',true,'invoice_id',p_invoice_id,
      'line_count',v_line_count,'binding_count',0,'empty',v_line_count=0
    );
  end if;
  if not v_has_source_header then
    raise exception 'WEEKLY_SOURCE_INVOICE_HEADER_INVALID' using errcode='55000';
  end if;
  select pg_catalog.count(*)::integer into v_line_count
  from public.invoice_lines invoice_line where invoice_line.invoice_id=p_invoice_id;

  if exists(
    select 1 from public.invoice_lines invoice_line
    where invoice_line.invoice_id=p_invoice_id
      and not exists(
        select 1 from public.weekly_source_invoice_line_bindings binding
        where binding.invoice_line_id=invoice_line.id
          and binding.invoice_id=p_invoice_id and binding.state='CURRENT'
      )
      and private.weekly_source_invoice_adjustment_line_valid_v1(invoice_line.id,p_invoice_id) is distinct from true
  ) then
    raise exception 'WEEKLY_SOURCE_INVOICE_EXTRA_LINE' using errcode='55000';
  end if;

  perform private.weekly_source_invoice_receipt_projection_assert_v1(p_invoice_id);
  if exists(
    select 1
    from public.weekly_source_invoice_line_bindings binding
    join public.weekly_source_billing_movements movement
      on movement.id=binding.billing_movement_id
    join public.weekly_source_invoice_presentation_lines presentation
      on presentation.id=binding.presentation_line_id
    join public.invoice_lines invoice_line on invoice_line.id=binding.invoice_line_id
    join public.weekly_source_invoice_placements placement
      on placement.billing_movement_id=movement.id and placement.is_current
    join public.weekly_source_manifest_movements manifest_movement
      on manifest_movement.billing_movement_id=movement.id
    join public.weekly_source_client_manifests manifest
      on manifest.id=manifest_movement.client_manifest_id
    where binding.invoice_id=p_invoice_id and binding.state='CURRENT'
      and (
        invoice_line.invoice_id is distinct from p_invoice_id
        or placement.invoice_id is distinct from p_invoice_id
        or placement.invoice_line_id is distinct from invoice_line.id
        or placement.placement_state<>'PLACED'
        or placement.original_automatic_cycle_id is distinct from coalesce(manifest.invoice_window_cycle_id,manifest.source_cycle_id)
        or private.weekly_source_invoice_movement_window_id_v1(movement.id) is distinct from coalesce(manifest.invoice_window_cycle_id,manifest.source_cycle_id)
        or binding.client_id is distinct from v_invoice.client_id
        or movement.actual_client_id is distinct from v_invoice.client_id
        or presentation.client_id is distinct from v_invoice.client_id
        or manifest.client_id is distinct from v_invoice.client_id
        or manifest_movement.movement_hash is distinct from movement.movement_economic_hash
        or binding.manifest_hash is distinct from manifest.manifest_hash
        or presentation.client_manifest_id is distinct from manifest.id
        or presentation.final_revision_id is distinct from movement.final_revision_id
        or presentation.original_finalisation_cycle_id is distinct from movement.finalisation_cycle_id
        or invoice_line.timesheet_id is distinct from movement.invoice_timesheet_id
        or invoice_line.total_pay_ex_vat is distinct from presentation.total_pay_ex_vat
        or invoice_line.total_charge_ex_vat is distinct from presentation.total_charge_ex_vat
        or invoice_line.vat_rate_pct is distinct from presentation.vat_rate_pct
        or invoice_line.vat_amount is distinct from presentation.vat_amount
        or invoice_line.total_inc_vat is distinct from presentation.total_inc_vat
        or (presentation.invoice_hold_release_id is not null and (presentation.source_hash is distinct from
          private.weekly_source_invoice_presentation_source_hash_v1((select array_agg(b.billing_movement_id order by b.billing_movement_id)
            from public.weekly_source_invoice_line_bindings b where b.presentation_line_id=presentation.id and b.state='CURRENT'),presentation.invoice_hold_release_id)
          or invoice_line.meta_json->'invoice_hold_release_authority' is distinct from private.weekly_source_invoice_presentation_release_authority_v1(
            (select array_agg(b.billing_movement_id order by b.billing_movement_id) from public.weekly_source_invoice_line_bindings b
              where b.presentation_line_id=presentation.id and b.state='CURRENT'),presentation.invoice_hold_release_id)))
      )
  ) then
    raise exception 'WEEKLY_SOURCE_INVOICE_ALLOCATION_MISMATCH' using errcode='55000';
  end if;

  if exists(
    select 1
    from (
      select binding.invoice_line_id,
             pg_catalog.count(*)::integer as member_count,
             pg_catalog.count(distinct movement.correction_unit_id) as correction_count,
             pg_catalog.count(distinct movement.work_event_id) as event_count,
             pg_catalog.count(distinct movement.final_revision_id) as revision_count,
             pg_catalog.count(distinct movement.finalisation_cycle_id) as cycle_count,
             pg_catalog.count(distinct movement.actual_client_id) as client_count,
             pg_catalog.count(*) filter(where movement.source_profile_kind='NHSP_TRUST_BACKING_REPORT') as nhsp_count,
             pg_catalog.array_agg(movement.movement_role order by movement.movement_role) as roles,
             pg_catalog.min(presentation.correction_role) as correction_role
      from public.weekly_source_invoice_line_bindings binding
      join public.weekly_source_billing_movements movement
        on movement.id=binding.billing_movement_id
      join public.weekly_source_invoice_presentation_lines presentation
        on presentation.id=binding.presentation_line_id
      where binding.invoice_id=p_invoice_id and binding.state='CURRENT'
      group by binding.invoice_line_id
    ) grouped
    where grouped.member_count not in (1,2)
       or (grouped.member_count=2 and (
         grouped.correction_count<>1 or grouped.event_count<>1
         or grouped.revision_count<>1 or grouped.cycle_count<>1
         or grouped.client_count<>1 or grouped.nhsp_count<>0
         or grouped.correction_role is distinct from 'NET_DIFFERENCE'
         or grouped.roles not in (
           array['REPLACEMENT','REVERSAL']::text[],
           array['EXPENSE_REPLACEMENT','EXPENSE_REVERSAL']::text[]
         )
       ))
  ) then
    raise exception 'WEEKLY_SOURCE_INVOICE_NET_CARDINALITY_INVALID' using errcode='55000';
  end if;

  if v_invoice.subtotal_ex_vat is distinct from (
       select pg_catalog.round(coalesce(pg_catalog.sum(line.total_charge_ex_vat),0),2)
       from public.invoice_lines line where line.invoice_id=p_invoice_id
     )
     or v_invoice.vat_amount is distinct from (
       select pg_catalog.round(coalesce(pg_catalog.sum(line.vat_amount),0),2)
       from public.invoice_lines line where line.invoice_id=p_invoice_id
     )
     or v_invoice.total_inc_vat is distinct from (
       select pg_catalog.round(coalesce(pg_catalog.sum(line.total_inc_vat),0),2)
       from public.invoice_lines line where line.invoice_id=p_invoice_id
     ) then
    raise exception 'WEEKLY_SOURCE_INVOICE_TOTAL_MISMATCH' using errcode='55000';
  end if;

  return pg_catalog.jsonb_build_object(
    'ok',true,'is_source_invoice',true,'invoice_id',p_invoice_id,
    'line_count',v_line_count,'binding_count',v_binding_count
  );
end;
$function$;

create or replace function public.trg_tsfin_timesheet_validations_wakeup()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_ts_id uuid;
  v_skip boolean := false;
begin
  v_ts_id := coalesce(new.timesheet_id, old.timesheet_id);

  if v_ts_id is null then
    return coalesce(new, old);
  end if;

  -- ------------------------------------------------------------
  -- Skip if timesheet is invoice-locked (issued/paid etc), or revoked, or missing
  -- We gate on timesheets_financials.is_current + locked_by_invoice_id
  -- and also ensure the timesheet exists and is current.
  -- ------------------------------------------------------------
  select
    (
      tf.timesheet_id is null
      or tf.is_current is not true
      or tf.locked_by_invoice_id is not null
      or ts.timesheet_id is null
      or ts.is_current is not true
      or ts.revoked_at is not null
    ) as should_skip
  into v_skip
  from public.timesheets ts
  left join public.timesheets_financials tf
    on tf.timesheet_id = ts.timesheet_id
   and tf.is_current = true
  where ts.timesheet_id = v_ts_id
  limit 1;

  if coalesce(v_skip, true) then
    return coalesce(new, old);
  end if;

  -- Priority TSFIN enqueue (idempotent on (timesheet_id, reason))
  perform public.enqueue_ts_financials_priority(
    array[v_ts_id],
    'CONTEXT_CHANGED'::public.ts_fin_reason_enum
  );

  return coalesce(new, old);
end;
$$;

create or replace function private.timesheet_correction_a0_reference_before_v1()
returns trigger language plpgsql volatile security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare v_ids uuid[]; v_bookings text[];
begin
  if tg_table_schema<>'public' or tg_table_name not in('timesheet_validations','invoice_lines') or tg_op not in('INSERT','UPDATE') then
    raise exception 'CORRECTION_A0_WRITER_TRIGGER_CONTEXT_INVALID' using errcode='55000'; end if;
  if tg_table_name='invoice_lines' then
    if tg_op='UPDATE' then
      if new.timesheet_id is not distinct from old.timesheet_id and new.booking_id is not distinct from old.booking_id then return new; end if;
      v_bookings:=array[old.booking_id,new.booking_id];
    else v_bookings:=array[new.booking_id]; end if;
  elsif tg_op='UPDATE' and new.timesheet_id is not distinct from old.timesheet_id then return new;
  end if;
  if tg_op='UPDATE' then
    select array_agg(distinct x.id order by x.id) into v_ids from unnest(array[old.timesheet_id,new.timesheet_id]) x(id) where x.id is not null;
  else v_ids:=case when new.timesheet_id is null then null else array[new.timesheet_id] end; end if;
  if v_ids is not null or v_bookings is not null then perform private.timesheet_correction_a0_writer_admit_v1(v_ids,v_bookings,
    case when tg_table_name='invoice_lines' then 'INVOICE_REFERENCE' else 'VALIDATION_REFERENCE' end); end if;
  return new;
end;
$function$;

create or replace function private._candidate_office_service_context_valid_v1(
  p_environment text,
  p_actor_user_id uuid,
  p_action text
)
returns boolean
language plpgsql
stable
security definer
set search_path = pg_catalog, public, private, pg_temp
as $function$
declare
  v_context jsonb;
begin
  begin
    v_context:=nullif(current_setting('cloudtms.office_candidate_context',true),'')::jsonb;
  exception when others then
    return false;
  end;
  return coalesce(v_context->>'contract_version','')='CANDIDATE_OFFICE_SERVICE_CONTEXT_V1'
    and (p_environment is null
      or v_context->>'environment'=private._candidate_assert_environment(p_environment))
    and (p_actor_user_id is null
      or v_context->>'actor_user_id'=p_actor_user_id::text)
    and (
      v_context->>'action'=upper(btrim(coalesce(p_action,'')))
      or (
        v_context->>'permission'='reject_submission'
        and v_context->>'action'='REJECT_EXPENSE_CATEGORY'
        and upper(btrim(coalesce(p_action,''))) in (
          'WORKER_SUBMIT','PAPER_PREPARE','PAPER_MANIFEST_PROMOTE'
        )
      )
    );
end;
$function$;

create or replace function private._timesheet_route_resubmission_notifications_v1(
  p_old_timesheet_id uuid,
  p_new_timesheet_id uuid,
  p_new_version integer,
  p_target_action text,
  p_now_utc timestamptz default now()
)
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, public, private, pg_temp
as $function$
declare
  v_old public.timesheets%rowtype;
  v_new public.timesheets%rowtype;
  v_candidate public.candidates%rowtype;
  v_account public.candidate_app_accounts%rowtype;
  v_environment text;
  v_action text:=upper(btrim(coalesce(p_target_action,'')));
  v_key text;
  v_template text;
  v_created integer:=0;
  v_recipients integer:=0;
  v_existing boolean;
  v_push_enabled boolean;
  v_keys jsonb:='[]'::jsonb;
begin
  select * into v_old from public.timesheets where timesheet_id=p_old_timesheet_id;
  select * into v_new from public.timesheets where timesheet_id=p_new_timesheet_id;
  -- CONTRACT ownership is authoritative and does not depend on a GCK.  DAILY
  -- may fall through to current TSFIN/workflow/occupant identity.
  select candidate_row.* into v_candidate
  from public.contracts contract_row
  join public.candidates candidate_row on candidate_row.id=contract_row.candidate_id
  where contract_row.id=coalesce(v_new.contract_id,v_old.contract_id)
  limit 1;
  if not found then
    select candidate_row.* into v_candidate
    from public.timesheets_financials financial_row
    join public.candidates candidate_row on candidate_row.id=financial_row.candidate_id
    where financial_row.timesheet_id in (p_new_timesheet_id,p_old_timesheet_id)
      and financial_row.is_current=true
    order by (financial_row.timesheet_id=p_new_timesheet_id) desc,
      financial_row.updated_at desc,financial_row.id desc limit 1;
  end if;
  if not found then
    select workflow_candidate.* into v_candidate
  from public.candidate_submission_workflows workflow
  join public.candidates workflow_candidate on workflow_candidate.id=workflow.candidate_id
  where workflow.id=v_old.candidate_workflow_id
     or workflow.target_timesheet_id=p_old_timesheet_id
     or workflow.anchor_timesheet_id=p_old_timesheet_id
  order by (workflow.id=v_old.candidate_workflow_id) desc,workflow.updated_at_utc desc
  limit 1;
  end if;
  if not found then
    select * into v_candidate from public.candidates candidate_row
    where candidate_row.active=true
      and nullif(btrim(coalesce(candidate_row.key_norm,'')),'') is not null
      and btrim(candidate_row.key_norm)=btrim(coalesce(v_old.occupant_key_norm,''))
    order by candidate_row.id limit 1;
  end if;
  select candidate_app_environment into v_environment
  from public.settings_defaults where id=1;
  if v_candidate.id is null or v_environment is null then
    return jsonb_build_object('notification_required',true,'notification_created',false,
      'notification_created_count',0,'notification_recipient_count',0,
      'notification_recipient_unavailable',true,'notification_dedupe_keys','[]'::jsonb);
  end if;
  v_template:=case when v_action='ALLOW_QR_AGAIN'
    then 'candidate-paper-resubmission-required-v1'
    else 'candidate-electronic-resubmission-required-v1' end;

  for v_account in
    select distinct account_row.*
    from public.candidate_app_accounts account_row
    where account_row.environment=v_environment and account_row.status='ACTIVE'
      and (
        account_row.email_normalized=lower(btrim(coalesce(v_candidate.email,'')))
        or exists(select 1 from public.candidate_app_sessions session_row
          where session_row.account_id=account_row.id
            and session_row.selected_candidate_id=v_candidate.id)
        or exists(select 1 from public.candidate_submission_workflows workflow_row
          where workflow_row.account_id=account_row.id
            and workflow_row.candidate_id=v_candidate.id)
      )
    order by account_row.id
  loop
    v_recipients:=v_recipients+1;
    v_key:='candidate-resubmission-required:'||v_account.id::text||':'
      ||p_new_timesheet_id::text||':'||coalesce(p_new_version,1)::text;
    select exists(select 1 from public.candidate_notifications where dedupe_key=v_key)
      into v_existing;
    v_push_enabled:=coalesce(
      (v_account.notification_preferences_json->>'resubmission_required')::boolean,true
    );
    insert into public.candidate_notifications(
      account_id,candidate_id,workflow_id,timesheet_id,event_type,preference_category,
      template_key,template_params,deep_link_json,state,push_state,dedupe_key,created_at_utc
    ) values (
      v_account.id,v_candidate.id,null,p_new_timesheet_id,'RESUBMISSION_REQUIRED',
      'resubmission_required',v_template,
      jsonb_build_object('route',case when v_action='ALLOW_QR_AGAIN' then 'PAPER' else 'ELECTRONIC' end),
      jsonb_build_object('type','timesheet','timesheet_id',p_new_timesheet_id,
        'submission_route',case when v_action='ALLOW_QR_AGAIN' then 'PAPER' else 'ELECTRONIC' end),
      'UNREAD',case when v_push_enabled then 'PENDING' else 'SKIPPED' end,
      v_key,p_now_utc
    ) on conflict (dedupe_key) do update set dedupe_key=excluded.dedupe_key;
    if not v_existing then v_created:=v_created+1; end if;
    v_keys:=v_keys||jsonb_build_array(v_key);
  end loop;
  return jsonb_build_object(
    'notification_required',true,'notification_created',v_created>0,
    'notification_created_count',v_created,'notification_recipient_count',v_recipients,
    'notification_recipient_unavailable',v_recipients=0,
    'notification_dedupe_keys',v_keys
  );
end;
$function$;

create or replace function private._timesheet_work_intervals_v1(
  p_submission_json jsonb,
  p_actual_schedule_json jsonb,
  p_worked_start_iso timestamptz,
  p_worked_end_iso timestamptz
) returns table(work_start_utc timestamptz,work_end_utc timestamptz,work_date date)
language plpgsql immutable security invoker
set search_path='pg_catalog','pg_temp' as $function$
declare
  v_schedule jsonb;
  v_row jsonb;
  v_start_text text;
  v_end_text text;
  v_date_text text;
  v_start_clock text;
  v_end_clock text;
  v_date date;
  v_end_date date;
  v_start timestamptz;
  v_end timestamptz;
begin
  v_schedule:=case
    when jsonb_typeof(p_submission_json#>'{hours_submission,timesheet_patch_json,actual_schedule_json}')='array'
      then p_submission_json#>'{hours_submission,timesheet_patch_json,actual_schedule_json}'
    when jsonb_typeof(p_submission_json#>'{timesheet_patch_json,actual_schedule_json}')='array'
      then p_submission_json#>'{timesheet_patch_json,actual_schedule_json}'
    when jsonb_typeof(p_submission_json->'actual_schedule_json')='array'
      then p_submission_json->'actual_schedule_json'
    when jsonb_typeof(p_actual_schedule_json)='array'
      then p_actual_schedule_json
    else '[]'::jsonb
  end;

  for v_row in select value from jsonb_array_elements(v_schedule)
  loop
    if jsonb_typeof(v_row)<>'object' then
      raise exception using errcode='22023',message='TIMESHEET_WORK_INTERVAL_INVALID';
    end if;

    v_start_text:=nullif(btrim(COALESCE(
      v_row->>'start_iso',v_row->>'worked_start_iso',v_row->>'start_utc',v_row->>'worked_start',''
    )), '');
    v_end_text:=nullif(btrim(COALESCE(
      v_row->>'end_iso',v_row->>'worked_end_iso',v_row->>'end_utc',v_row->>'worked_end',''
    )), '');

    if v_start_text is not null or v_end_text is not null then
      if v_start_text is null or v_end_text is null then
        raise exception using errcode='22023',message='TIMESHEET_WORK_INTERVAL_INVALID';
      end if;
      v_start:=v_start_text::timestamptz;
      v_end:=v_end_text::timestamptz;
    else
      v_date_text:=nullif(btrim(COALESCE(v_row->>'date',v_row->>'work_date','')), '');
      v_start_clock:=nullif(btrim(COALESCE(v_row->>'start',v_row->>'start_time','')), '');
      v_end_clock:=nullif(btrim(COALESCE(v_row->>'end',v_row->>'end_time','')), '');
      if v_date_text is null or v_start_clock is null or v_end_clock is null then
        raise exception using errcode='22023',message='TIMESHEET_WORK_INTERVAL_INVALID';
      end if;
      v_date:=v_date_text::date;
      v_end_date:=v_date+case when v_end_clock::time<=v_start_clock::time then 1 else 0 end;
      v_start:=(v_date::text||' '||v_start_clock)::timestamp without time zone at time zone 'Europe/London';
      v_end:=(v_end_date::text||' '||v_end_clock)::timestamp without time zone at time zone 'Europe/London';
    end if;

    if v_end<=v_start then
      raise exception using errcode='22023',message='TIMESHEET_WORK_INTERVAL_INVALID';
    end if;
    work_start_utc:=v_start;
    work_end_utc:=v_end;
    work_date:=(v_start at time zone 'Europe/London')::date;
    return next;
  end loop;

  if jsonb_array_length(v_schedule)=0
     and (p_worked_start_iso is not null or p_worked_end_iso is not null) then
    if p_worked_start_iso is null or p_worked_end_iso is null
       or p_worked_end_iso<=p_worked_start_iso then
      raise exception using errcode='22023',message='TIMESHEET_WORK_INTERVAL_INVALID';
    end if;
    work_start_utc:=p_worked_start_iso;
    work_end_utc:=p_worked_end_iso;
    work_date:=(p_worked_start_iso at time zone 'Europe/London')::date;
    return next;
  end if;
end;$function$;

create or replace function private._candidate_timesheet_summary_workflow_revision_trg_v1()
returns trigger
language plpgsql
security definer
set search_path=pg_catalog,public,private,extensions,pg_temp
as $function$
declare
  v_current_timesheet_id uuid;
  v_contract_week_id uuid;
  v_identity_id uuid;
  v_timesheet_ids uuid[];
  v_contract_week_ids uuid[];
begin
  if tg_op='INSERT' then
    v_current_timesheet_id:=coalesce(new.target_timesheet_id,new.anchor_timesheet_id);
    v_contract_week_id:=new.contract_week_id;
    v_timesheet_ids:=array_remove(array[new.anchor_timesheet_id,new.target_timesheet_id]::uuid[],null);
    v_contract_week_ids:=array_remove(array[new.contract_week_id]::uuid[],null);
  elsif tg_op='UPDATE' then
    v_current_timesheet_id:=coalesce(new.target_timesheet_id,new.anchor_timesheet_id);
    v_contract_week_id:=coalesce(new.contract_week_id,old.contract_week_id);
    v_timesheet_ids:=array_remove(array[
      old.anchor_timesheet_id,old.target_timesheet_id,new.anchor_timesheet_id,new.target_timesheet_id
    ]::uuid[],null);
    v_contract_week_ids:=array_remove(array[old.contract_week_id,new.contract_week_id]::uuid[],null);
  else
    v_current_timesheet_id:=coalesce(old.target_timesheet_id,old.anchor_timesheet_id);
    v_contract_week_id:=old.contract_week_id;
    v_timesheet_ids:=array_remove(array[old.anchor_timesheet_id,old.target_timesheet_id]::uuid[],null);
    v_contract_week_ids:=array_remove(array[old.contract_week_id]::uuid[],null);
  end if;

  for v_identity_id in
    select distinct identity_id from unnest(v_timesheet_ids) as ids(identity_id)
  loop
    perform private._candidate_timesheet_summary_revision_upsert_v1(
      'TIMESHEET',v_identity_id,coalesce(v_current_timesheet_id,v_identity_id),v_contract_week_id
    );
  end loop;
  for v_identity_id in
    select distinct identity_id from unnest(v_contract_week_ids) as ids(identity_id)
  loop
    perform private._candidate_timesheet_summary_revision_upsert_v1(
      'CONTRACT_WEEK',v_identity_id,v_current_timesheet_id,v_identity_id
    );
  end loop;

  if tg_op='DELETE' then return old; end if;
  return new;
end;
$function$;

create or replace function private._timesheet_submission_workflow_overlap_trg_v1()
returns trigger language plpgsql volatile security definer
set search_path='public','private','pg_temp' as $function$
declare
  v_booking_id text;
begin
  if new.worker_submitted_at_utc is null
     or new.immutable_submission_json is null
     or new.state not in (
       'WORKER_SUBMITTED','WORKER_SUBMITTED_PENDING_REVIEW_DOCUMENT',
       'READY_FOR_MANAGER_APPROVAL','AWAITING_MANAGER_APPROVAL',
       'MANAGER_APPROVED','MANAGER_APPROVED_PENDING_FINAL_DOCUMENT',
       'READY_TO_FINALISE','AWAITING_PAPER_RETURN','RECEIVED','FINALISED'
     ) then return new; end if;

  if tg_op='UPDATE'
     and old.worker_submitted_at_utc is not distinct from new.worker_submitted_at_utc
     and old.immutable_submission_json is not distinct from new.immutable_submission_json
     and old.state in (
       'WORKER_SUBMITTED','WORKER_SUBMITTED_PENDING_REVIEW_DOCUMENT',
       'READY_FOR_MANAGER_APPROVAL','AWAITING_MANAGER_APPROVAL',
       'MANAGER_APPROVED','MANAGER_APPROVED_PENDING_FINAL_DOCUMENT',
       'READY_TO_FINALISE','AWAITING_PAPER_RETURN','RECEIVED','FINALISED'
     ) then return new; end if;

  select t.booking_id into v_booking_id
  from public.timesheets t
  where t.timesheet_id=COALESCE(new.target_timesheet_id,new.anchor_timesheet_id)
  limit 1;

  perform private._timesheet_cross_record_overlap_assert_v1(
    new.candidate_id,new.immutable_submission_json,null,null,null,
    new.id,COALESCE(new.target_timesheet_id,new.anchor_timesheet_id),v_booking_id
  );
  return new;
end;$function$;

create or replace function private._candidate_workflow_creation_identity_guard_v1()
returns trigger
language plpgsql
security definer
set search_path = pg_catalog, public, private, pg_temp
as $function$
begin
  if old.creation_request_sha256 is not null
     and (
       new.creation_request_sha256 is distinct from old.creation_request_sha256
       or new.creation_identity_json is distinct from old.creation_identity_json
     ) then
    raise exception 'CANDIDATE_CREATION_IDENTITY_IMMUTABLE' using errcode='55000';
  end if;
  if (new.creation_request_sha256 is null)<>(new.creation_identity_json is null) then
    raise exception 'CANDIDATE_CREATION_IDENTITY_INVALID' using errcode='22023';
  end if;
  return new;
end;
$function$;

create or replace function private._candidate_expense_workflow_sync_trigger_v1()
returns trigger
language plpgsql
security definer
set search_path = pg_catalog, private, pg_temp
as $function$
begin
  if new.workflow_kind in ('CONTRACT_EXPENSE','CONTRACT_COMBINED')
     and new.immutable_submission_json is not null
     and not exists(
       select 1 from public.candidate_pending_expense_updates update_row
       where update_row.workflow_id=new.id and update_row.state in ('EDITING','RENDERING')
     ) then
    perform private._candidate_expense_components_sync_v1(new.id,pg_catalog.transaction_timestamp());
  end if;
  return new;
end;
$function$;

create or replace function private.candidate_hours_received_audit_v1()
returns trigger
language plpgsql
security definer
set search_path to 'pg_catalog','pg_temp'
as $function$
declare
  v_timesheet_id uuid;
  v_correlation_id text;
begin
  if new.workflow_kind <> 'CONTRACT_HOURS'
    or new.state <> 'WORKER_SUBMITTED'
    or new.candidate_signed_at_utc is null
    or new.worker_submitted_at_utc is null
    or (old.generation = new.generation
      and old.state is not distinct from new.state
      and old.candidate_signed_at_utc is not distinct from new.candidate_signed_at_utc
      and old.worker_submitted_at_utc is not distinct from new.worker_submitted_at_utc)
  then
    return new;
  end if;

  v_timesheet_id:=coalesce(new.target_timesheet_id,new.anchor_timesheet_id);
  if v_timesheet_id is null then
    return new;
  end if;
  v_correlation_id:='candidate-hours-received:'||new.id::text||':'||new.generation::text;
  if not exists (
    select 1 from public.audit_events audit
    where audit.correlation_id=v_correlation_id
      and audit.object_type='timesheets'
      and audit.object_id_text=v_timesheet_id::text
      and audit.action='CANDIDATE_HOURS_RECEIVED'
  ) then
    insert into public.audit_events(
      ts_utc,actor_display,actor_role_at_time,object_type,object_id_text,
      action,after_json,reason,correlation_id
    ) values (
      new.worker_submitted_at_utc,'Candidate','candidate','timesheets',v_timesheet_id::text,
      'CANDIDATE_HOURS_RECEIVED',
      pg_catalog.jsonb_build_object('workflow_id',new.id,'generation',new.generation,
        'candidate_signed_at_utc',new.candidate_signed_at_utc,
        'workflow_kind',new.workflow_kind),
      'Candidate hours submitted',v_correlation_id
    );
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION private._candidate_expense_components_sync_financial_v1(p_timesheet_id uuid, p_now_utc timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
declare
  v_fin public.timesheets_financials%rowtype;
  v_timesheet public.timesheets%rowtype;
  v_component public.candidate_expense_components%rowtype;
  v_before jsonb;
  v_agency text;
  v_count integer:=0;
begin
  if private._candidate_expense_source_family_v1(p_timesheet_id) then
    return jsonb_build_object('ok',true,'timesheet_id',p_timesheet_id,'component_count',0);
  end if;
  select * into v_timesheet from public.timesheets row
  where row.timesheet_id=p_timesheet_id;
  select * into v_fin from public.timesheets_financials row
  where row.timesheet_id=p_timesheet_id and row.is_current
  order by row.computed_at_utc desc nulls last,row.updated_at desc,row.id desc limit 1;
  if not found or v_timesheet.timesheet_id is null then
    return jsonb_build_object('ok',true,'component_count',0);
  end if;
  v_agency:=case
    when v_fin.paid_at_utc is not null or upper(coalesce(v_timesheet.status::text,''))='PAID'
      then 'PAID'
    when v_fin.locked_by_invoice_id is not null
      or upper(coalesce(v_timesheet.status::text,''))='INVOICED' then 'INVOICED'
    when v_fin.authorised_at_utc is not null or v_timesheet.authorised_at_server is not null
      or upper(coalesce(v_timesheet.status::text,'')) in ('AUTHORISED','AUTHORIZED')
      then 'AUTHORISED'
    else 'NOT_AUTHORISED' end;
  for v_component in
    select component.*
    from public.candidate_expense_components component
    where component.lifecycle_state not in (
      'MANAGER_REFUSED','OFFICE_REJECTED','WITHDRAWN','CANCELLED','SUPERSEDED'
    )
      and private._candidate_expense_owned_timesheet_id_v1(
        component.workflow_id,component.owning_timesheet_id
      )=p_timesheet_id
    order by component.expense_component_id
    for update
  loop
    if v_component.agency_authorisation_state is distinct from v_agency
       or v_component.owning_timesheet_id is distinct from p_timesheet_id then
      v_before:=to_jsonb(v_component);
      update public.candidate_expense_components set
        component_generation=component_generation+1,
        owning_timesheet_id=p_timesheet_id,
        agency_authorisation_state=v_agency,
        updated_at_utc=p_now_utc
      where expense_component_id=v_component.expense_component_id
      returning * into v_component;
      insert into public.candidate_expense_component_events(
        expense_component_id,workflow_id,component_generation,event_type,actor_kind,
        before_state_json,after_state_json,idempotency_key,occurred_at_utc
      ) values (
        v_component.expense_component_id,v_component.workflow_id,
        v_component.component_generation,
        case when v_before->>'agency_authorisation_state' is not distinct from v_agency
          then 'OWNER_ROTATED'
          else case v_agency when 'PAID' then 'PAID' when 'INVOICED' then 'INVOICED'
            when 'AUTHORISED' then 'AUTHORISED' else 'AGENCY_PROTECTION_CLEARED' end end,
        'SYSTEM',v_before,to_jsonb(v_component),
        'financial-protection-sync:'||v_fin.id::text||':'
          ||v_component.expense_component_id::text||':'||v_agency||':'
          ||p_timesheet_id::text,p_now_utc
      ) on conflict(expense_component_id,idempotency_key) do nothing;
      v_count:=v_count+1;
    end if;
  end loop;
  return jsonb_build_object('ok',true,'timesheet_id',p_timesheet_id,
    'component_count',v_count);
end;
$function$;

CREATE OR REPLACE FUNCTION private.weekly_source_ordinary_authorisation_guard_v1(p_timesheet_id uuid, p_booking_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
DECLARE current_id uuid;
 n_current integer; n_live_current integer; other_live boolean;
 actual_booking text; bound boolean:=false; relevant boolean;
 ok boolean:=false; managed boolean:=false; contradictory boolean:=false;
 authorised boolean; refuse boolean; reason text; basis text;
 result_family text; result_current uuid;
BEGIN
 IF p_timesheet_id IS NULL THEN
  RETURN jsonb_build_object('refuse',true,'refusal_basis','WEEKLY_SOURCE_MANAGED_ROOT',
   'reason','ROOT_ID_REQUIRED','timesheet_id',null,'managed',true,'ok',false,
   'weekly_source_bound',true,'authorisation_record_without_authorised_timesheet',false);
 END IF;
 SELECT booking_id INTO actual_booking FROM public.timesheets WHERE timesheet_id=p_timesheet_id;
 relevant:=FOUND;
 IF NOT relevant THEN
  relevant:=EXISTS(SELECT 1 FROM public.weekly_source_row_timesheet_lineages WHERE timesheet_id=p_timesheet_id)
    OR EXISTS(SELECT 1 FROM public.weekly_source_root_authorisations WHERE root_timesheet_id=p_timesheet_id)
    OR EXISTS(SELECT 1 FROM public.weekly_exceptional_pay_target_families WHERE root_timesheet_id=p_timesheet_id);
  IF relevant THEN reason:='BOOKING_IDENTITY_MISSING';bound:=true;managed:=true;
  ELSE reason:='ROOT_NOT_FOUND'; END IF;
 ELSE
  PERFORM private.bpay_source_family_try_lock_v1(actual_booking);
  IF p_booking_id IS DISTINCT FROM actual_booking THEN
   PERFORM private.bpay_source_family_try_lock_v1(p_booking_id);
  END IF;
  -- S-02: ordinary rotations take no family lock; decide under native share locks on the requested row
  -- (already row-locked when called from the authorisation trigger) and on the family's current row.
  PERFORM private.bpay_source_row_gate_v1(p_timesheet_id,false);
  PERFORM private.bpay_source_family_current_gate_v1(actual_booking);
  IF (SELECT t.booking_id FROM public.timesheets t WHERE t.timesheet_id=p_timesheet_id) IS DISTINCT FROM actual_booking THEN
   RAISE EXCEPTION 'BPAY_SOURCE_FAMILY_BUSY' USING ERRCODE='55P03';
  END IF;
  -- Stored lineage family is enforced against its original physical identity;
  -- no expansion of all Timesheet versions is needed to establish binding.
  bound:=EXISTS(SELECT 1 FROM public.weekly_source_row_timesheet_lineages l
                WHERE l.timesheet_id=p_timesheet_id)
    OR (btrim(actual_booking)<>'' AND
       (EXISTS(SELECT 1 FROM public.weekly_source_row_timesheet_lineages l
                 WHERE btrim(l.family_booking_id)=btrim(actual_booking))
        OR EXISTS(SELECT 1 FROM public.weekly_exceptional_pay_target_families f
                 WHERE btrim(f.root_family_booking_id)=btrim(actual_booking))));
  IF actual_booking IS NULL OR btrim(actual_booking)='' THEN
   reason:='BOOKING_IDENTITY_MISSING'; managed:=true;
  ELSE
   IF NOT EXISTS(SELECT 1 FROM private.bpay_clock_rows_v1 r
     JOIN private.bpay_clock_families_v1 f ON f.id=r.family_id
     WHERE r.timesheet_id=p_timesheet_id AND f.booking_id=actual_booking) THEN
    RAISE EXCEPTION 'BPAY_SOURCE_DIRECTORY_NOT_READY' USING ERRCODE='55000';
   END IF;
   IF EXISTS(SELECT 1 FROM private.bpay_clock_families_v1 f
      WHERE btrim(f.booking_id)=btrim(actual_booking) AND f.booking_id<>actual_booking) THEN
    reason:='BOOKING_REFERENCE_CANONICAL_COLLISION'; managed:=true;
   ELSE
    SELECT count(*),min(t.timesheet_id::text)::uuid INTO n_current,current_id
    FROM (SELECT timesheet_id FROM public.timesheets
          WHERE booking_id=actual_booking AND is_current LIMIT 2) t;
    IF n_current<>1 THEN
     reason:=CASE WHEN n_current=0 THEN 'CANONICAL_AMBIGUOUS' ELSE 'CURRENT_ROW_CARDINALITY' END;
     managed:=true;
    ELSE
     -- Only live authority influences ordinary authorisation. Withdrawn
     -- records are immutable history, not rows that this operation must lock.
     PERFORM 1 FROM public.weekly_source_root_authorisations a
      WHERE a.family_booking_id=actual_booking AND a.withdrawn_at_utc IS NULL
      LIMIT 2 FOR UPDATE;
     SELECT count(*) INTO n_live_current FROM
       (SELECT 1 FROM public.weekly_source_root_authorisations a
        WHERE a.root_timesheet_id=current_id AND a.withdrawn_at_utc IS NULL LIMIT 2) a;
     other_live:=EXISTS(SELECT 1 FROM public.weekly_source_root_authorisations a
       WHERE a.family_booking_id=actual_booking AND a.withdrawn_at_utc IS NULL
       AND a.root_timesheet_id<>current_id);
     IF n_live_current>1 THEN
      reason:='ROOT_AUTHORISATION_CARDINALITY'; managed:=true;bound:=true;
      result_family:=actual_booking;result_current:=current_id;
     ELSIF other_live THEN
      reason:='AUTHORISED_ROOT_NOT_CANONICAL'; managed:=true;bound:=true;
      result_family:=actual_booking;result_current:=current_id;
     ELSE
      authorised:=EXISTS(SELECT 1 FROM public.timesheets t
                    WHERE t.timesheet_id=current_id AND t.authorised_at_server IS NOT NULL)
        OR EXISTS(SELECT 1 FROM public.timesheets_financials f
                    WHERE f.timesheet_id=current_id AND f.is_current AND f.authorised_at_utc IS NOT NULL)
        OR EXISTS(SELECT 1 FROM public.contract_weeks w
                    WHERE w.timesheet_id=current_id AND upper(btrim(w.status::text))='AUTHORISED');
      managed:=n_live_current=1 AND authorised;
      contradictory:=n_live_current=1 AND NOT authorised;
      ok:=true;result_family:=actual_booking;result_current:=current_id;
     END IF;
    END IF;
   END IF;
  END IF;
 END IF;
 refuse:=(managed AND (ok OR bound)) OR contradictory;
 basis:=CASE WHEN reason IN ('FAMILY_SPLIT_BY_WHITESPACE','BOOKING_REFERENCE_CANONICAL_COLLISION')
          THEN 'BOOKING_REFERENCE_CANONICAL_COLLISION'
        WHEN managed AND ok THEN 'WEEKLY_SOURCE_MANAGED_ROOT'
        WHEN managed THEN 'WEEKLY_SOURCE_BOUND_OR_PROTECTED_ROOT_UNRESOLVABLE'
        WHEN contradictory THEN 'AUTHORISATION_RECORD_WITHOUT_AUTHORISED_TIMESHEET'
        ELSE 'WEEKLY_SOURCE_MANAGED_ROOT' END;
 RETURN jsonb_build_object('refuse',refuse,'refusal_basis',CASE WHEN refuse THEN basis ELSE NULL END,
  'reason',reason,'timesheet_id',p_timesheet_id,'canonical_timesheet_id',result_current,
  'family_booking_id',result_family,'managed',managed,'ok',ok,'weekly_source_bound',bound,
  'authorisation_record_without_authorised_timesheet',contradictory);
END; $function$;

CREATE OR REPLACE FUNCTION private.bpay_clock_rebuild_v1(p_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
DECLARE t public.timesheets%rowtype; f uuid; financial_at timestamptz; consumed timestamptz;
BEGIN
 SELECT * INTO t FROM public.timesheets WHERE timesheet_id=p_id FOR NO KEY UPDATE;
 IF NOT FOUND OR t.booking_id IS NULL OR btrim(t.booking_id)='' THEN
  DELETE FROM private.bpay_clock_rows_v1 WHERE timesheet_id=p_id; RETURN;
 END IF;
 SELECT id INTO f FROM private.bpay_clock_families_v1 WHERE booking_id=t.booking_id;
 IF f IS NULL THEN
  INSERT INTO private.bpay_clock_families_v1(booking_id) VALUES(t.booking_id)
  ON CONFLICT(booking_id) DO UPDATE SET booking_id=excluded.booking_id RETURNING id INTO f;
 END IF;
 SELECT authorised_at_utc INTO financial_at FROM public.timesheets_financials
 WHERE timesheet_id=p_id ORDER BY authorised_at_utc DESC NULLS LAST LIMIT 1;
 SELECT advance_authorisation_consumed_at_utc INTO consumed
 FROM public.timesheet_summary_pay_state_cache WHERE timesheet_id=p_id;
 INSERT INTO private.bpay_clock_rows_v1 VALUES(p_id,f,greatest(t.authorised_at_server,t.revoked_at,financial_at),consumed)
 ON CONFLICT(timesheet_id) DO UPDATE SET family_id=excluded.family_id,
 authorisation_at=excluded.authorisation_at,consumed_at=excluded.consumed_at;
END;
$function$;

CREATE OR REPLACE FUNCTION private.bpay_source_family_try_lock_v1(p_booking text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
BEGIN
 IF p_booking IS NULL OR btrim(p_booking)='' THEN RETURN; END IF;
 -- Nonblocking acquisition is essential for row-trigger callers: never wait
 -- for a family lock while retaining a row lock wanted by that family owner.
 IF NOT pg_try_advisory_xact_lock(hashtext(btrim(p_booking))) THEN
  RAISE EXCEPTION 'BPAY_SOURCE_FAMILY_BUSY' USING ERRCODE='55P03';
 END IF;
 IF p_booking<>btrim(p_booking)
 AND NOT pg_try_advisory_xact_lock(hashtext(p_booking)) THEN
  RAISE EXCEPTION 'BPAY_SOURCE_FAMILY_BUSY' USING ERRCODE='55P03';
 END IF;
END; $function$;

create or replace function private.timesheet_correction_applied_assert_v1(p_request_id uuid)
returns void language plpgsql security definer
set search_path to 'pg_catalog','public','private','pg_temp'
as $function$
declare v_request private.timesheet_correction_requests%rowtype; v_row record; v_role text;
begin
  select request.* into strict v_request from private.timesheet_correction_requests request where request.id=p_request_id;
  if v_request.state<>'APPLIED' then return; end if;
  if (select count(*) from public.timesheets t where t.timesheet_id in(v_request.reversal_timesheet_id,v_request.replacement_timesheet_id)
      and t.is_current and t.archived_at_utc is null and t.correction_id=v_request.correction_id
      and t.parent_timesheet_id=v_request.root_timesheet_id and t.adjustment_origin=v_request.origin)<>2
    or (select count(*) from public.timesheets t join public.timesheets_financials tf on tf.timesheet_id=t.timesheet_id and tf.is_current
      where t.timesheet_id in(v_request.reversal_timesheet_id,v_request.replacement_timesheet_id,v_request.reversed_timesheet_id)
        and t.is_current)<>3
    or (select count(*) from public.timesheets t join public.timesheets_financials tf on tf.timesheet_id=t.timesheet_id and tf.is_current
      where t.timesheet_id in(v_request.reversal_timesheet_id,v_request.replacement_timesheet_id))<>2
    or exists(select 1 from public.timesheets r join public.timesheets p on p.timesheet_id=v_request.replacement_timesheet_id
      where r.timesheet_id=v_request.reversal_timesheet_id
        and (r.authorised_at_server is null) is distinct from (p.authorised_at_server is null)) then
    raise exception 'WHOLE_CORRECTION_COMPLETE_UNIT_REQUIRED' using errcode='23514';
  end if;
  for v_row in select t.timesheet_id,t.authorised_at_server,to_jsonb(t) timesheet,to_jsonb(tf) financial,tf.id financial_id,tf.authorised_at_utc
    from public.timesheets t join public.timesheets_financials tf on tf.timesheet_id=t.timesheet_id and tf.is_current
    where t.timesheet_id in(v_request.reversal_timesheet_id,v_request.replacement_timesheet_id,v_request.reversed_timesheet_id)
  loop
    v_role:=case when v_row.timesheet_id=v_request.reversal_timesheet_id then 'reversal'
      when v_row.timesheet_id=v_request.replacement_timesheet_id then 'replacement' else 'original' end;
    if v_row.financial_id::text is distinct from v_request.terminal_receipt_json->>(v_role||'_financial_id')
      or private.timesheet_correction_timesheet_authority_hash_v1(v_row.timesheet)
        is distinct from v_request.terminal_receipt_json->>(v_role||'_timesheet_authority_hash')
      or private.timesheet_correction_financial_authority_hash_v1(v_row.financial)
        is distinct from v_request.terminal_receipt_json->>(v_role||'_financial_authority_hash')
      or (v_role<>'original' and (v_row.authorised_at_server is null) is distinct from (v_row.authorised_at_utc is null))
      or (v_role='original' and coalesce((v_request.terminal_receipt_json->>'original_authorisation_required')::boolean,false)
        and (v_row.authorised_at_server is null or v_row.authorised_at_utc is null)) then
      raise exception 'WHOLE_CORRECTION_FROZEN_FINANCIAL_IDENTITY_CHANGED' using errcode='23514',detail=v_role;
    end if;
  end loop;
end;
$function$;

create or replace function private._weekly_source_effective_policy_v1(
  p_client_id uuid,
  p_contract_id uuid,
  p_work_date date
) returns jsonb
language plpgsql
stable
security definer
set search_path to 'pg_catalog','pg_temp'
as $function$
declare
  v_group record;
  v_client_policy public.weekly_source_client_policies%rowtype;
  v_contract_policy public.weekly_source_contract_policies%rowtype;
  v_group_count integer;
  v_client_policy_count integer;
  v_contract_policy_count integer;
  v_contract_client_id uuid;
  v_policy jsonb;
  v_source_expenses boolean;
  v_source_expense_vat boolean;
  v_candidate_queries boolean;
  v_manager_queries boolean;
  v_completed_copy boolean;
  v_manager_recipient text;
  v_completed_recipient text;
begin
  if p_client_id is null or p_work_date is null then
    raise exception 'WEEKLY_SOURCE_POLICY_SCOPE_REQUIRED' using errcode='22023';
  end if;

  select count(*) into v_group_count
  from public.weekly_source_group_clients gc
  join public.weekly_source_groups g on g.id=gc.source_group_id
  where gc.client_id=p_client_id
    and g.active
    and p_work_date between gc.valid_from and coalesce(gc.valid_to,'infinity'::date);
  if v_group_count<>1 then
    raise exception 'WEEKLY_SOURCE_GROUP_CARDINALITY_INVALID'
      using errcode='55000',
            detail=pg_catalog.jsonb_build_object(
              'reason_code','WEEKLY_SOURCE_GROUP_CARDINALITY_INVALID',
              'client_id',p_client_id,
              'work_date',p_work_date,
              'match_count',v_group_count
            )::text;
  end if;

  select g.*,gc.id as membership_id into strict v_group
  from public.weekly_source_group_clients gc
  join public.weekly_source_groups g on g.id=gc.source_group_id
  where gc.client_id=p_client_id
    and g.active
    and p_work_date between gc.valid_from and coalesce(gc.valid_to,'infinity'::date);

  select count(*) into v_client_policy_count
  from public.weekly_source_client_policies cp
  where cp.source_group_id=v_group.id
    and cp.client_id=p_client_id
    and p_work_date between cp.effective_from and coalesce(cp.effective_to,'infinity'::date);
  if v_client_policy_count<>1 then
    raise exception 'WEEKLY_SOURCE_CLIENT_POLICY_CARDINALITY_INVALID'
      using errcode='55000',
            detail=pg_catalog.jsonb_build_object(
              'reason_code','WEEKLY_SOURCE_CLIENT_POLICY_CARDINALITY_INVALID',
              'client_id',p_client_id,
              'source_group_id',v_group.id,
              'work_date',p_work_date,
              'match_count',v_client_policy_count
            )::text;
  end if;

  select cp.* into strict v_client_policy
  from public.weekly_source_client_policies cp
  where cp.source_group_id=v_group.id
    and cp.client_id=p_client_id
    and p_work_date between cp.effective_from and coalesce(cp.effective_to,'infinity'::date);

  if p_contract_id is not null then
    select c.client_id into strict v_contract_client_id
    from public.contracts c where c.id=p_contract_id;
    if v_contract_client_id is distinct from p_client_id then
      raise exception 'WEEKLY_SOURCE_CONTRACT_CLIENT_MISMATCH' using errcode='22023';
    end if;
    select count(*) into v_contract_policy_count
    from public.weekly_source_contract_policies ctp
    where ctp.contract_id=p_contract_id
      and p_work_date between ctp.effective_from and coalesce(ctp.effective_to,'infinity'::date);
    if v_contract_policy_count>1 then
      raise exception 'WEEKLY_SOURCE_CONTRACT_POLICY_CARDINALITY_INVALID' using errcode='55000';
    end if;
    if v_contract_policy_count=1 then
      select ctp.* into strict v_contract_policy
      from public.weekly_source_contract_policies ctp
      where ctp.contract_id=p_contract_id
        and p_work_date between ctp.effective_from and coalesce(ctp.effective_to,'infinity'::date);
    end if;
  end if;

  v_source_expenses:=coalesce(
    v_contract_policy.source_fixed_expenses_enabled_override,
    v_client_policy.source_fixed_expenses_enabled
  );
  v_source_expense_vat:=v_source_expenses and coalesce(
    v_contract_policy.source_expense_vat_enabled_override,
    v_client_policy.source_expense_vat_enabled
  );
  v_candidate_queries:=coalesce(
    v_contract_policy.candidate_queries_enabled_override,
    v_client_policy.candidate_queries_enabled
  );
  v_manager_queries:=coalesce(
    v_contract_policy.manager_queries_enabled_override,
    v_client_policy.manager_queries_enabled
  );
  v_completed_copy:=coalesce(
    v_contract_policy.completed_pack_copy_enabled_override,
    v_client_policy.completed_pack_copy_enabled
  );
  v_manager_recipient:=case when v_manager_queries then nullif(pg_catalog.btrim(coalesce(
    v_contract_policy.manager_query_recipient_override,
    v_client_policy.manager_query_recipient
  )), '') end;
  v_completed_recipient:=case when v_completed_copy then nullif(pg_catalog.btrim(coalesce(
    v_contract_policy.completed_pack_recipient_override,
    v_client_policy.completed_pack_recipient
  )), '') end;

  if v_completed_copy and v_completed_recipient is null then
    raise exception 'WEEKLY_SOURCE_COMPLETED_PACK_RECIPIENT_REQUIRED' using errcode='55000';
  end if;

  v_policy:=pg_catalog.jsonb_build_object(
    'policy_version','WEEKLY_SOURCE_EFFECTIVE_POLICY_V1',
    'source_group_id',v_group.id,
    'source_group_membership_id',v_group.membership_id,
    'source_group_code',v_group.code,
    'source_family',v_group.source_family,
    'timezone',v_group.timezone,
    'cutoff_weekday',v_group.cutoff_weekday,
    'cutoff_local_time',v_group.cutoff_local_time,
    'client_id',p_client_id,
    'contract_id',p_contract_id,
    'work_date',p_work_date,
    'authority_mode',v_client_policy.authority_mode,
    'document_mode',v_client_policy.document_mode,
    'self_bill_enabled',v_client_policy.self_bill_enabled,
    'self_bill_correction_presentation',v_client_policy.self_bill_correction_presentation,
    'source_fixed_expenses_enabled',v_source_expenses,
    'source_expense_vat_enabled',v_source_expense_vat,
    'weekly_rate_classification_method',coalesce(
      v_contract_policy.weekly_rate_classification_method_override,
      v_client_policy.weekly_rate_classification_method
    ),
    'duration_break_tie_rule',coalesce(
      v_contract_policy.duration_break_tie_rule_override,
      v_client_policy.duration_break_tie_rule
    ),
    'candidate_queries_enabled',v_candidate_queries,
    'manager_queries_enabled',v_manager_queries,
    'manager_query_recipient',v_manager_recipient,
    'completed_pack_copy_enabled',v_completed_copy,
    'completed_pack_recipient',v_completed_recipient,
    'c1_source_mode',case
      when v_client_policy.authority_mode='SOURCE_AUTHORITY'
       and v_client_policy.self_bill_enabled
       and v_group.source_family='NHSP' then 'NHSP_WEEKLY'
      when v_client_policy.authority_mode='SOURCE_AUTHORITY'
       and v_client_policy.self_bill_enabled
       and v_group.source_family='ROSTER' then 'HEALTHROSTER_WEEKLY'
      else null
    end,
    'client_policy_id',v_client_policy.id,
    'contract_policy_id',v_contract_policy.id
  );

  return v_policy || pg_catalog.jsonb_build_object(
    'policy_sha256',pg_catalog.encode(
      extensions.digest(pg_catalog.convert_to(v_policy::text,'UTF8'),'sha256'),'hex'
    )
  );
exception
  when no_data_found then
    raise exception 'WEEKLY_SOURCE_POLICY_SCOPE_NOT_FOUND' using errcode='22023';
end;
$function$;

create or replace function private.weekly_source_effective_rule_set_v1(p_client_id uuid,p_cycle_id uuid)
returns jsonb language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare normal jsonb; auth jsonb; result jsonb;
begin
  normal:=private.weekly_source_operational_effective_rule_set_v1(p_client_id,p_cycle_id);
  if normal is not null then return normal; end if;
  auth:=private.weekly_source_rule_qualification_context_v1(p_client_id,p_cycle_id);
  if auth is null then return null; end if;
  select jsonb_build_object('contract','WEEKLY_SOURCE_EFFECTIVE_RULE_SET_V1','source_group_id',g.id,
    'assignment_id',a.id,'assignment_version',a.version,'rule_set_id',rules.id,'rule_set_version_id',v.id,
    'version_number',v.version_number,'values_sha256',v.values_sha256,'values',v.values_json) into strict result
  from public.weekly_source_cycles c join public.weekly_source_groups g on g.id=c.source_group_id and g.active and g.source_family='ROSTER'
  join public.weekly_source_group_clients member on member.source_group_id=g.id and member.client_id=p_client_id
    and c.finalisation_week_ending between member.valid_from and coalesce(member.valid_to,'infinity'::date)
  join public.weekly_source_group_rule_assignments a on a.source_group_id=g.id and a.id=(auth->>'assignment_id')::uuid and not a.feature_enabled
    and c.finalisation_week_ending between a.effective_from_week_ending and coalesce(a.effective_to_week_ending,'infinity'::date)
  join public.weekly_source_rule_set_versions v on v.id=a.rule_set_version_id and v.id=(auth->>'rule_set_version_id')::uuid
  join public.weekly_source_rule_sets rules on rules.id=v.rule_set_id and rules.agency_id=g.agency_id and rules.environment=g.environment
  where c.id=p_cycle_id;
  return result;
end;
$function$;

create or replace function private.weekly_source_is_import_authoritative_v1(p_client_id uuid,p_contract_id uuid,p_work_date date)
returns boolean language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare v_policy jsonb;
begin
  if p_client_id is null or p_work_date is null or not exists(select 1
    from public.weekly_source_group_clients gc join public.weekly_source_groups g on g.id=gc.source_group_id
    where gc.client_id=p_client_id and g.active and g.source_family='ROSTER'
      and p_work_date between gc.valid_from and coalesce(gc.valid_to,'infinity'::date)) then return false; end if;
  if p_contract_id is not null and not exists(select 1 from public.contracts c
    where c.id=p_contract_id and c.client_id=p_client_id) then return false; end if;
  if not exists(select 1 from public.weekly_source_client_policies cp join public.weekly_source_groups g on g.id=cp.source_group_id
    join public.weekly_source_group_clients gc on gc.source_group_id=g.id and gc.client_id=cp.client_id
    where cp.client_id=p_client_id and g.active and g.source_family='ROSTER'
      and p_work_date between gc.valid_from and coalesce(gc.valid_to,'infinity'::date)
      and p_work_date between cp.effective_from and coalesce(cp.effective_to,'infinity'::date)) then return false; end if;
  v_policy:=private._weekly_source_effective_policy_v1(p_client_id,p_contract_id,p_work_date);
  return v_policy->>'source_family'='ROSTER' and v_policy->>'authority_mode'='SOURCE_AUTHORITY'
    and v_policy->>'document_mode'='CHECK_ONLY';
end;
$function$;

create or replace function public._import_review_effective_authority_core_v1(
  p_source_route text,
  p_contract_id uuid,
  p_client_id uuid,
  p_evidence_date date default null
)
returns table (
  route_eligible boolean,
  validation_eligible boolean,
  import_authoritative boolean,
  authority_mode text,
  authority_basis text,
  effective_is_nhsp boolean,
  effective_autoprocess_hr boolean,
  effective_requires_hr boolean,
  effective_no_timesheet_required boolean,
  settings_as_of_date date,
  client_settings_id uuid,
  client_settings_effective_from date,
  client_settings_updated_at timestamptz,
  contract_updated_at timestamptz,
  authority_fingerprint text
)
language plpgsql
stable
security definer
set search_path = pg_catalog, public, private, extensions, pg_temp
as $function$
declare
  v_route text:=upper(btrim(coalesce(p_source_route,'')));
  v_workflow text;
  v_authority jsonb;
  v_is_nhsp boolean;
  v_requires_hr boolean;
  v_autoprocess_hr boolean;
  v_no_timesheet boolean;
  v_route_ok boolean;
  v_validation boolean;
  v_authoritative boolean;
begin
  if p_evidence_date is null then
    raise exception 'IMPORT_AUTHORITY_EVIDENCE_DATE_REQUIRED' using errcode='22023';
  end if;
  v_workflow:=case when v_route in ('HR_DAILY','HEALTHROSTER_DAILY') then 'DAILY' else 'IMPORT' end;
  v_authority:=private._contract_settings_effective_core_v1(
    p_client_id,p_contract_id,p_evidence_date,v_workflow,null
  );
  v_is_nhsp:=coalesce((v_authority#>>'{values,is_nhsp}')::boolean,false);
  v_requires_hr:=coalesce((v_authority#>>'{values,requires_hr}')::boolean,false);
  v_autoprocess_hr:=coalesce((v_authority#>>'{values,autoprocess_hr}')::boolean,false);
  v_no_timesheet:=coalesce((v_authority#>>'{values,no_timesheet_required}')::boolean,false);
  v_route_ok:=case
    when v_route='NHSP' then v_is_nhsp
    when v_route in ('HR_WEEKLY','HEALTHROSTER','HEALTHROSTER_WEEKLY','HR_DAILY','HEALTHROSTER_DAILY')
      then v_autoprocess_hr and (v_requires_hr or v_no_timesheet)
    else false end;
  v_validation:=case
    when v_route in ('HR_WEEKLY','HEALTHROSTER','HEALTHROSTER_WEEKLY','HR_DAILY','HEALTHROSTER_DAILY')
      then v_requires_hr and v_autoprocess_hr and not v_no_timesheet
    else false end;
  v_authoritative:=case
    when v_route='NHSP' then v_is_nhsp
    when v_route in ('HR_WEEKLY','HEALTHROSTER','HEALTHROSTER_WEEKLY','HR_DAILY','HEALTHROSTER_DAILY')
      then v_autoprocess_hr and v_no_timesheet
    else false end;
  return query select
    v_route_ok,v_validation,v_authoritative,
    case when not v_route_ok then 'OUT_OF_SCOPE'
      when v_authoritative then 'AUTHORITATIVE'
      when v_validation then 'VALIDATION_ONLY' else 'OUT_OF_SCOPE' end,
    case when coalesce((v_authority->>'override_client_settings')::boolean,false)
      then 'CONTRACT_OVERRIDE' else 'CLIENT_SETTINGS' end,
    v_is_nhsp,v_autoprocess_hr,v_requires_hr,v_no_timesheet,
    p_evidence_date,
    nullif(v_authority->>'client_settings_id','')::uuid,
    nullif(v_authority->>'client_settings_effective_from','')::date,
    nullif(v_authority->>'client_settings_updated_at','')::timestamptz,
    nullif(v_authority->>'contract_updated_at','')::timestamptz,
    v_authority->>'authority_fingerprint';
end
$function$;

CREATE OR REPLACE FUNCTION public._pay_workbench_candidate_serial_active_state(p_job_id uuid DEFAULT NULL::uuid, p_candidate_id uuid DEFAULT NULL::uuid, p_job_type text DEFAULT NULL::text, p_payload_json jsonb DEFAULT '{}'::jsonb, p_now_utc timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := COALESCE(p_now_utc, clock_timestamp());
  v_payload jsonb := CASE WHEN jsonb_typeof(COALESCE(p_payload_json, '{}'::jsonb)) = 'object' THEN COALESCE(p_payload_json, '{}'::jsonb) ELSE '{}'::jsonb END;
  v_candidate_id uuid := public._pay_workbench_candidate_serial_candidate_id(p_candidate_id, p_payload_json);
  v_serial_key text := public._pay_workbench_candidate_serial_key(public._pay_workbench_candidate_serial_candidate_id(p_candidate_id, p_payload_json));
  v_candidate_job boolean := false;
  v_is_chain_continuation boolean := false;
  v_projection_run_id_text text := NULL::text;
  v_projection_run_id uuid := NULL::uuid;
  v_active_job_id uuid := NULL::uuid;
  v_active_job_type text := NULL::text;
  v_active_job_status text := NULL::text;
  v_active_job_started_at_utc timestamptz := NULL::timestamptz;
  v_active_job_run_at_utc timestamptz := NULL::timestamptz;
  v_active_chain_id text := NULL::text;
  v_queued_chain_job_id uuid := NULL::uuid;
  v_queued_chain_job_type text := NULL::text;
  v_queued_chain_job_status text := NULL::text;
  v_queued_chain_started_at_utc timestamptz := NULL::timestamptz;
  v_queued_chain_run_at_utc timestamptz := NULL::timestamptz;
  v_queued_chain_id text := NULL::text;
  v_projection_blocker_id uuid := NULL::uuid;
  v_projection_blocker_status text := NULL::text;
  v_projection_blocker_started_at_utc timestamptz := NULL::timestamptz;
  v_projection_blocker_updated_at_utc timestamptz := NULL::timestamptz;
  v_blocked boolean := false;
  v_reason text := NULL::text;
BEGIN
  v_candidate_job := public._pay_workbench_candidate_serial_is_candidate_job(p_job_type, v_candidate_id, v_payload);

  IF v_candidate_id IS NULL OR v_candidate_job IS NOT TRUE THEN
    RETURN jsonb_build_object(
      'ok', true,
      'blocked', false,
      'candidate_serial_blocked', false,
      'reason', 'NO_CANDIDATE_SERIAL_SCOPE',
      'candidate_serial_wait_reason', 'NO_CANDIDATE_SERIAL_SCOPE',
      'candidate_id', CASE WHEN v_candidate_id IS NULL THEN NULL ELSE v_candidate_id::text END,
      'candidate_serial_key', v_serial_key
    );
  END IF;

  v_is_chain_continuation := (
    lower(BTRIM(COALESCE(v_payload->>'continuation', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
    OR UPPER(BTRIM(COALESCE(v_payload->>'run_mode', ''))) IN ('BOUNDED_CONTINUATION', 'CONTINUATION', 'STAGE_CONTINUATION')
    OR lower(BTRIM(COALESCE(v_payload->>'fallback_from_delta', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
    OR (
      lower(BTRIM(COALESCE(v_payload->>'source_build_required', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
      AND NULLIF(BTRIM(COALESCE(v_payload->>'fallback_reason', '')), '') IS NOT NULL
    )
    OR (
      NULLIF(BTRIM(COALESCE(v_payload->>'source_job_id', v_payload->>'continuation_source_job_id', v_payload->>'bounded_continuation_source_job_id', '')), '') IS NOT NULL
      AND UPPER(BTRIM(COALESCE(v_payload->>'run_mode', ''))) NOT IN ('LATEST_STATE_HEAD', 'LATEST_RERUN_AFTER_RUNNING')
    )
  );

  v_projection_run_id_text := COALESCE(
    NULLIF(BTRIM(COALESCE(v_payload->>'projection_run_id', '')), ''),
    NULLIF(BTRIM(COALESCE(v_payload#>>'{cursor,projection_run_id}', '')), ''),
    NULLIF(BTRIM(COALESCE(v_payload#>>'{cursor,cursor,projection_run_id}', '')), ''),
    NULLIF(BTRIM(COALESCE(v_payload#>>'{cursor_json,projection_run_id}', '')), ''),
    NULLIF(BTRIM(COALESCE(v_payload#>>'{cursor_json,cursor,projection_run_id}', '')), '')
  );
  IF v_projection_run_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_projection_run_id := v_projection_run_id_text::uuid;
  END IF;

  SELECT running_job.id,
         running_job.job_type,
         running_job.status,
         running_job.started_at_utc,
         running_job.run_at_utc,
         COALESCE(NULLIF(BTRIM(COALESCE(running_job.payload_json->>'candidate_serial_active_chain_id', '')), ''), NULLIF(BTRIM(COALESCE(running_job.payload_json->>'source_job_id', '')), ''), running_job.id::text)
  INTO v_active_job_id, v_active_job_type, v_active_job_status, v_active_job_started_at_utc, v_active_job_run_at_utc, v_active_chain_id
  FROM public.banking_pay_workbench_jobs AS running_job
  WHERE running_job.status = 'RUNNING'
    -- A14: status = 'RUNNING' is the original test under the validated status CHECK (exact values),
    -- so the live-status index is used instead of scanning every job ever written.
    AND UPPER(BTRIM(COALESCE(running_job.status, ''))) = 'RUNNING'
    -- A14: implied by the serial-candidate test below (it returns candidate_id when present);
    -- evaluated first so other Candidates' rows never reach the payload/plpgsql tests.
    AND (running_job.candidate_id = v_candidate_id OR running_job.candidate_id IS NULL)
    AND running_job.id IS DISTINCT FROM p_job_id
    AND public._pay_workbench_candidate_serial_candidate_id(running_job.candidate_id, running_job.payload_json) = v_candidate_id
    AND public._pay_workbench_candidate_serial_is_candidate_job(running_job.job_type, running_job.candidate_id, running_job.payload_json)
  ORDER BY running_job.started_at_utc ASC NULLS FIRST, running_job.created_at_utc ASC, running_job.id ASC
  LIMIT 1;

  IF v_active_job_id IS NOT NULL THEN
    v_blocked := true;
    v_reason := 'CANDIDATE_SERIAL_BLOCKED_BY_ACTIVE_JOB';
  END IF;

  IF v_blocked IS NOT TRUE AND v_is_chain_continuation IS NOT TRUE THEN
    SELECT queued_job.id,
           queued_job.job_type,
           queued_job.status,
           queued_job.started_at_utc,
           queued_job.run_at_utc,
           COALESCE(NULLIF(BTRIM(COALESCE(queued_job.payload_json->>'candidate_serial_active_chain_id', '')), ''), NULLIF(BTRIM(COALESCE(queued_job.payload_json->>'source_job_id', '')), ''), queued_job.id::text)
    INTO v_queued_chain_job_id, v_queued_chain_job_type, v_queued_chain_job_status, v_queued_chain_started_at_utc, v_queued_chain_run_at_utc, v_queued_chain_id
    FROM public.banking_pay_workbench_jobs AS queued_job
    WHERE queued_job.status = 'QUEUED'
      -- A14: status = 'QUEUED' is the original test under the validated status CHECK (exact values),
      -- so the live-status index is used instead of scanning every job ever written.
      AND UPPER(BTRIM(COALESCE(queued_job.status, ''))) = 'QUEUED'
      -- A14: implied by the serial-candidate test below (it returns candidate_id when present);
      -- evaluated first so other Candidates' rows never reach the payload/plpgsql tests.
      AND (queued_job.candidate_id = v_candidate_id OR queued_job.candidate_id IS NULL)
      AND queued_job.id IS DISTINCT FROM p_job_id
      AND public._pay_workbench_candidate_serial_candidate_id(queued_job.candidate_id, queued_job.payload_json) = v_candidate_id
      AND public._pay_workbench_candidate_serial_is_candidate_job(queued_job.job_type, queued_job.candidate_id, queued_job.payload_json)
      AND (
        lower(BTRIM(COALESCE(queued_job.payload_json->>'continuation', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        OR UPPER(BTRIM(COALESCE(queued_job.payload_json->>'run_mode', ''))) IN ('BOUNDED_CONTINUATION', 'CONTINUATION', 'STAGE_CONTINUATION')
        OR lower(BTRIM(COALESCE(queued_job.payload_json->>'fallback_from_delta', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        OR (
          lower(BTRIM(COALESCE(queued_job.payload_json->>'source_build_required', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
          AND NULLIF(BTRIM(COALESCE(queued_job.payload_json->>'fallback_reason', '')), '') IS NOT NULL
        )
        OR (
          NULLIF(BTRIM(COALESCE(queued_job.payload_json->>'source_job_id', queued_job.payload_json->>'continuation_source_job_id', queued_job.payload_json->>'bounded_continuation_source_job_id', '')), '') IS NOT NULL
          AND UPPER(BTRIM(COALESCE(queued_job.payload_json->>'run_mode', ''))) NOT IN ('LATEST_STATE_HEAD', 'LATEST_RERUN_AFTER_RUNNING')
        )
      )
    ORDER BY queued_job.run_at_utc ASC, queued_job.priority ASC, queued_job.created_at_utc ASC, queued_job.id ASC
    LIMIT 1;

    IF v_queued_chain_job_id IS NOT NULL THEN
      v_blocked := true;
      v_reason := 'CANDIDATE_SERIAL_BLOCKED_BY_ACTIVE_CONTINUATION';
    END IF;
  END IF;

  IF v_blocked IS NOT TRUE THEN
    SELECT projection_run.id, projection_run.status, projection_run.started_at_utc, projection_run.updated_at_utc
    INTO v_projection_blocker_id, v_projection_blocker_status, v_projection_blocker_started_at_utc, v_projection_blocker_updated_at_utc
    FROM public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run
    WHERE projection_run.candidate_id = v_candidate_id
      AND UPPER(BTRIM(COALESCE(projection_run.status, ''))) IN ('RUNNING', 'PROCESSING', 'IN_PROGRESS')
      AND (v_projection_run_id IS NULL OR projection_run.id IS DISTINCT FROM v_projection_run_id)
    ORDER BY projection_run.started_at_utc ASC NULLS FIRST, projection_run.updated_at_utc ASC NULLS FIRST, projection_run.id ASC
    LIMIT 1;

    IF v_projection_blocker_id IS NOT NULL THEN
      v_blocked := true;
      v_reason := 'CANDIDATE_SERIAL_BLOCKED_BY_ACTIVE_PROJECTION_RUN';
    END IF;
  END IF;

  IF v_blocked IS TRUE THEN
    PERFORM public._pay_workbench_candidate_serial_audit(
      COALESCE(v_reason, 'CANDIDATE_SERIAL_BLOCKED'),
      p_job_id,
      v_candidate_id,
      jsonb_strip_nulls(jsonb_build_object(
        'candidate_serial_key', v_serial_key,
        'blocked_job_id', CASE WHEN v_active_job_id IS NULL THEN NULL ELSE v_active_job_id::text END,
        'blocked_job_type', v_active_job_type,
        'blocked_job_status', v_active_job_status,
        'blocked_job_started_at_utc', v_active_job_started_at_utc,
        'blocked_job_run_at_utc', v_active_job_run_at_utc,
        'blocked_chain_job_id', CASE WHEN v_queued_chain_job_id IS NULL THEN NULL ELSE v_queued_chain_job_id::text END,
        'blocked_chain_job_type', v_queued_chain_job_type,
        'blocked_chain_job_status', v_queued_chain_job_status,
        'blocked_chain_started_at_utc', v_queued_chain_started_at_utc,
        'blocked_chain_run_at_utc', v_queued_chain_run_at_utc,
        'active_chain_id', COALESCE(v_active_chain_id, v_queued_chain_id),
        'projection_run_id', CASE WHEN v_projection_blocker_id IS NULL THEN NULL ELSE v_projection_blocker_id::text END,
        'projection_status', v_projection_blocker_status,
        'projection_started_at_utc', v_projection_blocker_started_at_utc,
        'projection_updated_at_utc', v_projection_blocker_updated_at_utc,
        'candidate_serial_wait_reason', COALESCE(v_reason, 'CANDIDATE_SERIAL_BLOCKED')
      )),
      COALESCE(v_reason, 'CANDIDATE_SERIAL_BLOCKED'),
      NULL::uuid
    );
  END IF;

  RETURN jsonb_strip_nulls(jsonb_build_object(
    'ok', true,
    'blocked', COALESCE(v_blocked, false),
    'candidate_serial_blocked', COALESCE(v_blocked, false),
    'reason', COALESCE(v_reason, 'CANDIDATE_SERIAL_CLEAR'),
    'candidate_serial_wait_reason', COALESCE(v_reason, 'CANDIDATE_SERIAL_CLEAR'),
    'candidate_id', v_candidate_id::text,
    'candidate_serial_key', v_serial_key,
    'is_chain_continuation', COALESCE(v_is_chain_continuation, false),
    'blocked_job_id', CASE WHEN v_active_job_id IS NULL THEN NULL ELSE v_active_job_id::text END,
    'blocking_job_id', CASE WHEN v_active_job_id IS NULL THEN NULL ELSE v_active_job_id::text END,
    'blocked_job_type', v_active_job_type,
    'blocked_job_status', v_active_job_status,
    'blocking_status', COALESCE(v_active_job_status, v_queued_chain_job_status, v_projection_blocker_status),
    'blocked_job_started_at_utc', v_active_job_started_at_utc,
    'blocked_job_run_at_utc', v_active_job_run_at_utc,
    'blocking_started_at_utc', COALESCE(v_active_job_started_at_utc, v_queued_chain_started_at_utc, v_projection_blocker_started_at_utc),
    'blocking_run_at_utc', COALESCE(v_active_job_run_at_utc, v_queued_chain_run_at_utc, v_projection_blocker_updated_at_utc),
    'blocked_chain_job_id', CASE WHEN v_queued_chain_job_id IS NULL THEN NULL ELSE v_queued_chain_job_id::text END,
    'blocked_chain_job_type', v_queued_chain_job_type,
    'blocked_chain_job_status', v_queued_chain_job_status,
    'blocked_chain_started_at_utc', v_queued_chain_started_at_utc,
    'blocked_chain_run_at_utc', v_queued_chain_run_at_utc,
    'active_chain_id', COALESCE(v_active_chain_id, v_queued_chain_id),
    'projection_run_id', CASE WHEN v_projection_blocker_id IS NULL THEN NULL ELSE v_projection_blocker_id::text END,
    'blocking_projection_run_id', CASE WHEN v_projection_blocker_id IS NULL THEN NULL ELSE v_projection_blocker_id::text END,
    'projection_status', v_projection_blocker_status,
    'projection_started_at_utc', v_projection_blocker_started_at_utc,
    'projection_updated_at_utc', v_projection_blocker_updated_at_utc
  ));
END;
$function$;

CREATE OR REPLACE FUNCTION public._pay_workbench_candidate_serial_audit(p_action text, p_job_id uuid DEFAULT NULL::uuid, p_candidate_id uuid DEFAULT NULL::uuid, p_after_json jsonb DEFAULT '{}'::jsonb, p_reason text DEFAULT NULL::text, p_actor_user_id uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_action text := COALESCE(NULLIF(BTRIM(p_action), ''), 'CANDIDATE_SERIAL_EVENT');
  v_candidate_id uuid := p_candidate_id;
  v_after jsonb := CASE WHEN jsonb_typeof(COALESCE(p_after_json, '{}'::jsonb)) = 'object' THEN COALESCE(p_after_json, '{}'::jsonb) ELSE '{}'::jsonb END;
BEGIN
  IF v_candidate_id IS NULL THEN
    v_candidate_id := public._pay_workbench_candidate_serial_candidate_id(NULL::uuid, v_after);
  END IF;

  PERFORM public._audit_insert(
    'banking_pay_workbench_job',
    COALESCE(p_job_id::text, CASE WHEN v_candidate_id IS NULL THEN NULL ELSE 'candidate:' || v_candidate_id::text END),
    v_action,
    NULL::jsonb,
    jsonb_strip_nulls(
      jsonb_build_object(
        'job_id', CASE WHEN p_job_id IS NULL THEN NULL ELSE p_job_id::text END,
        'candidate_id', CASE WHEN v_candidate_id IS NULL THEN NULL ELSE v_candidate_id::text END,
        'candidate_serial_key', public._pay_workbench_candidate_serial_key(v_candidate_id)
      ) || v_after
    ),
    COALESCE(NULLIF(BTRIM(p_reason), ''), v_action),
    p_actor_user_id
  );
EXCEPTION WHEN OTHERS THEN
  RETURN;
END;
$function$;

CREATE OR REPLACE FUNCTION public._pay_workbench_candidate_serial_candidate_id(p_candidate_id uuid DEFAULT NULL::uuid, p_payload_json jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_candidate_id uuid := NULL::uuid;
  v_candidate_count integer := 0;
BEGIN
  IF p_candidate_id IS NOT NULL THEN
    RETURN p_candidate_id;
  END IF;

  SELECT COUNT(*)::integer
  INTO v_candidate_count
  FROM public._pay_workbench_candidate_serial_candidate_ids(p_candidate_id, p_payload_json) AS candidate_ids(candidate_id);

  IF COALESCE(v_candidate_count, 0) = 1 THEN
    SELECT candidate_ids.candidate_id
    INTO v_candidate_id
    FROM public._pay_workbench_candidate_serial_candidate_ids(p_candidate_id, p_payload_json) AS candidate_ids(candidate_id)
    LIMIT 1;

    RETURN v_candidate_id;
  END IF;

  RETURN NULL::uuid;
END;
$function$;

CREATE OR REPLACE FUNCTION public._pay_workbench_candidate_serial_is_candidate_job(p_job_type text, p_candidate_id uuid DEFAULT NULL::uuid, p_payload_json jsonb DEFAULT '{}'::jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_job_type text := UPPER(BTRIM(COALESCE(p_job_type, '')));
  v_candidate_id uuid := public._pay_workbench_candidate_serial_candidate_id(p_candidate_id, p_payload_json);
BEGIN
  IF v_candidate_id IS NULL THEN
    RETURN false;
  END IF;

  IF v_job_type IN ('WORKBENCH_SESSION_SCOPE_SEED', 'SESSION_SCOPE_SEED', 'WORKBENCH_SESSION_CLONE_REBASE', 'SESSION_CLONE_REBASE', 'CLONE_REBASE') THEN
    RETURN false;
  END IF;

  IF v_job_type IN (
    'WORKBENCH_CANDIDATE_DIRTY_APPLY',
    'WORKBENCH_CANDIDATE_DELTA_REFRESH', 'CANDIDATE_DELTA_REFRESH', 'DELTA_REFRESH',
    'WORKBENCH_CANDIDATE_SOURCE_BUILD', 'WORKBENCH_CANDIDATE_SOURCE_BUILD_CHUNK', 'WORKBENCH_CANDIDATE_SOURCE_BUILD_PAGE', 'CANDIDATE_SOURCE_BUILD', 'CANDIDATE_SOURCE_BUILD_CHUNK', 'SOURCE_BUILD', 'SOURCE_BUILD_PAGE',
    'WORKBENCH_CANDIDATE_LINE_WORK_SEED', 'WORKBENCH_CANDIDATE_LINE_WORK_SEED_PAGE', 'CANDIDATE_LINE_WORK_SEED', 'CANDIDATE_LINE_WORK_SEED_PAGE', 'LINE_WORK_SEED_PAGE', 'SNAPSHOT_CANDIDATE_REFRESH', 'CANDIDATE_REFRESH',
    'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS', 'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS_CHUNK', 'CANDIDATE_LINE_WORK_PROCESS', 'CANDIDATE_LINE_WORK_PROCESS_CHUNK', 'LINE_WORK_PROCESS', 'LINE_WORK_PROCESS_CHUNK',
    'WORKBENCH_PREVIEW_ROWS_MATERIALISE', 'WORKBENCH_PREVIEW_ROWS_MATERIALIZE', 'WORKBENCH_PREVIEW_ROWS_MATERIALISE_CHUNK', 'WORKBENCH_PREVIEW_ROWS_MATERIALIZE_CHUNK', 'PREVIEW_ROWS_MATERIALISE', 'PREVIEW_ROWS_MATERIALIZE', 'PREVIEW_ROWS_MATERIALISE_CHUNK', 'PREVIEW_ROWS_MATERIALIZE_CHUNK', 'PREVIEW_ROW_MATERIALISE_CHUNK', 'PREVIEW_ROW_MATERIALIZE_CHUNK',
    'WORKBENCH_FINANCE_CASE_DIRTY_APPLY',
    'CONTRACT_CLIENT_DIRTY_FANOUT'
  ) THEN
    RETURN true;
  END IF;

  IF v_job_type LIKE E'WORKBENCH_CANDIDATE\\_%' ESCAPE E'\\' THEN
    RETURN true;
  END IF;

  IF v_job_type LIKE E'WORKBENCH\\_%' ESCAPE E'\\'
     AND (
       COALESCE(p_payload_json, '{}'::jsonb) ? 'candidate_id'
       OR COALESCE(p_payload_json, '{}'::jsonb) ? 'candidateId'
       OR COALESCE(p_payload_json, '{}'::jsonb) ? 'candidate_uuid'
       OR COALESCE(p_payload_json, '{}'::jsonb)#>>'{candidate,id}' IS NOT NULL
     ) THEN
    RETURN true;
  END IF;

  RETURN false;
END;
$function$;

create or replace function private._candidate_manager_authoriser_effective_v2(
  p_client_policy jsonb,
  p_contract_policy jsonb default null
)
returns jsonb
language plpgsql
immutable
parallel safe
set search_path=''
as $function$
declare
  v_client jsonb:=private._candidate_manager_authoriser_policy_normalize_v2(p_client_policy,'CLIENT');
  v_contract_source jsonb:=case when pg_catalog.jsonb_typeof(p_contract_policy)='object' then p_contract_policy else '{"mode":"INHERIT"}'::jsonb end;
  v_mode text:=pg_catalog.upper(pg_catalog.btrim(coalesce(v_contract_source->>'mode','INHERIT')));
  v_contract jsonb;
  v_emails jsonb;
  v_domains jsonb;
  v_allow_free boolean;
  v_source_mode text;
begin
  if p_contract_policy is null or v_mode='INHERIT' then
    return v_client||pg_catalog.jsonb_build_object('source_mode','INHERIT');
  end if;

  if v_mode in ('EXTEND','CONTRACT_ONLY') then
    v_contract:=private._candidate_manager_authoriser_policy_normalize_v2(v_contract_source,'CONTRACT_WRITE');
  else
    -- Compatibility: the former resolver treated every non-INHERIT value as a
    -- complete replacement. Preserve that meaning without rewriting stored rows.
    v_contract:=private._candidate_manager_authoriser_policy_normalize_v2(v_contract_source,'EFFECTIVE');
  end if;

  if v_mode='EXTEND' then
    select coalesce(pg_catalog.jsonb_agg(x.value order by x.value),'[]'::jsonb)
      into v_emails
    from (
      select distinct value
      from pg_catalog.jsonb_array_elements_text((v_client->'approved_emails')||(v_contract->'approved_emails'))
    ) x;
    select coalesce(pg_catalog.jsonb_agg(x.value order by x.value),'[]'::jsonb)
      into v_domains
    from (
      select distinct value
      from pg_catalog.jsonb_array_elements_text((v_client->'approved_domains')||(v_contract->'approved_domains'))
    ) x;
    v_allow_free:=coalesce((v_client->>'allow_free_business_email')::boolean,false);
    v_source_mode:='EXTEND';
  elsif v_mode='CONTRACT_ONLY' then
    v_emails:=v_contract->'approved_emails';
    v_domains:=v_contract->'approved_domains';
    v_allow_free:=false;
    v_source_mode:='CONTRACT_ONLY';
  else
    v_emails:=v_contract->'approved_emails';
    v_domains:=v_contract->'approved_domains';
    v_allow_free:=coalesce((v_contract->>'allow_free_business_email')::boolean,false);
    v_source_mode:='LEGACY_REPLACEMENT';
  end if;
  return pg_catalog.jsonb_build_object(
    'approved_emails',v_emails,'approved_domains',v_domains,
    'allow_free_business_email',v_allow_free,'source_mode',v_source_mode
  );
end;
$function$;

create or replace function private._timesheet_settings_authority_frozen_v1(
  p_timesheet_id uuid
)
returns jsonb
language plpgsql
stable
security definer
set search_path = pg_catalog, public, private, extensions, pg_temp
as $function$
declare v_snapshot jsonb; v_version text; v_fingerprint text; v_expected text;
begin
  select t.settings_authority_json,t.settings_authority_version,
    t.settings_authority_fingerprint
  into v_snapshot,v_version,v_fingerprint
  from public.timesheets t
  where t.timesheet_id=p_timesheet_id;
  if not found then
    raise exception 'CONTRACT_SETTINGS_TIMESHEET_NOT_FOUND' using errcode='P0002';
  end if;
  if coalesce(v_snapshot,'{}'::jsonb)='{}'::jsonb
     or v_version is distinct from 'CONTRACT_SETTINGS_AUTHORITY_V1'
     or coalesce(v_fingerprint,'') !~ '^[0-9a-f]{64}$' then
    raise exception 'CONTRACT_SETTINGS_TIMESHEET_AUTHORITY_NOT_FROZEN' using errcode='55000';
  end if;
  v_expected:=encode(digest(convert_to(
    (v_snapshot-'authority_fingerprint'-'resolved_at_utc')::text,'UTF8'
  ),'sha256'),'hex');
  if v_expected is distinct from v_fingerprint
     or v_snapshot->>'authority_fingerprint' is distinct from v_fingerprint then
    raise exception 'CONTRACT_SETTINGS_TIMESHEET_AUTHORITY_INVALID' using errcode='22023';
  end if;
  return v_snapshot;
end
$function$;

create or replace function private.weekly_source_invoice_adjustment_line_valid_v1(p_invoice_line_id uuid,p_invoice_id uuid)
returns boolean language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare line public.invoice_lines%rowtype; v_authority jsonb; v_actual jsonb; v_ids uuid[]; v_meta jsonb;
begin
  select * into line from public.invoice_lines where id=p_invoice_line_id and invoice_id=p_invoice_id;
  if not found or line.timesheet_id is not null or line.booking_id is not null or line.source_key not like 'ADJ:%'
    or line.meta_json->>'line_type' is distinct from 'ADJUSTMENT' or line.total_pay_ex_vat is distinct from 0
    or line.total_charge_ex_vat is null or line.total_charge_ex_vat>=0 or line.margin_ex_vat is distinct from line.total_charge_ex_vat
    or (line.hours_day,line.hours_night,line.hours_sat,line.hours_sun,line.hours_bh) is distinct from (0::numeric,0::numeric,0::numeric,0::numeric,0::numeric)
    or (line.pay_day,line.pay_night,line.pay_sat,line.pay_sun,line.pay_bh,line.charge_day,line.charge_night,line.charge_sat,line.charge_sun,line.charge_bh)
      is distinct from (null::numeric,null::numeric,null::numeric,null::numeric,null::numeric,null::numeric,null::numeric,null::numeric,null::numeric,null::numeric)
    or line.vat_amount is null or line.vat_rate_pct is null
    or line.total_inc_vat is distinct from round(line.total_charge_ex_vat+line.vat_amount,2)
    or line.meta_json ? 'credited_work_event_id' then return false; end if;
  v_authority:=line.meta_json->'weekly_source_adjustment_authority';
  if jsonb_typeof(v_authority) is distinct from 'object' or jsonb_typeof(v_authority->'binding_ids') is distinct from 'array' then return false; end if;
  select array_agg(value::uuid order by value::uuid) into v_ids from jsonb_array_elements_text(v_authority->'binding_ids') value;
  v_actual:=private.weekly_source_invoice_adjustment_authority_v1(p_invoice_id,v_ids);
  v_meta:=line.meta_json;
  if exists(select 1 from jsonb_object_keys(v_meta) k where k not in(
    'line_type','client_token','description','amount_ex_vat','vat_rate_pct','vat_amount','vat_chargeable',
    'vat_overridden','weekly_source_adjustment_authority')) then return false; end if;
  return coalesce(v_actual->>'allowed'='true' and v_actual=v_authority
    and line.vat_rate_pct=(v_actual->>'vat_rate_pct')::numeric
    and line.source_key='ADJ:'||(v_meta->>'client_token') and line.description=v_meta->>'description'
    and line.total_charge_ex_vat=(v_meta->>'amount_ex_vat')::numeric and line.vat_amount=(v_meta->>'vat_amount')::numeric
    and jsonb_typeof(v_meta->'vat_overridden')='boolean'
    and jsonb_typeof(v_meta->'vat_chargeable')='boolean'
    and (v_meta->>'vat_chargeable')::boolean=(line.vat_rate_pct<>0)
    and ((v_meta->>'vat_overridden')::boolean or line.vat_amount=public._inv_round2(line.total_charge_ex_vat*line.vat_rate_pct/100)),false);
exception when invalid_text_representation or numeric_value_out_of_range or invalid_parameter_value then return false;
end;
$function$;

create or replace function private.weekly_source_invoice_movement_window_id_v1(p_movement_id uuid)
returns uuid language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare m public.weekly_source_billing_movements%rowtype; target uuid;
begin
  select * into strict m from public.weekly_source_billing_movements where id=p_movement_id;
  target:=case when m.source_line_kind='INVOICE_VAT_ROUNDING' then coalesce(m.invoice_window_cycle_id,m.finalisation_cycle_id)
    when m.source_line_kind='SOURCE_INVOICE_CORRECTION' and m.movement_role in ('REVERSAL','REPLACEMENT')
      then nullif(m.source_facts_json->>'invoice_window_cycle_id','')::uuid else m.finalisation_cycle_id end;
  if target is null or not exists(select 1 from public.weekly_source_cycles actual join public.weekly_source_cycles original
    on original.id=m.finalisation_cycle_id and actual.source_group_id=original.source_group_id
    where actual.id=target and (actual.scope_client_id is null or actual.scope_client_id=m.actual_client_id)) then
    raise exception 'WEEKLY_SOURCE_INVOICE_MOVEMENT_WINDOW_INVALID' using errcode='55000'; end if;
  return target;
end;
$function$;

create or replace function private.weekly_source_invoice_presentation_release_authority_v1(p_movement_ids uuid[],p_invoice_hold_release_id uuid)
returns jsonb language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare ids uuid[];
begin
  if p_invoice_hold_release_id is null then return null; end if;
  select array_agg(m.id) into ids from public.weekly_source_billing_movements m
    join public.weekly_source_invoice_hold_releases receipt on receipt.id=p_invoice_hold_release_id
      and m.source_facts_json->>'upload_row_id'=receipt.upload_row_id::text
    where m.id=any(p_movement_ids) and m.movement_role in ('POSITIVE','REPLACEMENT')
      and m.source_line_kind in ('SOURCE_ORDINARY','SOURCE_REPLACEMENT','SOURCE_REBILL_LINE','SOURCE_INVOICE_CORRECTION');
  if cardinality(ids) is distinct from 1 then raise exception 'WEEKLY_SOURCE_INVOICE_RELEASE_MEMBER_INVALID' using errcode='55000'; end if;
  return private.weekly_source_invoice_movement_money_v1(ids[1],p_invoice_hold_release_id)->'release_authority';
end;
$function$;

create or replace function private.weekly_source_invoice_presentation_source_hash_v1(p_movement_ids uuid[],p_invoice_hold_release_id uuid default null)
returns bytea language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare members jsonb; original bytea; authority jsonb; count_rows integer;
begin
  select jsonb_agg(jsonb_build_object('movement_id',m.id,'movement_economic_hash',encode(m.movement_economic_hash,'hex')) order by m.id),count(*)
    into members,count_rows from public.weekly_source_billing_movements m where m.id=any(p_movement_ids);
  if count_rows is distinct from cardinality(p_movement_ids) or count_rows not in (1,2) then
    raise exception 'WEEKLY_SOURCE_INVOICE_SOURCE_MEMBER_INVALID' using errcode='55000'; end if;
  original:=private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_INVOICE_PRESENTATION_SOURCE_V1',members);
  if p_invoice_hold_release_id is null then return original; end if;
  authority:=private.weekly_source_invoice_presentation_release_authority_v1(p_movement_ids,p_invoice_hold_release_id);
  return private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_INVOICE_PRESENTATION_RELEASE_SOURCE_V1',
    jsonb_build_object('original_presentation_source_hash',encode(original,'hex'),'release_authority',authority));
end;
$function$;

