create or replace function private._candidate_assert_environment(p_environment text)
returns text
language plpgsql
stable
security definer
set search_path = pg_catalog, public, private, pg_temp
as $function$
declare
  v_requested text := upper(btrim(coalesce(p_environment,'')));
  v_configured text;
begin
  if v_requested not in ('TEST','LIVE') then
    raise exception 'CANDIDATE_ENVIRONMENT_INVALID'
      using errcode='22023', detail=jsonb_build_object('code','CANDIDATE_ENVIRONMENT_INVALID')::text;
  end if;

  select upper(btrim(candidate_app_environment))
  into v_configured
  from public.settings_defaults
  where id=1;

  if v_configured is null then
    raise exception 'CANDIDATE_ENVIRONMENT_NOT_CONFIGURED'
      using errcode='55000', detail=jsonb_build_object('code','CANDIDATE_ENVIRONMENT_NOT_CONFIGURED')::text;
  end if;

  if v_requested is distinct from v_configured then
    raise exception 'CANDIDATE_ENVIRONMENT_MISMATCH'
      using errcode='28000', detail=jsonb_build_object(
        'code','CANDIDATE_ENVIRONMENT_MISMATCH',
        'requested_environment',v_requested,
        'configured_environment',v_configured
      )::text;
  end if;

  return v_requested;
end;
$function$;

create or replace function private._candidate_timesheet_summary_revision_upsert_v1(
  p_identity_kind text,p_identity_id uuid,p_current_timesheet_id uuid,p_contract_week_id uuid
)
returns void
language plpgsql
security definer
set search_path=pg_catalog,public,private,extensions,pg_temp
as $function$
declare
  v_kind text:=upper(btrim(coalesce(p_identity_kind,'')));
  v_seq bigint;
begin
  if p_identity_id is null or v_kind not in ('TIMESHEET','CONTRACT_WEEK') then return; end if;
  if v_kind='TIMESHEET' and p_current_timesheet_id is null then return; end if;

  v_seq:=nextval('private.candidate_timesheet_summary_revision_seq'::regclass);
  insert into private.candidate_timesheet_summary_revisions as revision_row(
    identity_kind,identity_id,current_timesheet_id,contract_week_id,revision_seq,changed_at_utc
  ) values (
    v_kind,p_identity_id,p_current_timesheet_id,p_contract_week_id,v_seq,clock_timestamp()
  )
  on conflict(identity_kind,identity_id) do update set
    current_timesheet_id=excluded.current_timesheet_id,
    contract_week_id=excluded.contract_week_id,
    revision_seq=excluded.revision_seq,
    changed_at_utc=excluded.changed_at_utc;
end;
$function$;

create or replace function private._candidate_expense_components_sync_v1(
  p_workflow_id uuid,
  p_now_utc timestamptz default now()
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = pg_catalog, public, private, pg_temp
as $function$
declare
  v_workflow public.candidate_submission_workflows%rowtype;
  v_fin public.timesheets_financials%rowtype;
  v_timesheet public.timesheets%rowtype;
  v_approval public.candidate_approval_requests%rowtype;
  v_value record;
  v_component public.candidate_expense_components%rowtype;
  v_document_generation integer;
  v_lifecycle text;
  v_manager_state text;
  v_agency_state text;
  v_has_evidence boolean;
  v_changed boolean;
  v_count integer:=0;
  v_before jsonb;
begin
  select * into v_workflow from public.candidate_submission_workflows
  where id=p_workflow_id;
  if not found then raise exception 'CANDIDATE_WORKFLOW_NOT_FOUND' using errcode='P0002'; end if;
  if v_workflow.workflow_kind not in ('CONTRACT_EXPENSE','CONTRACT_COMBINED')
     or v_workflow.immutable_submission_json is null then
    return jsonb_build_object('ok',true,'workflow_id',v_workflow.id,'component_count',0);
  end if;
  v_document_generation:=case when v_workflow.state='FINALISED'
    then greatest(v_workflow.generation-1,1) else v_workflow.generation end;
  if v_workflow.target_timesheet_id is not null then
    select * into v_fin from public.timesheets_financials financial
    where financial.timesheet_id=v_workflow.target_timesheet_id and financial.is_current
    order by financial.computed_at_utc desc nulls last,financial.updated_at desc,financial.id desc limit 1;
    select * into v_timesheet from public.timesheets timesheet
    where timesheet.timesheet_id=v_workflow.target_timesheet_id and timesheet.is_current;
    if not found
       or v_timesheet.archived_at_utc is not null
       or v_timesheet.sheet_scope<>'WEEKLY'::public.timesheet_scope_enum then
      raise exception 'CANDIDATE_EXPENSE_COMPONENT_OWNER_SCOPE_INVALID'
        using errcode='23514';
    end if;
  end if;
  select * into v_approval from public.candidate_approval_requests request
  where request.workflow_id=v_workflow.id
    and request.workflow_generation=v_document_generation
  order by request.request_generation desc,request.updated_at_utc desc,request.id desc limit 1;
  v_lifecycle:=case
    when v_workflow.state='REFUSED' then 'MANAGER_REFUSED'
    when v_workflow.state='REJECTED' then 'OFFICE_REJECTED'
    when v_workflow.state='CANCELLED' then 'CANCELLED'
    when v_workflow.state in ('EXPIRED','SUPERSEDED') then 'SUPERSEDED'
    when v_workflow.state in ('MANAGER_APPROVED','MANAGER_APPROVED_PENDING_FINAL_DOCUMENT','READY_TO_FINALISE','FINALISED','RECEIVED') then 'MANAGER_APPROVED'
    when v_workflow.state in ('CREATED','WORKER_DRAFT') then 'DRAFT'
    else 'SUBMITTED' end;
  v_manager_state:=case
    when v_workflow.state='REFUSED' or v_approval.state='REFUSED' then 'REFUSED'
    when v_workflow.manager_approved_at_utc is not null or v_approval.state='APPROVED'
      or v_workflow.state in (
        'MANAGER_APPROVED','MANAGER_APPROVED_PENDING_FINAL_DOCUMENT',
        'READY_TO_FINALISE','FINALISED','RECEIVED'
      ) then 'APPROVED'
    when v_approval.id is not null and v_approval.state='PENDING' then 'PENDING'
    else 'NOT_REQUESTED' end;
  v_agency_state:=case
    when v_fin.paid_at_utc is not null or upper(coalesce(v_timesheet.status::text,''))='PAID' then 'PAID'
    when v_fin.locked_by_invoice_id is not null or upper(coalesce(v_timesheet.status::text,''))='INVOICED' then 'INVOICED'
    when v_fin.authorised_at_utc is not null
      or v_timesheet.authorised_at_server is not null
      or upper(coalesce(v_timesheet.status::text,'')) in ('AUTHORISED','AUTHORIZED')
      then 'AUTHORISED'
    else 'NOT_AUTHORISED' end;

  for v_value in select * from private._candidate_expense_component_values_v1(v_workflow.id) loop
    select exists(
      select 1 from public.candidate_submission_components evidence
      where evidence.workflow_id=v_workflow.id
        and evidence.workflow_generation=v_document_generation
        and evidence.expense_category=v_value.expense_category
        and evidence.component_kind in ('MILEAGE_FORM','EXPENSE_EVIDENCE')
        and evidence.state not in ('SUPERSEDED','REJECTED','ABANDONED')
    ) into v_has_evidence;
    if v_value.amount<=0 and v_value.mileage_units<=0 and not v_has_evidence then continue; end if;
    select * into v_component from public.candidate_expense_components component
    where component.workflow_id=v_workflow.id
      and component.expense_category=v_value.expense_category
    for update;
    if not found then
      v_before:='{}'::jsonb;
      insert into public.candidate_expense_components(
        workflow_id,workflow_generation,expense_category,owning_timesheet_id,amount,mileage_units,
        lifecycle_state,manager_approval_state,agency_authorisation_state,approval_request_id,
        submitted_at_utc,manager_approved_at_utc,refusal_kind,refusal_reason,refused_at_utc,
        removed_at_utc,created_at_utc,updated_at_utc
      ) values (
        v_workflow.id,v_document_generation,v_value.expense_category,v_workflow.target_timesheet_id,
        v_value.amount,v_value.mileage_units,v_lifecycle,v_manager_state,v_agency_state,v_approval.id,
        v_workflow.worker_submitted_at_utc,v_workflow.manager_approved_at_utc,
        case when v_lifecycle='MANAGER_REFUSED' then 'MANAGER_REFUSAL'
          when v_lifecycle='OFFICE_REJECTED' then 'AGENCY_REJECTION' else null end,
        case when v_lifecycle in ('MANAGER_REFUSED','OFFICE_REJECTED')
          then coalesce(v_approval.refusal_reason,v_workflow.rejection_reason,'No reason recorded') else null end,
        case when v_lifecycle in ('MANAGER_REFUSED','OFFICE_REJECTED')
          then coalesce(v_approval.refused_at_utc,v_workflow.updated_at_utc) else null end,
        case when v_lifecycle in ('OFFICE_REJECTED','CANCELLED','SUPERSEDED') then v_workflow.updated_at_utc else null end,
        p_now_utc,p_now_utc
      ) returning * into v_component;
      v_changed:=true;
    else
      -- A deliberate component withdrawal/cancellation is historical truth;
      -- a later generic workflow sync must never silently reactivate it.
       if v_component.lifecycle_state in (
         'MANAGER_REFUSED','OFFICE_REJECTED','WITHDRAWN','CANCELLED','SUPERSEDED'
       ) then
        v_count:=v_count+1;
        continue;
      end if;
      v_changed:=v_component.workflow_generation is distinct from v_document_generation
        or v_component.owning_timesheet_id is distinct from v_workflow.target_timesheet_id
        or v_component.amount is distinct from v_value.amount
        or v_component.mileage_units is distinct from v_value.mileage_units
        or v_component.lifecycle_state is distinct from v_lifecycle
        or v_component.manager_approval_state is distinct from v_manager_state
        or v_component.agency_authorisation_state is distinct from v_agency_state
        or v_component.approval_request_id is distinct from v_approval.id;
      if v_changed then
        v_before:=to_jsonb(v_component);
        update public.candidate_expense_components set
          workflow_generation=v_document_generation,
          component_generation=component_generation+1,
          owning_timesheet_id=v_workflow.target_timesheet_id,
          amount=v_value.amount,mileage_units=v_value.mileage_units,
          lifecycle_state=v_lifecycle,manager_approval_state=v_manager_state,
          agency_authorisation_state=v_agency_state,approval_request_id=v_approval.id,
          submitted_at_utc=coalesce(submitted_at_utc,v_workflow.worker_submitted_at_utc),
          manager_approved_at_utc=v_workflow.manager_approved_at_utc,
          refusal_kind=case when v_lifecycle='MANAGER_REFUSED' then 'MANAGER_REFUSAL'
            when v_lifecycle='OFFICE_REJECTED' then 'AGENCY_REJECTION' else null end,
          refusal_reason=case when v_lifecycle in ('MANAGER_REFUSED','OFFICE_REJECTED')
            then coalesce(v_approval.refusal_reason,v_workflow.rejection_reason,'No reason recorded') else null end,
          refused_at_utc=case when v_lifecycle in ('MANAGER_REFUSED','OFFICE_REJECTED')
            then coalesce(v_approval.refused_at_utc,v_workflow.updated_at_utc) else null end,
          removed_at_utc=case when v_lifecycle in ('OFFICE_REJECTED','CANCELLED','SUPERSEDED')
            then v_workflow.updated_at_utc else null end,
          updated_at_utc=p_now_utc
        where expense_component_id=v_component.expense_component_id
        returning * into v_component;
      end if;
    end if;
    if v_changed then
      insert into public.candidate_expense_component_events(
        expense_component_id,workflow_id,component_generation,event_type,actor_kind,
        before_state_json,after_state_json,idempotency_key,occurred_at_utc
      ) values (
        v_component.expense_component_id,v_workflow.id,v_component.component_generation,
        case v_component.lifecycle_state
          when 'MANAGER_APPROVED' then 'MANAGER_APPROVED'
          when 'MANAGER_REFUSED' then 'MANAGER_REFUSED'
          when 'OFFICE_REJECTED' then 'OFFICE_REJECTED'
          when 'SUBMITTED' then 'SUBMITTED'
          when 'CANCELLED' then 'CANCELLED'
          when 'SUPERSEDED' then 'SUPERSEDED'
          else 'CREATED' end,
        'SYSTEM',coalesce(v_before,'{}'::jsonb),to_jsonb(v_component),
        'component-sync:'||v_component.expense_component_id::text||':'
          ||v_component.component_generation::text,p_now_utc
      ) on conflict(expense_component_id,idempotency_key) do nothing;
    end if;
    v_count:=v_count+1;
  end loop;
  return jsonb_build_object('ok',true,'workflow_id',v_workflow.id,'component_count',v_count);
end;
$function$;

CREATE OR REPLACE FUNCTION private._candidate_expense_source_root_guard_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
BEGIN
 IF NEW.lifecycle_state NOT IN
  ('MANAGER_REFUSED','OFFICE_REJECTED','WITHDRAWN','CANCELLED','SUPERSEDED') THEN
  IF NEW.owning_timesheet_id IS NOT NULL
  AND (TG_OP='INSERT' OR NEW.owning_timesheet_id IS DISTINCT FROM OLD.owning_timesheet_id)
  AND NOT EXISTS (SELECT 1 FROM public.timesheets t WHERE t.timesheet_id=NEW.owning_timesheet_id) THEN
   RAISE EXCEPTION 'BPAY_EXPENSE_TIMESHEET_NOT_VISIBLE' USING ERRCODE='23503';
  END IF;
  PERFORM private.bpay_expense_identity_gate_v1(NEW.owning_timesheet_id);
  IF private._candidate_expense_source_family_v1(NEW.owning_timesheet_id) THEN
   RAISE EXCEPTION 'SOURCE_ROOT_HAS_SEPARATE_CLAIM_COMPONENT' USING ERRCODE='55000';
  END IF;
 END IF;
 RETURN NEW;
END; $function$;

CREATE OR REPLACE FUNCTION private.bpay_source_family_current_gate_v1(p_booking text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
DECLARE locked uuid[]; visible uuid[];
BEGIN
 -- S-02: share-lock the family's CURRENT Timesheet row(s), then re-verify with a fresh snapshot that the
 -- locked set is exactly the current set. A rotation/delete in flight holds that row => refused (BUSY);
 -- a rotation committed meanwhile is seen by the re-read (EvalPlanQual re-checks is_current/booking).
 IF p_booking IS NULL OR btrim(p_booking)='' THEN RETURN; END IF;
 SELECT coalesce(array_agg(q.timesheet_id ORDER BY q.timesheet_id),'{}'::uuid[]) INTO locked
 FROM (SELECT t.timesheet_id FROM public.timesheets t
       WHERE t.booking_id=p_booking AND t.is_current FOR SHARE SKIP LOCKED) q;
 SELECT coalesce(array_agg(t.timesheet_id ORDER BY t.timesheet_id),'{}'::uuid[]) INTO visible
 FROM public.timesheets t WHERE t.booking_id=p_booking AND t.is_current;
 IF locked IS DISTINCT FROM visible THEN
  RAISE EXCEPTION 'BPAY_SOURCE_FAMILY_BUSY' USING ERRCODE='55P03';
 END IF;
END; $function$;

CREATE OR REPLACE FUNCTION private.bpay_source_row_gate_v1(p_id uuid, p_exclusive boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
BEGIN
 -- S-02: native row lock on one Timesheet (tuple lock, no lock-table slot). SHARE conflicts with every
 -- UPDATE/DELETE of the row; NO KEY UPDATE also conflicts with SHARE holders. SKIP LOCKED never waits:
 -- a visible row held by another writer is refused promptly, exactly like the family try-lock.
 -- Returns false only when the row is not visible to this transaction (caller decides).
 IF p_id IS NULL THEN RETURN false; END IF;
 IF p_exclusive THEN
  PERFORM 1 FROM public.timesheets t WHERE t.timesheet_id=p_id FOR NO KEY UPDATE SKIP LOCKED;
 ELSE
  PERFORM 1 FROM public.timesheets t WHERE t.timesheet_id=p_id FOR SHARE SKIP LOCKED;
 END IF;
 IF FOUND THEN RETURN true; END IF;
 IF EXISTS (SELECT 1 FROM public.timesheets t WHERE t.timesheet_id=p_id) THEN
  RAISE EXCEPTION 'BPAY_SOURCE_FAMILY_BUSY' USING ERRCODE='55P03';
 END IF;
 RETURN false;
END; $function$;

CREATE OR REPLACE FUNCTION private.bpay_clock_retirement_changed_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
DECLARE f uuid;
BEGIN
 IF TG_TABLE_SCHEMA='private' THEN f:=OLD.family_id;
 ELSE f:=OLD.bpay_clock_family_id_v1; END IF;
 PERFORM private.bpay_clock_retire_family_v1(f); RETURN NULL;
END;
$function$;

create or replace function private.weekly_source_rule_qualification_context_v1(p_client_id uuid,p_cycle_id uuid)
returns jsonb language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare frame jsonb; auth jsonb; n integer; stack text;
begin
  select count(*),jsonb_agg(audit.after_json)->0 into n,frame from public.audit_events audit
    where audit.object_type='weekly_source_off_rule_command' and audit.action='WEEKLY_SOURCE_OFF_RULE_COMMAND_ADMITTED'
      and audit.event_sequence_is_authoritative and audit.after_json->>'transaction_id'=pg_current_xact_id_if_assigned()::text
      and audit.after_json->>'backend_pid'=pg_backend_pid()::text
      and not exists(select 1 from public.audit_events closed where closed.object_type=audit.object_type and closed.object_id_text=audit.object_id_text
        and closed.action='WEEKLY_SOURCE_OFF_RULE_COMMAND_COMPLETED' and closed.event_sequence_is_authoritative);
  if n=0 then return null; end if;
  get diagnostics stack=pg_context;
  if n<>1 or stack !~ 'PL/pgSQL function (private\.)?weekly_source_rule_qualification_execute_v1\(jsonb\)'
    or frame->>'source_cycle_id' is distinct from p_cycle_id::text or frame->'operational_ready' is distinct from 'false'::jsonb
    or frame->>'command_sha256' is distinct from encode(private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_OFF_RULE_COMMAND_V1',frame-'command_sha256'),'hex') then
    raise exception 'WEEKLY_SOURCE_RULE_QUALIFICATION_COMMAND_UNAVAILABLE' using errcode='55000'; end if;
  auth:=private.weekly_source_rule_qualification_scope_assert_v1(frame->'authorization',(frame->>'actor_user_id')::uuid,false);
  if p_client_id is not null and not(auth#>'{fixture_manifest,client_ids}' @> jsonb_build_array(p_client_id)) then
    raise exception 'WEEKLY_SOURCE_RULE_QUALIFICATION_FOREIGN_CLIENT' using errcode='42501'; end if;
  return auth;
end;
$function$;

create or replace function private._candidate_manager_authoriser_policy_normalize_v2(
  p_policy jsonb,
  p_scope text default 'EFFECTIVE'
)
returns jsonb
language plpgsql
immutable
parallel safe
set search_path=''
as $function$
declare
  v_source jsonb:=case when pg_catalog.jsonb_typeof(p_policy)='object' then p_policy else '{}'::jsonb end;
  v_scope text:=pg_catalog.upper(pg_catalog.btrim(coalesce(p_scope,'EFFECTIVE')));
  v_mode text:=pg_catalog.upper(pg_catalog.btrim(coalesce(v_source->>'mode','INHERIT')));
  v_emails jsonb;
  v_domains jsonb;
  v_allow_free boolean:=false;
begin
  if v_scope not in ('CLIENT','CONTRACT_WRITE','EFFECTIVE') then
    raise exception using errcode='22023',message='CANDIDATE_MANAGER_POLICY_SCOPE_INVALID';
  end if;
  if v_scope='CLIENT' and exists (
    select 1 from pg_catalog.jsonb_object_keys(v_source) k
    where k not in ('approved_emails','approved_domains','allow_free_business_email')
  ) then
    raise exception using errcode='22023',message='CANDIDATE_MANAGER_CLIENT_POLICY_FIELD_INVALID';
  end if;
  if v_scope='CONTRACT_WRITE' and exists (
    select 1 from pg_catalog.jsonb_object_keys(v_source) k
    where k not in ('mode','approved_emails','approved_domains')
  ) then
    raise exception using errcode='22023',message='CANDIDATE_MANAGER_CONTRACT_POLICY_FIELD_INVALID';
  end if;
  v_emails:=private._candidate_manager_authoriser_email_array_v2(v_source->'approved_emails');
  v_domains:=private._candidate_manager_authoriser_domain_array_v2(v_source->'approved_domains');
  if v_source ? 'allow_free_business_email' then
    if pg_catalog.jsonb_typeof(v_source->'allow_free_business_email')<>'boolean' then
      raise exception using errcode='22023',message='CANDIDATE_MANAGER_FREE_EMAIL_SETTING_INVALID';
    end if;
    v_allow_free:=(v_source->>'allow_free_business_email')::boolean;
  end if;

  if v_scope='CLIENT' then
    return pg_catalog.jsonb_build_object(
      'approved_emails',v_emails,'approved_domains',v_domains,
      'allow_free_business_email',v_allow_free
    );
  elsif v_scope='CONTRACT_WRITE' then
    if v_mode not in ('INHERIT','EXTEND','CONTRACT_ONLY') then
      raise exception using errcode='22023',message='CANDIDATE_MANAGER_CONTRACT_MODE_INVALID';
    end if;
    if v_mode='INHERIT' and (pg_catalog.jsonb_array_length(v_emails)>0 or pg_catalog.jsonb_array_length(v_domains)>0) then
      raise exception using errcode='22023',message='CANDIDATE_MANAGER_INHERIT_HAS_ADDITIONS';
    end if;
    if v_mode='CONTRACT_ONLY' and pg_catalog.jsonb_array_length(v_emails)=0 and pg_catalog.jsonb_array_length(v_domains)=0 then
      raise exception using errcode='22023',message='CANDIDATE_MANAGER_CONTRACT_ONLY_EMPTY';
    end if;
    return pg_catalog.jsonb_build_object(
      'mode',v_mode,'approved_emails',v_emails,'approved_domains',v_domains
    );
  end if;

  return pg_catalog.jsonb_build_object(
    'approved_emails',v_emails,'approved_domains',v_domains,
    'allow_free_business_email',v_allow_free
  );
end;
$function$;

create or replace function private.weekly_source_invoice_adjustment_authority_v1(p_invoice_id uuid,p_binding_ids uuid[] default null)
returns jsonb language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare inv public.invoices%rowtype; v_ids uuid[]; v_count integer; v_rates integer; v_null_rates integer;
  v_rate numeric; v_records jsonb; v_payload jsonb; v_group uuid; v_versions uuid[];
begin
  select * into inv from public.invoices where id=p_invoice_id;
  if not found or inv.type::text is distinct from 'INVOICE'
    or inv.header_snapshot_json->>'schema_version' is distinct from 'WEEKLY_SOURCE_SELF_BILL_INVOICE_V1'
    or inv.header_snapshot_json#>>'{meta,source}' is distinct from 'WEEKLY_FINAL_SOURCE' then
    return jsonb_build_object('allowed',false); end if;
  if pg_input_is_valid(inv.header_snapshot_json#>>'{meta,source_group_id}','uuid') is distinct from true then
    raise exception 'WEEKLY_SOURCE_INVOICE_ADJUSTMENT_AUTHORITY_UNAVAILABLE' using errcode='55000'; end if;
  v_group:=(inv.header_snapshot_json#>>'{meta,source_group_id}')::uuid;
  if p_binding_ids is null then
    select array_agg(id order by id) into v_ids from public.weekly_source_invoice_line_bindings where invoice_id=inv.id and state='CURRENT';
  else
    if cardinality(p_binding_ids)=0 or array_position(p_binding_ids,null::uuid) is not null then
      raise exception 'WEEKLY_SOURCE_INVOICE_ADJUSTMENT_AUTHORITY_UNAVAILABLE' using errcode='55000'; end if;
    select array_agg(distinct id order by id) into v_ids from unnest(p_binding_ids) id;
  end if;
  if v_ids is null or cardinality(v_ids)=0 then return jsonb_build_object('allowed',false); end if;
  -- CURRENT proves new edit admission. A sealed existing adjustment can retain
  -- its exact SUPERSEDED binding history after an ordinary Source move; it
  -- never follows the movement to another invoice or chooses a new tax rate.
  select count(*) into v_count from public.weekly_source_invoice_line_bindings binding
    join public.weekly_source_billing_movements movement on movement.id=binding.billing_movement_id
    join public.weekly_source_final_revisions revision on revision.id=binding.original_final_revision_id and revision.id=movement.final_revision_id
    join public.weekly_source_cycles cycle on cycle.id=binding.original_cycle_id and cycle.id=revision.source_cycle_id
    join public.weekly_source_rule_set_versions rules on rules.id=revision.rule_set_version_id
    where binding.id=any(v_ids) and binding.invoice_id=inv.id and binding.state in('CURRENT','SUPERSEDED')
      and binding.client_id=inv.client_id and movement.actual_client_id=inv.client_id and cycle.source_group_id=v_group
      and rules.values_json->>'invoice_sender'='CLIENT_SELF_BILL'
      and rules.values_json->>'negative_adjustment_policy'='NEGATIVE_ADJUSTMENT_LINE';
  if v_count<>cardinality(v_ids) then return jsonb_build_object('allowed',false); end if;
  select count(distinct movement.vat_rate_pct),count(*) filter(where movement.vat_rate_pct is null),min(movement.vat_rate_pct)
    into v_rates,v_null_rates,v_rate from public.weekly_source_invoice_line_bindings binding
    join public.weekly_source_billing_movements movement on movement.id=binding.billing_movement_id
    where binding.id=any(v_ids) and movement.source_line_kind<>'INVOICE_VAT_ROUNDING';
  if v_rates<>1 or v_null_rates<>0 or v_rate is null or v_rate<0 then
    raise exception 'WEEKLY_SOURCE_INVOICE_ADJUSTMENT_VAT_UNAVAILABLE' using errcode='55000'; end if;
  select jsonb_agg(jsonb_build_object('binding_id',binding.id,'movement_id',movement.id,
      'final_revision_id',revision.id,'source_cycle_id',cycle.id,'manifest_hash',encode(binding.manifest_hash,'hex'),
      'rule_set_version_id',rules.id,'rule_values_sha256',rules.values_sha256,'vat_rate_pct',movement.vat_rate_pct) order by binding.id),
    array_agg(distinct rules.id order by rules.id) into v_records,v_versions
    from public.weekly_source_invoice_line_bindings binding
    join public.weekly_source_billing_movements movement on movement.id=binding.billing_movement_id
    join public.weekly_source_final_revisions revision on revision.id=binding.original_final_revision_id
    join public.weekly_source_cycles cycle on cycle.id=binding.original_cycle_id
    join public.weekly_source_rule_set_versions rules on rules.id=revision.rule_set_version_id where binding.id=any(v_ids);
  v_payload:=jsonb_build_object('schema_version','WEEKLY_SOURCE_INVOICE_ADJUSTMENT_AUTHORITY_V1','allowed',true,
    'invoice_id',inv.id,'client_id',inv.client_id,'source_group_id',v_group,'binding_ids',to_jsonb(v_ids),
    'rule_set_version_ids',to_jsonb(v_versions),'vat_rate_pct',v_rate,'bound_movements',v_records);
  return v_payload||jsonb_build_object('authority_sha256',encode(private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_SOURCE_INVOICE_ADJUSTMENT_AUTHORITY_V1',v_payload),'hex'));
end;
$function$;

create or replace function private.weekly_source_invoice_movement_money_v1(p_movement_id uuid,p_invoice_hold_release_id uuid default null)
returns jsonb language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare m public.weekly_source_billing_movements%rowtype; s public.weekly_source_upload_rows%rowtype;
  receipt public.weekly_source_invoice_hold_releases%rowtype; release_id uuid:=p_invoice_hold_release_id;
  ids uuid[]; rules jsonb; authority jsonb;
begin
  select * into strict m from public.weekly_source_billing_movements where weekly_source_billing_movements.id=p_movement_id;
  if release_id is null then
    -- Historical money follows its exact admitted presentation. An unadmitted
    -- live receipt or today's settings never reprices a prior movement.
    select array_agg(distinct p.invoice_hold_release_id) into ids
      from public.weekly_source_invoice_line_bindings b join public.weekly_source_invoice_presentation_lines p on p.id=b.presentation_line_id
      where b.billing_movement_id=m.id and b.state='CURRENT' and p.invoice_hold_release_id is not null
        and m.movement_role in ('POSITIVE','REPLACEMENT') and m.source_line_kind in ('SOURCE_ORDINARY','SOURCE_REPLACEMENT','SOURCE_REBILL_LINE','SOURCE_INVOICE_CORRECTION');
    if cardinality(ids)>1 then raise exception 'WEEKLY_SOURCE_INVOICE_RELEASE_PRESENTATION_AMBIGUOUS' using errcode='55000'; end if;
    release_id:=ids[1];
    if release_id is null and exists(select 1 from public.weekly_source_invoice_line_bindings old_binding
      join public.weekly_source_invoice_presentation_lines old_presentation on old_presentation.id=old_binding.presentation_line_id
      where old_binding.billing_movement_id=m.id and old_presentation.invoice_hold_release_id is not null) then
      raise exception 'WEEKLY_SOURCE_INVOICE_RELEASE_HISTORICAL_IDENTITY_UNAVAILABLE' using errcode='55000'; end if;
  end if;
  if release_id is null then return jsonb_build_object('net_pence',m.invoice_presentation_charge_pence,
    'vat_pence',(m.vat_amount*100)::bigint,'gross_pence',(m.total_inc_vat*100)::bigint,'release_authority',null); end if;
  select * into strict receipt from public.weekly_source_invoice_hold_releases where weekly_source_invoice_hold_releases.id=release_id;
  select * into strict s from public.weekly_source_upload_rows where weekly_source_upload_rows.id=receipt.upload_row_id;
  rules:=private.weekly_source_frozen_rule_values_v1(m.final_revision_id);
  if receipt.hold_kind<>'VAT_FIT' or m.source_facts_json->>'upload_row_id' is distinct from s.id::text
    or m.source_profile_kind<>'HEALTHROSTER_ACTUAL_ROWS'
    or not ((m.source_line_kind in ('SOURCE_ORDINARY','SOURCE_REPLACEMENT','SOURCE_REBILL_LINE') and m.movement_role in ('POSITIVE','REPLACEMENT'))
      or (m.source_line_kind='SOURCE_INVOICE_CORRECTION' and m.movement_role='REPLACEMENT'))
    or rules is null or rules->>'invoice_sender' is distinct from 'CLIENT_SELF_BILL'
    or rules->>'invoice_amount_basis' is distinct from 'SOURCE_AMOUNT'
    or rules->>'source_amount_basis' is distinct from 'EXPORT_ACTUAL_COST_INC_VAT_NET_AGENCY_WORKER_PAY'
    or s.source_shift_charge_pence is distinct from receipt.net_pence or m.invoice_presentation_charge_pence is distinct from receipt.net_pence
    or s.source_gross_pence is null or s.source_vat_pence is null
    or abs(5::numeric*s.source_gross_pence-6::numeric*s.source_shift_charge_pence)<=5
    or receipt.vat_pence is distinct from (case receipt.action when 'BILL_AT_NET_PLUS_20' then round(receipt.net_pence::numeric*20/100)::bigint
      when 'BILL_AS_FILE' then s.source_vat_pence else null end)
    or receipt.gross_pence is distinct from receipt.net_pence+receipt.vat_pence
    or receipt.release_hash is distinct from private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_INVOICE_HOLD_RELEASE_V1',jsonb_build_object(
      'upload_row_id',s.id,'source_row_hash',encode(s.normalised_row_hash,'hex'),'hold_kind',receipt.hold_kind,'action',receipt.action,
      'net_pence',receipt.net_pence,'vat_pence',receipt.vat_pence,'gross_pence',receipt.gross_pence,'actor_user_id',receipt.actor_user_id)) then
    raise exception 'WEEKLY_SOURCE_INVOICE_RELEASE_AUTHORITY_INVALID' using errcode='55000'; end if;
  authority:=jsonb_build_object('invoice_hold_release_id',receipt.id,'release_hash',encode(receipt.release_hash,'hex'),
    'upload_row_id',s.id,'source_row_hash',encode(s.normalised_row_hash,'hex'),'original_movement_id',m.id,
    'original_movement_hash',encode(m.movement_economic_hash,'hex'),'net_pence',receipt.net_pence,
    'vat_pence',receipt.vat_pence,'gross_pence',receipt.gross_pence);
  return jsonb_build_object('net_pence',receipt.net_pence,'vat_pence',receipt.vat_pence,'gross_pence',receipt.gross_pence,'release_authority',authority);
end;
$function$;

create or replace function private.weekly_source_invoice_admitted_member_money_v1(p_presentation_id uuid,p_movement_id uuid)
returns jsonb language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare p public.weekly_source_invoice_presentation_lines%rowtype; m public.weekly_source_billing_movements%rowtype;
  authority jsonb; receipt public.weekly_source_invoice_hold_releases%rowtype;
begin
  select * into strict p from public.weekly_source_invoice_presentation_lines where id=p_presentation_id;
  select * into strict m from public.weekly_source_billing_movements where id=p_movement_id;
  if not exists(select 1 from public.weekly_source_invoice_line_bindings b where b.presentation_line_id=p.id
    and b.billing_movement_id=m.id and b.state='CURRENT') then
    raise exception 'WEEKLY_SOURCE_INVOICE_ADMITTED_MEMBER_INVALID' using errcode='55000'; end if;
  authority:=private.weekly_source_invoice_rounding_authority_rebuild_v1(p.id);
  if authority is not null then
    if authority->>'rounding_movement_id' is distinct from m.id::text then
      raise exception 'WEEKLY_SOURCE_INVOICE_ROUNDING_MEMBER_INVALID' using errcode='55000'; end if;
    return jsonb_build_object('net_pence',0,'vat_pence',authority->'admitted_rounding_vat_pence','gross_pence',authority->'admitted_rounding_vat_pence');
  end if;
  if p.invoice_hold_release_id is not null then
    select * into strict receipt from public.weekly_source_invoice_hold_releases where id=p.invoice_hold_release_id;
    if receipt.upload_row_id::text=m.source_facts_json->>'upload_row_id' and m.movement_role in ('POSITIVE','REPLACEMENT') then
      return private.weekly_source_invoice_movement_money_v1(m.id,receipt.id); end if;
  end if;
  -- NULL is the original immutable money at this exact historical identity.
  return jsonb_build_object('net_pence',m.invoice_presentation_charge_pence,
    'vat_pence',(m.vat_amount*100)::bigint,'gross_pence',(m.total_inc_vat*100)::bigint);
end;
$function$;

create or replace function private.weekly_source_invoice_presentation_expected_source_hash_v1(p_presentation_id uuid)
returns bytea language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare p public.weekly_source_invoice_presentation_lines%rowtype; ids uuid[]; original bytea; authority jsonb;
begin
  select * into strict p from public.weekly_source_invoice_presentation_lines where id=p_presentation_id;
  select array_agg(binding.billing_movement_id order by binding.billing_movement_id) into ids
    from public.weekly_source_invoice_line_bindings binding where binding.presentation_line_id=p.id and binding.state='CURRENT';
  original:=private.weekly_source_invoice_presentation_source_hash_v1(ids,p.invoice_hold_release_id);
  authority:=private.weekly_source_invoice_rounding_authority_rebuild_v1(p.id);
  if authority is null then return original; end if;
  return private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_INVOICE_ROUNDING_PRESENTATION_V1',
    jsonb_build_object('original_movement_source_hash',encode(original,'hex'),
      'rounding_authority_sha256',authority->>'authority_sha256'));
end;
$function$;

create or replace function private.weekly_source_invoice_rounding_authority_rebuild_v1(p_presentation_id uuid)
returns jsonb language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare p public.weekly_source_invoice_presentation_lines%rowtype; receipt_map jsonb; result jsonb;
begin
  select * into strict p from public.weekly_source_invoice_presentation_lines where id=p_presentation_id;
  if p.invoice_rounding_authority_json is null then return null; end if;
  if p.line_kind<>'INVOICE_VAT_ROUNDING' or p.origin_kind<>'INVOICE_VAT_ROUNDING'
    or jsonb_typeof(p.invoice_rounding_authority_json->'member_witnesses') is distinct from 'array' then
    raise exception 'WEEKLY_SOURCE_ROUNDING_PRESENTATION_AUTHORITY_INVALID' using errcode='55000'; end if;
  select coalesce(jsonb_agg(jsonb_build_object('billing_movement_id',w->'billing_movement_id',
    'invoice_hold_release_id',w->'invoice_hold_release_id') order by w->>'billing_movement_id'),'[]'::jsonb)
    into receipt_map from jsonb_array_elements(p.invoice_rounding_authority_json->'member_witnesses') w;
  result:=private.weekly_source_invoice_rounding_receipt_set_v1(p.client_manifest_id,receipt_map);
  if result is distinct from p.invoice_rounding_authority_json then
    raise exception 'WEEKLY_SOURCE_ROUNDING_PRESENTATION_AUTHORITY_INVALID' using errcode='55000'; end if;
  -- Every admitted witness must be tied to the exact original presentation of
  -- the actual member, including an explicit NULL original-money decision.
  if exists(select 1 from jsonb_array_elements(result->'member_witnesses') w
    where not exists(select 1 from public.weekly_source_invoice_line_bindings binding
      join public.weekly_source_invoice_presentation_lines original on original.id=binding.presentation_line_id
      where binding.billing_movement_id=(w->>'billing_movement_id')::uuid and binding.state='CURRENT'
        and original.client_manifest_id=p.client_manifest_id
        and original.invoice_hold_release_id is not distinct from nullif(w->>'invoice_hold_release_id','')::uuid)) then
    raise exception 'WEEKLY_SOURCE_ROUNDING_RECEIPT_PRESENTATION_SET_INVALID' using errcode='55000'; end if;
  return result;
end;
$function$;

CREATE OR REPLACE FUNCTION public._pay_policy_x_resolve_pre_draft_economic_key(
  p_timesheet_id uuid DEFAULT NULL::uuid,
  p_live_source_json jsonb DEFAULT '{}'::jsonb,
  p_item_type text DEFAULT NULL::text,
  p_key_type_hint text DEFAULT NULL::text,
  p_key_value_hint text DEFAULT NULL::text,
  p_work_date date DEFAULT NULL::date
)
RETURNS TABLE(
  timesheet_id uuid,
  key_type text,
  key_value text,
  key_resolution_source text,
  key_resolution_failure_reason text
)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_source_json jsonb := CASE
    WHEN jsonb_typeof(COALESCE(p_live_source_json, '{}'::jsonb)) = 'object' THEN COALESCE(p_live_source_json, '{}'::jsonb)
    ELSE '{}'::jsonb
  END;
  v_timesheet_id uuid := p_timesheet_id;
  v_timesheet_id_text text;
  v_item_type text := UPPER(NULLIF(BTRIM(COALESCE(p_item_type, '')), ''));
  v_direct_key_type text;
  v_direct_key_value text;
  v_resolved_key_type text := NULL::text;
  v_resolved_key_value text := NULL::text;
  v_resolved_source text := NULL::text;
  v_failure_reason text := NULL::text;
  v_assert_ok boolean := false;
  v_assert_key_type text := NULL::text;
  v_assert_key_value text := NULL::text;
  v_assert_failure_reason text := NULL::text;
  v_work_date_text text := NULL::text;
  v_segment_id_text text := NULL::text;
  v_segment_key_text text := NULL::text;
  v_segment_stable_key_text text := NULL::text;
  v_ref_num_text text := NULL::text;
  v_adjustment_id_text text := NULL::text;
  v_additional_code_text text := NULL::text;
  v_expense_code_text text := NULL::text;
  v_segments_json jsonb := '[]'::jsonb;
  v_live_schedule_json jsonb := '{}'::jsonb;
  v_segment_match_found boolean := false;
  v_segment_match_date_text text := NULL::text;
  v_timesheet_start_date_text text := NULL::text;
BEGIN
  v_timesheet_id_text := NULLIF(BTRIM(COALESCE(v_source_json->>'timesheet_id', '')), '');
  IF v_timesheet_id IS NULL
     AND v_timesheet_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_timesheet_id := v_timesheet_id_text::uuid;
  END IF;

  IF v_item_type IS NULL THEN
    v_item_type := UPPER(NULLIF(BTRIM(COALESCE(
      v_source_json->>'item_type',
      v_source_json->>'line_type',
      v_source_json->>'component_type',
      v_source_json#>>'{source_basis_json,item_type}',
      ''
    )), ''));
  END IF;

  v_direct_key_type := UPPER(NULLIF(BTRIM(COALESCE(
    p_key_type_hint,
    v_source_json->>'component_key_type',
    v_source_json->>'key_type',
    v_source_json#>>'{source_basis_json,component_key_type}',
    v_source_json#>>'{source_basis_json,key_type}',
    ''
  )), ''));

  v_direct_key_value := NULLIF(BTRIM(COALESCE(
    p_key_value_hint,
    v_source_json->>'component_key_value',
    v_source_json->>'key_value',
    v_source_json#>>'{source_basis_json,component_key_value}',
    v_source_json#>>'{source_basis_json,key_value}',
    ''
  )), '');

  IF v_direct_key_type IS NOT NULL OR v_direct_key_value IS NOT NULL THEN
    SELECT
      key_check.ok,
      key_check.key_type,
      key_check.key_value,
      key_check.failure_reason
    INTO
      v_assert_ok,
      v_assert_key_type,
      v_assert_key_value,
      v_assert_failure_reason
    FROM public._pay_policy_x_assert_economic_key(
      p_timesheet_id => v_timesheet_id,
      p_key_type => v_direct_key_type,
      p_key_value => v_direct_key_value,
      p_context => 'PRE_DRAFT_RESOLVE_DIRECT_KEY',
      p_authority_scope => 'PRE_DRAFT',
      p_resolution_source => 'PRE_DRAFT_LIVE_DIRECT_KEY',
      p_required => true,
      p_source_json => v_source_json
    ) AS key_check;

    IF COALESCE(v_assert_ok, false) THEN
      v_resolved_key_type := v_assert_key_type;
      v_resolved_key_value := v_assert_key_value;
      v_resolved_source := 'PRE_DRAFT_LIVE_DIRECT_KEY';
    ELSE
      v_failure_reason := v_assert_failure_reason;
    END IF;
  END IF;

  IF v_resolved_key_type IS NULL THEN
    v_work_date_text := COALESCE(
      CASE WHEN p_work_date IS NULL THEN NULL::text ELSE p_work_date::text END,
      NULLIF(BTRIM(COALESCE(v_source_json->>'work_date', '')), ''),
      NULLIF(BTRIM(COALESCE(v_source_json->>'date', '')), ''),
      NULLIF(BTRIM(COALESCE(v_source_json#>>'{source_basis_json,work_date}', '')), ''),
      NULLIF(BTRIM(COALESCE(v_source_json#>>'{source_basis_json,date}', '')), ''),
      NULLIF(BTRIM(COALESCE(v_source_json#>>'{segment,work_date}', '')), ''),
      NULLIF(BTRIM(COALESCE(v_source_json#>>'{segment,date}', '')), ''),
      NULLIF(BTRIM(COALESCE(v_source_json#>>'{segment_json,work_date}', '')), ''),
      NULLIF(BTRIM(COALESCE(v_source_json#>>'{segment_json,date}', '')), '')
    );

    v_segment_id_text := NULLIF(BTRIM(COALESCE(
      v_source_json->>'segment_id',
      v_source_json#>>'{source_basis_json,segment_id}',
      v_source_json#>>'{segment,segment_id}',
      v_source_json#>>'{segment_json,segment_id}',
      ''
    )), '');

    v_segment_key_text := NULLIF(BTRIM(COALESCE(
      v_source_json->>'segment_key',
      v_source_json#>>'{source_basis_json,segment_key}',
      v_source_json#>>'{segment,segment_key}',
      v_source_json#>>'{segment_json,segment_key}',
      ''
    )), '');

    v_segment_stable_key_text := NULLIF(BTRIM(COALESCE(
      v_source_json->>'segment_stable_key',
      v_source_json#>>'{source_basis_json,segment_stable_key}',
      v_source_json#>>'{segment,segment_stable_key}',
      v_source_json#>>'{segment_json,segment_stable_key}',
      ''
    )), '');

    v_ref_num_text := NULLIF(BTRIM(COALESCE(
      v_source_json->>'ref_num',
      v_source_json#>>'{source_basis_json,ref_num}',
      v_source_json#>>'{segment,ref_num}',
      v_source_json#>>'{segment_json,ref_num}',
      ''
    )), '');

    v_adjustment_id_text := NULLIF(BTRIM(COALESCE(
      v_source_json->>'adjustment_id',
      v_source_json->>'adjustment_code',
      v_source_json#>>'{source_basis_json,adjustment_id}',
      v_source_json#>>'{source_basis_json,adjustment_code}',
      ''
    )), '');

    v_additional_code_text := NULLIF(BTRIM(COALESCE(
      v_source_json->>'additional_code',
      v_source_json#>>'{source_basis_json,additional_code}',
      ''
    )), '');

    v_expense_code_text := NULLIF(BTRIM(COALESCE(
      v_source_json->>'expense_code',
      v_source_json->>'mileage_code',
      v_source_json#>>'{source_basis_json,expense_code}',
      v_source_json#>>'{source_basis_json,mileage_code}',
      ''
    )), '');

    IF v_item_type IN ('SEGMENT_DELTA', 'SEGMENT', 'TIMESHEET_SEGMENT', 'HOURS') THEN
      IF v_work_date_text IS NOT NULL AND v_work_date_text ~ '^\d{4}-\d{2}-\d{2}$' THEN
        v_resolved_key_type := 'TS_DAY';
        v_resolved_key_value := v_work_date_text;
        v_resolved_source := 'PRE_DRAFT_LIVE_WORK_DATE';
      END IF;

      IF v_resolved_key_type IS NULL THEN
        IF jsonb_typeof(v_source_json->'segments') = 'array' THEN
          v_segments_json := v_source_json->'segments';
        ELSIF jsonb_typeof(v_source_json#>'{actual_schedule_json,segments}') = 'array' THEN
          v_segments_json := v_source_json#>'{actual_schedule_json,segments}';
        ELSIF jsonb_typeof(v_source_json#>'{schedule_json,segments}') = 'array' THEN
          v_segments_json := v_source_json#>'{schedule_json,segments}';
        ELSE
          v_segments_json := '[]'::jsonb;
        END IF;

        IF jsonb_array_length(v_segments_json) > 0 THEN
          SELECT
            NULLIF(BTRIM(COALESCE(segment_choice.segment_json->>'date', segment_choice.segment_json->>'work_date', '')), ''),
            true
          INTO
            v_segment_match_date_text,
            v_segment_match_found
          FROM jsonb_array_elements(v_segments_json) AS segment_choice(segment_json)
          WHERE segment_choice.segment_json IS NOT NULL
            AND jsonb_typeof(segment_choice.segment_json) = 'object'
            AND (
              (v_work_date_text IS NOT NULL AND NULLIF(BTRIM(COALESCE(segment_choice.segment_json->>'date', segment_choice.segment_json->>'work_date', '')), '') = v_work_date_text)
              OR (v_ref_num_text IS NOT NULL AND NULLIF(BTRIM(COALESCE(segment_choice.segment_json->>'ref_num', '')), '') = v_ref_num_text)
              OR (v_segment_id_text IS NOT NULL AND NULLIF(BTRIM(COALESCE(segment_choice.segment_json->>'segment_id', '')), '') = v_segment_id_text)
              OR (v_segment_key_text IS NOT NULL AND NULLIF(BTRIM(COALESCE(segment_choice.segment_json->>'segment_key', segment_choice.segment_json->>'segment_id', '')), '') = v_segment_key_text)
              OR (v_segment_stable_key_text IS NOT NULL AND NULLIF(BTRIM(COALESCE(segment_choice.segment_json->>'segment_stable_key', segment_choice.segment_json->>'segment_id', segment_choice.segment_json->>'segment_key', '')), '') = v_segment_stable_key_text)
            )
          ORDER BY
            CASE
              WHEN v_work_date_text IS NOT NULL AND NULLIF(BTRIM(COALESCE(segment_choice.segment_json->>'date', segment_choice.segment_json->>'work_date', '')), '') = v_work_date_text THEN 0
              WHEN v_ref_num_text IS NOT NULL AND NULLIF(BTRIM(COALESCE(segment_choice.segment_json->>'ref_num', '')), '') = v_ref_num_text THEN 1
              WHEN v_segment_id_text IS NOT NULL AND NULLIF(BTRIM(COALESCE(segment_choice.segment_json->>'segment_id', '')), '') = v_segment_id_text THEN 2
              WHEN v_segment_key_text IS NOT NULL AND NULLIF(BTRIM(COALESCE(segment_choice.segment_json->>'segment_key', segment_choice.segment_json->>'segment_id', '')), '') = v_segment_key_text THEN 3
              WHEN v_segment_stable_key_text IS NOT NULL AND NULLIF(BTRIM(COALESCE(segment_choice.segment_json->>'segment_stable_key', segment_choice.segment_json->>'segment_id', segment_choice.segment_json->>'segment_key', '')), '') = v_segment_stable_key_text THEN 4
              ELSE 9
            END
          LIMIT 1;

          IF COALESCE(v_segment_match_found, false)
             AND v_segment_match_date_text IS NOT NULL
             AND v_segment_match_date_text ~ '^\d{4}-\d{2}-\d{2}$' THEN
            v_resolved_key_type := 'TS_DAY';
            v_resolved_key_value := v_segment_match_date_text;
            v_resolved_source := 'PRE_DRAFT_LIVE_SEGMENT_DATE';
          ELSIF COALESCE(v_segment_match_found, false) THEN
            v_resolved_key_type := 'TS_TOTAL';
            v_resolved_key_value := 'TOTAL';
            v_resolved_source := 'PRE_DRAFT_LIVE_SEGMENT_TOTAL_FALLBACK';
          END IF;
        END IF;
      END IF;

      IF v_resolved_key_type IS NULL AND v_timesheet_id IS NOT NULL THEN
        SELECT COALESCE(latest_finance.actual_schedule_json, timesheet_row.actual_schedule_json, '{}'::jsonb)
        INTO v_live_schedule_json
        FROM public.timesheets AS timesheet_row
        LEFT JOIN LATERAL (
          SELECT finance_row.actual_schedule_json
          FROM public.timesheets_financials AS finance_row
          WHERE finance_row.timesheet_id = timesheet_row.timesheet_id
            AND finance_row.is_current = true
          ORDER BY finance_row.computed_at_utc DESC, finance_row.id DESC
          LIMIT 1
        ) AS latest_finance ON true
        WHERE timesheet_row.timesheet_id = v_timesheet_id
        LIMIT 1;

        IF jsonb_typeof(v_live_schedule_json->'segments') = 'array' THEN
          v_segments_json := v_live_schedule_json->'segments';
        ELSE
          v_segments_json := '[]'::jsonb;
        END IF;

        IF jsonb_array_length(v_segments_json) > 0 THEN
          v_segment_match_found := false;
          v_segment_match_date_text := NULL::text;

          SELECT
            NULLIF(BTRIM(COALESCE(segment_choice.segment_json->>'date', segment_choice.segment_json->>'work_date', '')), ''),
            true
          INTO
            v_segment_match_date_text,
            v_segment_match_found
          FROM jsonb_array_elements(v_segments_json) AS segment_choice(segment_json)
          WHERE segment_choice.segment_json IS NOT NULL
            AND jsonb_typeof(segment_choice.segment_json) = 'object'
            AND (
              (v_ref_num_text IS NOT NULL AND NULLIF(BTRIM(COALESCE(segment_choice.segment_json->>'ref_num', '')), '') = v_ref_num_text)
              OR (v_segment_id_text IS NOT NULL AND NULLIF(BTRIM(COALESCE(segment_choice.segment_json->>'segment_id', '')), '') = v_segment_id_text)
              OR (v_segment_key_text IS NOT NULL AND NULLIF(BTRIM(COALESCE(segment_choice.segment_json->>'segment_key', segment_choice.segment_json->>'segment_id', '')), '') = v_segment_key_text)
              OR (v_segment_stable_key_text IS NOT NULL AND NULLIF(BTRIM(COALESCE(segment_choice.segment_json->>'segment_stable_key', segment_choice.segment_json->>'segment_id', segment_choice.segment_json->>'segment_key', '')), '') = v_segment_stable_key_text)
            )
          ORDER BY
            CASE
              WHEN v_ref_num_text IS NOT NULL AND NULLIF(BTRIM(COALESCE(segment_choice.segment_json->>'ref_num', '')), '') = v_ref_num_text THEN 1
              WHEN v_segment_id_text IS NOT NULL AND NULLIF(BTRIM(COALESCE(segment_choice.segment_json->>'segment_id', '')), '') = v_segment_id_text THEN 2
              WHEN v_segment_key_text IS NOT NULL AND NULLIF(BTRIM(COALESCE(segment_choice.segment_json->>'segment_key', segment_choice.segment_json->>'segment_id', '')), '') = v_segment_key_text THEN 3
              WHEN v_segment_stable_key_text IS NOT NULL AND NULLIF(BTRIM(COALESCE(segment_choice.segment_json->>'segment_stable_key', segment_choice.segment_json->>'segment_id', segment_choice.segment_json->>'segment_key', '')), '') = v_segment_stable_key_text THEN 4
              ELSE 9
            END
          LIMIT 1;

          IF COALESCE(v_segment_match_found, false)
             AND v_segment_match_date_text IS NOT NULL
             AND v_segment_match_date_text ~ '^\d{4}-\d{2}-\d{2}$' THEN
            v_resolved_key_type := 'TS_DAY';
            v_resolved_key_value := v_segment_match_date_text;
            v_resolved_source := 'PRE_DRAFT_LIVE_TIMESHEET_SEGMENT_DATE';
          ELSIF COALESCE(v_segment_match_found, false) THEN
            v_resolved_key_type := 'TS_TOTAL';
            v_resolved_key_value := 'TOTAL';
            v_resolved_source := 'PRE_DRAFT_LIVE_TIMESHEET_SEGMENT_TOTAL_FALLBACK';
          END IF;
        END IF;
      END IF;

      IF v_resolved_key_type IS NULL AND v_timesheet_id IS NOT NULL THEN
        SELECT COALESCE(timesheet_row.worked_start_iso::date::text, timesheet_row.scheduled_start_iso::date::text)
        INTO v_timesheet_start_date_text
        FROM public.timesheets AS timesheet_row
        WHERE timesheet_row.timesheet_id = v_timesheet_id
        LIMIT 1;

        IF v_timesheet_start_date_text IS NOT NULL THEN
          v_resolved_key_type := 'TS_DAY';
          v_resolved_key_value := v_timesheet_start_date_text;
          v_resolved_source := 'PRE_DRAFT_LIVE_TIMESHEET_START_DATE';
        END IF;
      END IF;

      IF v_resolved_key_type IS NULL THEN
        v_resolved_key_type := 'TS_TOTAL';
        v_resolved_key_value := 'TOTAL';
        v_resolved_source := 'PRE_DRAFT_LIVE_TOTAL_FALLBACK';
      END IF;

    ELSIF v_item_type = 'ADJUSTMENT_DELTA' AND v_adjustment_id_text IS NOT NULL THEN
      v_resolved_key_type := 'ADJUSTMENT_CODE';
      v_resolved_key_value := v_adjustment_id_text;
      v_resolved_source := 'PRE_DRAFT_LIVE_ADJUSTMENT_KEY';

    ELSIF v_item_type = 'EXPENSE_DELTA' AND v_additional_code_text IS NOT NULL THEN
      v_resolved_key_type := 'ADDITIONAL_CODE';
      v_resolved_key_value := UPPER(v_additional_code_text);
      v_resolved_source := 'PRE_DRAFT_LIVE_ADDITIONAL_CODE';

    ELSIF v_item_type IN ('EXPENSE_DELTA', 'MILEAGE_DELTA') AND v_expense_code_text IS NOT NULL THEN
      v_resolved_key_type := 'EXPENSE_CODE';
      v_resolved_key_value := UPPER(v_expense_code_text);
      v_resolved_source := 'PRE_DRAFT_LIVE_EXPENSE_CODE';
    END IF;
  END IF;

  SELECT
    key_check.ok,
    key_check.key_type,
    key_check.key_value,
    key_check.failure_reason
  INTO
    v_assert_ok,
    v_assert_key_type,
    v_assert_key_value,
    v_assert_failure_reason
  FROM public._pay_policy_x_assert_economic_key(
    p_timesheet_id => v_timesheet_id,
    p_key_type => v_resolved_key_type,
    p_key_value => v_resolved_key_value,
    p_context => 'PRE_DRAFT_RESOLVE_FINAL',
    p_authority_scope => 'PRE_DRAFT',
    p_resolution_source => COALESCE(v_resolved_source, 'PRE_DRAFT_KEY_RESOLUTION_FAILED'),
    p_required => true,
    p_source_json => v_source_json
  ) AS key_check;

  IF COALESCE(v_assert_ok, false) THEN
    timesheet_id := v_timesheet_id;
    key_type := v_assert_key_type;
    key_value := v_assert_key_value;
    key_resolution_source := v_resolved_source;
    key_resolution_failure_reason := NULL::text;
  ELSE
    timesheet_id := v_timesheet_id;
    key_type := NULL::text;
    key_value := NULL::text;
    key_resolution_source := 'KEY_RESOLUTION_FAILED';
    key_resolution_failure_reason := COALESCE(v_failure_reason, v_assert_failure_reason, 'PRE_DRAFT_KEY_RESOLUTION_FAILED');
  END IF;

  RETURN NEXT;
END;
$function$;

CREATE OR REPLACE FUNCTION public.timesheet_financial_retention_mark_v1(
  p_timesheet_ids uuid[]
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_requested_count integer := 0;
  v_locked_count integer := 0;
  v_inserted_count integer := 0;
BEGIN
  SELECT COALESCE(array_agg(DISTINCT requested.timesheet_id ORDER BY requested.timesheet_id), ARRAY[]::uuid[])
    INTO v_timesheet_ids
  FROM unnest(COALESCE(p_timesheet_ids, ARRAY[]::uuid[])) AS requested(timesheet_id)
  WHERE requested.timesheet_id IS NOT NULL;

  v_requested_count := COALESCE(array_length(v_timesheet_ids, 1), 0);

  IF v_requested_count = 0 THEN
    RAISE EXCEPTION USING
      MESSAGE = 'TIMESHEET_IDS_REQUIRED',
      DETAIL = jsonb_build_object('function', 'timesheet_financial_retention_mark_v1')::text;
  END IF;

  IF v_requested_count > 1000 THEN
    RAISE EXCEPTION USING
      MESSAGE = 'RETENTION_MARK_SCOPE_TOO_LARGE',
      DETAIL = jsonb_build_object('maximum', 1000, 'actual', v_requested_count)::text;
  END IF;

  SELECT COUNT(*)::integer
    INTO v_locked_count
  FROM (
    SELECT t.timesheet_id
    FROM public.timesheets AS t
    JOIN unnest(v_timesheet_ids) AS requested(timesheet_id)
      ON requested.timesheet_id = t.timesheet_id
    ORDER BY t.timesheet_id
    FOR KEY SHARE OF t
  ) AS locked_timesheets;

  IF v_locked_count IS DISTINCT FROM v_requested_count THEN
    RAISE EXCEPTION USING
      MESSAGE = 'RETENTION_MARK_TIMESHEET_NOT_FOUND',
      DETAIL = jsonb_build_object(
        'requested_count', v_requested_count,
        'locked_count', v_locked_count,
        'timesheet_ids', to_jsonb(v_timesheet_ids)
      )::text;
  END IF;

  INSERT INTO public.timesheet_financial_retention(timesheet_id)
  SELECT requested.timesheet_id
  FROM unnest(v_timesheet_ids) AS requested(timesheet_id)
  ORDER BY requested.timesheet_id
  ON CONFLICT (timesheet_id) DO NOTHING;

  GET DIAGNOSTICS v_inserted_count = ROW_COUNT;

  RETURN jsonb_build_object(
    'ok', true,
    'requested_count', v_requested_count,
    'locked_count', v_locked_count,
    'inserted_count', v_inserted_count,
    'already_marked_count', v_requested_count - v_inserted_count
  );
END;
$function$;

create or replace function public._ctms_correction_policy_envelope_read_v1(
  p_timesheet_id uuid
)
returns jsonb
language plpgsql
stable
security definer
set search_path to 'public', 'extensions', 'pg_temp'
set plpgsql_check.mode to 'disabled'
as $function$
declare
  v_class jsonb;
  v_envelope jsonb;
  v_stored_fingerprint text;
  v_recomputed_fingerprint text;
begin
  v_class := public._ctms_import_correction_classify_v1(p_timesheet_id);

  if coalesce((v_class ->> 'is_import_authoritative_correction')::boolean, false) is not true then
    return null;
  end if;

  select coalesce(
    ts.candidate_hint_text -> 'correction_financials_policy_envelope',
    tf.policy_snapshot_json -> 'correction_financials_policy_envelope',
    tf.rate_source_refs_json -> 'correction_financials_policy_envelope'
  )
  into v_envelope
  from public.timesheets ts
  left join public.timesheets_financials tf
    on tf.timesheet_id = ts.timesheet_id
   and tf.is_current = true
  where ts.timesheet_id = p_timesheet_id;

  if jsonb_typeof(v_envelope) <> 'object' then
    raise exception 'IMPORT_CORRECTION_POLICY_ENVELOPE_MISSING'
      using errcode = 'P0001',
            detail = jsonb_build_object(
              'code', 'IMPORT_CORRECTION_POLICY_ENVELOPE_MISSING',
              'timesheet_id', p_timesheet_id
            )::text;
  end if;

  v_stored_fingerprint := nullif(btrim(v_envelope ->> 'envelope_fingerprint'), '');
  v_recomputed_fingerprint := encode(
    extensions.digest(
      convert_to((v_envelope - 'envelope_fingerprint')::text, 'UTF8'),
      'sha256'::text
    ),
    'hex'
  );

  if v_stored_fingerprint is null
     or v_stored_fingerprint is distinct from v_recomputed_fingerprint then
    raise exception 'IMPORT_CORRECTION_POLICY_ENVELOPE_FINGERPRINT_INVALID'
      using errcode = 'P0001',
            detail = jsonb_build_object(
              'code', 'IMPORT_CORRECTION_POLICY_ENVELOPE_FINGERPRINT_INVALID',
              'timesheet_id', p_timesheet_id,
              'stored_fingerprint', v_stored_fingerprint,
              'recomputed_fingerprint', v_recomputed_fingerprint
            )::text;
  end if;

  return v_envelope;
end;
$function$;

create or replace function private._candidate_expense_component_values_v1(
  p_workflow_id uuid
)
returns table(expense_category text,amount numeric,mileage_units numeric)
language plpgsql
stable
security definer
set search_path = pg_catalog, public, private, pg_temp
as $function$
declare
  v_submission jsonb;
  v_claim jsonb;
begin
  select workflow.immutable_submission_json into v_submission
  from public.candidate_submission_workflows workflow where workflow.id=p_workflow_id;
  if not found then raise exception 'CANDIDATE_WORKFLOW_NOT_FOUND' using errcode='P0002'; end if;
  v_claim:=coalesce(
    v_submission#>'{expense_submission,canonical_tsfin_snapshot}',
    v_submission->'expense_submission',
    v_submission#>'{expense_claim,canonical_tsfin_snapshot}',
    v_submission->'expense_claim',
    v_submission->'canonical_tsfin_snapshot',
    '{}'::jsonb
  );
  return query
  select category.category_name,
    case category.category_name
      when 'MILEAGE' then private._candidate_expense_number_v1(v_claim,'mileage_pay_ex_vat')
      when 'TRAVEL' then private._candidate_expense_number_v1(v_claim,'travel_pay_ex_vat')
      when 'ACCOMMODATION' then private._candidate_expense_number_v1(v_claim,'accommodation_pay_ex_vat')
      else private._candidate_expense_number_v1(v_claim,'other_pay_ex_vat')
    end,
    case when category.category_name='MILEAGE'
      then private._candidate_expense_number_v1(v_claim,'mileage_units') else 0 end
  from (values ('MILEAGE'),('TRAVEL'),('ACCOMMODATION'),('OTHER')) category(category_name);
end;
$function$;

CREATE OR REPLACE FUNCTION private.bpay_expense_identity_gate_v1(p_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
DECLARE booking text; seen boolean; recheck text; locked boolean;
BEGIN
 IF p_id IS NULL THEN RETURN; END IF;
 SELECT t.booking_id INTO booking FROM public.timesheets t WHERE t.timesheet_id=p_id;
 seen:=FOUND;
 IF seen AND btrim(booking)<>'' THEN
  PERFORM private.bpay_source_family_try_lock_v1(booking);
 ELSIF NOT pg_try_advisory_xact_lock(hashtext('BPAY_EXPENSE_IDENTITY_V1'),hashtext(p_id::text)) THEN
  RAISE EXCEPTION 'BPAY_SOURCE_FAMILY_BUSY' USING ERRCODE='55P03';
 END IF;
 -- S-02: ordinary Timesheet writers no longer take the family/identity lock, so the claim/lineage writer
 -- share-locks the row itself (prompt BUSY if an ordinary writer holds it) and re-reads under that lock.
 locked:=private.bpay_source_row_gate_v1(p_id,false);
 SELECT t.booking_id INTO recheck FROM public.timesheets t WHERE t.timesheet_id=p_id;
 IF FOUND IS DISTINCT FROM seen OR recheck IS DISTINCT FROM booking THEN
  RAISE EXCEPTION 'BPAY_SOURCE_FAMILY_BUSY' USING ERRCODE='55P03';
 END IF;
END; $function$;

CREATE OR REPLACE FUNCTION private.bpay_clock_retire_family_v1(p_family uuid) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,private,pg_temp AS $fn$
BEGIN
-- Serialize last-reference checks. Without this, two concurrent removals can
-- each see the other's old reference and both leave an orphan directory row.
PERFORM 1 FROM private.bpay_clock_families_v1 WHERE id=p_family FOR UPDATE;
IF NOT FOUND THEN RETURN; END IF;
DELETE FROM private.bpay_clock_families_v1 f WHERE f.id=p_family
 AND NOT EXISTS(SELECT 1 FROM private.bpay_clock_rows_v1 c WHERE c.family_id=f.id)
 AND NOT EXISTS(SELECT 1 FROM public.timesheet_payment_overrides o WHERE o.bpay_clock_family_id_v1=f.id);
END;
$fn$;

create or replace function private.weekly_source_rule_qualification_scope_assert_v1(p_auth jsonb,p_actor_id uuid,p_initial_open boolean default false)
returns jsonb language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare auth jsonb; c public.weekly_source_cycles%rowtype; g public.weekly_source_groups%rowtype;
  a public.weekly_source_group_rule_assignments%rowtype; v public.weekly_source_rule_set_versions%rowtype;
  manifest jsonb; item jsonb; clients uuid[]; actual jsonb; lease jsonb; n integer; today date;
begin
  auth:=private.weekly_source_rule_qualification_authorization_v1((p_auth->>'source_cycle_id')::uuid,p_actor_id,p_auth->>'purpose');
  if auth is distinct from p_auth then raise exception 'WEEKLY_SOURCE_RULE_QUALIFICATION_AUTHORIZATION_CHANGED' using errcode='40001'; end if;
  perform private._weekly_source_settings_require_admin_v1((auth->>'setup_actor_user_id')::uuid);
  select * into strict c from public.weekly_source_cycles where id=(auth->>'source_cycle_id')::uuid;
  select * into strict g from public.weekly_source_groups where id=c.source_group_id and active and source_family='ROSTER' and environment='TEST';
  perform private._weekly_source_settings_deployment_v1(g.agency_id,g.environment);
  perform private.weekly_source_office_authority_v1(p_actor_id,'APPROVE_PROTECTED_PAY',g.id,null,c.finalisation_week_ending);
  if not private.weekly_source_pay_actor_allowed_v1(p_actor_id) then raise exception 'WEEKLY_SOURCE_RULE_QUALIFICATION_ACTOR_REFUSED' using errcode='42501'; end if;
  select * into strict a from public.weekly_source_group_rule_assignments where id=(auth->>'assignment_id')::uuid
    and source_group_id=g.id and not feature_enabled and rule_set_version_id=(auth->>'rule_set_version_id')::uuid
    and c.finalisation_week_ending between effective_from_week_ending and coalesce(effective_to_week_ending,'infinity'::date);
  select version.* into strict v from public.weekly_source_rule_set_versions version
    join public.weekly_source_rule_sets rules on rules.id=version.rule_set_id and rules.agency_id=g.agency_id and rules.environment=g.environment
    where version.id=a.rule_set_version_id;
  today:=(clock_timestamp() at time zone 'Europe/London')::date;
  if (g.id::text,g.agency_id::text,c.finalisation_week_ending::text,a.version::text) is distinct from
    (auth->>'source_group_id',auth->>'agency_id',auth->>'week_ending',auth->>'assignment_version')
    or encode(private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_OFF_RULE_ASSIGNMENT_V1',to_jsonb(a)),'hex') is distinct from auth->>'assignment_sha256'
    or v.values_sha256 is distinct from auth->>'rule_values_sha256'
    or v.values_json->>'invoice_sender' is distinct from 'CLIENT_SELF_BILL'
    or (auth->>'purpose'='AUTOMATIC_JOURNEY' and (v.values_json->>'equal_protected_hours' is distinct from 'CLEAR_AUTOMATICALLY'
      or (select automatic_reconcile_actor_user_id from public.weekly_source_global_settings where singleton) is distinct from p_actor_id))
    or exists(select 1 from public.weekly_source_group_rule_assignments enabled where enabled.source_group_id=g.id and enabled.feature_enabled)
    or private.weekly_source_bulk_producer_ready_v1(c.id) or private.weekly_source_automatic_reconcile_producer_ready_v1(c.id) then
    raise exception 'WEEKLY_SOURCE_RULE_QUALIFICATION_SCOPE_CHANGED' using errcode='40001'; end if;
  manifest:=auth->'fixture_manifest';
  if not private.weekly_source_qualification_closed_object_v1(manifest,array['group_code','client_ids','contract_ids','candidate_ids','client_refs','candidate_refs'])
    or g.code is distinct from manifest->>'group_code' or g.code !~ '^WSQ_TEST_[A-Z0-9_]+$'
    or jsonb_typeof(manifest->'client_ids') is distinct from 'array' or jsonb_array_length(manifest->'client_ids') not between 1 and 100 then
    raise exception 'WEEKLY_SOURCE_RULE_QUALIFICATION_FIXTURE_REFUSED' using errcode='42501'; end if;
  select array_agg(value::uuid order by value::uuid) into clients from jsonb_array_elements_text(manifest->'client_ids') value;
  if to_jsonb(clients) is distinct from manifest->'client_ids'
    or cardinality(clients)<>(select count(distinct value) from unnest(clients) value)
    or exists(select 1 from unnest(clients) client where not exists(select 1 from public.weekly_source_group_clients member
      where member.source_group_id=g.id and member.client_id=client and c.finalisation_week_ending between member.valid_from and coalesce(member.valid_to,'infinity'::date))) then
    raise exception 'WEEKLY_SOURCE_RULE_QUALIFICATION_FIXTURE_REFUSED' using errcode='42501'; end if;
  for item in select value from jsonb_array_elements(manifest->'client_refs') value loop
    if not private.weekly_source_qualification_closed_object_v1(item,array['client_id','cli_ref']) or item->>'cli_ref' !~ '^CLI-913013[0-9]{2}$'
      or not exists(select 1 from public.clients client where client.id=(item->>'client_id')::uuid and client.id=any(clients) and client.cli_ref=item->>'cli_ref') then
      raise exception 'WEEKLY_SOURCE_RULE_QUALIFICATION_FIXTURE_REFUSED' using errcode='42501'; end if;
  end loop;
  for item in select value from jsonb_array_elements(manifest->'candidate_refs') value loop
    if not private.weekly_source_qualification_closed_object_v1(item,array['candidate_id','tms_ref']) or item->>'tms_ref' !~ '^CCR-913013[0-9]{2}$'
      or not exists(select 1 from public.candidates candidate where candidate.id=(item->>'candidate_id')::uuid and candidate.tms_ref=item->>'tms_ref') then
      raise exception 'WEEKLY_SOURCE_RULE_QUALIFICATION_FIXTURE_REFUSED' using errcode='42501'; end if;
  end loop;
  select coalesce(jsonb_agg(contract.id order by contract.id),'[]'::jsonb) into actual from public.contracts contract
    where contract.client_id=any(clients) and daterange(contract.start_date,contract.end_date,'[]')
      && daterange(c.finalisation_week_ending-6,c.finalisation_week_ending,'[]');
  if actual is distinct from manifest->'contract_ids' or (select coalesce(jsonb_agg(distinct contract.candidate_id order by contract.candidate_id),'[]'::jsonb)
    from public.contracts contract where contract.id in(select value::uuid from jsonb_array_elements_text(manifest->'contract_ids') value)) is distinct from manifest->'candidate_ids'
    or jsonb_array_length(manifest->'client_refs')<>cardinality(clients)
    or (select coalesce(jsonb_agg(value->'client_id' order by value->'client_id'),'[]'::jsonb) from jsonb_array_elements(manifest->'client_refs') value) is distinct from manifest->'client_ids'
    or (select coalesce(jsonb_agg(value->'candidate_id' order by value->'candidate_id'),'[]'::jsonb) from jsonb_array_elements(manifest->'candidate_refs') value) is distinct from manifest->'candidate_ids' then
    raise exception 'WEEKLY_SOURCE_RULE_QUALIFICATION_FIXTURE_REFUSED' using errcode='42501'; end if;
  perform private._weekly_source_rule_group_context_v1(g.id,a.effective_from_week_ending,a.effective_to_week_ending,v.values_json,true);
  -- HISTORICAL_FIXTURE_OPEN_BOUNDARY: every use rechecks the real native
  -- assignment audit; only the first source OPEN additionally requires zero
  -- prior uploads. No historical operational enablement is inferred.
  if a.effective_from_week_ending<today then
    perform private.weekly_source_historical_fixture_setup_assert_v1(auth,p_initial_open and auth->>'purpose'='SOURCE_FIXTURE_SETUP');
  end if;
  if p_initial_open then
    if auth->>'purpose'='SOURCE_FIXTURE_SETUP' and (c.finalisation_week_ending<>a.effective_from_week_ending
      or c.current_final_revision_id is not null or c.state in ('FINALISING','FINALISED','CORRECTION_IN_PROGRESS')
      or exists(select 1 from public.weekly_source_final_revisions final where final.source_cycle_id=c.id)
      or auth->'original_source_cas' is distinct from 'null'::jsonb) then
      raise exception 'WEEKLY_SOURCE_RULE_QUALIFICATION_FUTURE_UNFINALISED_REQUIRED' using errcode='55000'; end if;
  else
    select count(*),jsonb_agg(audit.after_json)->0 into n,lease from public.audit_events audit
      where audit.object_type='weekly_source_off_rule_test_journey' and audit.object_id_text=auth->>'scope_id'
        and audit.action='WEEKLY_SOURCE_OFF_RULE_TEST_OPENED' and audit.event_sequence_is_authoritative
        and not exists(select 1 from public.audit_events terminal where terminal.object_type=audit.object_type and terminal.object_id_text=audit.object_id_text
          and terminal.event_sequence_is_authoritative and terminal.action in ('WEEKLY_SOURCE_OFF_RULE_TEST_CLOSED','WEEKLY_SOURCE_OFF_RULE_TEST_REVOKED'));
    if n<>1 or lease->>'authorization_sha256' is distinct from auth->>'authorization_sha256'
      or lease->>'scope_sha256' is distinct from encode(private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_OFF_RULE_TEST_SCOPE_V1',lease-'scope_sha256'),'hex') then
      raise exception 'WEEKLY_SOURCE_RULE_QUALIFICATION_SCOPE_UNAVAILABLE' using errcode='55000'; end if;
  end if;
  if auth->>'purpose'='AUTOMATIC_JOURNEY' then
    if not p_initial_open then
      -- ORIGINAL_CAPTURED_PHYSICAL_ROOTS: recheck the OPEN union of Source
      -- pay roots and signed evidence roots, including genuine physical NULL
      -- Client. Never recollect only surviving OPEN incidents after a round.
      if lease#>>'{original_census,schema_version}' is distinct from 'WEEKLY_SOURCE_QUALIFICATION_CENSUS_V1'
        or lease#>>'{original_census,source_cycle_id}' is distinct from c.id::text
        or lease#>>'{original_census,source_group_id}' is distinct from g.id::text
        or lease#>>'{original_census,week_ending}' is distinct from c.finalisation_week_ending::text
        or lease#>'{original_census,original_client_ids}' is distinct from auth#>'{fixture_manifest,client_ids}'
        or lease#>>'{original_census,census_sha256}' is distinct from encode(private.weekly_source_sha256_jsonb_v1(
          'WEEKLY_SOURCE_QUALIFICATION_CENSUS_V1',lease->'original_census'-'census_sha256'),'hex') then
        raise exception 'WEEKLY_SOURCE_RULE_QUALIFICATION_ORIGINAL_ROOT_CHANGED' using errcode='40001'; end if;
      for item in select value from jsonb_array_elements(lease#>'{original_census,original_root_identities}') value loop
        if not private.weekly_source_qualification_closed_object_v1(item,array['timesheet_id','booking_id','contract_id','candidate_id','client_id']) then
          raise exception 'WEEKLY_SOURCE_RULE_QUALIFICATION_ORIGINAL_ROOT_CHANGED' using errcode='40001'; end if;
        select jsonb_build_object('timesheet_id',sheet.timesheet_id,'booking_id',sheet.booking_id,'contract_id',contract.id,
          'candidate_id',contract.candidate_id,'client_id',sheet.client_id) into actual
          from public.timesheets sheet join public.contracts contract on contract.id=sheet.contract_id
          where sheet.timesheet_id=(item->>'timesheet_id')::uuid and (sheet.client_id is null or sheet.client_id=contract.client_id);
        if actual is distinct from item then
          raise exception 'WEEKLY_SOURCE_RULE_QUALIFICATION_ORIGINAL_ROOT_CHANGED' using errcode='40001'; end if;
      end loop;
    end if;
    if cardinality(clients)<>1 or auth->'original_source_cas' is null or auth->'original_source_cas'='null'::jsonb
      or private.weekly_source_bulk_source_cas_v1(c.id,clients) is distinct from auth->'original_source_cas'
      or not exists(select 1 from public.weekly_source_final_revisions final where final.id=c.current_final_revision_id
        and final.source_cycle_id=c.id and final.state='CURRENT' and final.rule_set_version_id=v.id) then
      raise exception 'WEEKLY_SOURCE_RULE_QUALIFICATION_ORIGINAL_SOURCE_CHANGED' using errcode='40001'; end if;
  end if;
  return auth;
exception when no_data_found or too_many_rows or invalid_text_representation or datetime_field_overflow then
  raise exception 'WEEKLY_SOURCE_RULE_QUALIFICATION_SCOPE_UNAVAILABLE' using errcode='55000';
end;
$function$;

create or replace function private._candidate_manager_authoriser_domain_array_v2(p_value jsonb)
returns jsonb
language plpgsql
immutable
parallel safe
set search_path=''
as $function$
declare
  v_result jsonb;
  v_count integer;
begin
  if p_value is not null and pg_catalog.jsonb_typeof(p_value)<>'array' then
    raise exception using errcode='22023',message='CANDIDATE_MANAGER_APPROVED_DOMAINS_INVALID';
  end if;
  select pg_catalog.count(*),coalesce(pg_catalog.jsonb_agg(v.domain order by v.domain),'[]'::jsonb)
    into v_count,v_result
  from (
    select distinct private._candidate_normalize_domain_v1(e.value) as domain
    from pg_catalog.jsonb_array_elements_text(coalesce(p_value,'[]'::jsonb)) e
  ) v
  where v.domain<>'';
  if v_count>50 or exists (
    select 1
    from pg_catalog.jsonb_array_elements_text(v_result) e
    where pg_catalog.char_length(e.value)>253
       or e.value!~'^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?(?:\.[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?)+$'
  ) then
    raise exception using errcode='22023',message='CANDIDATE_MANAGER_APPROVED_DOMAIN_INVALID';
  end if;
  return v_result;
end;
$function$;

create or replace function private._candidate_manager_authoriser_email_array_v2(p_value jsonb)
returns jsonb
language plpgsql
immutable
parallel safe
set search_path=''
as $function$
declare
  v_result jsonb;
  v_count integer;
begin
  if p_value is not null and pg_catalog.jsonb_typeof(p_value)<>'array' then
    raise exception using errcode='22023',message='CANDIDATE_MANAGER_APPROVED_EMAILS_INVALID';
  end if;
  select pg_catalog.count(*),coalesce(pg_catalog.jsonb_agg(v.email order by v.email),'[]'::jsonb)
    into v_count,v_result
  from (
    select distinct private._candidate_normalize_email(e.value) as email
    from pg_catalog.jsonb_array_elements_text(coalesce(p_value,'[]'::jsonb)) e
  ) v
  where v.email<>'';
  if v_count>50 or exists (
    select 1
    from pg_catalog.jsonb_array_elements_text(v_result) e
    where pg_catalog.char_length(e.value)>320
       or e.value!~'^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'
  ) then
    raise exception using errcode='22023',message='CANDIDATE_MANAGER_APPROVED_EMAIL_INVALID';
  end if;
  return v_result;
end;
$function$;

create or replace function private.weekly_source_invoice_rounding_receipt_set_v1(
  p_client_manifest_id uuid,p_receipt_set jsonb
) returns jsonb language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare manifest public.weekly_source_client_manifests%rowtype; rounding public.weekly_source_billing_movements%rowtype;
  member record; item jsonb; receipt_id uuid; money jsonb; rules jsonb; facts jsonb;
  witness jsonb:='[]'::jsonb; net numeric:=0; raw_vat numeric:=0; admitted_vat numeric:=0;
  target bigint; raw_target bigint; actual_count integer:=0; supplied_count integer; rate_count integer; rate numeric;
begin
  select * into strict manifest from public.weekly_source_client_manifests where id=p_client_manifest_id;
  rules:=private.weekly_source_frozen_rule_values_v1(manifest.final_revision_id);
  if rules is null or rules->>'invoice_sender' is distinct from 'CLIENT_SELF_BILL'
    or rules->>'invoice_vat_method'='SUM_OF_LINES' then return null; end if;
  if jsonb_typeof(p_receipt_set) is distinct from 'array' then
    raise exception 'WEEKLY_SOURCE_ROUNDING_RECEIPT_SET_INVALID' using errcode='22023'; end if;
  supplied_count:=jsonb_array_length(p_receipt_set);
  if exists(select 1 from jsonb_array_elements(p_receipt_set) supplied where jsonb_typeof(supplied)<>'object'
      or not(supplied ?& array['billing_movement_id','invoice_hold_release_id'])
      or jsonb_typeof(supplied->'billing_movement_id') is distinct from 'string'
      or not pg_input_is_valid(coalesce(supplied->>'billing_movement_id',''),'uuid')
      or (supplied->'invoice_hold_release_id'<>'null'::jsonb and (jsonb_typeof(supplied->'invoice_hold_release_id') is distinct from 'string'
        or not pg_input_is_valid(coalesce(supplied->>'invoice_hold_release_id',''),'uuid')))
      or exists(select 1 from jsonb_object_keys(supplied) key where key not in ('billing_movement_id','invoice_hold_release_id')))
    or (select count(distinct supplied->>'billing_movement_id') from jsonb_array_elements(p_receipt_set) supplied)<>supplied_count then
    raise exception 'WEEKLY_SOURCE_ROUNDING_RECEIPT_SET_INVALID' using errcode='22023'; end if;
  select m.* into rounding from public.weekly_source_manifest_movements mm
    join public.weekly_source_billing_movements m on m.id=mm.billing_movement_id
    where mm.client_manifest_id=manifest.id and m.source_line_kind='INVOICE_VAT_ROUNDING';

  for member in select m.*,mm.movement_hash from public.weekly_source_manifest_movements mm
    join public.weekly_source_billing_movements m on m.id=mm.billing_movement_id
    where mm.client_manifest_id=manifest.id and m.source_line_kind<>'INVOICE_VAT_ROUNDING' order by m.id
  loop
    actual_count:=actual_count+1;
    if member.final_revision_id<>manifest.final_revision_id or member.finalisation_cycle_id<>manifest.source_cycle_id
      or member.actual_client_id<>manifest.client_id or member.movement_hash<>member.movement_economic_hash
      or private.weekly_source_invoice_movement_window_id_v1(member.id)<>coalesce(manifest.invoice_window_cycle_id,manifest.source_cycle_id) then
      raise exception 'WEEKLY_SOURCE_ROUNDING_MANIFEST_INVALID' using errcode='55000'; end if;
    select supplied into item from jsonb_array_elements(p_receipt_set) supplied where supplied->>'billing_movement_id'=member.id::text;
    if not found then raise exception 'WEEKLY_SOURCE_ROUNDING_RECEIPT_SET_CENSUS_INVALID' using errcode='55000'; end if;
    receipt_id:=nullif(item->>'invoice_hold_release_id','')::uuid;
    if receipt_id is null then
      -- Explicit original money: never use the implicit CURRENT-presentation
      -- branch of movement_money_v1 for a null frozen receipt-map entry.
      money:=jsonb_build_object('net_pence',member.invoice_presentation_charge_pence,
        'vat_pence',(member.vat_amount*100)::bigint,'gross_pence',(member.total_inc_vat*100)::bigint,'release_authority',null);
    else money:=private.weekly_source_invoice_movement_money_v1(member.id,receipt_id); end if;
    if (money->>'net_pence')::bigint<>member.invoice_presentation_charge_pence
      or (money->>'gross_pence')::bigint<>(money->>'net_pence')::bigint+(money->>'vat_pence')::bigint then
      raise exception 'WEEKLY_SOURCE_ROUNDING_RELEASE_MONEY_INVALID' using errcode='55000'; end if;
    net:=net+member.invoice_presentation_charge_pence; raw_vat:=raw_vat+member.vat_amount*100;
    admitted_vat:=admitted_vat+(money->>'vat_pence')::numeric;
    witness:=witness||jsonb_build_array(jsonb_build_object('billing_movement_id',member.id,
      'movement_hash',encode(member.movement_economic_hash,'hex'),'invoice_hold_release_id',receipt_id,
      'release_authority',money->'release_authority','net_pence',member.invoice_presentation_charge_pence,
      'original_vat_pence',(member.vat_amount*100)::bigint,'admitted_vat_pence',(money->>'vat_pence')::bigint));
  end loop;
  if actual_count<>supplied_count then raise exception 'WEEKLY_SOURCE_ROUNDING_RECEIPT_SET_CENSUS_INVALID' using errcode='55000'; end if;
  select min(m.vat_rate_pct),count(distinct m.vat_rate_pct) into rate,rate_count
    from public.weekly_source_manifest_movements mm join public.weekly_source_billing_movements m on m.id=mm.billing_movement_id
    where mm.client_manifest_id=manifest.id and m.source_line_kind<>'INVOICE_VAT_ROUNDING';
  if rate_count<>1 then raise exception 'WEEKLY_SOURCE_VAT_ROUNDING_RATE_AMBIGUOUS' using errcode='55000'; end if;
  raw_target:=private.weekly_source_invoice_vat_target_pence_v1(net,raw_vat,rules->>'invoice_vat_method',rate);
  target:=private.weekly_source_invoice_vat_target_pence_v1(net,admitted_vat,rules->>'invoice_vat_method',rate);
  if rounding.id is null then
    if target is null or raw_target<>raw_vat or target<>admitted_vat
      or exists(select 1 from jsonb_array_elements(witness) w where (w->>'original_vat_pence')::bigint<>(w->>'admitted_vat_pence')::bigint) then
      raise exception 'WEEKLY_SOURCE_FROZEN_ROUNDING_AUTHORITY_REQUIRED' using errcode='55000'; end if;
    return null;
  end if;
  if target is null or (raw_target-raw_vat)::bigint<>(rounding.vat_amount*100)::bigint then
    raise exception 'WEEKLY_SOURCE_FROZEN_ROUNDING_AMOUNT_INVALID' using errcode='55000'; end if;
  facts:=jsonb_build_object('contract','WEEKLY_SOURCE_INVOICE_ROUNDING_AUTHORITY_V1','client_manifest_id',manifest.id,
    'manifest_hash',encode(manifest.manifest_hash,'hex'),'final_revision_id',manifest.final_revision_id,
    'actual_client_id',manifest.client_id,'invoice_window_cycle_id',coalesce(manifest.invoice_window_cycle_id,manifest.source_cycle_id),
    'rounding_movement_id',rounding.id,'rounding_movement_hash',encode(rounding.movement_economic_hash,'hex'),
    'frozen_rule_set_version_id',(select r.rule_set_version_id from public.weekly_source_final_revisions r where r.id=manifest.final_revision_id),
    'frozen_rule_values_sha256',(select v.values_sha256 from public.weekly_source_final_revisions r
      join public.weekly_source_rule_set_versions v on v.id=r.rule_set_version_id where r.id=manifest.final_revision_id),
    'invoice_vat_method',rules->>'invoice_vat_method','vat_rate_pct',rate,'membership_net_pence',net,
    'original_rounding_vat_pence',(rounding.vat_amount*100)::bigint,'admitted_line_vat_pence',admitted_vat,
    'target_vat_pence',target,'admitted_rounding_vat_pence',target-admitted_vat,'member_witnesses',witness,
    'suppress_visible_rounding_line',target-admitted_vat=0);
  return facts||jsonb_build_object('authority_sha256',encode(private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_INVOICE_ROUNDING_AUTHORITY_V1',facts),'hex'));
end;
$function$;

CREATE OR REPLACE FUNCTION public._pay_policy_x_assert_economic_key(
  p_timesheet_id uuid,
  p_key_type text,
  p_key_value text,
  p_context text DEFAULT NULL::text,
  p_authority_scope text DEFAULT NULL::text,
  p_resolution_source text DEFAULT NULL::text,
  p_required boolean DEFAULT true,
  p_source_json jsonb DEFAULT '{}'::jsonb
)
RETURNS TABLE(
  ok boolean,
  timesheet_id uuid,
  key_type text,
  key_value text,
  failure_reason text,
  failure_detail text,
  resolution_source text
)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_timesheet_id uuid := p_timesheet_id;
  v_key_type text := UPPER(NULLIF(BTRIM(COALESCE(p_key_type, '')), ''));
  v_key_value text := NULLIF(BTRIM(COALESCE(p_key_value, '')), '');
  v_context text := UPPER(REPLACE(NULLIF(BTRIM(COALESCE(p_context, '')), ''), '-', '_'));
  v_authority_scope text := UPPER(REPLACE(NULLIF(BTRIM(COALESCE(p_authority_scope, '')), ''), '-', '_'));
  v_resolution_source text := UPPER(REPLACE(NULLIF(BTRIM(COALESCE(p_resolution_source, '')), ''), '-', '_'));
  v_required boolean := COALESCE(p_required, true);
  v_source_json jsonb := CASE
    WHEN jsonb_typeof(COALESCE(p_source_json, '{}'::jsonb)) = 'object' THEN COALESCE(p_source_json, '{}'::jsonb)
    ELSE '{}'::jsonb
  END;
  v_failure_reason text := NULL::text;
  v_failure_detail text := NULL::text;
  v_date_text text := NULL::text;
  v_source_live_component_flag text := NULL::text;
  v_source_live_tsfin_flag text := NULL::text;
  v_source_live_truth_flag text := NULL::text;
  v_source_live_segment_flag text := NULL::text;
  v_source_missing_snapshot_flag text := NULL::text;
BEGIN
  v_source_live_component_flag := LOWER(BTRIM(COALESCE(v_source_json->>'live_component_identity_used', '')));
  v_source_live_tsfin_flag := LOWER(BTRIM(COALESCE(v_source_json->>'live_tsfin_used', v_source_json->>'live_tsfin_identity_used', '')));
  v_source_live_truth_flag := LOWER(BTRIM(COALESCE(v_source_json->>'live_truth_used', '')));
  v_source_live_segment_flag := LOWER(BTRIM(COALESCE(v_source_json->>'live_segment_identity_used', '')));
  v_source_missing_snapshot_flag := LOWER(BTRIM(COALESCE(v_source_json->>'missing_deterministic_post_draft_snapshot', v_source_json->>'missing_frozen_snapshot', '')));

  IF v_authority_scope = 'POST_DRAFT'
     AND (
       v_resolution_source = 'LIVE'
       OR v_resolution_source LIKE 'LIVE_%'
       OR v_resolution_source LIKE '%_LIVE'
       OR v_resolution_source LIKE '%_LIVE_%'
       OR v_resolution_source LIKE '%LIVE_FINANCE%'
       OR v_resolution_source LIKE '%LIVE_COMPONENT%'
       OR v_resolution_source LIKE '%LIVE_TSFIN%'
       OR v_source_live_component_flag IN ('true', 't', 'yes', '1')
       OR v_source_live_tsfin_flag IN ('true', 't', 'yes', '1')
       OR v_source_live_truth_flag IN ('true', 't', 'yes', '1')
       OR v_source_live_segment_flag IN ('true', 't', 'yes', '1')
     ) THEN
    v_failure_reason := 'POST_DRAFT_LIVE_COMPONENT_KEY_REJECTED';
    v_failure_detail := 'Post-draft economic key resolution cannot use live truth, live TSFIN, live segment identity, or live finance-component identity.';

  ELSIF v_timesheet_id IS NULL AND v_required THEN
    v_failure_reason := CASE
      WHEN v_authority_scope = 'POST_DRAFT' THEN 'POST_DRAFT_KEY_RESOLUTION_FAILED'
      ELSE 'TIMESHEET_ID_NOT_RESOLVED'
    END;
    v_failure_detail := 'timesheet_id is required for economic entitlement keyspace resolution.';

  ELSIF v_authority_scope = 'POST_DRAFT'
     AND v_required
     AND (v_key_type IS NULL OR v_key_value IS NULL)
     AND v_source_missing_snapshot_flag IN ('true', 't', 'yes', '1') THEN
    v_failure_reason := 'MISSING_DETERMINISTIC_POST_DRAFT_SNAPSHOT_EVIDENCE';
    v_failure_detail := 'Post-draft batch artefacts did not contain deterministic frozen snapshot evidence for the economic key.';

  ELSIF v_key_type IS NULL AND v_required THEN
    v_failure_reason := CASE
      WHEN v_authority_scope = 'POST_DRAFT' THEN 'POST_DRAFT_KEY_RESOLUTION_FAILED'
      ELSE 'KEY_TYPE_NOT_RESOLVED'
    END;
    v_failure_detail := 'key_type is required and was not resolved.';

  ELSIF v_key_value IS NULL AND v_required THEN
    v_failure_reason := CASE
      WHEN v_authority_scope = 'POST_DRAFT' THEN 'POST_DRAFT_KEY_RESOLUTION_FAILED'
      ELSE 'KEY_VALUE_NOT_RESOLVED'
    END;
    v_failure_detail := 'key_value is required and was not resolved.';

  ELSIF v_key_type IN (
    'SEGMENT_ID',
    'SEGMENT_KEY',
    'SEGMENT_STABLE_KEY',
    'STABLE_SEGMENT_KEY',
    'SEGMENT_STABLE_ID',
    'SEGMENT_HANDLE',
    'UI_SELECTION_ID',
    'SELECTION_ID',
    'SELECTION_HANDLE',
    'SNOOZE_ID',
    'SNOOZE_KEY',
    'PREVIEW_ROW_ID',
    'ROW_ID',
    'LINE_ID',
    'PAY_BATCH_ITEM_ID',
    'FINANCE_COMPONENT_ID',
    'COMPONENT_ID'
  ) THEN
    v_failure_reason := 'IDENTITY_HANDLE_NOT_ECONOMIC_KEY';
    v_failure_detail := 'Identity handles may locate evidence but cannot be used as entitlement buckets.';

  ELSIF v_key_type = 'TS_DAY' THEN
    IF v_key_value IS NULL THEN
      v_failure_reason := CASE
        WHEN v_authority_scope = 'POST_DRAFT' THEN 'POST_DRAFT_KEY_RESOLUTION_FAILED'
        ELSE 'KEY_VALUE_NOT_RESOLVED'
      END;
      v_failure_detail := 'TS_DAY requires a YYYY-MM-DD work-date key_value.';
    ELSIF v_key_value !~ '^\d{4}-\d{2}-\d{2}$' THEN
      v_failure_reason := CASE
        WHEN v_key_value ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          OR v_key_value ~* '^(seg|segment|stable|snooze|row|selection)[:_\-]'
        THEN 'TS_DAY_KEY_VALUE_IDENTITY_HANDLE'
        ELSE 'TS_DAY_KEY_VALUE_NOT_DATE'
      END;
      v_failure_detail := 'TS_DAY must remain date-bucketed with key_value formatted as YYYY-MM-DD.';
    ELSE
      BEGIN
        v_date_text := to_char(v_key_value::date, 'YYYY-MM-DD');
        IF v_date_text IS DISTINCT FROM v_key_value THEN
          v_failure_reason := 'TS_DAY_KEY_VALUE_NOT_DATE';
          v_failure_detail := 'TS_DAY key_value is not a valid canonical YYYY-MM-DD date.';
        END IF;
      EXCEPTION
        WHEN OTHERS THEN
          v_failure_reason := 'TS_DAY_KEY_VALUE_NOT_DATE';
          v_failure_detail := 'TS_DAY key_value could not be cast to a valid date.';
      END;
    END IF;
  END IF;

  ok := v_failure_reason IS NULL;
  timesheet_id := v_timesheet_id;
  key_type := CASE WHEN v_failure_reason IS NULL THEN v_key_type ELSE NULL::text END;
  key_value := CASE WHEN v_failure_reason IS NULL THEN v_key_value ELSE NULL::text END;
  failure_reason := v_failure_reason;
  failure_detail := v_failure_detail;
  resolution_source := v_resolution_source;
  RETURN NEXT;
END;
$function$;

create or replace function private._weekly_source_rule_group_context_v1(
  p_group_id uuid,p_from date,p_to date,p_values jsonb,p_require_live boolean default false
) returns void language plpgsql stable security definer
set search_path to 'pg_catalog','pg_temp'
as $function$
declare
  v_group public.weekly_source_groups%rowtype;
  v_row record; v_policy jsonb; v_settings jsonb; v_scope_date date;
  v_contract_context record; v_contract_policy jsonb;
  v_agency boolean:=p_values->>'invoice_sender'='AGENCY_INVOICE';
  v_count integer:=0;
begin
  select * into v_group from public.weekly_source_groups where id=p_group_id and active;
  if not found or v_group.source_family<>'ROSTER' then
    raise exception 'WEEKLY_SOURCE_RULE_R10' using errcode='22023';
  end if;
  if v_agency and exists(select 1 from public.weekly_source_uploads u
    join public.weekly_source_cycles c on c.id=u.source_cycle_id
    join public.weekly_source_format_profiles f on f.id=u.source_format_profile_id
    where c.source_group_id=p_group_id and f.profile_code<>'HEALTHROSTER_WEEKLY_FROM_TO_ACTUAL_V1'
      and u.state in ('SEALED','CURRENT','SUPERSEDED','CORRECTION_READY')) then
    raise exception 'WEEKLY_SOURCE_RULE_AGENCY_PROFILE_CONFLICT' using errcode='22023';
  end if;
  if p_values is not null and p_values->>'checking_profile_kind'<>'ROSTER_WEEKLY_SUMMARY_ACTUAL_V1' and not v_agency
    and (((p_values->>'earliest_final_weekday')::integer+6)%7*1440
      +extract(hour from (p_values->>'earliest_final_local_time')::time)::integer*60
      +extract(minute from (p_values->>'earliest_final_local_time')::time)::integer
      <(v_group.cutoff_weekday+6)%7*1440+extract(hour from v_group.cutoff_local_time)::integer*60
      +extract(minute from v_group.cutoff_local_time)::integer) then
    raise exception 'WEEKLY_SOURCE_RULE_R9' using errcode='22023';
  end if;
  -- Evaluate every effective policy boundary in the requested dated interval.
  -- Membership and policy tables already exclude overlap; missing coverage is
  -- refused rather than being filled with a guessed policy.
  for v_row in
    select gc.client_id,greatest(gc.valid_from,p_from) as scope_date
    from public.weekly_source_group_clients gc
    where gc.source_group_id=p_group_id and daterange(gc.valid_from,coalesce(gc.valid_to,'infinity'::date),'[]')
      && daterange(p_from,coalesce(p_to,'infinity'::date),'[]')
    union
    select gc.client_id,cp.effective_from
    from public.weekly_source_group_clients gc join public.weekly_source_client_policies cp
      on cp.client_id=gc.client_id and cp.source_group_id=gc.source_group_id
    where gc.source_group_id=p_group_id and cp.effective_from>=p_from
      and cp.effective_from<=coalesce(p_to,'infinity'::date)
      and cp.effective_from between gc.valid_from and coalesce(gc.valid_to,'infinity'::date)
    union
    select gc.client_id,cp.effective_to+1
    from public.weekly_source_group_clients gc join public.weekly_source_client_policies cp
      on cp.client_id=gc.client_id and cp.source_group_id=gc.source_group_id
    where gc.source_group_id=p_group_id and cp.effective_to is not null and cp.effective_to+1>=p_from
      and cp.effective_to+1<=coalesce(p_to,'infinity'::date)
      and cp.effective_to+1 between gc.valid_from and coalesce(gc.valid_to,'infinity'::date)
    order by client_id,scope_date
  loop
    v_count:=v_count+1; v_scope_date:=v_row.scope_date;
    if not exists(select 1 from public.weekly_source_client_policies cp where cp.source_group_id=p_group_id
      and cp.client_id=v_row.client_id and v_scope_date between cp.effective_from and coalesce(cp.effective_to,'infinity'::date)) then
      raise exception 'WEEKLY_SOURCE_RULE_R8' using errcode='22023';
    end if;
    v_policy:=private._weekly_source_effective_policy_v1(v_row.client_id,null,v_scope_date);
    if p_values is null then
      if v_policy->>'authority_mode'<>'TIMESHEET_AUTHORITY' or v_policy->>'document_mode'<>'INVOICE_EVIDENCE_REQUIRED'
        or (v_policy->>'self_bill_enabled')::boolean then
        raise exception 'WEEKLY_SOURCE_RULE_SIGNED_GROUP_REQUIRED' using errcode='22023';
      end if;
      if p_require_live then
        v_settings:=private._contract_settings_effective_core_v1(v_row.client_id,null,v_scope_date,'DAILY',null);
        if not coalesce((v_settings->'applicability'->>'configuration_valid')::boolean,false)
          or not coalesce((v_settings->'values'->>'requires_hr')::boolean,false)
          or not coalesce((v_settings->'values'->>'autoprocess_hr')::boolean,false)
          or coalesce((v_settings->'values'->>'no_timesheet_required')::boolean,true)
          or coalesce((v_settings->'values'->>'is_nhsp')::boolean,true)
          or coalesce((v_settings->'values'->>'self_bill')::boolean,true) then
          raise exception 'WEEKLY_SOURCE_RULE_SIGNED_GROUP_REQUIRED' using errcode='22023'; end if;
      end if;
    elsif v_agency then
      if (v_policy->>'self_bill_enabled')::boolean
        or (p_require_live and (v_policy->>'authority_mode'<>'SOURCE_AUTHORITY' or v_policy->>'document_mode'<>'CHECK_ONLY'))
        or (not p_require_live and not ((v_policy->>'authority_mode'='SOURCE_AUTHORITY' and v_policy->>'document_mode'='CHECK_ONLY')
          or (v_policy->>'authority_mode'='TIMESHEET_AUTHORITY' and v_policy->>'document_mode'='INVOICE_EVIDENCE_REQUIRED'))) then
        raise exception 'WEEKLY_SOURCE_RULE_R14' using errcode='22023';
      end if;
      if exists(select 1 from public.weekly_source_group_rule_assignments a
        where a.source_group_id=p_group_id and a.feature_purpose='SIGNED_CHECK_ONLY'
          and daterange(a.effective_from_week_ending,coalesce(a.effective_to_week_ending,'infinity'::date),'[]')
            && daterange(p_from,coalesce(p_to,'infinity'::date),'[]')) then
        raise exception 'WEEKLY_SOURCE_RULE_R14' using errcode='22023';
      end if;
    elsif v_policy->>'authority_mode'<>'SOURCE_AUTHORITY' or v_policy->>'document_mode'<>'CHECK_ONLY'
      or not (v_policy->>'self_bill_enabled')::boolean then
      raise exception 'WEEKLY_SOURCE_RULE_R15' using errcode='22023';
    end if;
    -- SP-20 has no installed first-use witness in this source stage. Fail closed.
    if p_values is not null and (v_policy->>'source_fixed_expenses_enabled')::boolean then
      raise exception 'WEEKLY_SOURCE_RULE_R7' using errcode='22023';
    end if;
    perform private.weekly_source_magnit_contract_price_assert_v1(p_values,v_policy);
    if v_agency and coalesce((select cs.self_bill_no_invoices_sent from public.client_settings cs
      where cs.client_id=v_row.client_id and (cs.effective_from is null or cs.effective_from<=v_scope_date)
      order by cs.effective_from desc nulls last,cs.updated_at desc,cs.id desc limit 1),false) then
      raise exception 'WEEKLY_SOURCE_RULE_R14' using errcode='22023';
    end if;
    if v_agency and exists(select 1 from public.contracts c where c.client_id=v_row.client_id
      and c.weekly_timesheet_source::text='HEALTHROSTER'
      and daterange(c.start_date,c.end_date,'[]') && daterange(v_scope_date,coalesce(p_to,'infinity'::date),'[]')
      and exists(select 1 from public.weekly_source_group_clients gc where gc.source_group_id=p_group_id
        and gc.client_id=c.client_id and greatest(c.start_date,v_scope_date) between gc.valid_from and coalesce(gc.valid_to,'infinity'::date))
      and (coalesce(c.self_bill,false) or coalesce(c.no_timesheet_required,false) or coalesce(c.is_nhsp,false))) then
      raise exception 'WEEKLY_SOURCE_RULE_R14' using errcode='22023';
    end if;
    -- Contract overrides are resolved by the established dated settings owner.
    for v_contract_context in select c.id,greatest(c.start_date,v_scope_date) as work_date
      from public.contracts c where c.client_id=v_row.client_id and c.weekly_timesheet_source::text='HEALTHROSTER'
        and daterange(c.start_date,c.end_date,'[]') && daterange(v_scope_date,coalesce(p_to,'infinity'::date),'[]')
        and exists(select 1 from public.weekly_source_group_clients gc where gc.source_group_id=p_group_id
          and gc.client_id=c.client_id and greatest(c.start_date,v_scope_date) between gc.valid_from and coalesce(gc.valid_to,'infinity'::date))
    loop
      v_settings:=private._contract_settings_effective_core_v1(v_row.client_id,v_contract_context.id,v_contract_context.work_date,'WEEKLY',null);
      v_contract_policy:=private._weekly_source_effective_policy_v1(v_row.client_id,v_contract_context.id,v_contract_context.work_date);
      if p_values is not null and coalesce((v_contract_policy->>'source_fixed_expenses_enabled')::boolean,false) then
        raise exception 'WEEKLY_SOURCE_RULE_R7' using errcode='22023'; end if;
      perform private.weekly_source_magnit_contract_price_assert_v1(p_values,v_contract_policy);
      if v_agency and (coalesce((v_settings->'values'->>'self_bill')::boolean,true)
        or coalesce((v_settings->'values'->>'no_timesheet_required')::boolean,true)
        or coalesce((v_settings->'values'->>'is_nhsp')::boolean,true)
        or not coalesce((v_settings->'values'->>'requires_hr')::boolean,false)
        or not coalesce((v_settings->'values'->>'autoprocess_hr')::boolean,false)
        or not coalesce((v_settings->'applicability'->>'configuration_valid')::boolean,false)) then
        raise exception 'WEEKLY_SOURCE_RULE_R14' using errcode='22023';
      end if;
    end loop;
  end loop;
  if p_require_live and v_count=0 then
    raise exception 'WEEKLY_SOURCE_RULE_GROUP_MEMBERS_REQUIRED' using errcode='22023';
  end if;
end;
$function$;

create or replace function private._weekly_source_settings_deployment_v1(
  p_agency_id uuid,
  p_environment text
) returns text
language plpgsql
immutable
security invoker
set search_path to 'pg_catalog','pg_temp'
as $function$
declare
  v_environment text:=pg_catalog.upper(pg_catalog.btrim(coalesce(p_environment,'')));
begin
  if p_agency_id is null or v_environment not in ('TEST','LIVE') then
    raise exception 'WEEKLY_SOURCE_SETTINGS_DEPLOYMENT_INVALID' using errcode='22023';
  end if;
  return v_environment;
end;
$function$;

create or replace function private._weekly_source_settings_require_admin_v1(
  p_actor_user_id uuid
) returns void
language plpgsql
stable
security definer
set search_path to 'pg_catalog','pg_temp'
as $function$
begin
  if p_actor_user_id is null or not exists(
    select 1
    from public.tms_users office_user
    where office_user.id=p_actor_user_id
      and office_user.is_active
      and pg_catalog.lower(pg_catalog.btrim(coalesce(office_user.role,'')))='admin'
  ) then
    raise exception 'WEEKLY_SOURCE_SETTINGS_ADMIN_REQUIRED' using errcode='42501';
  end if;
end;
$function$;

create or replace function private.weekly_source_automatic_reconcile_producer_ready_v1(p_cycle_id uuid)
returns boolean language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare q jsonb; c public.weekly_source_cycles%rowtype; actual_client uuid; rules jsonb;
begin
  q:=private.weekly_source_protected_capability_receipt_v1(p_cycle_id);
  if q->>'schema_version' is distinct from 'WEEKLY_SOURCE_PROTECTED_CAPABILITY_OPERATIONAL_QUALIFICATION_V1'
    or q->>'phase' is distinct from 'ALL_PRE_SWITCH_GATES_QUALIFIED'
    or not(q->'capabilities' @> '["AUTOMATIC_RECONCILE"]'::jsonb) then return false; end if;
  select * into strict c from public.weekly_source_cycles where id=p_cycle_id;
  actual_client:=private.weekly_source_checking_client_scope_v1(c.current_projection_publication_id);
  if actual_client is not null then
    rules:=private.weekly_source_effective_rule_set_v1(actual_client,c.id)->'values';
    return coalesce(rules->>'invoice_sender'='CLIENT_SELF_BILL' and rules->>'equal_protected_hours'='CLEAR_AUTOMATICALLY',false);
  end if;
  -- Legacy group-wide scope is retained. Each actual event's S18b rule check
  -- remains in the normal selection owner; readiness grants no event permission.
  return exists(select 1 from public.weekly_source_group_clients member where member.source_group_id=c.source_group_id
    and c.finalisation_week_ending between member.valid_from and coalesce(member.valid_to,'infinity'::date)
    and private.weekly_source_effective_rule_set_v1(member.client_id,c.id)#>>'{values,invoice_sender}'='CLIENT_SELF_BILL'
    and private.weekly_source_effective_rule_set_v1(member.client_id,c.id)#>>'{values,equal_protected_hours}'='CLEAR_AUTOMATICALLY');
exception when no_data_found or too_many_rows or sqlstate '55000' then return false;
end;
$function$;

create or replace function private.weekly_source_bulk_producer_ready_v1(p_cycle_id uuid)
returns boolean language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
