create or replace function private.weekly_source_office_authority_v1(
  p_actor_user_id uuid,
  p_operation text,
  p_source_group_id uuid default null,
  p_client_id uuid default null,
  p_scope_date date default null
) returns jsonb
language plpgsql stable security definer
set search_path to 'public','private','extensions','pg_temp'
as $function$
declare
  v_actor public.tms_users%rowtype;
  v_operation text:=pg_catalog.upper(pg_catalog.btrim(coalesce(p_operation,'')));
  v_payment_operation boolean;
  v_scope_date date:=coalesce(p_scope_date,current_date);
  v_payload jsonb;
begin
  if p_actor_user_id is null or v_operation not in (
    'OPEN_QUERY_NOTICE','VIEW_SOURCE_PROGRESS','VIEW_PAY_WORK','OPEN_PAY_QUERY','UPLOAD_SOURCE','SEAL_SOURCE',
    'SUPERSEDE_SOURCE','RECHECK_SOURCE','ASK_CANDIDATES','SEND_MANAGER',
    'RESEND_MANAGER','ACCEPT_SYSTEM_HOURS','FINALISE_WEEK',
    'ADMIT_SOURCE_INVOICE','MOVE_SOURCE_INVOICE',
    'APPROVE_PROTECTED_PAY','AMEND_PROTECTED_PAY','WITHDRAW_PROTECTED_PAY',
    'RECORD_NOT_WORKED','RECONCILE_PROTECTED_PAY','CORRECT_FINAL_SOURCE'
  ) then
    raise exception 'WEEKLY_SOURCE_OFFICE_OPERATION_INVALID' using errcode='22023';
  end if;

  select * into v_actor
  from public.tms_users
  where id=p_actor_user_id;
  if not found or not v_actor.is_active then
    raise exception 'WEEKLY_SOURCE_OFFICE_ACTOR_INACTIVE' using errcode='42501';
  end if;

  v_payment_operation:=v_operation in (
    'APPROVE_PROTECTED_PAY','AMEND_PROTECTED_PAY','WITHDRAW_PROTECTED_PAY',
    'RECORD_NOT_WORKED','RECONCILE_PROTECTED_PAY','ACCEPT_SYSTEM_HOURS',
    'OPEN_PAY_QUERY','VIEW_PAY_WORK'
  );
  if v_payment_operation then
    if not private.weekly_source_pay_actor_allowed_v1(p_actor_user_id) then
      raise exception 'WEEKLY_SOURCE_PAYMENT_AUTHORISER_REQUIRED' using errcode='42501';
    end if;
  elsif v_operation<>'OPEN_QUERY_NOTICE'
     and pg_catalog.lower(pg_catalog.btrim(coalesce(v_actor.role,'')))<>'admin' then
    raise exception 'WEEKLY_SOURCE_OFFICE_ADMIN_REQUIRED' using errcode='42501';
  end if;

  if p_source_group_id is not null and not exists(
    select 1 from public.weekly_source_groups source_group
    where source_group.id=p_source_group_id and source_group.active
  ) then
    raise exception 'WEEKLY_SOURCE_GROUP_NOT_ACTIVE' using errcode='22023';
  end if;

  if p_client_id is not null and (
    p_source_group_id is null or not exists(
      select 1
      from public.weekly_source_group_clients membership
      where membership.source_group_id=p_source_group_id
        and membership.client_id=p_client_id
        and v_scope_date between membership.valid_from
          and coalesce(membership.valid_to,'infinity'::date)
    )
  ) then
    raise exception 'WEEKLY_SOURCE_CLIENT_NOT_IN_GROUP' using errcode='22023';
  end if;

  v_payload:=pg_catalog.jsonb_build_object(
    'actor_user_id',v_actor.id,
    'actor_active',v_actor.is_active,
    'actor_role',pg_catalog.lower(pg_catalog.btrim(coalesce(v_actor.role,''))),
    'payment_authoriser',coalesce(v_actor.payment_authoriser,false),
    'payment_golden_key',coalesce(v_actor.payment_golden_key,false),
    'operation',v_operation,
    'source_group_id',p_source_group_id,
    'client_id',p_client_id,
    'scope_date',v_scope_date
  );
  return v_payload || pg_catalog.jsonb_build_object(
    'allowed',true,
    'decision_fingerprint',pg_catalog.encode(
      private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_OFFICE_AUTHORITY_V1',v_payload),
      'hex'
    )
  );
end;
$function$;

create or replace function private.weekly_source_invoice_vat_target_pence_v1(
  p_net_pence numeric,p_line_vat_pence numeric,p_method text,p_rate_pct numeric
) returns bigint language plpgsql immutable set search_path to 'pg_catalog','pg_temp'
as $function$
begin
  if p_net_pence is null or p_line_vat_pence is null or p_rate_pct is null
    or p_net_pence<>trunc(p_net_pence) or p_line_vat_pence<>trunc(p_line_vat_pence)
    or p_rate_pct<0 or p_rate_pct>100 then
    raise exception 'WEEKLY_SOURCE_VAT_ROUNDING_MONEY_INVALID' using errcode='22023'; end if;
  return case p_method when 'SUM_OF_LINES' then p_line_vat_pence::bigint
    when 'ONCE_ON_TOTAL_HALF_UP' then round(p_net_pence*p_rate_pct/100)::bigint
    when 'ONCE_ON_TOTAL_TRUNCATE' then trunc(p_net_pence*p_rate_pct/100)::bigint
    else null end;
end;
$function$;

create or replace function private.weekly_source_checking_client_scope_v1(p_publication_id uuid)
returns uuid language plpgsql stable security definer
set search_path to 'pg_catalog','pg_temp'
as $function$
declare v_publication public.weekly_source_projection_publications%rowtype;
  v_cycle public.weekly_source_cycles%rowtype; v_upload public.weekly_source_uploads%rowtype; v_client uuid;
begin
  select * into strict v_publication from public.weekly_source_projection_publications where id=p_publication_id;
  select * into strict v_cycle from public.weekly_source_cycles where id=v_publication.source_cycle_id;
  select * into strict v_upload from public.weekly_source_uploads where id=v_publication.upload_id and source_cycle_id=v_cycle.id;
  v_client:=nullif(v_upload.file_metadata_json->>'client_id','')::uuid;
  if v_cycle.scope_client_id is not null and v_client is not null and v_cycle.scope_client_id is distinct from v_client then
    raise exception 'WEEKLY_SOURCE_PROJECTION_SCOPE_INVALID' using errcode='55000'; end if;
  return coalesce(v_cycle.scope_client_id,v_client);
exception when invalid_text_representation or no_data_found or too_many_rows then
  raise exception 'WEEKLY_SOURCE_PROJECTION_SCOPE_INVALID' using errcode='55000';
end;
$function$;

create or replace function private.weekly_source_protected_capability_receipt_v1(p_cycle_id uuid)
returns jsonb language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare c public.weekly_source_cycles%rowtype; g public.weekly_source_groups%rowtype;
  a public.weekly_source_group_rule_assignments%rowtype; q jsonb; receipt jsonb;
begin
  select * into strict c from public.weekly_source_cycles where id=p_cycle_id;
  select * into strict g from public.weekly_source_groups where id=c.source_group_id and active and source_family='ROSTER';
  select * into strict a from public.weekly_source_group_rule_assignments where source_group_id=g.id and feature_enabled
    and c.finalisation_week_ending between effective_from_week_ending and coalesce(effective_to_week_ending,'infinity'::date);
  receipt:=a.feature_receipt_json;
  if a.feature_purpose is null or a.feature_purpose not in ('RULE_SET','PROTECTED_SOURCE')
    or (a.feature_purpose='PROTECTED_SOURCE' and a.rule_set_version_id is not null)
    or receipt->>'contract' is distinct from 'WEEKLY_SOURCE_RULE_FEATURE_RECEIPT_V1'
    or receipt->>'assignment_id' is distinct from a.id::text or receipt->>'assignment_version' is distinct from a.version::text
    or receipt->>'source_group_id' is distinct from g.id::text
    or receipt->>'rule_set_version_id' is distinct from a.rule_set_version_id::text
    or receipt->>'feature_purpose' is distinct from a.feature_purpose or receipt->'feature_enabled' is distinct from 'true'::jsonb
    or receipt->>'actor_user_id' is distinct from a.feature_changed_by_user_id::text
    or receipt->>'request_id' is distinct from a.feature_request_id::text or receipt->>'release_id' is distinct from a.feature_release_id
    or receipt->>'effective_from_week_ending' is distinct from a.effective_from_week_ending::text
    or a.feature_request_sha256 is null or a.feature_changed_at_utc is null
    or not exists(select 1 from public.tms_users actor where actor.id=a.feature_changed_by_user_id and actor.is_active and actor.role='admin') then
    raise exception 'WEEKLY_SOURCE_PROTECTED_CAPABILITY_ACTIVATION_UNQUALIFIED' using errcode='55000'; end if;
  q:=private.weekly_source_protected_capability_release_evidence_v1(g.id,a.effective_from_week_ending,a.effective_to_week_ending,
    receipt#>>'{protected_capability_qualification,qualification_sha256}');
  if q->>'schema_version' is distinct from 'WEEKLY_SOURCE_PROTECTED_CAPABILITY_OPERATIONAL_QUALIFICATION_V1'
    or q->>'phase' is distinct from 'ALL_PRE_SWITCH_GATES_QUALIFIED'
    or q is distinct from receipt->'protected_capability_qualification' or q->>'release_id' is distinct from a.feature_release_id then
    raise exception 'WEEKLY_SOURCE_PROTECTED_CAPABILITY_ACTIVATION_UNQUALIFIED' using errcode='55000'; end if;
  return q;
end;
$function$;

create or replace function private.weekly_source_protected_qualification_release_v1()
returns jsonb language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare r private.cloudtms_database_releases%rowtype; i private.cloudtms_database_identity%rowtype;
begin
  select * into strict i from private.cloudtms_database_identity where singleton and environment='TEST';
  select * into strict r from private.cloudtms_database_releases order by started_at_utc desc,release_id desc limit 1;
  if current_database()<>'cloudtms_test_clone' or r.status is distinct from 'VERIFIED'
    or r.completed_at_utc is null or r.installed_contract_sha256 is distinct from r.repository_contract_sha256
    or r.evidence_json#>>'{managed_release,environment}' is distinct from 'TEST'
    or r.evidence_json#>>'{managed_release,expected_database}' is distinct from current_database()
    or r.evidence_json#>>'{weekly_source_protected_qualification_catalogue,schema_version}'
      is distinct from 'WEEKLY_SOURCE_QUALIFICATION_INSTALLED_CATALOGUE_V1'
    or r.evidence_json#>>'{weekly_source_protected_qualification_catalogue,contract_sha256}' is distinct from r.installed_contract_sha256
    or r.evidence_json#>>'{weekly_source_protected_qualification_catalogue,jsonb_sha256}' is distinct from encode(
      private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_QUALIFICATION_INSTALLED_CATALOGUE_V1',
        private.weekly_source_protected_qualification_current_catalogue_v1()),'hex') then
    raise exception 'WEEKLY_SOURCE_QUALIFICATION_INSTALLED_RELEASE_REQUIRED' using errcode='55000'; end if;
  return jsonb_build_object('release_id',r.release_id,'source_commit',r.git_commit,
    'contract_sha256',r.installed_contract_sha256,'installation_id',i.installation_id,
    'environment',i.environment,'database',current_database(),
    'managed_manifest_sha256',r.evidence_json#>>'{managed_release,manifest_sha256}',
    'installed_catalogue_jsonb_sha256',r.evidence_json#>>'{weekly_source_protected_qualification_catalogue,jsonb_sha256}');
exception when no_data_found or too_many_rows then
  raise exception 'WEEKLY_SOURCE_QUALIFICATION_INSTALLED_RELEASE_REQUIRED' using errcode='55000';
end;
$function$;

create or replace function private.weekly_exceptional_json_keys_exact_v1(
  p_value jsonb,
  p_allowed_keys text[]
) returns boolean
language sql immutable
set search_path to 'pg_catalog','pg_temp'
as $function$
  select pg_catalog.jsonb_typeof(p_value)='object'
    and not exists(
      select 1
      from pg_catalog.jsonb_object_keys(p_value) supplied(key)
      where not (supplied.key=any(p_allowed_keys))
    );
$function$;

create or replace function private.weekly_source_off_rule_setup_shape_assert_v1(p_auth jsonb)
returns void language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare manifest jsonb:=p_auth->'fixture_manifest'; key text; ids jsonb; sorted jsonb; permitted text[];
begin
  if not private.weekly_source_qualification_closed_object_v1(manifest,array['group_code','client_ids','contract_ids','candidate_ids','client_refs','candidate_refs'])
    or coalesce(manifest->>'group_code','') !~ '^WSQ_TEST_[A-Z0-9_]+$'
    or coalesce(p_auth->>'week_ending','') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
    or (p_auth->>'week_ending')::date::text is distinct from p_auth->>'week_ending'
    or extract(dow from (p_auth->>'week_ending')::date)<>0
    or coalesce(p_auth->>'expires_at_utc','') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]{1,6})?(Z|[+-][0-9]{2}:[0-9]{2})$' then
    raise exception 'WEEKLY_SOURCE_OFF_RULE_SETUP_SHAPE_INVALID' using errcode='22023'; end if;
  for key in select unnest(array['client_ids','contract_ids','candidate_ids']) loop
    ids:=manifest->key;
    if jsonb_typeof(ids) is distinct from 'array' or jsonb_array_length(ids) not between 1 and 100
      or exists(select 1 from jsonb_array_elements(ids) id where jsonb_typeof(id) is distinct from 'string'
        or coalesce(id#>>'{}','') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$') then
      raise exception 'WEEKLY_SOURCE_OFF_RULE_SETUP_SHAPE_INVALID' using errcode='22023'; end if;
    select jsonb_agg(id order by id) into sorted from (select distinct id from jsonb_array_elements(ids) id) dedupe;
    if ids is distinct from sorted then raise exception 'WEEKLY_SOURCE_OFF_RULE_SETUP_SHAPE_INVALID' using errcode='22023'; end if;
  end loop;
  if jsonb_typeof(manifest->'client_refs') is distinct from 'array' or jsonb_typeof(manifest->'candidate_refs') is distinct from 'array'
    or (select coalesce(jsonb_agg(value->'client_id' order by ord),'[]'::jsonb) from jsonb_array_elements(manifest->'client_refs') with ordinality refs(value,ord)) is distinct from manifest->'client_ids'
    or (select coalesce(jsonb_agg(value->'candidate_id' order by ord),'[]'::jsonb) from jsonb_array_elements(manifest->'candidate_refs') with ordinality refs(value,ord)) is distinct from manifest->'candidate_ids'
    or exists(select 1 from jsonb_array_elements(manifest->'client_refs') ref where not private.weekly_source_qualification_closed_object_v1(ref,array['client_id','cli_ref'])
      or coalesce(ref->>'cli_ref','') !~ '^CLI-913013[0-9]{2}$')
    or exists(select 1 from jsonb_array_elements(manifest->'candidate_refs') ref where not private.weekly_source_qualification_closed_object_v1(ref,array['candidate_id','tms_ref'])
      or coalesce(ref->>'tms_ref','') !~ '^CCR-913013[0-9]{2}$')
    or (select count(distinct value->>'cli_ref') from jsonb_array_elements(manifest->'client_refs'))<>jsonb_array_length(manifest->'client_ids')
    or (select count(distinct value->>'tms_ref') from jsonb_array_elements(manifest->'candidate_refs'))<>jsonb_array_length(manifest->'candidate_ids') then
    raise exception 'WEEKLY_SOURCE_OFF_RULE_SETUP_SHAPE_INVALID' using errcode='22023'; end if;
  permitted:=case p_auth->>'purpose' when 'SOURCE_FIXTURE_SETUP' then array[
    'weekly_source_upload_context_v1','weekly_source_upload_stage_begin_atomic_v1','weekly_source_upload_stage_rows_atomic_v1','weekly_source_upload_seal_atomic_v1',
    'weekly_source_projection_begin_atomic_v1','weekly_source_projection_rows_apply_atomic_v1','weekly_source_projection_publish_atomic_v1',
    'weekly_source_import_prepare_atomic_v1','weekly_source_finalise_atomic_v1','weekly_source_finalisation_pay_open_atomic_v1',
    'weekly_source_finalisation_pay_task_start_atomic_v1','weekly_source_ordinary_pay_projection_apply_atomic_v1','weekly_source_finalisation_pay_task_finish_atomic_v1',
    'REPORT_FIN_AB_FINALISE'] when 'AUTOMATIC_JOURNEY' then array['weekly_source_automatic_reconcile_atomic_v1','weekly_exceptional_pay_prepare_action_v1',
    'weekly_exceptional_pay_action_context_v1','weekly_exceptional_pay_action_publication_status_v1','weekly_exceptional_pay_stage_c1_request_v1'] else null end;
  ids:=p_auth->'allowed_operations';
  if permitted is null or jsonb_typeof(ids) is distinct from 'array' or jsonb_array_length(ids) not between 1 and cardinality(permitted)
    or exists(select 1 from jsonb_array_elements(ids) op where jsonb_typeof(op)<>'string' or not(op#>>'{}'=any(permitted))) then
    raise exception 'WEEKLY_SOURCE_OFF_RULE_SETUP_SHAPE_INVALID' using errcode='22023'; end if;
  select jsonb_agg(op order by op) into sorted from (select distinct op from jsonb_array_elements(ids) op) dedupe;
  if ids is distinct from sorted then raise exception 'WEEKLY_SOURCE_OFF_RULE_SETUP_SHAPE_INVALID' using errcode='22023'; end if;
  if p_auth->>'purpose'='AUTOMATIC_JOURNEY' and (not private.weekly_source_qualification_closed_object_v1(p_auth->'original_source_cas',
      array['schema_version','source_cycle_id','client_ids','source_cas_sha256'])
    or p_auth#>>'{original_source_cas,schema_version}' is distinct from 'WEEKLY_SOURCE_BULK_SOURCE_CAS_V1'
    or p_auth#>>'{original_source_cas,source_cycle_id}' is distinct from p_auth->>'source_cycle_id'
    or p_auth#>'{original_source_cas,client_ids}' is distinct from manifest->'client_ids'
    or jsonb_array_length(manifest->'client_ids')<>1
    or coalesce(p_auth#>>'{original_source_cas,source_cas_sha256}','') !~ '^[0-9a-f]{64}$') then
    raise exception 'WEEKLY_SOURCE_OFF_RULE_SETUP_SHAPE_INVALID' using errcode='22023'; end if;
exception when invalid_text_representation or datetime_field_overflow or invalid_datetime_format then
  raise exception 'WEEKLY_SOURCE_OFF_RULE_SETUP_SHAPE_INVALID' using errcode='22023';
end;
$function$;

